import React, { useState, useEffect, useMemo, useCallback } from "react";

/* ══════════════ FRAGENPOOL ══════════════ */
const POOL = [{"id":"k1-edc2d70c0a","kap":1,"sec":"1.2 Teildisziplinen","stem":"Innerhalb der Psychologie wird zwischen Methoden-, Grundlagen- und Anwendungsfächern unterschieden. Welche Aussage über diese Einteilung trifft zu?","opts":[{"t":"Die Grundlagenfächer zeichnen sich dadurch aus, dass sie psychologisches Wissen in verschiedenen Berufsfeldern praktisch zur Anwendung bringen.","c":false,"fb":"Das ist die Beschreibung der Anwendungsfächer. Grundlagenfächer erforschen allgemeine Gesetzmäßigkeiten, ohne primär auf die praktische Anwendung zu zielen."},{"t":"Die Klinische Psychologie zählt im Skript zu den Grundlagenfächern der Psychologie.","c":false,"fb":"Die Klinische Psychologie ist ein Anwendungsfach. Grundlagenfächer sind Biologische, Allgemeine, Entwicklungs-, Sozial- sowie Differentielle und Persönlichkeitspsychologie."},{"t":"Die Methodenfächer bilden das Grundgerüst psychologischer Forschung und umfassen unter anderem Ethik, Wissenschaftstheorie, Methodenlehre und Statistik.","c":true,"fb":"Genau so beschreibt das Skript die Methodenfächer: Grundgerüst der Forschung mit Ethik, Wissenschaftstheorie, Methodenlehre und Statistik."},{"t":"Die Grundlagenfächer bilden eine trennscharfe Ordnung ohne inhaltliche Überschneidungen zwischen den Fächern.","c":false,"fb":"Das Skript betont ausdrücklich, dass die Aufteilung künstlich ist: Es gibt Überschneidungen, und ein Phänomen kann Inhalt mehrerer Fächer sein."}],"concept":{"title":"Die drei Fächergruppen der Psychologie","points":["<b>Methodenfächer</b>: Grundgerüst der Forschung — Ethik, Wissenschaftstheorie, Methodenlehre, Statistik.","<b>Grundlagenfächer</b>: erforschen allgemeine Gesetzmäßigkeiten psychischer Prozesse (Biologische, Allgemeine, Entwicklungs-, Sozial-, Differentielle/Persönlichkeitspsychologie).","<b>Anwendungsfächer</b>: bringen psychologisches Wissen praktisch in Berufsfeldern zur Anwendung (Pädagogische, Klinische, AOW-, Gesundheitspsychologie).","<b>Funktion</b>: Ordnungssystem für Forschung und Lehre, häufig in den Curricula des Psychologiestudiums.","<b>Merke</b>: Die Aufteilung ist künstlich — Fächer überschneiden sich, ein Phänomen kann mehreren zugeordnet werden."]}},{"id":"k1-29952ea7ae","kap":1,"sec":"1.1 Definition & Kognition","stem":"Was besagen die Herkunft und die grundlegende Definition des Begriffs „Psychologie“ laut Skript?","opts":[{"t":"Das Wort setzt sich aus den griechischen Wörtern „psyche“ (Seele, Gemüt) und „logos“ (Kunde, Wissenschaft) zusammen und bedeutet wörtlich „Seelenkunde“.","c":true,"fb":"„psyche“ = Seele/Gemüt, „logos“ = Kunde/Wissenschaft — wörtlich übersetzt Seelenkunde."},{"t":"Der Wortbestandteil „logos“ ist aus dem Lateinischen abgeleitet und bedeutet „erkennen“.","c":false,"fb":"„cognoscere“ (= erkennen) ist lateinisch und die Wurzel von „Kognition“. „logos“ hingegen ist griechisch und meint Kunde bzw. Wissenschaft."},{"t":"Kognitive Prozesse — also Prozesse, die das Denken betreffen — sind aus der Definition der Psychologie ausdrücklich ausgeschlossen.","c":false,"fb":"Im Gegenteil: Kognitive, das Denken betreffende Prozesse fallen ausdrücklich unter den Gegenstand der Psychologie."},{"t":"Allgemein versteht man unter Psychologie die Wissenschaft vom Erleben und Verhalten des Menschen.","c":true,"fb":"Das ist die gängige Definition (Gazzaniga et al., 2017): Wissenschaft vom Erleben und Verhalten des Menschen."}],"concept":{"title":"Definition und Wortherkunft der Psychologie","points":["<b>Etymologie</b>: griech. „psyche“ (Seele, Gemüt) + „logos“ (Kunde, Wissenschaft) = wörtlich Seelenkunde.","<b>Definition</b>: Wissenschaft vom Erleben und Verhalten des Menschen (Gazzaniga et al., 2017).","<b>Kognition eingeschlossen</b>: auch kognitive (das Denken betreffende) Prozesse sind Gegenstand.","<b>Charakter</b>: empirische Wissenschaft, grundlagen- und anwendungsorientiert, vereint Geistes-, Sozial- und Naturwissenschaften.","<b>Nicht verwechseln</b>: „cognoscere“ (lat., erkennen) gehört zu „Kognition“, nicht zu „logos“."]}},{"id":"k1-8db141be2d","kap":1,"sec":"1.4 Ziele der Psychologie","stem":"Welche der folgenden Aussagen zu den vier Zielen der wissenschaftlichen Psychologie treffen zu?","opts":[{"t":"Das Ziel des Veränderns ist vor allem in der Grundlagenforschung angesiedelt und spielt in der praktischen Tätigkeit kaum eine Rolle.","c":false,"fb":"Umgekehrt: Das Verändern von Erleben und Verhalten ist häufig das Hauptanliegen praktisch arbeitender Psycholog:innen, etwa in der Therapie."},{"t":"Die vier Ziele lauten: Erleben und Verhalten beschreiben, erklären, vorhersagen und verändern.","c":true,"fb":"Genau diese vier Ziele nennt das Skript — sie finden sich in der Forschung wie in den Anwendungsfeldern."},{"t":"Beim Beschreiben wird zunächst der Ist-Zustand möglichst objektiv erfasst; die so gewonnenen Informationen werden auch Daten genannt.","c":true,"fb":"Beschreiben heißt, den Ist-Zustand objektiv und systematisch zu erfassen; die erfassten Informationen heißen Daten."},{"t":"Unter Vorhersagen versteht man Aussagen über die Wahrscheinlichkeit, mit der ein bestimmtes Verhalten auftreten wird.","c":true,"fb":"Vorhersagen sind Aussagen über die Auftretenswahrscheinlichkeit künftigen Verhaltens; sie müssen exakt formuliert sein, um prüfbar zu bleiben."}],"concept":{"title":"Die vier Ziele der Psychologie","points":["<b>Beschreiben</b>: Ist-Zustand objektiv und systematisch erfassen (→ Daten; Methoden: Beobachtung, Befragung, Test, Experiment).","<b>Erklären</b>: über das Beobachtbare hinausgehen; Theorien mit dispositionalen und situativen Faktoren.","<b>Vorhersagen</b>: Wahrscheinlichkeit künftigen Verhaltens; exakt formuliert, damit prüf- und widerlegbar.","<b>Verändern</b>: oft Hauptanliegen der Praxis (Therapie); erfordert einen Behandlungsauftrag und ist ethisch gebunden.","<b>Merke</b>: Die Ziele bauen aufeinander auf — ohne Beschreibung keine Erklärung, ohne Erklärung keine tragfähige Vorhersage."]}},{"id":"k1-6291204575","kap":1,"sec":"1.2 Teildisziplinen","stem":"Welche Zuordnungen von Grundlagenfach zu Untersuchungsgegenstand sind korrekt?","opts":[{"t":"Die Allgemeine Psychologie untersucht allgemeingültige, allen Menschen gemeine Prozesse wie Wahrnehmung, Denken, Lernen, Gedächtnis, Sprache, Emotion und Motivation.","c":true,"fb":"Die Allgemeine Psychologie sucht allgemeingültige Gesetzmäßigkeiten der allen Menschen gemeinsamen Prozesse."},{"t":"Die Sozialpsychologie untersucht in erster Linie die physischen Abläufe im Nervensystem, die psychischen Phänomenen zugrunde liegen.","c":false,"fb":"Physische Abläufe im Nervensystem sind Gegenstand der Biologischen Psychologie. Die Sozialpsychologie untersucht soziale Einflüsse und die Interaktion mit anderen."},{"t":"Die Entwicklungspsychologie befasst sich mit Veränderungen psychischer Prozesse im Laufe des gesamten Lebens.","c":true,"fb":"Die Entwicklungspsychologie betrachtet Veränderungen psychischer Prozesse über die gesamte Lebensspanne."},{"t":"Die Differentielle und Persönlichkeitspsychologie beschäftigt sich ausschließlich mit Unterschieden zwischen verschiedenen Personen, nicht jedoch innerhalb einer Person.","c":false,"fb":"Sie untersucht Unterschiede zwischen Personen und innerhalb einer Person (z. B. zu verschiedenen Zeitpunkten) — nicht nur zwischen Personen."}],"concept":{"title":"Die fünf Grundlagenfächer der Psychologie","points":["<b>Biologische Psychologie</b>: physische Abläufe im Körper, vor allem im Nervensystem (Kap. 4).","<b>Allgemeine Psychologie</b>: allen Menschen gemeine, allgemeingültige Prozesse — Wahrnehmung, Denken, Lernen, Gedächtnis, Sprache, Emotion, Motivation (Kap. 5).","<b>Entwicklungspsychologie</b>: Veränderungen psychischer Prozesse über die gesamte Lebensspanne (Kap. 6).","<b>Sozialpsychologie</b>: Wirkung sozialer Einflüsse und der Interaktion mit anderen (Kap. 7).","<b>Differentielle/Persönlichkeitspsychologie</b>: Unterschiede zwischen und innerhalb von Personen; Einfluss von Genen, Umwelt und Kultur (Kap. 8)."]}},{"id":"k1-b9dae3b9ce","kap":1,"sec":"1.3 Ansätze der Psychologie","stem":"Welche Aussagen über den behavioristischen und den psychodynamischen Ansatz sind zutreffend?","opts":[{"t":"Der psychodynamische Ansatz geht davon aus, dass Verhalten primär durch bewusste, rationale Abwägung gesteuert wird.","c":false,"fb":"Der psychodynamische Ansatz betont innere Kräfte (Triebe) und unbewusste Prozesse — nicht die bewusste, rationale Abwägung."},{"t":"Der behavioristische Ansatz erklärt Verhalten über beobachtbare Reize, Reaktionen und die darauf folgenden Konsequenzen; nicht beobachtbare mentale Prozesse bleiben unberücksichtigt.","c":true,"fb":"Der Behaviorismus stützt sich auf beobachtbare Reize, Reaktionen und Konsequenzen; nicht direkt beobachtbare mentale Prozesse werden ausgeklammert."},{"t":"Als Begründer des psychodynamischen Ansatzes gilt Carl Rogers.","c":false,"fb":"Begründer ist Sigmund Freud. Carl Rogers steht für den humanistischen Ansatz (Gesprächspsychotherapie)."},{"t":"Als Begründer des Behaviorismus gilt John Watson.","c":true,"fb":"John Watson gilt als Begründer des Behaviorismus (vgl. Kap. 2.4.3 und 5.3.3)."}],"concept":{"title":"Fünf Ansätze der Psychologie im Überblick","points":["<b>Psychodynamisch</b>: Verhalten durch innere Triebe und unbewusste Prozesse; Begründer Sigmund Freud.","<b>Behavioristisch</b>: nur beobachtbare Reize, Reaktionen, Konsequenzen; Begründer John Watson.","<b>Humanistisch</b>: Mensch als aktives, nach positiver Entwicklung strebendes Wesen; Rogers, Maslow, Bühler; holistisch (ab 1950).","<b>Kognitiv</b>: nicht direkt beobachtbare Vorgänge (Aufmerksamkeit, Denken, Erinnern); heute dominierend.","<b>Biologisch-neurowissenschaftlich</b>: psychische Phänomene aus biochemischen Vorgängen (Gene, Nerven-, Hormonsystem).","<b>Merke</b>: Die Ansätze schließen einander nicht aus; ihre Kombination heißt eklektischer Ansatz."]}},{"id":"k1-5bf3dcea9d","kap":1,"sec":"1.1 Definition & Kognition","stem":"Die Infobox 1.1 beschreibt den Begriff „Kognition“. Welche Aussagen dazu sind korrekt?","opts":[{"t":"Der Begriff ist vom lateinischen „cognoscere“ (= erkennen) abgeleitet.","c":true,"fb":"„cognoscere“ ist lateinisch und bedeutet „(er-)kennen“ — daraus leitet sich „Kognition“ ab."},{"t":"Kognition ist ein Sammelbegriff für mentale Fähigkeiten und Prozesse, mit denen Informationen aufgenommen, verarbeitet und gespeichert werden.","c":true,"fb":"Genau so definiert die Infobox Kognition (Neisser, 2014): Aufnehmen, Verarbeiten und Speichern von Informationen."},{"t":"Kognition bezeichnet ausschließlich emotionale und motivationale Vorgänge und grenzt das Denken bewusst aus.","c":false,"fb":"Gerade das Denken gehört zum Kern der Kognition; emotionale und motivationale Vorgänge sind nicht ihr definierender Inhalt."},{"t":"Zu den kognitiven Prozessen zählen unter anderem Aufmerksamkeit, Wahrnehmung, Gedächtnis, Schlussfolgern sowie Denken und Problemlösen.","c":true,"fb":"Diese Prozesse nennt die Infobox ausdrücklich als Beispiele für Kognition."}],"concept":{"title":"Kognition (Infobox 1.1, Neisser, 2014)","points":["<b>Wortherkunft</b>: lat. „cognoscere“ = (er-)kennen.","<b>Definition</b>: Sammelbegriff für mentale Fähigkeiten/Prozesse des Aufnehmens, Verarbeitens und Speicherns von Information.","<b>Beispiele</b>: Aufmerksamkeit, Wahrnehmung, Gedächtnis, Schlussfolgern, Denken, Problemlösen.","<b>Stellenwert</b>: gehört zum Standardvokabular der Psychologie und kommt in vielen Kapiteln wieder vor.","<b>Merke</b>: Kognition betrifft Denken und Informationsverarbeitung — nicht primär Emotion oder Motivation."]}},{"id":"k1-ae43cc7b2e","kap":1,"sec":"1.2 Teildisziplinen","stem":"Welche der folgenden Beschreibungen von Anwendungsfächern der Psychologie treffen laut Skript zu?","opts":[{"t":"Die Klinische Psychologie befasst sich mit psychischen Störungen sowie deren Prävention, Behandlung und Rehabilitation.","c":true,"fb":"Betätigungsfelder der Klinischen Psychologie sind psychische Störungen und deren Prävention, Behandlung und Rehabilitation."},{"t":"Die Pädagogische Psychologie beschreibt und erklärt psychologische Komponenten in Erziehungs- und Bildungsprozessen.","c":true,"fb":"Die Pädagogische Psychologie widmet sich psychologischen Komponenten von Erziehung und Bildung (z. B. Lernmotivation, Wissensvermittlung)."},{"t":"Die AOW-Psychologie betrachtet Erleben und Verhalten von Personen im Beruf und in Unternehmen und berät etwa bei Personalauswahl oder Marketing.","c":true,"fb":"Die AOW-Psychologie (Arbeit, Organisation, Wirtschaft) betrachtet Beruf und Unternehmen, betreibt Marktforschung und berät u. a. bei Personalauswahl und Marketing."},{"t":"Die Gesundheitspsychologie entwickelt gesundheitserhaltende und -fördernde Maßnahmen und berücksichtigt dabei biologische, psychische und soziale Faktoren.","c":true,"fb":"Die Gesundheitspsychologie zielt auf gesundheitserhaltende und -fördernde Maßnahmen und bezieht biologische, psychische und soziale Faktoren ein."}],"concept":{"title":"Anwendungsfächer der Psychologie","points":["<b>Pädagogische Psychologie</b>: psychologische Komponenten von Erziehung und Bildung (Lernmotivation, Wissensvermittlung, Talentförderung).","<b>AOW-Psychologie</b>: Arbeit, Organisation, Wirtschaft — Beruf, Unternehmen, Marktforschung, Personalauswahl, Marketing.","<b>Klinische Psychologie</b>: psychische Störungen, Prävention, Behandlung, Rehabilitation.","<b>Gesundheitspsychologie</b>: gesundheitserhaltende/-fördernde Maßnahmen; biologische, psychische, soziale Faktoren (Ernährung, Bewegung, Stress …).","<b>Psychologische Diagnostik</b>: Sonderrolle — mal Anwendungsfach, mal fachübergreifende Fertigkeit für fundierte Entscheidungen."]}},{"id":"k1-d80bcfd940","kap":1,"sec":"1.5 Ethische Prinzipien","stem":"Die American Psychological Association (APA) hat fünf ethische Grundsätze formuliert. Welcher der folgenden Grundsätze zählt tatsächlich zu diesem Katalog?","opts":[{"t":"Prinzip der maximalen Wirksamkeit: Interventionen sind stets so zu wählen, dass der Therapieerfolg maximiert wird.","c":false,"fb":"Ein solches „Prinzip der maximalen Wirksamkeit“ gehört nicht zu den fünf ethischen Grundsätzen der APA."},{"t":"Integrität: Psycholog:innen handeln nach Ehrlichkeit, Genauigkeit und Wahrhaftigkeit und unterlassen Betrug oder Täuschung.","c":true,"fb":"Integrität ist einer der fünf Grundsätze: Ehrlichkeit, Genauigkeit, Wahrhaftigkeit; keine Täuschung oder Falschdarstellung von Fakten."},{"t":"Prinzip der wissenschaftlichen Neutralität: Psycholog:innen enthalten sich in Forschung und Praxis jeder persönlichen Wertung.","c":false,"fb":"Eine „wissenschaftliche Neutralität“ in diesem Sinne ist kein Grundsatz des APA-Katalogs."},{"t":"Prinzip der ökonomischen Verhältnismäßigkeit: Der Aufwand einer Behandlung ist stets ihrem wirtschaftlichen Nutzen unterzuordnen.","c":false,"fb":"Eine „ökonomische Verhältnismäßigkeit“ zählt nicht zu den fünf ethischen Grundsätzen."}],"concept":{"title":"Die fünf ethischen Grundsätze der APA (2017)","points":["<b>Wohltätigkeit und Nicht-Schaden</b>: Wohl aller Beteiligten verfolgen, Schaden verhindern oder minimieren.","<b>Loyalität und Verantwortung</b>: Vertrauen bewusst wahrnehmen, berufliche Standards einhalten, im besten Interesse handeln.","<b>Integrität</b>: Ehrlichkeit, Genauigkeit, Wahrhaftigkeit; kein Betrug, keine Täuschung (vgl. Milgram-Experiment).","<b>Gerechtigkeit</b>: gleicher Zugang zu den Erkenntnissen der Psychologie; eigene Grenzen und Voreingenommenheit erkennen.","<b>Respekt für Rechte und Würde</b>: Privatsphäre, Vertraulichkeit, Selbstbestimmung; kultur- und rollenspezifische Unterschiede achten."]}},{"id":"k1-aee0f732f1","kap":1,"sec":"1.3 Ansätze der Psychologie","stem":"Welche Aussage über den humanistischen Ansatz trifft zu?","opts":[{"t":"Er rückt die nicht direkt beobachtbaren Vorgänge wie Aufmerksamkeit, Denken und Erinnern in den Mittelpunkt und gilt heute als dominierender Ansatz.","c":false,"fb":"Das beschreibt den kognitiven Ansatz, der in den letzten Jahrzehnten zum dominierenden Ansatz geworden ist."},{"t":"Er lehnt eine holistische Betrachtung des Menschen ab und beschränkt sich strikt auf das beobachtbare Verhalten.","c":false,"fb":"Das Gegenteil trifft zu: Der humanistische Ansatz ist ausdrücklich holistisch (der Mensch als Ganzes). Die Beschränkung auf beobachtbares Verhalten kennzeichnet den Behaviorismus."},{"t":"Er entwickelte sich ab 1950 als Alternative zu den psychodynamischen und behavioristischen Ansichten und sieht den Menschen als aktives, nach positiver Entwicklung strebendes Wesen.","c":true,"fb":"Der humanistische Ansatz entstand ab 1950 als Gegenentwurf und betont den Menschen als aktives, auf positive Entwicklung ausgerichtetes Wesen."},{"t":"Bekannte Vertreter sind John Watson und Sigmund Freud.","c":false,"fb":"Vertreter:innen sind Carl Rogers, Abraham Maslow und Charlotte Bühler. Watson steht für den Behaviorismus, Freud für die Psychodynamik."}],"concept":{"title":"Der humanistische Ansatz","points":["<b>Entstehung</b>: ab 1950, als Alternative zu psychodynamischen und behavioristischen Ansichten.","<b>Menschenbild</b>: aktives Wesen, dessen Hauptaufgabe das Streben nach positiver Entwicklung ist.","<b>Vertreter:innen</b>: Carl Rogers, Abraham Maslow, Charlotte Bühler.","<b>Holistisch</b>: der Mensch als Ganzes; auch soziale und kulturelle Faktoren werden einbezogen.","<b>Zentrale Elemente</b>: Freiheit, das Selbst (Selbstverwirklichung/Selbstbewusstsein), Bedürfnisse, Interessen und Ziele.","<b>Therapiebezug</b>: Gesprächspsychotherapie nach Carl Rogers."]}},{"id":"k1-404dade6ae","kap":1,"sec":"1.4 Ziele der Psychologie","stem":"Beim Ziel des Erklärens werden dispositionale und situative Faktoren unterschieden. Welche Aussagen dazu sind korrekt?","opts":[{"t":"Dispositionale Faktoren sind zeitlich stabile Merkmale innerhalb der Person, etwa genetische Ausstattung, Fähigkeiten oder Persönlichkeitsmerkmale.","c":true,"fb":"Dispositionale Faktoren liegen zeitlich stabil in der Person: Gene, erlernte Verhaltensweisen, Fähigkeiten, Bedürfnisse, Interessen, Persönlichkeitsmerkmale."},{"t":"Die Persönlichkeitspsychologie beschäftigt sich in erster Linie mit situativen Faktoren, die Sozialpsychologie primär mit dispositionalen.","c":false,"fb":"Es ist umgekehrt: Die Persönlichkeitspsychologie fokussiert dispositionale, die Sozialpsychologie situative Faktoren."},{"t":"Das Wetter zählt zu den dispositionalen Faktoren, weil es das Erleben einer Person unmittelbar prägt.","c":false,"fb":"Das Wetter ist ein situativer Faktor (er wirkt von der Umwelt auf das Individuum ein), kein dispositionaler."},{"t":"Situative Faktoren wirken von der Umwelt auf das Individuum ein, zum Beispiel das Verhalten anderer Personen oder das Wetter.","c":true,"fb":"Situative Faktoren kommen aus der Umwelt — etwa das Verhalten anderer, das Wetter oder Situationen, denen die Person ausgesetzt ist."}],"concept":{"title":"Erklärende Faktoren: dispositional vs. situativ","points":["<b>Dispositionale Faktoren</b>: zeitlich stabile Merkmale in der Person — Gene, erlernte Verhaltensweisen, Fähigkeiten, Bedürfnisse, Interessen, Persönlichkeitsmerkmale.","<b>Situative Faktoren</b>: von der Umwelt einwirkend — Verhalten anderer, Wetter, konkrete Situationen.","<b>Grundannahme</b>: Verhalten entsteht meist durch die Kombination mehrerer Faktoren.","<b>Persönlichkeitspsychologie</b>: Fokus primär auf dispositionalen Faktoren.","<b>Sozialpsychologie</b>: Fokus in erster Linie auf situativen Faktoren."]}},{"id":"k2-2009b87aa8","kap":2,"sec":"2.2.3 Naturwissenschaftliche Neubegründung","stem":"Welche Aussagen über Wilhelm Wundt und seine Auffassung von Psychologie treffen zu?","opts":[{"t":"Er gründete 1879 an der Universität Leipzig das erste ausgewiesene Labor für experimentelle Psychologie und führte es zunächst als Privateinrichtung.","c":true,"fb":"Das Labor war anfangs mit persönlich angeschafften Instrumenten bestückt und wurde erst später mit wissenschaftlichen Geldern ausgestattet."},{"t":"Mit Apperzeption bezeichnete er die Aufnahme des Inhalts einer Wahrnehmung, Erinnerung oder eines Denkprozesses – aktiv und willentlich oder auch passiv und unvorbereitet.","c":true,"fb":"Die Aufmerksamkeit auf Sinneseindrücke, Gefühle und Vorstellungen ermöglicht die „schöpferische Synthese“, in der qualitativ neue Gebilde entstehen."},{"t":"Komplexere Tatbestände wie Denken, Sprache und Sitten hielt er für dem Experiment nicht zugänglich und behandelte sie ab 1900 im zehnbändigen Werk Völkerpsychologie.","c":true,"fb":"Die vorwiegend experimentell betriebene physiologische Psychologie erforschte für ihn nur die elementaren Tatbestände des Seelischen."},{"t":"Neben der kontrollierten Selbstbeobachtung setzte er die Methode der Inhaltsanalyse ein und berücksichtigte damit ein experimentelles wie ein interpretatives Paradigma.","c":true,"fb":"Seine Konzeption war multiperspektivisch; eine Reduzierung auf die experimentelle Psychologie würde seinem Schaffen nicht gerecht."}],"concept":{"title":"Wilhelm Wundt und die experimentelle Psychologie (mit Infobox 2.3)","points":["<b>Labor 1879</b>: erstes ausgewiesenes Labor für experimentelle Psychologie in Leipzig, zunächst Privateinrichtung; aus der Doktorandenausbildung gingen Labore rund um den Globus hervor.","<b>Selbstverständnis</b>: Psychologie als empirische Geisteswissenschaft, in der Philosophie verankert – nicht als reine Naturwissenschaft.","<b>Apperzeption</b>: Aufnahme des Inhalts einer Wahrnehmung, Erinnerung oder eines Denkprozesses; aktiv-willentlich oder passiv-unvorbereitet.","<b>Schöpferische Synthese</b>: durch Verbindung, Verschmelzung und Verdichtung entstehen qualitativ neue Gebilde im Fokus des Bewusstseins.","<b>Zwei Methodenstränge</b>: experimentelle Introspektion (Infobox 2.3: „Innenschau“, Wissen über eigene gegenwärtige Zustände ohne externe Quellen) und Inhaltsanalyse geistiger Objektivationen (Völkerpsychologie, ab 1900, zehn Bände).","<b>Schule</b>: mit seinem Schüler Edward Titchener Mitbegründer des Strukturalismus."]}},{"id":"k2-18c630f36a","kap":2,"sec":"2.1.1 Ursprünge des Seelenbegriffs","stem":"Welche Aussage zu den Seelenarten des Aristoteles und zur Temperamentenlehre trifft zu?","opts":[{"t":"Die vegetative Seele oder Pflanzenseele formt über die Grundfähigkeiten hinaus die Sinneswahrnehmung, die Begierde und die Fortbewegung.","c":false,"fb":"Diese Leistungen schreibt Aristoteles der animalischen Seele bzw. Tierseele zu; die vegetative Seele umfasst Ernährung, Wachstum und Fortpflanzung."},{"t":"Die Vier-Säfte-Lehre geht auf Galen zurück; rund 600 Jahre später stellte Hippokrates mit der Temperamentenlehre den Bezug zur Persönlichkeit her.","c":false,"fb":"Die Reihenfolge ist vertauscht: Hippokrates (ca. 460–370 v. Chr.) formulierte die Vier-Säfte-Lehre, Galen (ca. 129–199 n. Chr.) entwarf daraus die Temperamentenlehre."},{"t":"Melancholiker werden nach Galen von der schwarzen Galle dominiert und neigen zu Schwermut und Trübsinn.","c":true,"fb":"Jedem Typ ist ein dominanter Körpersaft zugeordnet; die schwarze Galle steht für starke Gefühle von Traurigkeit."},{"t":"Aristoteles blieb zeitlebens bei der dualistischen Sicht seines Lehrers Platon, wonach die Seele unabhängig vom Körper besteht.","c":false,"fb":"Anfangs war er dieser Ansicht zugewandt, kam aber zu der Auffassung, dass Seele und Körper untrennbar verbunden sind und die Seele den Körper erst zum Lebewesen vervollständigt."}],"concept":{"title":"Seelenarten bei Aristoteles und die Temperamentenlehre","points":["<b>Vegetative Seele (Pflanzenseele)</b>: Grundfähigkeit zu Ernährung, Wachstum und Fortpflanzung.","<b>Animalische Seele (Tierseele)</b>: zusätzlich Sinneswahrnehmung, Begierde und Fortbewegung.","<b>Denkende Seele (Geistseele)</b>: zusätzlich die Fähigkeit zur Logik – diese Seelengruppe besitzen nur Menschen.","<b>Aristoteles (384–322 v. Chr.)</b>: Schüler Platons, eigene Schule; die Seele gibt den Organen Form, Gestalt und damit Zweckmäßigkeit (die Seele formt das Auge, das Auge dient dem Sehen).","<b>Zwei Personen, zwei Schritte</b>: Hippokrates (ca. 460–370 v. Chr.) – Vier-Säfte-Lehre als medizinische Krankheitserklärung; Galen (ca. 129–199 n. Chr.) – Temperamentenlehre mit funktionellem Zusammenhang von Physischem und Psychischem.","<b>Die vier Typen</b>: Sanguiniker (Blut, freudvoll, stark erregbar), Phlegmatiker (Schleim, langsame und schwache Reaktionen, freundlich), Choleriker (gelbe Galle, temperamentvoll, leicht zu verärgern), Melancholiker (schwarze Galle, traurig, schwermütig)."]}},{"id":"k2-4f5b64c28a","kap":2,"sec":"2.4.3 Behaviorismus","stem":"Welche Aussagen zum Behaviorismus und zu seinen Vertretern treffen zu?","opts":[{"t":"Zu Beginn des 20. Jahrhunderts entstand in den USA der Behaviorismus, parallel dazu in Russland die Reflexologie – zwei Richtungen mit weitgehend deckungsgleichen Ansichten.","c":true,"fb":"Iwan Pawlow (1849–1936) ist die zentrale Figur der Reflexologie; mit dem Nachweis der Klassischen Konditionierung lieferte er einen wesentlichen Beitrag zu den behavioristischen Lerntheorien."},{"t":"Skinner beschrieb mit der Operanten Konditionierung, dass bekräftigende Folgereize die Auftretenswahrscheinlichkeit eines Verhaltens senken und entkräftende sie erhöhen.","c":false,"fb":"Die Richtung ist umgekehrt: Bekräftigende Folgereize stärken die Verbindung und erhöhen die Auftretenswahrscheinlichkeit, entkräftende schwächen sie."},{"t":"Thorndike stellte bei seiner Forschung an Reiz-Reaktions-Verknüpfungen fest, dass die Verhaltensreaktion umso wahrscheinlicher ist, je stärker die Verbindung zwischen den beiden Reizen ausfällt.","c":true,"fb":"Auf diesen Untersuchungen baute Skinner seine Lerntheorie der Operanten Konditionierung auf."},{"t":"Als „Black Box“ wird die vom Behaviorismus ausgeklammerte Wissenslücke zwischen Reiz und Reaktion bezeichnet; der Neobehaviorismus bezieht sie als Organismusvariable mit ein.","c":true,"fb":"Kritische Stimmen bemängelten genau diese Ausklammerung mentaler Zustände wie Denkprozesse."}],"concept":{"title":"Behaviorismus: Grundannahmen und Vertreter","points":["<b>Gegenstand</b>: beobachtbares Verhalten als Reaktion auf äußere Reize sowie Verhaltensanpassungen; abgelehnt werden Strukturalismus, Elementarismus und Funktionalismus als zu „subjektiv“.","<b>Watson (1878–1958)</b>: Hauptbegründer; Verhalten als Reaktion auf einen äußeren Reiz, Verbindung zweier an sich unabhängiger Reize möglich.","<b>Impulse zum Paradigmenwechsel (Cox, 2019)</b>: Forderung nach einer gesellschaftlich nützlichen Psychologie, Erfolge der europäischen Physiologie Mitte des 19. Jahrhunderts, Forderungen des Positivismus.","<b>Lerntheorien</b>: Pawlow – Klassische Konditionierung; Thorndike – Verknüpfungsstärke; Skinner – Operante Konditionierung mit bekräftigenden und entkräftenden Folgereizen.","<b>Hull (1884–1952)</b>: allgemeine Verhaltenstheorie 1952 – Reiz und Reaktion als elementare Komponenten, deren Kombination zur Gewohnheit wird; Triebstärke, Anreizwert der Belohnung und Reizintensität beeinflussen die Häufigkeit.","<b>Black Box und Neobehaviorismus</b>: Erweiterung des Reiz-Reaktions-Schemas um eine „mentale Variable“; bis Ende der 1960er Jahre schleichendes Ende der radikal behavioristischen Sichtweise."]}},{"id":"k2-bc9d9e6e53","kap":2,"sec":"2.2.2 Entwicklungen im 18. und 19. Jahrhundert","stem":"Welche Annahmen bzw. Forderungen des Positivismus führt Schönpflug (2013) an?","opts":[{"t":"Metaphysische Deutungen sind als ergänzende Erklärungsebene zulässig, solange sie den beobachteten Tatsachen nicht widersprechen.","c":false,"fb":"Der Positivismus schließt metaphysische Deutungen als wissenschaftlich unzulässig aus – ohne Einschränkung."},{"t":"Maßstab der Wahrheit ist die Gewissheit, die durch die Übereinstimmung der Forschenden entsteht.","c":true,"fb":"Wahrheit wird damit an intersubjektive Übereinstimmung gebunden, nicht an eine metaphysisch begründete Gewissheit."},{"t":"Das Sammeln von Beobachtungen genügt als wissenschaftliche Grundlage; die Ableitung von Theorien bleibt der Philosophie überlassen.","c":false,"fb":"Das Skript hebt ausdrücklich das Gegenteil hervor: Das alleinige Sammeln von Beobachtungen reicht nicht aus, aus Beobachtungen sind Theorien abzuleiten."},{"t":"Wissenschaft ist grundsätzlich unvollendet – es bleibt stets eine Wirklichkeit, die durch Wissen nicht erfasst wird.","c":true,"fb":"Diese Selbstbeschränkung gehört neben der Beschränkung auf Tatsachen zu den Kernforderungen."}],"concept":{"title":"Der Positivismus (Begründer: Auguste Comte, 1798–1857)","points":["<b>Grundforderung</b>: vorurteilsfreie Erfassung ausschließlich überprüfbarer Tatsachen, Beschränkung auf Erfahrung als einzige Erkenntnisquelle.","<b>Analyse</b>: stützt sich auf Tatsachen und deren beobachtbare Beziehungen; metaphysische Deutungen sind unzulässig.","<b>Wahrheitsmaßstab</b>: Gewissheit durch Übereinstimmung der Forschenden.","<b>Grenzen und Anspruch</b>: Wissenschaft bleibt grundsätzlich unvollendet; Beobachtungen allein genügen nicht, aus ihnen sind Theorien abzuleiten.","<b>Zweck</b>: positive Wissenschaft dient dem technischen und sozialen Fortschritt.","<b>Wirkung</b>: quantitative Methoden der Zählung und Messung; am deutlichsten fortgeführt im amerikanischen Behaviorismus – Comte gilt zugleich als Begründer der Soziologie."]}},{"id":"k2-fe9c8803cd","kap":2,"sec":"2.4.4 Tiefenpsychologie","stem":"Welche Aussage zu Alfred Adler und C. G. Jung trifft zu?","opts":[{"t":"Für Jung ist die Libido ausschließlich sexuelle Triebenergie, während Freud sie als allgemeine Lebensenergie verstand.","c":false,"fb":"Genau umgekehrt: Bei Freud ist die Libido sexuelle Triebenergie, für Jung eine allgemeine Lebensenergie."},{"t":"Adler begründete die Individualpsychologie und verstand neurotische Verhaltensformen als Überkompensation individueller Unzulänglichkeiten.","c":true,"fb":"Damit wandte er sich in den Grundzügen von Freuds Fokussierung auf die Sexualität ab."},{"t":"Nach Adler wird das Geltungsstreben durch den Archetypus der Magna Mater kompensiert.","c":false,"fb":"Adler nahm eine Kompensation durch das Gemeinschaftsgefühl an; die Magna Mater ist ein Archetypus aus Jungs Analytischer Psychologie."},{"t":"Jung begründete die Neopsychoanalyse, die weniger die Triebe als die familiären und sozialen Gegebenheiten des Menschen betont.","c":false,"fb":"Jung begründete die Analytische Psychologie; die Neopsychoanalyse spaltete sich durch Forschende wie Karen Horney und Erich Fromm von der klassischen Psychoanalyse ab."}],"concept":{"title":"Tiefenpsychologische Richtungen neben Freud","points":["<b>Adler (1870–1937)</b>: Individualpsychologie; Neurosen als Überkompensation individueller Unzulänglichkeiten.","<b>Adlers Motivationsannahme</b>: Streben nach Macht, Überlegenheit und Anerkennung; dieses Geltungsstreben wird durch das Gemeinschaftsgefühl kompensiert, das aus der Geborgenheit in der Mutterbeziehung und später in der schulischen Sozialisation entsteht.","<b>Jung (1875–1961)</b>: Analytische Psychologie; neben unbewussten Aspekten auch die gesunde, schöpferische Entfaltung des Menschen.","<b>Jungs Kernbegriffe</b>: Libido als allgemeine Lebensenergie, kollektives Unbewusstes als Reservoir der Erfahrungen der Spezies Mensch, Archetypus (z. B. Magna Mater – schützende und zugleich vereinnahmende Mutter).","<b>Neopsychoanalyse</b>: Horney und Fromm; weniger Triebstudium, mehr Umgebung, familiäre und soziale Gegebenheiten sowie Zugehörigkeitssehnsucht als Quelle neurotischer Entwicklungen.","<b>Merkhilfe</b>: Adler → Geltungsstreben und Gemeinschaftsgefühl; Jung → kollektives Unbewusstes und Archetypen; Anna Freud zählt ebenfalls zu den berühmtesten Vertreter:innen der Tiefenpsychologie."]}},{"id":"k2-ce09b14a8d","kap":2,"sec":"2.1.2 Römische Antike und Mittelalter","stem":"Welche Aussagen zu Augustinus und Thomas von Aquin treffen zu?","opts":[{"t":"Augustinus verortete die Seele nicht in einem einzelnen Körperteil, sondern sah sie im gesamten Körper gegenwärtig.","c":true,"fb":"Körper und Seele waren für ihn zwei gegensätzliche Substanzen, die von Natur aus zusammengehören."},{"t":"Augustinus hielt ein Einwirken des Körpers auf die Seele für unmöglich, sah aber im Nervensystem den Vermittler für die Wirksamkeit der Seele.","c":true,"fb":"Reize der Außenwelt rufen körperliche Reaktionen hervor, die wiederum die Aufmerksamkeit der Seele erregen."},{"t":"Nach Thomas von Aquin ist die Geistseele ebenso wie die vegetative und die sensitive Seele an den Körper als tragende Materie gebunden und vergeht mit dessen Tod.","c":false,"fb":"Gerade das unterscheidet die Geistseele: Als von Gott Geschaffenes ist sie nicht an die Materie gebunden und kann nach dem Tod des Körpers nicht vergehen."},{"t":"Thomas von Aquin war ein Hauptvertreter der Scholastik und verband aristotelisches Denken mit der christlichen Lehre.","c":true,"fb":"Er kommentierte im 13. Jahrhundert die Schriften der alten Griechen und schuf eine Schnittstelle zwischen Glauben und Wissenschaft."}],"concept":{"title":"Von der römischen Antike zur Scholastik","points":["<b>Rom</b>: keine eigenen Schulen; Gelehrte trugen die griechischen Lehren weiter. Mit dem Christentum trat das Ziel frommen Lebens an die Stelle des Erkenntnisstrebens.","<b>Augustinus (354–430 n. Chr.)</b>: Kirchenvater und Philosoph; höchste Erfahrungsform ist der Glaube, Einigkeit von Körper, Geist und Seele als Natur des Menschen.","<b>Augustinus’ Zweiteilung</b>: Körper als Materie = „äußerer Mensch“, Seele als Immaterielles = „innerer Mensch“; die Seele steht wertmäßig über dem Körper, weil sie dem Göttlichen geöffnet ist.","<b>Thomas von Aquin (1225–1274)</b>: Hauptvertreter der Scholastik – Vereinigung aristotelischen Denkens mit christlicher Lehre.","<b>Aquins drei Arten von Seelen</b>: Vegetation (unbeweglich, nicht schmerzempfindlich), Tiere (sensitiv, beweglich, schmerzempfindlich), Menschen (intellektiv, mit Denkvermögen, strukturiert Sinneswahrnehmungen).","<b>Mittelalterliche Universitäten</b>: Forschung zunächst in Klöster- und Stiftsschulen; an den Universitäten standen Medizin, Rechtswissenschaft und Theologie neben der übergeordneten Philosophie (Metaphysik, Natur- und Moralphilosophie)."]}},{"id":"k2-9d74b3379e","kap":2,"sec":"2.4.5 Kognitive Wende","stem":"Welche Aussagen zu den Anfängen der Kognitiven Wende treffen zu?","opts":[{"t":"Das 1948 von der Hixon-Stiftung finanzierte Symposium zum Thema „Cerebral mechanisms in behavior“ gilt vielfach als Beginn der Kognitiven Wende.","c":true,"fb":"Dort begann die interdisziplinäre Zusammenarbeit von Psychologie, Informationstheorie, Linguistik, Philosophie, Neurowissenschaften und Kybernetik."},{"t":"George Miller zeigte, dass die Zahl der Einheiten, die Menschen im Kurzzeitgedächtnis behalten können, auf etwa fünf plus/minus zwei beschränkt ist.","c":false,"fb":"Die Grenze liegt bei maximal sieben Elementen plus/minus zwei (7±2)."},{"t":"Allen Newell und Herbert Simon stellten am MIT ein Modell der universellen Grammatik vor.","c":false,"fb":"Die universelle, nicht erlernte Grammatik stammt von Noam Chomsky; Newell und Simon beschrieben die Logiktheorie-Maschine, die logische Theoreme beweisen konnte."},{"t":"Mit Beginn der 1970er Jahre avancierte die Kognitionspsychologie zur dominierenden Richtung innerhalb der Psychologie.","c":true,"fb":"Die Kognitive Wende erfasste neben der Allgemeinen Psychologie sämtliche Teilgebiete bis hin zu den Anwendungsbereichen."}],"concept":{"title":"Die Kognitive Wende","points":["<b>1948, Hixon-Symposium</b>: „Cerebral mechanisms in behavior“ – Beginn der interdisziplinären Zusammenarbeit (Gardner, 1989).","<b>11. September 1956</b>: Symposium on Information Theory am MIT, das als Geburtsdatum der Kognitionswissenschaft gilt.","<b>Die drei Beiträge</b>: Psychologie – George Miller (7±2 Elemente im Kurzzeitgedächtnis); Linguistik – Noam Chomsky (universelle, nicht erlernte Grammatik); Computerwissenschaft – Newell und Simon (Logiktheorie-Maschine).","<b>Anlass</b>: Der Behaviorismus konnte weder in physiologischer noch in psychologischer Form die eigenen Ansprüche erfüllen; die ausgeklammerte „Black Box“ wurde in Frage gestellt.","<b>Kognitivismus</b>: nicht direkt beobachtbare höhere Funktionen – Aufmerksamkeit, Wahrnehmen, Denken, Entscheiden, Erinnern – vor dem Hintergrund der Informationsverarbeitung.","<b>Menschenbild</b>: statt eines passiv reagierenden ein planendes, selbsttätig handelndes Individuum; Verhalten resultiert auch aus internen Handlungszielen. Ab den 1970er Jahren dominierende Richtung."]}},{"id":"k2-fbb9d12690","kap":2,"sec":"2.1.3 Rationalismus und Empirismus","stem":"Welche Aussagen zum Empirismus treffen zu?","opts":[{"t":"Als zwei Quellen der Erkenntnis gelten die Sensation – die Wahrnehmung äußerer Reize über die Sinne – und die Reflexion, also Bewusstseinsvorgänge und die Beobachtung des eigenen Denkens.","c":true,"fb":"Beide Quellen bleiben an Erfahrung gebunden; die Reflexion richtet sich auf die Tätigkeiten des Geistes selbst."},{"t":"Der Empirismus geht davon aus, dass der menschliche Geist bei der Geburt ein unbeschriebenes Blatt ist.","c":true,"fb":"Erkenntnis ist demnach nur durch sinnliche Erfahrung der stofflichen Welt möglich."},{"t":"John Locke beschrieb den Erkenntnisprozess in vier Stufen: partikuläre Ideen aus sinnlicher Erfahrung, Abstraktion, Verbalisierung und schließlich Diskurs über unterschiedliche Erfahrungen.","c":true,"fb":"Locke (1632–1704) verfasste auch die erste empiristische Erkenntnistheorie (Schönpflug, 2013)."},{"t":"David Hume sah die Assoziation als alleiniges Prinzip der geistigen Ordnung und nannte als Assoziationsprinzipien die Ähnlichkeit und die Kontiguität.","c":true,"fb":"Diese Überlegungen bildeten den Beginn der Assoziationstheorie."}],"concept":{"title":"Der Empirismus","points":["<b>Kernhaltung</b>: Zweifel an der Existenz einer objektiven Welt; der Ursprung des Wissens liegt allein in dem, was wahrgenommen werden kann.","<b>Erkenntniszugang</b>: Studium subjektiver Eindrücke durch (Sinnes-)Erfahrung – über Beobachtung oder Experiment (Liesen, 2010) –, nicht allein durch Vernunft.","<b>Zwei Erkenntnisquellen</b>: Sensation (äußere Reize über die Sinne) und Reflexion (Bewusstseinsvorgänge, Tätigkeiten des Geistes, Beobachtung des eigenen Denkens).","<b>Locke (1632–1704)</b>: erste empiristische Erkenntnistheorie; vier Stufen – partikuläre Ideen, Abstraktion, Verbalisierung, Diskurs.","<b>Hume (1711–1776)</b>: Assoziation als alleiniges Prinzip der geistigen Ordnung; Prinzipien der Ähnlichkeit und der Kontiguität; Beginn der Assoziationstheorie.","<b>Abgrenzung</b>: Der Rationalismus hält Empfindungen für keine vertrauenswürdige Quelle und lässt Erkenntnis nur über den Verstand zu – der Empirismus dreht dieses Verhältnis um."]}},{"id":"k2-e1ba77b0ca","kap":2,"sec":"2.2.3 Naturwissenschaftliche Neubegründung","stem":"Welche Zuordnung eines Schülers Wilhelm Wundts zu seinem Wirkungsfeld ist korrekt?","opts":[{"t":"James McKeen Cattell: Begründer der Pädagogischen Psychologie.","c":false,"fb":"Cattell war Mitbegründer der Testpsychologie; die Pädagogische Psychologie begründete Ernst Meumann."},{"t":"Hugo Münsterberg: Gründer der ersten psychologischen Klinik in den USA.","c":false,"fb":"Diese Klinik gründete Lightner Witmer; Münsterberg war zentrale Figur der Arbeits- und Wirtschaftspsychologie."},{"t":"Ernst Meumann: zentrale Figur der Arbeits- und Wirtschaftspsychologie.","c":false,"fb":"Das trifft auf Hugo Münsterberg zu; Meumann begründete die Pädagogische Psychologie."},{"t":"Oswald Külpe: Begründer der Würzburger Schule der Denkpsychologie.","c":true,"fb":"Külpe (1862–1915) verlagerte die Fragestellung auf den Ablauf von Denkvorgängen."}],"concept":{"title":"Schüler Wilhelm Wundts und ihre Arbeitsfelder","points":["<b>James McKeen Cattell</b>: Mitbegründer der Testpsychologie.","<b>Oswald Külpe</b>: Begründer der Würzburger Schule der Denkpsychologie.","<b>Ernst Meumann</b>: Begründer der Pädagogischen Psychologie.","<b>Hugo Münsterberg</b>: zentrale Figur in der Arbeits- und Wirtschaftspsychologie.","<b>Lightner Witmer</b>: Gründer der ersten psychologischen Klinik in den USA, in der auch Psycholog:innen und nicht nur medizinisches Fachpersonal arbeiten durften; Leitfigur der Klinischen Psychologie.","<b>Merkhilfe</b>: Mit der Einrichtung des Leipziger Labors ging die Doktorandenausbildung einher – mehrere Schüler gründeten selbst Labore rund um den Globus."]}},{"id":"k2-30a75d3224","kap":2,"sec":"2.4.2 Gestaltpsychologie","stem":"Welche Aussagen zur Gestaltpsychologie und zu den Gestaltgesetzen treffen zu?","opts":[{"t":"Das Gesetz der Nähe besagt, dass ähnlichere Formen als zusammengehörig wahrgenommen werden.","c":false,"fb":"Das ist das Gesetz der Ähnlichkeit; beim Gesetz der Nähe werden Linien aufgrund ihrer räumlichen Nähe als zusammengehörig wahrgenommen."},{"t":"Die „Ordnungsprinzipien“, nach denen sich Einzelteile zu einem Ganzen fügen, nannte Wertheimer Gestaltfaktoren; heute sind sie als Gestaltgesetze bekannt.","c":true,"fb":"Für Wertheimer waren sie ein sich selbst erfüllendes Naturprinzip, weil ihre Anwendung keine bewussten Denkprozesse erfordert."},{"t":"Nach dem Gesetz der guten Fortsetzung werden zwei sich kreuzende gepunktete Linien als durchgehende Linien wahrgenommen und nicht als einzelne Punkte oder geknickte Linien.","c":true,"fb":"Die Wahrnehmung folgt dem einfachsten durchgehenden Verlauf statt der objektiv ebenfalls möglichen Knickdeutung."},{"t":"Ihren Höhepunkt erreichte die Gestaltpsychologie erst nach dem Aufkommen der Kognitiven Psychologie in den 1950er und 1960er Jahren.","c":false,"fb":"Der Höhepunkt lag in den 1920er und 1930er Jahren – und damit noch vor dem Aufkommen der Kognitiven Psychologie."}],"concept":{"title":"Die Gestaltpsychologie (Frankfurter bzw. Berliner Schule)","points":["<b>Zeitliche Einordnung</b>: Höhepunkt in den 1920er und 1930er Jahren, noch vor dem Aufkommen der Kognitiven Psychologie.","<b>Grundannahme</b>: Die mentale Repräsentation von Objekten erfolgt strukturiert – Objekte werden tendenziell anders wahrgenommen, als sie in der Wirklichkeit repräsentiert sind.","<b>Wertheimer (1880–1943)</b>: Das Ganze unterscheidet sich qualitativ von der Summe seiner Teile; korrekter als „mehr als“ ist die Formel „Das Ganze ist etwas Anderes als die Summe seiner Teile“, weil die Gesamtheit zusätzliche Eigenschaften hervorbringt.","<b>Die vier dargestellten Gestaltgesetze</b>: Nähe (räumliche Nähe), Ähnlichkeit (ähnlichere Formen), gute Fortsetzung (durchgehende statt geknickter Linien), Geschlossenheit (zwei überlappende geschlossene Kreise).","<b>Weitere Vertreter der Berliner Schule</b>: Wolfgang Köhler (1887–1967), Kurt Koffka (1886–1941), Kurt Lewin (1890–1947); geforscht wurde auch zu Gedächtnis, Problemlösen, Motivation und Lernen.","<b>Institutionelle Schwäche</b>: In Deutschland stand der Wundtsche Elementarismus als Gegenspieler, in den USA der Behaviorismus – einflussreiche Lehrstühle blieben aus."]}},{"id":"k2-29148f3d79","kap":2,"sec":"2.1.1 Ursprünge des Seelenbegriffs","stem":"Welche Aussagen zur Seelenauffassung der Orphiker und Platons treffen zu?","opts":[{"t":"Die Orphiker sahen den Körper als Gefängnis der Seele und ordneten ihn dem als unvollkommen geltenden Diesseits zu.","c":true,"fb":"Die Seele gehörte demgegenüber zum Jenseits, das für Vollkommenheit, Güte und Glück stand."},{"t":"Platons begehrende Seele ist im Kopf angesiedelt und hat die Aufgabe, Begierden und Temperament zu kontrollieren.","c":false,"fb":"Die begehrende bzw. versorgende Seele sitzt im Unterleib; die Kontrollaufgabe kommt der denkenden bzw. vernünftigen Seele im Kopf zu."},{"t":"Nach orphischer Auffassung besitzt ein Körper genau eine Seele, während die Seele umgekehrt nicht zwingend einen Körper braucht.","c":true,"fb":"Beides gehört zu den vier orphischen Annahmen über das Schicksal der Seele, ebenso ihre Unsterblichkeit und ihre Wanderung als Kreislauf von Leben und Tod."},{"t":"Platons Lehre wird als dualistisch und idealistisch bezeichnet; der Körper gilt darin als trügerisch, unvollkommen und der Seele untergeordnet.","c":true,"fb":"Die unsterbliche Seele haucht dem Körper – der „Wohnstatt der Seele“ – Leben ein und besteht unabhängig vom Körperlichen."}],"concept":{"title":"Die Seele bei den Orphikern und bei Platon","points":["<b>Orphiker (ca. 600 v. Chr., Griechenland)</b>: Der Mensch besteht aus stofflichem Körper und unstofflicher Seele, beide voneinander getrennt; stirbt der Körper, kann die Seele weiterleben.","<b>Die vier orphischen Annahmen</b>: Ein Körper besitzt genau eine Seele; die Seele ist unsterblich; ihre Wanderung von Körper zu Körper ist ein Kreislauf von Leben und Tod; eine Seele braucht nicht zwingend einen Körper.","<b>Wertung</b>: Der Körper ist Gefängnis der Seele; die Seele kann sich im Schuldfall (Unkeuschheit, Geiz) durch Sühne befreien, der Körper nicht aus seiner Unvollkommenheit.","<b>Doppelter Dualismus</b>: Körper/Seele und Diesseits (unvollkommen, schlecht) / Jenseits (Vollkommenheit, Güte, Glück – Heimat der Seele).","<b>Platon (427–347 v. Chr.)</b>: dualistisch und idealistisch; drei Teilseelen – begehrende/versorgende Seele im Unterleib (Essen, Trinken, Fortpflanzung), zielstrebige/entschlossene Seele in der Brust (Emotionen), denkende/vernünftige Seele im Kopf.","<b>Funktion der Vernunftseele</b>: Sie kontrolliert Begierden und Temperament und führt die drei Teile zu einer vollständigen Seele zusammen."]}},{"id":"k2-20c3175edf","kap":2,"sec":"2.2.1 Vernunft als Schlüssel zur Wissenschaft","stem":"Welche Aussage zu Immanuel Kants Sicht auf die Psychologie trifft zu?","opts":[{"t":"Kant lehnte den empiristischen Grundsatz ab, dass Erkenntnis durch sinnliche Erfahrung entsteht, und führte Erkenntnis allein auf das reine Denken zurück.","c":false,"fb":"Er griff diesen Grundsatz gerade auf und ergänzte ihn: Sinneseindrücke müssen mit den Vorstellungen des Verstandes verknüpft werden."},{"t":"Weil er die Gegenstände der Psychologie für nicht exakt darstellbar bzw. „mathematisierbar“ hielt, sah Kant sie lediglich als beschreibende und nicht als exakte Wissenschaft an.","c":true,"fb":"Ohne Messung und mathematische Formulierung war für ihn keine exakte Wissenschaft möglich (vgl. Fahrenberg, 2022)."},{"t":"Kants Annahme wurde erst rund ein Jahrhundert später widerlegt, als Fechner die Assoziationstheorie mathematisch darstellen konnte.","c":false,"fb":"Widerlegt wurde sie bereits eine Generation später, und zwar von Herbart, der die Assoziationstheorie mathematisch darstellte."},{"t":"Nach Kant kommt der empirischen Psychologie unter den Wissenschaften ein besonders hoher Stellenwert zu.","c":false,"fb":"Er sprach ihr im Gegenteil einen geringeren Stellenwert unter den Wissenschaften zu (Kant, 1790, S. 47)."}],"concept":{"title":"Kant und die Wissenschaftlichkeit der Psychologie","points":["<b>Kant (1724–1804)</b>: greift den empiristischen Grundsatz auf, dass Erkenntnis durch sinnliche Erfahrung entsteht, und ergänzt ihn um die Verbindung zum Denken.","<b>Kernargument</b>: Reine empirische Beobachtung enthält nicht alle Informationen – Sinneseindrücke müssen mit den Vorstellungen des Verstandes verknüpft werden.","<b>Gütekriterien</b>: Er betont Eindeutigkeit, Gewissheit und Beständigkeit wissenschaftlicher Ergebnisse.","<b>Das Problem der Psychologie</b>: Gedanken, Stimmungen etc. seien nicht exakt darstellbar bzw. „mathematisierbar“ – ohne Messung keine exakte Wissenschaft, daher nur beschreibende Wissenschaft mit geringerem Stellenwert.","<b>Widerlegung (Fußnote 3)</b>: Bereits eine Generation später stellte Herbart die Assoziationstheorie mathematisch dar.","<b>Einordnung</b>: Nach der Aufklärung begann sich die Psychologie als eigenständige Wissenschaft zu etablieren, auch weil das Interesse an der Lehre über menschliches Verhalten wuchs."]}},{"id":"k2-8d7a3074c2","kap":2,"sec":"2.2.3 Naturwissenschaftliche Neubegründung","stem":"Welche Aussagen zu Strukturalismus und Funktionalismus treffen zu?","opts":[{"t":"Der Funktionalismus betrachtet menschliche Äußerungen und Verhaltensweisen als isolierte Einzelerscheinungen, deren Struktur unabhängig voneinander bestimmt wird.","c":false,"fb":"Die Betrachtung auf Basis eines systematischen Zusammenhangs statt isolierter Einzelerscheinungen gehört zum Strukturalismus; der Funktionalismus fragt nach der Funktion des Bewusstseins bzw. innerer mentaler Zustände."},{"t":"William James unterteilte das „Selbst“ in Bewusstsein („I“) und reflektierte Identität („Me“) und gilt als wichtiger Vertreter des Strukturalismus.","c":false,"fb":"Die Unterteilung stimmt, die Schulzuordnung nicht: James gilt als wichtiger Vertreter des Funktionalismus."},{"t":"Im Strukturalismus setzt sich die Struktur des Geistes aus grundlegenden Elementen zusammen, die miteinander in Verbindung stehen.","c":true,"fb":"Leitgedanke ist zudem, dass ein Mensch über subjektive Erfahrungen verfügt (Kaminski, 2022)."},{"t":"Wundt gilt gemeinsam mit seinem Schüler Edward Titchener als Mitbegründer des Strukturalismus.","c":true,"fb":"Sein neuartiges, systematisches Vorgehen in der experimentellen Psychologie machte ihn zum Mitbegründer dieser ersten psychologischen Schule."}],"concept":{"title":"Strukturalismus und Funktionalismus (Infobox 2.4)","points":["<b>Strukturalismus</b>: Der Mensch verfügt über subjektive Erfahrungen; die Struktur des Geistes besteht aus grundlegenden, miteinander verbundenen Elementen.","<b>Betrachtungsweise</b>: Äußerungen und Verhaltensweisen werden nicht isoliert, sondern auf Basis eines systematischen Zusammenhangs betrachtet, der ihre Struktur bestimmt (Kaminski, 2022).","<b>Vertreter</b>: Wundt und sein Schüler Edward Titchener als Mitbegründer der ersten psychologischen Schule.","<b>Funktionalismus</b>: Gegenströmung; im Vordergrund steht die Erklärung der Funktion des Bewusstseins bzw. innerer mentaler Zustände (vgl. Brüntrup, 2012).","<b>Menschenbild des Funktionalismus</b>: Die Psyche als funktionalistisches System, das im Dienst von Bedürfnissen steht und einer Zweckbestimmung folgt.","<b>William James (1842–1910)</b>: Begründer der amerikanischen Psychologie als Wissenschaft, Theorie des „Selbst“ mit „I“ und „Me“, wichtiger Vertreter des Funktionalismus; seine Schülerin Mary Whiton Calkins begründete 1891 ein eigenes Labor am Wellesley College und wurde 1905 erste APA-Präsidentin."]}},{"id":"k2-711a7cf9e9","kap":2,"sec":"2.3 Psychologie im Nationalsozialismus","stem":"Welche Aussagen zur Psychologie während des Nationalsozialismus treffen zu?","opts":[{"t":"Insgesamt emigrierten circa 35 Prozent der Universitätslehrenden und immerhin 15 Prozent der Mitglieder der Deutschen Gesellschaft für Psychologie, größtenteils in die USA.","c":true,"fb":"Der so entstandene „Wissensverlust“ bedeutete beachtliche Einbußen für die damalige deutschsprachige Psychologie (Schönpflug, 2017)."},{"t":"Die Psychologische Diagnostik erlebte einen Aufschwung, weil im Bereich der Wehrmacht Leistungstests zur Auslese von Luftwaffensoldaten und potentiellen Führungskandidaten entwickelt werden mussten.","c":true,"fb":"Hier zeichnete sich erstmals die Anwendung von Psychologie in der Praxis ab; es kam auch zur erstmaligen Einführung einer Diplomprüfungsordnung."},{"t":"Wolfgang Köhler unterstützte die nationalsozialistischen Praktiken und blieb bis Kriegsende in Deutschland.","c":false,"fb":"Er widersetzte sich, protestierte gegen die Entlassung jüdischer Professoren und emigrierte 1935 in die USA, nachdem sein Institut angegriffen worden war."},{"t":"Sigmund Freud emigrierte 1938 nach London, nachdem seine Schriften bereits 1933 in Berlin verbrannt worden waren.","c":true,"fb":"Er zählt damit zu den prominentesten Emigrationen dieser Zeit."}],"concept":{"title":"Psychologie während des Nationalsozialismus","points":["<b>1933</b>: Rassendiskriminierung an deutschen und österreichischen Universitäten; jüdischen Studierenden wurde die Inskription verwehrt, die Doktoratsabschlüsse gingen zurück.","<b>Berufsbeamtentum</b>: Der Gesetzeserlass ermöglichte die Entlassung von Staatsbeamten jüdischer Abstammung und politisch unerwünschter Personen – betroffen waren u. a. Charlotte Bühler, Max Wertheimer und William Stern; Kurt Lewin legte bereits vorher sein Amt nieder.","<b>Verfolgung</b>: Inhaftierungen (z. B. Viktor Frankl, Heinrich Düker), Ermordungen (z. B. Otto Selz, Kurt Huber); Köhler emigrierte 1935, Freud 1938.","<b>Umbau der Ausbildung</b>: neue Diplomordnung – Paradigmenwechsel hin zu stärkerer Praxisorientierung und von akademischer zu staatlicher Steuerung; Prüfungsfächer wie Charakterologie bevorzugten nationalistische und antisemitische Ansichten.","<b>Inhaltliche Neuausrichtung</b>: Rassenpsychologie verortete geistig-seelische Unterschiede in der Rassenzugehörigkeit; neu war die Bewertung – nicht arische Gruppen wurden als „minderwertig“ klassifiziert (Geuter, 1985).","<b>Nach dem Krieg</b>: Auflösung der DGP durch die Besatzungsmächte; 1946 Gründung des Berufsverbandes deutscher Psychologen, ab 1947 Wiedergründung der DGP in den Besatzungszonen, 1993 Gründung der Österreichischen Gesellschaft für Psychologie (ÖGP)."]}},{"id":"k2-73584c0700","kap":2,"sec":"2.1.3 Rationalismus und Empirismus","stem":"Welche Aussagen zu Descartes und zum Leib-Seele-Problem treffen zu?","opts":[{"t":"Als res cogitans bezeichnete Descartes die körperliche, stoffliche Welt und als res extensa die dem Stofflichen enthobene geistige Welt.","c":false,"fb":"Die Begriffe sind vertauscht: Die res extensa ist die körperliche, stoffliche Welt, die res cogitans die geistige."},{"t":"Descartes vermutete die Verbindung der beiden Entitäten über die Zirbeldrüse, die durch ihre Neigung auf unterschiedliche Nervenenden drückt und so körperliche Reaktionen auslöst.","c":true,"fb":"An die Seele werden dabei von in der Zirbeldrüse lokalisierten Animalgeistern Bilder übermittelt."},{"t":"Der Monismus propagiert eine Einheit von Körper und Seele; zu seinen Hauptvertretern zählte der niederländische Philosoph Baruch de Spinoza.","c":true,"fb":"Er bildet die Gegenposition zum Dualismus, der Leib und Seele als voneinander unabhängige Einheiten versteht."},{"t":"Descartes sah die sinnliche Wahrnehmung als Weg zur Wahrheit an und betrachtete die intellektuelle Wahrnehmung lediglich als vorteilhafte natürliche Funktion des Körpers.","c":false,"fb":"Genau umgekehrt: Die intellektuelle Wahrnehmung galt ihm als Weg zur Wahrheit, die sinnliche primär als vorteilhafte natürliche Körperfunktion (vgl. Hatfield, 2014)."}],"concept":{"title":"Rationalismus, Descartes und das Leib-Seele-Problem (Infobox 2.2)","points":["<b>Rationalismus</b>: Neben der körperlichen Welt gibt es eine Welt des Verstandes; Empfindungen gelten nicht als vertrauenswürdige Quelle, Wissen ist nur über den Verstand zu erlangen. Zeitalter der Aufklärung: ca. 1650–1800.","<b>Descartes (1596–1650)</b>: „cogito ergo sum“ – einzig die Vernunft ist Basis und bewährte Methode des Erkenntnisgewinns.","<b>Zwei Welten</b>: res extensa = körperlich-stoffliche Welt, res cogitans = geistige, dem Stofflichen enthobene Welt.","<b>Zirbeldrüse</b>: vermuteter Mechanismus, der Körper über Gefühle mit dem Geist verbindet; ihre Neigung drückt auf Nervenenden und löst körperliche Reaktionen aus.","<b>Mechanistisches Menschenbild</b>: der Körper als „Maschine“; Trennung von intellektueller Wahrnehmung (Weg zur Wahrheit) und sinnlicher Wahrnehmung (vorteilhafte Körperfunktion).","<b>Leib-Seele-Problem</b>: Frage, wie sich mentale zu körperlichen Zuständen verhalten – Dualismus (unabhängige Einheiten, z. B. Descartes) versus Monismus (Einheit von Körper und Seele, z. B. Spinoza, 1632–1677)."]}},{"id":"k2-43ed0cfb1c","kap":2,"sec":"2.4.5 Kognitive Wende","stem":"Welche Aussagen zur Kybernetik und zum Konnektionismus treffen zu?","opts":[{"t":"Die Kybernetik – wörtlich Steuerungslehre – beschäftigt sich mit Zusammenhängen komplexer organischer und anorganischer Systeme und war ursprünglich in Technik und Biologie verortet.","c":true,"fb":"Sie wurde später auf andere Disziplinen wie die Psychologie ausgeweitet."},{"t":"Kybernetische Systeme verfügen über Ziele in Form von Soll-Werten, über Wissen in Form eines Speichers und verwenden zur Zielerreichung Pläne.","c":true,"fb":"In den Biowissenschaften setzte sich damit die Sicht durch, dass Lebensvorgänge Regelkreisvorgänge und keine einseitigen Reiz-Reaktions-Beziehungen sind."},{"t":"Das TOTE-Modell beschreibt, dass zunächst die Situation hinsichtlich des Ziels getestet wird und bei einer Ist-Soll-Wert-Diskrepanz eine Operation zur Zielerreichung eingeleitet wird.","c":true,"fb":"Anschließend wird der Erfolg erneut getestet und die Handlung bei Erfolg beendet – Test-Operation-Test-Exit."},{"t":"Ein konnektionistisches Modell besteht aus Einheiten (units) und Verbindungen (connections), die in mehreren Schichten angeordnet sind und eine parallele Verarbeitung ermöglichen.","c":true,"fb":"Die Einheiten sind analog zu Neuronen, die Verbindungen analog zu Synapsen und die Schichten analog zu Neuronenschichten im Cortex konzipiert."}],"concept":{"title":"Kybernetik, TOTE-Modell und Konnektionismus","points":["<b>Informationsverarbeitung</b>: Erforschung kognitiver Prozesse anhand computerisierter Modelle; zuzuordnen der Kybernetik (Steuerungslehre).","<b>Kybernetische Systeme</b>: verfügen über Ziele (Soll-Werte), Wissen (Speicher) und Pläne (Computerprogramme) zur Zielerreichung; Lebensvorgänge als Regelkreise statt einseitiger Reiz-Reaktions-Beziehungen.","<b>Broadbent (1926–1993)</b>: Menschen empfangen, senden, verarbeiten und speichern Reize; Faktoren wie Müdigkeit wirken auf die Verarbeitungskapazität, die Wahrnehmung wird von Filterprozessen (z. B. selektiver Aufmerksamkeit) beeinflusst.","<b>TOTE-Modell (George A. Miller, 1920–2012, und Kollegen)</b>: Test – Operation – Test – Exit; interne Ziele und externe Bedingungen werden in einem Modell vereint.","<b>Konnektionismus</b>: 1986 von Rumelhart und McClelland mit „Parallel distributed processing“ postuliert; kognitive Phänomene lassen sich durch wenige allgemeingültige Informationsverarbeitungsprinzipien erklären.","<b>Reichweite</b>: Konnektionistische Modelle (= neuronale Netzwerke) erklären u. a. Beeinträchtigungen bei Hirnschäden und sind in der kognitiven Neuropsychologie bedeutsam – ein Paradigmenwechsel blieb jedoch aus."]}},{"id":"k2-b165d28808","kap":2,"sec":"2.4.1 Würzburger Schule","stem":"Welche Aussage zur Würzburger Schule trifft zu?","opts":[{"t":"Ihr Begründer Oswald Külpe war ein Schüler von Hermann Ebbinghaus; seine zentrale Frage lautete, wie Wahrnehmungsschwellen zustande kommen.","c":false,"fb":"Külpe war ein Schüler Wundts, und seine zentrale Fragestellung lautete: „Wie laufen Denkvorgänge ab?“"},{"t":"Wundt begrüßte das Vorgehen der Würzburger, weil es seine Annahme bestätigte, dass auch höhere geistige Funktionen experimentell zugänglich sind.","c":false,"fb":"Wundt kritisierte die Methode als „Ausfrageexperimente“ bzw. Scheinexperimente, weil für ihn nur elementare psychische Prozesse im Experiment erfassbar waren."},{"t":"Die Würzburger dehnten die methodisch kontrollierte Introspektion – anders als Wundt – auf höhere geistige Funktionen aus.","c":true,"fb":"Den Proband:innen wurden Denksportaufgaben bzw. Redensarten vorgelegt, deren Lösungsweg sie anschließend beschreiben sollten."},{"t":"Die Würzburger Schule gilt als direkte Vorläuferin des Behaviorismus, dessen Methodik sie maßgeblich prägte.","c":false,"fb":"Sie prägte die Gestaltpsychologie und kann neben dieser als Wegbereiterin der Kognitiven Psychologie gesehen werden (Lück & Guski-Leinwand, 2014)."}],"concept":{"title":"Die Würzburger Schule","points":["<b>Begründer</b>: Oswald Külpe (1862–1915), ein Schüler Wundts.","<b>Leitfrage</b>: „Wie laufen Denkvorgänge ab?“ – der Fokus liegt auf dem Denken, nicht auf elementaren Empfindungen.","<b>Methode</b>: methodisch kontrollierte Introspektion, im Unterschied zu Wundt auf höhere geistige Funktionen ausgedehnt.","<b>Vorgehen</b>: Denksportaufgaben bzw. Redensarten zur Interpretation; anschließend beschreiben die Proband:innen den eingeschlagenen Gedankenweg.","<b>Wundts Kritik</b>: „Ausfrageexperimente“ bzw. Scheinexperimente – für ihn waren nur elementare psychische Prozesse (z. B. einfache Reaktionen auf akustische Stimuli) experimentell zugänglich.","<b>Wirkung</b>: prägender Einfluss auf die Gestaltpsychologie; gemeinsam mit dieser Wegbereiterin der Kognitiven Psychologie."]}},{"id":"k2-254d6fb6f1","kap":2,"sec":"2.2.2 Entwicklungen im 18. und 19. Jahrhundert","stem":"Welche Aussagen zum Darwinismus und seiner Bedeutung für die Psychologie treffen zu?","opts":[{"t":"Nach Darwin ergeben sich neue Genkombinationen ausschließlich aus spontanen Mutationen, während die Paarung von Individuen dafür ohne Bedeutung ist.","c":false,"fb":"Beides wirkt zusammen: Die Gene sind spontanen Veränderungen (Mutationen) unterworfen, und neue Genkombinationen ergeben sich durch die Paarung von Individuen."},{"t":"Bis ins 18. Jahrhundert galten Arten als unveränderlich; die später verbreiteten Abstammungstheorien stießen vor allem deshalb auf Widerstand, weil sie der biblischen Schöpfungsgeschichte widersprachen.","c":true,"fb":"Erst danach setzten sich Theorien durch, die höhere Gattungen als Abkömmlinge niederer Gattungen ansahen."},{"t":"Der Ausdruck „Survival of the Fittest“ meint das Überleben jener, die am besten angepasst sind – und nicht das der Stärksten.","c":true,"fb":"Diese Präzisierung steht ausdrücklich in Fußnote 4 des Kapitels und gehört damit zum prüfungsrelevanten Stoff."},{"t":"Die Annahme einer gemeinsamen Komponente von Tier und Mensch führte zu einer Aufwertung des Mensch-Tier-Vergleichs und legte den Grund für die Vergleichende Psychologie.","c":true,"fb":"Damit einher ging auch die Etablierung des Tierversuchs in der Psychologie (Schönpflug, 2013)."}],"concept":{"title":"Der Darwinismus und seine Folgen für die Psychologie","points":["<b>Ausgangslage</b>: Bis ins 18. Jahrhundert galten Arten als unveränderlich; Abstammungstheorien stießen auf Widerstand, weil sie der biblischen Schöpfungsgeschichte widersprachen.","<b>Charles Darwin (1809–1882)</b>: Gene unterliegen spontanen Veränderungen (Mutationen); neue Genkombinationen entstehen durch die Paarung von Individuen.","<b>Variation und Anpassung</b>: Erscheinungen und Fähigkeiten variieren und sind unterschiedlich gut an die Umgebung angepasst.","<b>Selektion</b>: Bessere Anpassung bedeutet mehr Nahrung, Schutz und bessere Chancen auf Nachwuchs; unzureichend angepasste Arten sterben aus.","<b>Fußnote 4</b>: „Survival of the Fittest“ meint die am besten Angepassten, nicht die Stärksten.","<b>Folge für die Psychologie</b>: gemeinsame Komponente zwischen Tier und Mensch → Aufwertung des Mensch-Tier-Vergleichs, Grundlegung der Vergleichenden Psychologie und des Tierversuchs."]}},{"id":"k2-b3999ab789","kap":2,"sec":"2.4.4 Tiefenpsychologie","stem":"Welche Aussagen zu Sigmund Freuds Konzepten treffen zu?","opts":[{"t":"Das Es ist unbewusst, triebgesteuert und folgt dem Lustprinzip, während das Über-Ich als soziales Regulativ internalisierte Normen vertritt.","c":true,"fb":"Das Ich vermittelt zwischen diesen beiden Instanzen, die miteinander in Konflikt stehen."},{"t":"Das Ich ist die unbewusste, triebgesteuerte Instanz, während das Es zwischen Über-Ich und Außenwelt vermittelt.","c":false,"fb":"Die Rollen sind vertauscht: Das Es ist die unbewusste, triebgesteuerte Instanz, das Ich der Vermittler zwischen Es und Über-Ich."},{"t":"Freud nahm an, dass die Abwehrfähigkeiten des Ichs nachts stärker ausgeprägt sind, weshalb verdrängte Inhalte vor allem tagsüber ins Bewusstsein gelangen.","c":false,"fb":"Er ging vom Gegenteil aus: Die Ich-induzierten Abwehrfähigkeiten sind nachts geringer, weshalb sich verdrängte Inhalte in Form von Träumen ihren Weg ins Bewusstsein bahnen."},{"t":"Der Ödipuskomplex beschreibt die Rivalität gegenüber dem gleichgeschlechtlichen Elternteil aufgrund der Liebe zum gegengeschlechtlichen Elternteil.","c":true,"fb":"Der Begriff gehört zu den zahlreichen Konzepten, die Freud im Umfeld von Triebbefriedigung und Lustprinzip prägte."}],"concept":{"title":"Freud und die Psychoanalyse","points":["<b>Tiefenpsychologie</b>: Sammelbegriff für psychologische und psychotherapeutische Konzepte, in denen unbewusste seelische Vorgänge den zentralen Aspekt für Erleben und Verhalten bilden.","<b>Freud (1856–1939)</b>: Wiener Arzt; begründete mit der Psychoanalyse eine eigene Schule, in der emotionale Reaktionen auf Kindheitserfahrungen und unbewusste Denkprozesse zentral sind.","<b>Grundannahmen</b>: Bewusstes und Unbewusstes als zwei getrennte Instanzen; Ängste entstehen durch das Leben in der Zivilisation, viele psychische Probleme gehen auf die Verdrängung von Ängsten zurück.","<b>Psychodynamische Kräfte</b>: Triebbefriedigung und Lustprinzip, die aufgrund gesellschaftlicher Konventionen in der sozialen Gruppe nicht ausgelebt werden dürfen; Ödipuskomplex als Rivalität gegenüber dem gleichgeschlechtlichen Elternteil.","<b>Instanzenmodell</b>: Es (unbewusst, triebgesteuert, Lustprinzip), Über-Ich (soziales Regulativ, internalisierte Normen), Ich (Vermittler zwischen beiden).","<b>Abwehr und Traum</b>: Das Ich bedient sich Abwehrmechanismen wie der Verdrängung; nachts sind die Abwehrfähigkeiten geringer, sodass verdrängte Inhalte als Träume ins Bewusstsein gelangen."]}},{"id":"k2-92f43a153a","kap":2,"sec":"2.2.2 Entwicklungen im 18. und 19. Jahrhundert","stem":"Welche Aussage zur Ausdruckspsychologie trifft zu?","opts":[{"t":"Franz Joseph Gall ging davon aus, dass sich aufgrund der Form und Größe des Schädels die Ausprägung der darunterliegenden Hirnareale abschätzen lasse.","c":true,"fb":"Er brachte die Hirnareale zudem mit bestimmten Charaktereigenschaften und Fähigkeiten in Verbindung."},{"t":"Johann Caspar Lavater begründete die Phrenologie und erklärte über die Schädelform auch die Neigung zu kriminellem und pathologischem Verhalten.","c":false,"fb":"Lavater war Hauptvertreter der Physiognomik; die Schädelausprägungen und die Erklärung kriminellen Verhaltens gehören zu Galls Phrenologie."},{"t":"Die Physiognomik beruht auf der Annahme, dass sich Körperliches im Seelischen ausdrückt, und schließt daher vom Charakter auf die Gesichtsform.","c":false,"fb":"Die Richtung ist umgekehrt: Seelisches drückt sich im Körperlichen aus, und aus den Ausdrucksmerkmalen wird auf die Charaktereigenschaften geschlossen."},{"t":"Galls Annahmen bestätigten sich später dadurch, dass sich spezifischen Cortexarealen konkrete Aufgaben zuordnen ließen.","c":false,"fb":"Seine Annahmen stellten sich als falsch heraus; die Zuordnung konkreter Aufgaben zu Cortexarealen (z. B. Broca-Areal) wurde unabhängig davon gezeigt."}],"concept":{"title":"Ausdruckspsychologie: Physiognomik und Phrenologie","points":["<b>Ausdruckspsychologie</b>: erste – mittlerweile veraltete – Lehre über die körperliche Erscheinung und ihre psychologische Bedeutung.","<b>Physiognomik</b>: schließt aus den Ausdrucksmerkmalen von Gesicht und Körper auf Charaktereigenschaften; Grundannahme ist, dass sich Seelisches im Körperlichen ausdrückt.","<b>Lavater (1741–1801)</b>: Hauptvertreter der Physiognomik, Regeln zur Diagnose von Charakterzügen – hohe Stirn als Zeichen von Intelligenz, Nasenform im Zusammenhang mit dem Drang zur Selbstverwirklichung (Physiognomische Fragmente, 1789).","<b>Phrenologie</b>: schließt von Form und Größe des Schädels auf die Ausprägung der darunterliegenden Hirnareale und diese wiederum auf Charakter und Fähigkeiten.","<b>Gall (1758–1828)</b>: erklärte über Schädelausprägungen auch die Neigung zu kriminellem und pathologischem Verhalten (Schönpflug, 2013).","<b>Bewertung</b>: Beide Annahmen erwiesen sich als falsch; unabhängig davon konnte später gezeigt werden, dass spezifischen Cortexarealen konkrete Aufgaben zugeordnet werden können (z. B. Broca-Areal)."]}},{"id":"k2-02267e29c3","kap":2,"sec":"2.2.1 Vernunft als Schlüssel zur Wissenschaft","stem":"Welche Aussagen zu den Rubriken des Magazins für Erfahrungsseelenkunde treffen zu?","opts":[{"t":"Die Seelenzeichenkunde behandelte Typisierungen und Charaktermerkmale und entspricht heute der Persönlichkeitspsychologie und der Psychologischen Diagnostik.","c":true,"fb":"Diskutiert wurden dort Charaktermerkmale und ihre Kategorisierung."},{"t":"Die Seelenkrankheitskunde beschrieb psychische Phänomene, etwa die Natur von Kindheitserinnerungen oder Träumen.","c":false,"fb":"Das war Gegenstand der Seelennaturkunde; die Seelenkrankheitskunde befasste sich mit normabweichendem Verhalten und entspricht heute der Psychopathologie."},{"t":"Die Seelenheilkunde beschäftigte sich mit der Heilung von Seelenkrankheiten und entspricht heute dem Gebiet der Psychotherapie.","c":true,"fb":"Sie ist damit die auf Behandlung ausgerichtete der vier Rubriken."},{"t":"Als vierte Rubrik behandelte die Seelenwanderungskunde normabweichendes Verhalten und gilt als Vorreiterin der Klinischen Psychologie.","c":false,"fb":"Eine Rubrik dieses Namens gab es nicht; normabweichendes Verhalten war Thema der Seelenkrankheitskunde, die vierte Rubrik hieß Seelennaturkunde."}],"concept":{"title":"Das Magazin für Erfahrungsseelenkunde (Karl Philipp Moritz, 1756–1793)","points":["<b>Bedeutung</b>: erste deutschsprachige psychologische Zeitschrift, Ende des 18. Jahrhunderts begründet; Vorreiter psychologischer Fachzeitschriften (Meier, 1997).","<b>Anspruch</b>: empirische Erkenntnisse über Seelengesundheit und -krankheit bündeln – die Gesellschaft mit Fakten statt mit „Anekdoten und Tratsch“ versorgen; erschien zehn Jahre lang regelmäßig.","<b>Seelennaturkunde</b>: Beschreibung psychischer Phänomene, etwa Überlegungen zu Kindheitserinnerungen oder Träumen.","<b>Seelenzeichenkunde</b>: Typisierungen, Charaktermerkmale und ihre Kategorisierung – heute Persönlichkeitspsychologie und Psychologische Diagnostik.","<b>Seelenkrankheitskunde</b>: normabweichendes Verhalten (z. B. harte Strafen, Misshandlungen, Mord) – Vorreiterin der Klinischen Psychologie, heute Psychopathologie.","<b>Seelenheilkunde</b>: Heilung von Seelenkrankheiten – heute Psychotherapie. Beiträge lieferten neben Moritz auch Ärzte, Philosophen, Pastoren und andere Gelehrte."]}},{"id":"k2-1d5ee4e4c6","kap":2,"sec":"2.2.3 Naturwissenschaftliche Neubegründung","stem":"Welche Aussagen zu Ebbinghaus, Dilthey und der Institutionalisierung der Psychologie treffen zu?","opts":[{"t":"Ebbinghaus entwickelte die Untersuchungsmethode mit sogenannten sinnlosen Silben, um Fehlerquellen aus Erfahrung, Wissen und Inhalten zu minimieren.","c":true,"fb":"So ließen sich Lern- und Vergessensprozesse exakter untersuchen; sein präzises methodisches Vorgehen war zur damaligen Zeit ein Novum."},{"t":"Diltheys beschreibende und zergliedernde Psychologie zielt auf das Verstehen des Seelischen aus Motivations- und Sinnzusammenhängen; ihre Methode ist die Hermeneutik.","c":true,"fb":"Sie steht damit gegen den „erklärenden“ Ansatz, der auf Kausalzusammenhänge zurückführt; die Hermeneutik bezeichnete ursprünglich die Entschlüsselung von Gleichnissen in der Theologie."},{"t":"Die American Psychological Association wurde 1892 durch Granville Stanley Hall gegründet, die Deutsche Gesellschaft für Psychologie folgte 1904.","c":true,"fb":"Beide Fachgesellschaften existieren bis heute; die APA ist zudem die weltweit einflussreichste Fachgesellschaft, unter anderem durch ihre Publikations- und Zitierstandards."},{"t":"In der Auseinandersetzung um 1894/1896 verteidigte Ebbinghaus Diltheys Ansatz und bezeichnete die experimentelle Psychologie als „seltsame Polemik“.","c":false,"fb":"Umgekehrt: Ebbinghaus verteidigte für die Wundtsche Schule den experimentellen Ansatz und tat Diltheys Ansichten als „seltsame Polemik“ ab."}],"concept":{"title":"Zeitgenossen Wundts, Gegenpositionen und Institutionalisierung","points":["<b>Ebbinghaus (1850–1909)</b>: Mitbegründer der experimentellen Psychologie, Gedächtnisforschung in Berlin; formulierte angelehnt an Fechners Experimente die logarithmischen Kurven des Lernens und Vergessens; Methode der sinnlosen Silben.","<b>Dilthey (1833–1911)</b>: „beschreibende und zergliedernde“ – später verstehende bzw. geisteswissenschaftliche – Psychologie; Ziel ist das Verstehen aus Motivations- und Sinnzusammenhängen statt Erklärung durch Kausalzusammenhänge.","<b>Hermeneutik</b>: ursprünglich Entschlüsselung von Gleichnissen in der Theologie; nach Schleiermacher die Kunst, die Rede eines anderen richtig zu verstehen.","<b>Der Streit</b>: Auf Diltheys Ideen (1894) antwortete Ebbinghaus 1896 mit „Über erklärende und beschreibende Psychologie“ und nannte dessen Ansichten „seltsame Polemik“ – die Spaltung prägte die deutschsprachige Psychologie der ersten Hälfte des 20. Jahrhunderts.","<b>Fachgesellschaften</b>: APA 1892 durch Granville Stanley Hall, Deutsche Gesellschaft für Psychologie 1904, weitere europäische Gesellschaften zwischen 1901 und 1910.","<b>Fachzeitschriften</b>: Philosophische Studien (ab 1881), American Journal of Psychology (1887), Zeitschrift für Psychologie (1890), Psychological Review (1894)."]}},{"id":"k2-e9ea667885","kap":2,"sec":"2 Paradigmen und Schulen","stem":"Was verstehen die Infoboxen des Kapitels unter einem Paradigma bzw. einer psychologischen Schule?","opts":[{"t":"Eine psychologische Schule zeichnet sich dadurch aus, dass ihre Angehörigen bewusst auf gemeinsame Lehrmeinungen verzichten, um Abgrenzungen zu anderen Richtungen zu vermeiden.","c":false,"fb":"Angehörige einer Schule teilen die jeweiligen Ansichten und Lehrmeinungen; das führt oft gerade zu starkem kollegialem Zusammenhang und klarer Abgrenzung."},{"t":"Ein psychologisches Paradigma beschreibt ein vorherrschendes Denkmuster, Grundannahmen sowie akzeptierte Experimentalmethoden.","c":true,"fb":"Es bildet damit die Grundlage der wissenschaftlichen Orientierung."},{"t":"Ein Paradigma steuert zwar die wissenschaftliche Orientierung, bleibt aber unabhängig davon, was als „wahr“ oder „gültig“ angesehen wird.","c":false,"fb":"Genau das steuert es: Das Paradigma lenkt die wissenschaftliche Realitätsauslegung – also das, was derzeit als „wahr“ oder „gültig“ gilt."},{"t":"Ein Paradigmenwechsel bezeichnet die Veränderung der aktuell vorherrschenden Auffassungen innerhalb der wissenschaftlichen Psychologie.","c":true,"fb":"Zu solchen Wechseln kam es im Verlauf der Geschichte immer wieder, etwa beim Übergang vom Behaviorismus zum Kognitivismus."}],"concept":{"title":"Paradigma und psychologische Schule (Infobox 2.1 und Infobox 2.5)","points":["<b>Paradigma</b>: vorherrschendes Denkmuster, Grundannahmen sowie akzeptierte Experimentalmethoden.","<b>Funktion</b>: Grundlage der wissenschaftlichen Orientierung; steuert die wissenschaftliche Realitätsauslegung – das, was derzeit als „wahr“ oder „gültig“ gilt.","<b>Paradigmenwechsel</b>: Veränderung der aktuell vorherrschenden Auffassungen innerhalb der wissenschaftlichen Psychologie.","<b>Psychologische Schule</b>: meist von einer bestimmten Person ausgehende Denkrichtung, die die Forschung in eine neue Richtung führt und eine neue wissenschaftliche Tradition schafft.","<b>Gruppendynamik</b>: Angehörige teilen Ansichten und Lehrmeinungen – daraus folgen starker kollegialer Zusammenhang und klare Abgrenzung zu anderen Schulen.","<b>Die fünf dargestellten Richtungen des 20. Jahrhunderts</b>: Würzburger Schule, Gestaltpsychologie, Behaviorismus, Tiefenpsychologie und Kognitionspsychologie."]}},{"id":"k2-c2369e0367","kap":2,"sec":"2.4.2 Gestaltpsychologie","stem":"Welche Aussage zu Kurt Lewins Feldtheorie trifft zu?","opts":[{"t":"Der Lebensraum ist nach Lewin die Gesamtheit jener Tatsachen, die das Verhalten über die gesamte Lebensspanne hinweg konstant halten.","c":false,"fb":"Der Lebensraum umfasst die Tatsachen, die das Verhalten in einem gegebenen Augenblick bestimmen – und er ist in stetiger Veränderung."},{"t":"Lewin postulierte, dass das Verhalten eine Funktion von der Person und ihrer Umwelt darstellt.","c":true,"fb":"Der situative Einfluss steht damit gleichberechtigt neben der Person; die Feldtheorie erklärt absichtliche und zielgerichtete Handlungen."},{"t":"Als Aufforderungscharakter bzw. Valenz bezeichnete Lewin Umwelttendenzen, deren Art und Stärke unabhängig von den momentanen Bedürfnissen der Person feststehen.","c":false,"fb":"Art und Stärke eines Aufforderungscharakters werden gerade durch die momentanen Bedürfnisse der Person bestimmt."},{"t":"Positive Regionen wie das Bestehen einer Prüfung sind nach Lewin gerade dann erreichbar, wenn negative Valenzen umgangen werden.","c":false,"fb":"Umgekehrt: Positive Regionen sind nur zu erreichen, wenn negative Valenzen – etwa der Verzicht auf Freizeitaktivitäten – durchschritten werden."}],"concept":{"title":"Kurt Lewins Feldtheorie","points":["<b>Anliegen</b>: Erklärung absichtlicher und zielgerichteter Handlungen eines Menschen.","<b>Kernpostulat</b>: Verhalten ist eine Funktion von der Person und ihrer Umwelt (situativer Einfluss).","<b>Soziale Feldtheorie</b>: Erweiterung der Gestalttheorie – die Persönlichkeit steht in einem Feld sozialer Kräfte und Spannungen.","<b>Lebensraum</b>: Gesamtheit aller Tatsachen, die das Verhalten eines Individuums in einem gegebenen Augenblick bestimmen; in stetiger Veränderung.","<b>Aufforderungscharakter bzw. Valenz</b>: fordernde Umwelttendenzen (manche Dinge reizen zum Essen, andere zum Klettern); Art und Stärke werden durch die momentanen Bedürfnisse bestimmt. Positive Regionen sind oft nur über negative Valenzen erreichbar.","<b>Anwendungsfelder</b>: handlungs- und motivationspsychologische Fragestellungen in der Pädagogik (Schulze, 2002), der klinischen Psychologie (Stemberger, 2016) und der Organisationsberatung (Bachmann & Möller, 2020)."]}},{"id":"k2-2099188739","kap":2,"sec":"2.2.3 Naturwissenschaftliche Neubegründung","stem":"Welche Aussagen zu den Wegbereitern der experimentellen Psychologie treffen zu?","opts":[{"t":"Herbart schrieb Vorstellungen einen „kraftähnlichen“ Charakter zu: Diese Kräfte können stärker und schwächer werden, sich mit anderen vereinen oder durch andere gehemmt werden.","c":true,"fb":"Auf dieser Grundlage entwickelte er mathematische Modelle über die Statik und Mechanik der Vorstellungen."},{"t":"Die innere Psychophysik untersucht die Beziehung zwischen Sinnesreiz und Sinnesempfindung, die äußere jene zwischen Körpererregung und Sinnesempfindung.","c":false,"fb":"Die Zuordnung ist vertauscht: Die äußere Psychophysik betrifft Sinnesreiz (Physik) und Empfindung, die innere die Körpererregung (Physiologie) und Empfindung."},{"t":"Helmholtz gilt als Pionier der Erforschung der Nervenleitgeschwindigkeit, die er durch physiologische Messungen auf apparativer Grundlage bestimmte.","c":true,"fb":"Er stützte sich dabei ausdrücklich nicht auf Schätzungen aus einem theoretischen Modell."},{"t":"Fechners Methode der ebenmerklichen Unterschiede wird heute als Herstellungsmethode bezeichnet.","c":false,"fb":"Dieses experimentelle Vorgehen wird heute als Grenzmethode bezeichnet (siehe auch Kapitel 5.2.2)."}],"concept":{"title":"Wegbereiter der experimentellen Psychologie: Herbart, Helmholtz, Fechner","points":["<b>Herbart (1776–1841)</b>: Mathematisierung der Psychologie; Bewusstseinsinhalte seien ebenso empirisch erforschbar wie die äußere Welt. Mit den Modellen zur Statik und Mechanik der Vorstellungen widerlegte er Kants Annahme.","<b>Helmholtz (1821–1894)</b>: Handbuch der physiologischen Optik – vom anatomischen Aufbau des Auges über Netzhautzellen und Sehnerven bis zur Farbwahrnehmung; ermöglichte die Unterteilung in verschiedene Sinne statt eines „Gesamtsinns“.","<b>Helmholtz’ Erkenntnis</b>: Pionier der Nervenleitgeschwindigkeit auf apparativer Messgrundlage; zugleich enthält jede Beobachtung Einflüsse der beobachtenden Person – frühere Erfahrungen, Erwartungen und Vorurteile.","<b>Fechner (1801–1887)</b>: begründete die Psychophysik. Äußere Psychophysik: Sinnesreiz (Physik) ↔ Sinnesempfindung. Innere Psychophysik: Körpererregung (Physiologie) ↔ Sinnesempfindung.","<b>Fechners Methode</b>: Methode der ebenmerklichen Unterschiede (heute Grenzmethode), z. B. Vergleich von Gewichtsmaßen; er quantifizierte als einer der Ersten die Reizstärke eines nicht bewussten Stimulus mathematisch.","<b>Einordnung</b>: Fechner gilt vielfach als Begründer einer eigenständigen, naturwissenschaftlich orientierten Psychologie – eine Trennung von Psychologie und Philosophie lag ihm allerdings fern."]}},{"id":"k3-4a1448b548","kap":3,"sec":"3.1 Einführung & Forschungsprozess","stem":"Welche Aussagen über Heuristiken treffen zu?","opts":[{"t":"Heuristiken bezeichnen systematisch fehlerhafte Tendenzen beim Wahrnehmen, Erinnern, Denken und Urteilen.","c":false,"fb":"Das ist die Definition der kognitiven Verzerrung. Heuristiken sind die sparsamen Urteilsstrategien selbst — Verzerrungen sind die systematischen Fehler, die dabei entstehen können."},{"t":"Sie ermöglichen es, auch mit unvollständiger Information und wenig Zeit zu urteilen und zu entscheiden.","c":true,"fb":"Genau das leisten Heuristiken; sie werden deshalb auch als Faustregeln bezeichnet, die die Urteilsfindung erleichtern."},{"t":"Der Repräsentativitätsheuristik liegt die Annahme zugrunde, dass typischer erscheinende Ereignisse auch wahrscheinlicher sind.","c":true,"fb":"Deshalb wirkt die Münzfolge K–Z–Z–K–Z wahrscheinlicher als K–K–K–K–K, obwohl beide Folgen exakt gleich wahrscheinlich sind."},{"t":"Weil Heuristiken sparsam vorgehen, führen sie grundsätzlich zu fehlerhaften Urteilen.","c":false,"fb":"In vielen Fällen führen Heuristiken zu korrekten Urteilen. Die Sparsamkeit macht sie fehleranfällig, nicht grundsätzlich fehlerhaft."}],"concept":{"title":"Heuristiken und kognitive Verzerrungen","points":["<b>Heuristik</b>: Methode, mit unvollständiger Information und wenig Zeit zu urteilen und zu entscheiden — auch „Faustregel“ genannt.","<b>Kognitive Verzerrung</b>: systematisch fehlerhafte Tendenz beim Wahrnehmen, Erinnern, Denken und Urteilen. Nicht mit der Heuristik selbst verwechseln.","<b>Verhältnis der beiden</b>: Heuristiken führen in vielen Fällen zu korrekten Urteilen; ihre „sparsame“ Art macht sie fehleranfällig, nicht grundsätzlich fehlerhaft.","<b>Repräsentativitätsheuristik</b>: implizite Annahme, dass typischer erscheinende Ereignisse auch wahrscheinlicher sind.","<b>Münzwurf-Beispiel</b>: K–Z–Z–K–Z wirkt wahrscheinlicher als K–K–K–K–K, obwohl beide Folgen gleich wahrscheinlich sind — jeder Wurf hat 50 %, vorangegangene Würfe beeinflussen den aktuellen nicht."]}},{"id":"k3-3e4d0216e2","kap":3,"sec":"3.1 Einführung & Forschungsprozess","stem":"Welche Beschreibung trifft auf den Bestätigungsfehler (Confirmation Bias) zu?","opts":[{"t":"Der nachträgliche Eindruck, den Ausgang eines Geschehnisses schon vorher richtig vorausgesagt zu haben.","c":false,"fb":"Das ist der Rückschaufehler (Hindsight Bias) — etwa der Eindruck nach einem Spiel, den Sieger ohnehin gekannt zu haben."},{"t":"Eine Faustregel, die schnelle Lösungen liefert und dadurch die Urteilsfindung erleichtert.","c":false,"fb":"Das beschreibt eine Heuristik. Der Bestätigungsfehler ist keine Entscheidungsstrategie, sondern eine Verzerrung der Informationsgewichtung."},{"t":"Die Neigung, Informationen, die die eigene Überzeugung stützen, stärker zu gewichten als widersprechende Informationen.","c":true,"fb":"Genau das zeigt das Beispiel mit dem Zeitungsartikel über das Lieblingsteam: Der bestätigende Artikel gilt als aussagekräftig, der widersprechende als ahnungslos."},{"t":"Die Neigung, widersprechenden Informationen mehr Bedeutung beizumessen als bestätigenden.","c":false,"fb":"Die Richtung ist umgedreht. Der Bestätigungsfehler bevorzugt gerade die Information, die zur bestehenden Überzeugung passt."}],"concept":{"title":"Rückschaufehler und Bestätigungsfehler im Vergleich","points":["<b>Rückschaufehler (Hindsight Bias)</b>: der nachträgliche Eindruck, den Ausgang eines Geschehnisses schon vorher richtig vorausgesagt haben zu können (Sedlmeier & Renkewitz, 2013).","<b>Beispiel Rückschaufehler</b>: Nach einem Spiel meint man, vorher gewusst zu haben, wer gewinnt.","<b>Bestätigungsfehler (Confirmation Bias)</b>: die Neigung, bestätigenden Informationen mehr Bedeutung beizumessen als widersprechenden (Gazzaniga et al., 2017).","<b>Beispiel Bestätigungsfehler</b>: Ein kritischer Artikel über das Lieblingsteam wird abgewertet, ein positiver Artikel bestätigt die eigene Annahme.","<b>Gemeinsamer Rahmen</b>: Beide sind kognitive Verzerrungen, nicht Heuristiken — der Weg heraus ist das kritische Denken, also das systematische Hinterfragen und Bewerten von Informationen."]}},{"id":"k3-98cd58a6f4","kap":3,"sec":"3.1 Einführung & Forschungsprozess","stem":"Döring (2023) nennt vier Standards der Wissenschaftlichkeit. Welche der folgenden Bezeichnungen gehören tatsächlich zu diesem Katalog?","opts":[{"t":"Sicherung der ökonomischen Verwertbarkeit der Forschungsergebnisse","c":false,"fb":"Kein Standard der Wissenschaftlichkeit. Inhaltliche Relevanz meint den Beitrag zum Erkenntnisfortschritt und zur Lösung praktischer Probleme, nicht die wirtschaftliche Verwertung."},{"t":"Vollständige schriftliche Dokumentation des gesamten Forschungsprojekts","c":true,"fb":"Einer der vier Standards: Der Forschungsprozess muss für andere nachvollziehbar und replizierbar sein, weshalb alle Phasen genau dokumentiert werden."},{"t":"Nachweis der statistischen Signifikanz aller geprüften Hypothesen","c":false,"fb":"Erfunden. Eine Untersuchung ist nicht deshalb wissenschaftlich, weil ihre Hypothesen bestätigt wurden — auch widerlegte Hypothesen erfüllen die Standards."},{"t":"Formulierung eines wissenschaftlichen Forschungsproblems","c":true,"fb":"Einer der vier Standards: Thema und Forschungsfragen müssen empirisch untersuchbar und auf Basis des Forschungsstands theoretisch erklärbar sein. Die beiden übrigen Standards sind der wissenschaftliche Forschungsprozess und die Orientierung an der Forschungsethik."}],"concept":{"title":"Die vier Standards der Wissenschaftlichkeit (Döring, 2023)","points":["<b>1. Wissenschaftliches Forschungsproblem</b>: Thema und Fragestellungen müssen empirisch untersuchbar und auf Basis des aktuellen Forschungsstands theoretisch erklärbar sein.","<b>2. Wissenschaftlicher Forschungsprozess</b>: zugeschnitten auf das Forschungsproblem, mit etablierten Methoden und Techniken in allen Phasen.","<b>3. Wissenschafts- und Forschungsethik</b>: Plagiat, Datenmanipulation oder Schädigung Teilnehmender kosten der Untersuchung den Charakter der Wissenschaftlichkeit.","<b>4. Vollständige schriftliche Dokumentation</b>: der Prozess muss nachvollziehbar und replizierbar sein.","<b>Qualitätskriterien dazu</b>: inhaltliche Relevanz, methodische Strenge, ethische Strenge, Präsentationsqualität — eine unzureichend erfüllte Einzelkategorie bedeutet noch nicht schlechte Qualität."]}},{"id":"k3-63b90df42b","kap":3,"sec":"3.1 Einführung & Forschungsprozess","stem":"Welche Aussagen zu Replikationsstudien und zur Replikationskrise treffen zu?","opts":[{"t":"Direkte Replikationsstudien versuchen, die Originalstudie so detailliert wie möglich nachzustellen.","c":true,"fb":"Deshalb heißen sie auch exakte Replikationen — sie prüfen den Befund unter möglichst identischen Bedingungen."},{"t":"Weichen die Befunde einer Replikation von der Originalstudie ab, ist damit belegt, dass die Replikation nicht detailgetreu durchgeführt wurde.","c":false,"fb":"Das ist nur eine der möglichen Erklärungen. Ebenso kann es sich bei den früheren Befunden um Zufallsbefunde gehandelt haben."},{"t":"Konzeptionelle Replikationsstudien variieren Aspekte der Originalstudie systematisch, um Generalisierbarkeit oder Spezifität eines Befunds zu bestimmen.","c":true,"fb":"Beispiel aus dem Skript: Bei Wahrnehmungsexperimenten wird die Darbietungsdauer der Reize variiert, um zu prüfen, wann der Effekt auftritt."},{"t":"Als Ursachen der Replikationskrise werden unter anderem Daten- und Ergebnisfälschungen sowie ein nicht fachgemäßer Umgang mit wissenschaftlichen Methoden angenommen.","c":true,"fb":"Als Gegenmaßnahme wird der Forschungsprozess transparenter gestaltet — durch detaillierte Dokumentation und Veröffentlichung der zugrunde liegenden Daten."}],"concept":{"title":"Replikationsstudien und die Replikationskrise","points":["<b>Direkte (exakte) Replikation</b>: stellt die Originalstudie so detailliert wie möglich nach.","<b>Abweichende Befunde</b>: können auf eine nicht detailgetreue Durchführung hindeuten — oder darauf, dass die früheren Befunde Zufallsbefunde waren. Beides bleibt zunächst offen.","<b>Konzeptionelle Replikation</b>: wandelt Aspekte ab und variiert systematisch, um Generalisierbarkeit bzw. Spezifität zu bestimmen (z. B. Variation der Darbietungsdauer von Reizen).","<b>Replikationskrise</b>: viele Erkenntnisse der Psychologie und anderer Wissenschaften lassen sich in Replikationsstudien nicht bestätigen.","<b>Angenommene Ursachen</b>: u. a. Daten- und Ergebnisfälschungen sowie nicht-fachgemäßer Umgang mit wissenschaftlichen Methoden.","<b>Gegenmaßnahme</b>: maximale Transparenz — detaillierte Dokumentation und Veröffentlichung der zugrundeliegenden Daten (Wirtz, 2022)."]}},{"id":"k3-a68896e265","kap":3,"sec":"3.1 Einführung & Forschungsprozess","stem":"Welche Aussagen über quantitative und qualitative Forschung treffen zu?","opts":[{"t":"Die quantitative Forschung ist derzeit der in der Psychologie vorherrschende Ansatz.","c":true,"fb":"Sie macht psychologische Phänomene messbar und damit vergleichbar; das Kapitel orientiert sich in erster Linie an ihr."},{"t":"Ob qualitativ oder quantitativ vorgegangen wird, ist allein durch das Skalenniveau der erhobenen Daten festgelegt.","c":false,"fb":"Die Wahl hängt maßgeblich vom Forschungsparadigma und der konkreten Fragestellung ab. Das Skalenniveau ergibt sich erst aus der Operationalisierung."},{"t":"In der qualitativen Forschung stehen sinnverstehende und interpretative Aspekte im Vordergrund.","c":true,"fb":"Beim Theaterbeispiel entspricht die offene Frage nach dem Erleben dem qualitativen Vorgehen; man erhält individuelle Antworten statt eines Mittelwerts."},{"t":"Die quantitative Forschung interessiert sich vor allem für einzelne Personen und deren individuelle Beobachtungsrealitäten.","c":false,"fb":"Umgekehrt: Sie interessiert sich weniger für Einzelpersonen als für Gruppen, um einen für die Gruppe repräsentativen Wert zu ermitteln."}],"concept":{"title":"Quantitative und qualitative Forschung","points":["<b>Quantitative Forschung</b>: macht psychologische Phänomene messbar und damit vergleichbar; derzeit der in der Psychologie vorherrschende Ansatz.","<b>Interessensfokus</b>: nicht Einzelpersonen, sondern Gruppen — über mehrere Personen einer Gruppe wird ein typischer (repräsentativer) Wert ermittelt.","<b>Qualitative Forschung</b>: sinnverstehende und interpretative Aspekte stehen im Vordergrund; individuelle Antworten bilden die Beobachtungsrealitäten der Befragten ab.","<b>Theaterbeispiel</b>: Skala 1–10 zur Zufriedenheit = quantitativ (Mittelwert bildbar); offene Frage nach dem Erleben = qualitativ.","<b>Was die Wahl bestimmt</b>: das jeweilige Forschungsparadigma und die konkrete Fragestellung — nicht das Skalenniveau (Hussy, Schreier & Echterhoff, 2013)."]}},{"id":"k3-28419134f0","kap":3,"sec":"3.2 Theorien & Hypothesen","stem":"Welche Aussage über das Verhältnis von Theorie und Hypothese trifft zu?","opts":[{"t":"Widersprechen die Ergebnisse der Hypothese, erfährt die dahinterliegende Theorie Unterstützung und wird auf Grundlage neuer Hypothesen weiterentwickelt.","c":false,"fb":"Die Richtung ist vertauscht. Widersprechende Ergebnisse führen dazu, dass die Theorie keine Unterstützung erfährt und verworfen oder überarbeitet wird."},{"t":"Theorien sind konkrete, unmittelbar überprüfbare Vermutungen über einen einzelnen Sachverhalt.","c":false,"fb":"Das ist die Beschreibung von Hypothesen. Theorien sind breiter und allgemeiner formuliert — Piagets Theorie als Ganzes ist zu komplex für eine einzelne Untersuchung."},{"t":"Eine Theorie dient ausschließlich dazu, vergangene Beobachtungen zu erklären.","c":false,"fb":"Sie erklärt vergangene Beobachtungen und sagt zusätzlich zukünftige Beobachtungen vorher."},{"t":"Hypothesen werden aus Theorien abgeleitet und beziehen sich auf einen konkreten, überprüfbaren Sachverhalt.","c":true,"fb":"Aus dem Theoriebestandteil „Kinder unter zwei Jahren verfügen noch nicht über Objektpermanenz“ wird eine prüfbare Vorhersage über die Reaktion auf ein verdecktes Objekt."}],"concept":{"title":"Der zyklische Weg von der Theorie zur Hypothese","points":["<b>Theorie</b>: geordnete Menge von Begriffen und Aussagen, die ein Phänomen erklären soll; breit und allgemein formuliert.","<b>Doppelte Funktion der Theorie</b>: vergangene Beobachtungen erklären <i>und</i> zukünftige Beobachtungen vorhersagen.","<b>Hypothese</b>: konkrete, überprüfbare Vermutung über einen einzelnen Sachverhalt, abgeleitet aus der Theorie.","<b>Piaget-Beispiel</b>: Aus dem Theoriebestandteil „Kinder unter zwei Jahren verfügen noch nicht über Objektpermanenz“ wird die prüfbare Hypothese, dass Kinder auf ein verdecktes Objekt keine Reaktion mehr zeigen.","<b>Stützen</b>: Die Theorie wird auf Grundlage neuer Hypothesen und Studien weiterentwickelt.","<b>Widerlegen</b>: Die Theorie erfährt keine Unterstützung und wird verworfen oder überarbeitet."]}},{"id":"k3-e00428a4fa","kap":3,"sec":"3.2 Theorien & Hypothesen","stem":"Welche Aussagen über die Anforderungen an wissenschaftliche Hypothesen treffen zu?","opts":[{"t":"Hypothesen müssen präzise und widerspruchsfrei formuliert sein und sollen keinen Raum für Interpretationen lassen.","c":true,"fb":"„Kinder schlafen mehr“ verfehlt dieses Kriterium, weil offen bleibt, im Vergleich wozu oder unter welchen Umständen."},{"t":"Die Operationalisierbarkeit verlangt, dass die verwendeten abstrakten Begriffe einer Hypothese erfassbar und messbar sein müssen.","c":true,"fb":"Ohne messbare Begriffe lässt sich die Vermutung nicht empirisch prüfen — deshalb gehört die Operationalisierbarkeit zu den vier Merkmalen."},{"t":"Die Begründbarkeit verlangt, den aktuellen Stand der Wissenschaft zu berücksichtigen, sofern bereits theoretische Modellannahmen oder empirische Befunde vorliegen.","c":true,"fb":"Die Einschränkung ist wichtig: Das Kriterium gilt unter der Voraussetzung, dass zum Thema bereits etwas vorliegt."},{"t":"Hypothesen müssen vor der Datensammlung aufgestellt werden.","c":true,"fb":"Das illustriert die Bogenschützen-Karikatur: Erst zielen, dann schießen — nicht das Ziel nachträglich um den Treffer malen."}],"concept":{"title":"Anforderungen an wissenschaftliche Hypothesen (Hussy et al., 2013)","points":["<b>Präzise und widerspruchsfreie Formulierung</b>: kein Raum für Interpretationen. Gegenbeispiel: „Kinder schlafen mehr“ — offen bleibt: mehr als wer, unter welchen Umständen.","<b>Prinzipielle Widerlegbarkeit</b>: „Durch ein spezifisches Hirntrauma ändert sich die sprachliche Leistung oder sie ändert sich nicht“ ist nicht widerlegbar — und damit auch nicht widerspruchsfrei.","<b>Operationalisierbarkeit</b>: die verwendeten abstrakten Begriffe müssen erfassbar und messbar sein.","<b>Begründbarkeit</b>: der aktuelle Stand der Wissenschaft ist zu berücksichtigen, sofern theoretische Modellannahmen oder empirische Befunde bereits existieren.","<b>Zeitliche Bedingung</b>: Hypothesen müssen vor der Datensammlung aufgestellt werden."]}},{"id":"k3-17930e98d1","kap":3,"sec":"3.2 Theorien & Hypothesen","stem":"Welche Zuordnungen von Beispielaussage und Hypothesenart sind korrekt?","opts":[{"t":"„Die Anzahl der Stunden, die Eltern mit ihren Kindern lernen, kovariiert mit der durchschnittlichen Schulnote der Kinder.“ — Unterschiedshypothese","c":false,"fb":"Falsche Kategorie: Hier werden zwei Variablen in Beziehung gesetzt, es ist also eine Zusammenhangshypothese. Unterschiedshypothesen vergleichen Gruppen."},{"t":"„Linkshändigkeit tritt bei Männern häufiger auf als bei Frauen.“ — gerichtete Unterschiedshypothese","c":true,"fb":"Zwei Gruppen werden verglichen, und die Richtung des Unterschieds ist spezifiziert. Ungerichtet wäre: „… tritt unterschiedlich häufig auf.“"},{"t":"„Durch eine spezielle psychotherapeutische Behandlung kommt es zu einer Veränderung der depressiven Symptomatik.“ — gerichtete Veränderungshypothese","c":false,"fb":"Die Hypothesenart stimmt, die Richtungsangabe nicht: Es wird nur eine Veränderung behauptet, also ungerichtet. Gerichtet wäre „… reduziert sich“."},{"t":"„Je mehr Sport Personen treiben, desto schlechter schneiden sie in einem Gedächtnistest ab.“ — negativ gerichtete Zusammenhangshypothese","c":true,"fb":"Hohe Werte der einen Variable werden mit niedrigen Werten der anderen verknüpft — „negativ“ meint hier die Richtung, keine Wertung."}],"concept":{"title":"Die drei Arten von Hypothesen","points":["<b>Unterschiedshypothese</b>: Vermutung über einen Unterschied zwischen zwei oder mehr Gruppen hinsichtlich einer Variable.","<b>Ungerichtet vs. gerichtet</b>: „Linkshändigkeit tritt bei Männern und Frauen unterschiedlich häufig auf“ (ungerichtet) gegenüber „…bei Männern häufiger als bei Frauen“ (gerichtet).","<b>Zusammenhangshypothese</b>: Vermutung über den Zusammenhang zweier oder mehrerer Variablen — die Variablen kovariieren.","<b>Positiv vs. negativ gerichtet</b>: „Je mehr Sport, desto mehr Punkte im Gedächtnistest“ (positiv) gegenüber „Je mehr Sport, desto schlechter das Abschneiden“ (negativ). Positiv und negativ sind keine Wertung, sondern die Richtung.","<b>Veränderungshypothese</b>: Vermutung über die Veränderung von Variablen bei denselben Personen über die Zeit; benötigt im Unterschied zur Unterschiedshypothese mehrere Erhebungszeitpunkte.","<b>Prüfpunkt Kovariation</b>: Eine Aussage mit „kovariiert mit“ ist eine Zusammenhangs-, keine Unterschiedshypothese."]}},{"id":"k3-a171ce244e","kap":3,"sec":"3.2 Theorien & Hypothesen","stem":"Unter welchen Bedingungen ist aus einer beobachteten Kovariation zweier Variablen A und B ein Kausalschluss zulässig?","opts":[{"t":"Wenn zusätzlich A zeitlich vor B auftritt und andere Ursachen außer A ausgeschlossen werden können.","c":true,"fb":"Das sind die beiden Zusatzvoraussetzungen neben der Kovariation; im Experiment werden sie durch Manipulation der UV und Kontrolle der Störvariablen hergestellt."},{"t":"Wenn zusätzlich B zeitlich vor A auftritt und andere Ursachen außer B ausgeschlossen werden können.","c":false,"fb":"Die zeitliche Reihenfolge ist vertauscht: Die vermutete Ursache A muss der Wirkung B vorausgehen."},{"t":"Eine hinreichend deutliche Kovariation von A und B genügt bereits, um einen ursächlichen Einfluss zu behaupten.","c":false,"fb":"Kovariation allein reicht nie aus — sie ist nur eine von drei Voraussetzungen."},{"t":"Sobald der Korrelationskoeffizient einen Wert nahe 1 annimmt, ist der Kausalschluss gerechtfertigt.","c":false,"fb":"Die Höhe der Korrelation sagt nichts über Kausalität. Auch ein sehr hoher Zusammenhang kann durch eine dritte Variable zustande kommen."}],"concept":{"title":"Kovariation und Kausalität: die drei Bedingungen","points":["<b>Bedingung 1</b>: Kovariation von Variable A und Variable B muss vorliegen.","<b>Bedingung 2</b>: A tritt zeitlich vor B auf.","<b>Bedingung 3</b>: andere Ursachen außer A können ausgeschlossen werden.","<b>Warum Kovariation allein nicht reicht</b>: Aus dem Zusammenhang von Lerndauer und Schulnote folgt noch kein ursächlicher Einfluss.","<b>Korrelationshöhe irrelevant</b>: Auch ein r nahe 1 rechtfertigt keinen Kausalschluss — Kovariation bzw. Korrelation ist nicht gleichbedeutend mit Kausalität.","<b>Umsetzung</b>: Wie die Bedingungen hergestellt werden, zeigt die experimentelle Methode (Kapitel 3.4)."]}},{"id":"k3-059a507785","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Aussagen über Merkmale und deren Ausprägungen treffen zu?","opts":[{"t":"Bei quantitativen Merkmalen wird die Ausprägung anhand vordefinierter Kategorien beschrieben.","c":false,"fb":"Vordefinierte Kategorien kennzeichnen qualitative Merkmale (z. B. Nationalität). Bei quantitativen Merkmalen wird der Ausprägungsgrad auf einem Kontinuum beschrieben."},{"t":"Bestehen die Merkmalsausprägungen aus Zahlen, spricht man auch von Werten.","c":true,"fb":"Beispiel Körpergröße in Zentimeter: Die Ausprägung nimmt bei der Geburt in der Regel einen Wert um die 50 an."},{"t":"Merkmale können sowohl zwischen Personen als auch innerhalb einer Person über die Zeit variieren.","c":true,"fb":"Die Körpergröße unterscheidet sich zwischen Bekannten und verändert sich bei derselben Person über die Kindheit hinweg stark."},{"t":"Ein Merkmal kann nur dann als psychisches Merkmal gelten, wenn es direkt beobachtbar ist.","c":false,"fb":"Gerade die zentralen psychischen Merkmale — Intelligenz, Gedächtnis, Ängstlichkeit — sind latent und damit nicht direkt beobachtbar."}],"concept":{"title":"Merkmal, Merkmalsausprägung und Wert","points":["<b>Merkmal</b>: Eigenschaft, die zu einem Objekt oder einer Person gehört und unterschiedliche Ausprägungen aufweisen kann.","<b>Variabilität</b>: Merkmale können zwischen Personen <i>und</i> innerhalb einer Person zu verschiedenen Zeitpunkten variieren.","<b>Qualitative Merkmale</b>: verschiedene Kategorien, denen eine Person zugeordnet wird — etwa Nationalität oder Augenfarbe.","<b>Quantitative Merkmale</b>: keine vordefinierten Kategorien, sondern Ausprägungsgrad auf einem Kontinuum.","<b>Werte</b>: Bestehen die Ausprägungen aus Zahlen — etwa Körpergröße in Zentimeter — spricht man von Werten (Hussy et al., 2013; Leonhart, 2004).","<b>Beispiel Körpergröße</b>: bei Geburt in der Regel um 50 cm, über die Kindheit stark verändert; auch zwischen Bekannten unterschiedlich ausgeprägt."]}},{"id":"k3-3c4601fd8c","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Aussagen zu latenten und manifesten Merkmalen sowie zur Operationalisierung treffen zu?","opts":[{"t":"Latente Merkmale können nicht direkt beobachtet werden; man greift auf manifeste Merkmale zurück, die als Indikatoren dienen.","c":true,"fb":"Von der Ausprägung des manifesten Merkmals wird dann auf die Ausprägung des latenten Merkmals geschlossen — etwa vom Puls auf das Stresserleben."},{"t":"Das operationalisierte Merkmal wird als Variable bezeichnet.","c":true,"fb":"Das erhobene subjektive Stressempfinden auf der Skala 0–10 ist die Variable in der Untersuchung, Stress selbst bleibt das latente Merkmal."},{"t":"Bei manifesten Merkmalen umfasst die Operationalisierung zwingend auch die Auswahl geeigneter beobachtbarer Indikatoren.","c":false,"fb":"Bei manifesten Merkmalen genügt die Wahl des Messinstruments (z. B. ein Maßband). Die Indikatorenauswahl kommt erst bei latenten Merkmalen hinzu."},{"t":"Zur Operationalisierung gehört neben der Auswahl der Indikatoren auch die Festlegung, wie diese erhoben werden — also Messinstrument und Messart.","c":true,"fb":"Operationalisierung ist die Festlegung der gesamten Menge an Operationen zur Erfassung eines Merkmals, nicht nur der Indikatoren."}],"concept":{"title":"Latente und manifeste Merkmale, Operationalisierung","points":["<b>Latentes Merkmal</b>: nicht direkt beobachtbar oder messbar — etwa Stress, Intelligenz, Ängstlichkeit.","<b>Manifestes Merkmal</b>: direkt beobachtbar und messbar; dient als Indikator, von dessen Ausprägung auf das latente Merkmal geschlossen wird.","<b>Operationalisierung</b>: Festlegung der Menge an Operationen zur Erfassung eines Merkmals.","<b>Unterschied im Umfang</b>: Bei manifesten Merkmalen umfasst sie die Wahl des Messinstruments (z. B. Maßband); bei latenten Merkmalen zusätzlich die Auswahl geeigneter beobachtbarer Indikatoren.","<b>Variable</b>: so heißt das operationalisierte Merkmal (Renner et al., 2012; Leonhart, 2004).","<b>Stress-Beispiel</b>: latentes Merkmal Stress → manifestes Merkmal subjektives Stressempfinden → Messinstrument Skala 0–10 → resultierende Variable."]}},{"id":"k3-224ba62b18","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Aussage zu den psychometrischen Hauptgütekriterien trifft zu?","opts":[{"t":"Die Objektivität betrifft ausschließlich die Durchführung einer Messung, nicht deren Auswertung und Interpretation.","c":false,"fb":"Die Objektivität betrifft alle drei Ebenen: Durchführung, Auswertung und Interpretation."},{"t":"Reliabilität liegt vor, wenn ein Messinstrument inhaltlich das misst, was es zu messen vorgibt.","c":false,"fb":"Das ist die Definition der Validität. Reliabilität meint Zuverlässigkeit und Messgenauigkeit."},{"t":"Wird der Puls als Indikator für Stresserleben herangezogen, ist damit in erster Linie die Reliabilität der Messung gefährdet.","c":false,"fb":"Gefährdet ist die Validität: Der Puls kann auch durch Nervosität oder körperliche Betätigung steigen und bildet dann nicht (nur) Stress ab."},{"t":"Die Reliabilität lässt sich anhand der Reproduzierbarkeit des Messergebnisses schätzen.","c":true,"fb":"Wiederholte Messungen desselben Objekts sollen zu gleichen Ergebnissen führen, sofern sich dessen Eigenschaften nicht verändert haben."}],"concept":{"title":"Objektivität, Reliabilität und Validität","points":["<b>Objektivität</b>: Die Messung wird nicht dadurch beeinflusst, welche Person das Messinstrument einsetzt. Kommen verschiedene Versuchsleitungen bei derselben Versuchsperson zum gleichen Ergebnis, ist die Messung objektiv.","<b>Reichweite der Objektivität</b>: betrifft Durchführung <i>sowie</i> Auswertung und Interpretation.","<b>Reliabilität</b>: Zuverlässigkeit und Messgenauigkeit; geschätzt anhand der Reproduzierbarkeit — wiederholte Messung desselben Objekts soll zum gleichen Ergebnis führen, sofern sich das Objekt nicht verändert hat.","<b>Validität</b>: Das Instrument misst inhaltlich das, was es zu messen vorgibt.","<b>Puls-Beispiel</b>: Puls als Indikator für Stress kann auch durch Nervosität oder körperliche Betätigung beeinflusst werden — hier ist die Validität gefährdet, nicht die Reliabilität."]}},{"id":"k3-016378f802","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Zuordnungen von Merkmal und Skalenniveau sind korrekt?","opts":[{"t":"Der höchste Bildungsabschluss ist ordinalskaliert.","c":true,"fb":"Eine Rangordnung besteht (Master über Bachelor), die Abstände zwischen den Stufen sind aber unbekannt — ein arithmetisches Mittel wäre sinnlos."},{"t":"Die Reaktionszeit in Sekunden ist intervallskaliert; Verhältnisaussagen sind daher unzulässig.","c":false,"fb":"Die Reaktionszeit hat einen natürlichen Nullpunkt und ist verhältnisskaliert. Aussagen wie „dreimal so lang wie im nüchternen Zustand“ sind zulässig."},{"t":"Die Nationalität ist ordinalskaliert, weil sich die Kategorien in eine Rangordnung bringen lassen.","c":false,"fb":"Die Nationalität ist nominalskaliert. Die Zahlenzuordnung ist willkürlich; eine Rangordnung existiert nicht."},{"t":"Die Temperatur in Grad Celsius ist intervallskaliert, weil ein natürlicher Nullpunkt fehlt.","c":true,"fb":"Die Abstände sind gleich groß, aber 8 °C ist nicht doppelt so warm wie 4 °C. In Kelvin liegt dagegen Verhältnisskalenniveau vor."}],"concept":{"title":"Die vier Skalenniveaus im Überblick","points":["<b>Nominalskala</b>: nur Gleichheit bzw. Verschiedenheit; Zahlenzuordnung willkürlich. Beispiele: Nationalität, Beruf, Vorhandensein/Fehlen einer Erkrankung (dichotom).","<b>Ordinalskala</b>: Rangordnung definiert, Abstände nicht. Beispiele: Schulnoten (1–5), höchster Bildungsabschluss, militärische Ränge. Kein sinnvolles arithmetisches Mittel.","<b>Intervallskala</b>: Rangordnung <i>und</i> Abstände definiert, aber kein natürlicher Nullpunkt. Beispiele: Temperatur in Celsius, psychische Merkmale wie Intelligenz und Gewissenhaftigkeit.","<b>Verhältnisskala (Ratio)</b>: zusätzlich natürlicher Nullpunkt, daher sind Verhältnisaussagen zulässig. Beispiele: Temperatur in Kelvin, Längen- und Gewichtsmaße, Reaktionszeit in Sekunden.","<b>Kategorial vs. kontinuierlich</b>: nominal und ordinal zählen zu den kategorialen, Intervall- und Verhältnisskala zu den kontinuierlichen Variablen.","<b>Merksatz zu Celsius</b>: 8 °C ist nicht doppelt so warm wie 4 °C — 0 °C ist definiert, nicht natürlich."]}},{"id":"k3-c78a943296","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Aussagen zu Stichproben und deren Gewinnung treffen zu?","opts":[{"t":"Ein Selection Bias ist eine Verzerrung in den Daten, die dadurch entsteht, dass die Auswahl der Stichprobe nicht völlig zufällig erfolgt ist.","c":true,"fb":"Beispiel: Studierende mit schlechterer psychischer Gesundheit senden den Fragebogen seltener zurück — die berichtete Gesundheit wird dadurch überschätzt."},{"t":"Gelegenheitsstichproben werden vor allem wegen der wesentlich einfacheren Umsetzung herangezogen; Online-Umfragen sind ein Beispiel dafür.","c":true,"fb":"Auch die Rekrutierung von Studierenden über Aushänge an der Universität fällt darunter."},{"t":"Der Stichprobenumfang bezeichnet die Anzahl der Personen, die der Grundgesamtheit angehören.","c":false,"fb":"Der Stichprobenumfang ist die Anzahl der Personen in der Stichprobe, nicht in der Population."},{"t":"Mit zunehmendem Stichprobenumfang steigt die Aussagekraft der Ergebnisse, zugleich aber auch der Ressourcenverbrauch.","c":true,"fb":"Deshalb gilt: ausreichend viele, aber nicht zu viele Versuchspersonen. Einzelne „Ausnahmen“ beeinflussen große Stichproben weniger stark."}],"concept":{"title":"Population, Stichprobe und ihre Tücken","points":["<b>Population (Grundgesamtheit)</b>: Gesamtheit der Fälle, über die etwas ausgesagt werden soll.","<b>Stichprobe</b>: Teilmenge aus der Population; die zugehörigen Personen heißen Versuchspersonen oder Proband:innen.","<b>Repräsentativität</b>: Die Stichprobe soll ein Miniaturabbild der Population sein — Voraussetzung dafür, dass das Gütekriterium der externen Validität erfüllt wird.","<b>Zufallsstichprobe</b>: jede Person der Population hat die gleiche Chance, aufgenommen zu werden; in der Praxis meist schwer umsetzbar.","<b>Selection Bias</b>: Verzerrung in den Daten dadurch, dass die Auswahl nicht völlig zufällig erfolgt ist — etwa wenn gerade Personen mit schlechterer psychischer Gesundheit den Fragebogen nicht zurücksenden.","<b>Stichprobenumfang</b>: Anzahl der Personen <i>in der Stichprobe</i>. Mehr Personen bedeuten höhere Aussagekraft, aber auch höheren Ressourcenverbrauch."]}},{"id":"k3-f36832e079","kap":3,"sec":"3.3 Operationalisierung & Untersuchungsplanung","stem":"Welche Aussagen zu Labor- und Felduntersuchungen sowie zur internen und externen Validität treffen zu?","opts":[{"t":"In Felduntersuchungen lassen sich störende Faktoren besser kontrollieren als in Laboruntersuchungen.","c":false,"fb":"Genau umgekehrt: Störende Faktoren sind im Feld schlechter kontrollierbar — das ist der zentrale Nachteil dieses Untersuchungsorts."},{"t":"Felduntersuchungen weisen in der Regel eine geringere interne und eine größere externe Validität auf als Laboruntersuchungen.","c":true,"fb":"Der Preis für authentisches Verhalten in natürlicher Umgebung ist die schwächere Kontrolle und damit die geringere interne Validität."},{"t":"Die interne Validität ist erfüllt, wenn eine Untersuchung einen eindeutigen Kausalschluss zulässt.","c":true,"fb":"Dafür müssen die Kausalrichtung eindeutig bestimmbar und andere Variablen als Ursache ausgeschlossen sein."},{"t":"Die externe Validität wird vor allem dadurch erhöht, dass mögliche Störvariablen konstant gehalten werden.","c":false,"fb":"Konstanthaltung dient der internen Validität. Die externe Validität steigt durch eine möglichst repräsentative Stichprobe und die Übertragbarkeit der Situation auf den Alltag."}],"concept":{"title":"Laboruntersuchung, Felduntersuchung und die beiden Validitäten","points":["<b>Laboruntersuchung</b>: Versuchspersonen kommen in ein Labor; störende Faktoren lassen sich gut kontrollieren.","<b>Felduntersuchung</b>: Untersuchung in der natürlichen Umgebung; authentischeres Verhalten, bessere Übertragbarkeit, manche Verhaltensweisen nur dort beobachtbar.","<b>Nachteil des Feldes</b>: schlechtere Kontrolle möglicher Störfaktoren.","<b>Merksatz</b>: Felduntersuchungen haben geringere interne und größere externe Validität als Laboruntersuchungen.","<b>Interne Validität</b>: erfüllt, wenn die Untersuchung einen eindeutigen Kausalschluss zulässt.","<b>Externe Validität</b>: Übertragbarkeit auf andere Personen und Situationen; erhöht durch eine möglichst repräsentative Stichprobe und Alltagsnähe der Untersuchungssituation."]}},{"id":"k3-adeb194b57","kap":3,"sec":"3.4 Experimentelle Methode","stem":"Welche Aussagen über das wissenschaftliche Experiment treffen zu?","opts":[{"t":"Es wird mindestens eine Variable systematisch variiert und anschließend beobachtet, welchen Effekt sie auf eine oder mehrere andere Variablen hat.","c":true,"fb":"Das ist das erste der beiden charakterisierenden Merkmale des Experiments."},{"t":"Die Variable, von der ein ursächlicher Charakter vermutet wird, heißt unabhängige Variable.","c":true,"fb":"Die mutmaßlich beeinflusste Variable ist die abhängige Variable — sie hängt von der unabhängigen ab."},{"t":"Die Wirkung anderer Variablen, der Störvariablen, wird mittels Techniken zur Kontrolle ausgeschaltet oder kontrolliert.","c":true,"fb":"Das zweite charakterisierende Merkmal; erst dadurch lassen sich andere Ursachen ausschließen."},{"t":"Ein Experiment, bei dem die für einen Kausalschluss nötigen Bedingungen vollständig erfüllt sind, wird als intern valide bezeichnet.","c":true,"fb":"Experimente gelten deshalb als die aussagekräftigste wissenschaftliche Methode zur Prüfung von Ursache-Wirkungs-Hypothesen."}],"concept":{"title":"Die zwei Merkmale des wissenschaftlichen Experiments","points":["<b>Merkmal 1</b>: Mindestens eine Variable wird systematisch variiert und anschließend beobachtet, welchen Effekt sie auf eine oder mehrere andere Variablen hat.","<b>Merkmal 2</b>: Die Wirkung anderer Variablen — der Störvariablen — wird mittels Kontrolltechniken ausgeschaltet oder kontrolliert.","<b>Unabhängige Variable (UV)</b>: die Variable mit vermutetem ursächlichem Charakter; sie wird manipuliert.","<b>Abhängige Variable (AV)</b>: die Variable, die mutmaßlich durch die UV beeinflusst wird — sie hängt von der UV ab.","<b>Ziel</b>: Prüfung von Ursache-Wirkungs-Hypothesen; das Experiment gilt als die aussagekräftigste wissenschaftliche Methode.","<b>Intern valide</b>: so heißt ein Experiment, bei dem die für einen Kausalschluss nötigen Bedingungen vollständig erfüllt sind."]}},{"id":"k3-48d0f3e966","kap":3,"sec":"3.4 Experimentelle Methode","stem":"Welche Aussage zu Between-Subjects- und Within-Subjects-Designs trifft zu?","opts":[{"t":"Bei einem Between-Subjects-Design durchlaufen alle Versuchspersonen sämtliche Bedingungen des Experiments.","c":false,"fb":"Das beschreibt das Within-Subjects-Design. Im Between-Subjects-Design nimmt jede Person nur an einer Bedingung teil."},{"t":"Within-Subjects-Designs bieten Vorteile wie Ökonomie und mehr Daten, eignen sich aber nicht, wenn Vorwissen über den Versuchsablauf die abhängige Variable beeinflusst.","c":true,"fb":"Genau diese Einschränkung nennt Infobox 3.5 — bei manchen Fragestellungen ist ein Within-Design deshalb ausgeschlossen."},{"t":"Das Between-Subjects-Design heißt so, weil die experimentellen Bedingungen innerhalb derselben Gruppe von Personen verglichen werden.","c":false,"fb":"Die Begründung ist vertauscht: Es heißt so, weil das experimentelle Vorgehen zwischen den Versuchspersonen variiert wird."},{"t":"Bei einem Within-Subjects-Design werden die Versuchspersonen per Zufall genau einer von mehreren Gruppen zugewiesen.","c":false,"fb":"Die zufällige Zuweisung auf getrennte Gruppen ist das Kennzeichen des Between-Subjects-Designs."}],"concept":{"title":"Between-Subjects- und Within-Subjects-Design","points":["<b>Between-Subjects-Design</b>: zwei oder mehr verschiedene Gruppen — in der Regel mindestens eine Experimental- und eine Kontrollgruppe; Zuordnung per Zufall.","<b>Namensherkunft</b>: Das experimentelle Vorgehen wird <i>zwischen</i> den Versuchspersonen variiert; jede Person nimmt nur an einer Bedingung teil.","<b>Within-Subjects-Design</b>: Alle Versuchspersonen durchlaufen alle Bedingungen; verglichen wird innerhalb derselben Gruppe.","<b>Vorteile Within</b>: Ökonomie und mehr Daten.","<b>Grenze Within</b>: ungeeignet, wenn Vorwissen über den Versuchsablauf einen Einfluss auf die AV hat (Sedlmeier & Renkewitz, 2013).","<b>Experimental- vs. Kontrollbedingung</b>: UV gegeben (z. B. Schlafdeprivation) gegenüber UV nicht gegeben (keine Schlafdeprivation)."]}},{"id":"k3-352bf2b27d","kap":3,"sec":"3.4 Experimentelle Methode","stem":"Welche Aussagen zur Kontrolle von Störvariablen treffen zu?","opts":[{"t":"Unter Randomisierung versteht man die zufällige Zuweisung der Versuchspersonen zu den Versuchsbedingungen.","c":true,"fb":"Bei ausreichend großer Stichprobe sind die Störvariablen dadurch in den Bedingungen ähnlich verteilt, also balanciert."},{"t":"Die Parallelisierung hat gegenüber der Randomisierung den Vorteil, auch unbekannte personengebundene Störvariablen kontrollieren zu können.","c":false,"fb":"Der Vorteil liegt umgekehrt: Die Parallelisierung kontrolliert nur eine bekannte Störvariable, die Randomisierung dagegen bekannte wie unbekannte."},{"t":"Untersuchungen, die alle Kriterien eines Experiments außer der Randomisierung erfüllen, werden als Quasi-Experimente bezeichnet.","c":true,"fb":"Typischer Fall: Die UV lässt sich nicht manipulieren, etwa beim Vergleich von Personen mit und ohne Erkrankung. Das kostet interne Validität."},{"t":"Ein Within-Subjects-Design stellt eine perfekte Parallelisierung dar, weil in allen Bedingungen dieselben Personen untersucht werden.","c":true,"fb":"Personengebundene Störvariablen sind damit vollständig kontrolliert — umsetzbar ist ein solches Design aber nicht immer."}],"concept":{"title":"Vier Techniken gegen Störvariablen","points":["<b>Konfundierung</b>: Eine Störvariable kommt als Alternativerklärung infrage, wenn sie mit der abhängigen Variable kovariiert.","<b>Konstanthalten</b>: identischer Versuchsablauf — gleiche Instruktionen, gleicher Raum, gleiche Tageszeit. Nicht auf personengebundene Merkmale anwendbar.","<b>Balancieren</b>: Eine Variable gilt als balanciert, wenn sie in den Bedingungen im Schnitt die gleiche Ausprägung aufweist.","<b>Randomisierung</b>: zufällige Zuweisung der Versuchspersonen zu den Bedingungen; kontrolliert bei ausreichend großer Stichprobe alle personengebundenen Störvariablen — bekannte wie unbekannte.","<b>Parallelisieren</b>: gezielte Aufteilung nach vorab gemessener Ausprägung; sinnvoll bei kleinen Stichproben, kontrolliert aber nur eine bekannte Störvariable.","<b>Quasi-Experiment</b>: erfüllt alle Kriterien außer der Randomisierung — etwa beim Vergleich von Personen mit und ohne Erkrankung. Das kostet interne Validität."]}},{"id":"k3-527dcdb1bc","kap":3,"sec":"3.4 Experimentelle Methode","stem":"Welche Aussagen zu Erwartungseffekten aufseiten der Versuchspersonen treffen zu?","opts":[{"t":"Reaktivität, auch Hawthorne-Effekt genannt, beschreibt, dass bereits das Wissen, an einem Experiment teilzunehmen und beobachtet zu werden, das Verhalten verändern kann.","c":true,"fb":"Wer sich beobachtet und bewertet weiß, versucht etwa einen guten Eindruck zu hinterlassen — das gefährdet die interne Validität."},{"t":"Von einem Blindversuch spricht man, wenn die Versuchsleitung nicht weiß, welcher Bedingung die Versuchsperson angehört.","c":false,"fb":"Beim Blindversuch weiß die Versuchsperson es nicht. Wissen es beide Seiten nicht, handelt es sich um eine Doppelblindstudie."},{"t":"Der Nocebo-Effekt fasst unerwünschte Wirkungen nach Erfahrung einer nicht wirksamen Behandlung zusammen.","c":true,"fb":"Er ist das Gegenstück zum Placebo-Effekt, der eine positive Veränderung des Gesundheitszustands nach Einnahme eines Placebos beschreibt."},{"t":"Versuchspersonen dürfen aus ethischen Gründen erst nach Abschluss der Studie erfahren, dass sie möglicherweise keine wirksame Behandlung erhalten haben.","c":false,"fb":"Die Aufklärung darüber muss im Vorfeld erfolgen. Verschleiert werden darf lediglich, welcher der beiden Gruppen die Person angehört."}],"concept":{"title":"Erwartungseffekte aufseiten der Versuchspersonen","points":["<b>Reaktivität / Hawthorne-Effekt</b>: Bereits das Wissen, an einem Experiment teilzunehmen und beobachtet zu werden, kann das Verhalten verändern (Roethlisberger & Dickson, 1939).","<b>Warum das ein Problem ist</b>: Die Erwartung der Versuchsperson wirkt konfundierend und gefährdet die interne Validität.","<b>Gegenmaßnahmen</b>: Coverstory über den Untersuchungszweck (ethisch heikel), schwer verfälschbare Maße wie Bildgebung oder Hormonspiegel, implizite Verfahren wie der IAT.","<b>Placebo-Effekt</b>: positive Veränderung des Gesundheitszustandes nach Einnahme eines Scheinmedikaments, zurückzuführen auf den psychosozialen Kontext der Behandlung.","<b>Nocebo-Effekt</b>: unerwünschte Wirkungen nach Erfahrung einer nicht wirksamen Behandlung.","<b>Blindversuch</b>: Die <i>Versuchsperson</i> weiß nicht, ob sie zur Experimental- oder Kontrollgruppe gehört; über die mögliche Unwirksamkeit muss sie aus ethischen Gründen im Vorfeld aufgeklärt werden."]}},{"id":"k3-a6aac49b53","kap":3,"sec":"3.4 Experimentelle Methode","stem":"Welche Aussage zu Erwartungseffekten aufseiten der Versuchsleitung trifft zu?","opts":[{"t":"Der Rosenthal-Effekt ist ein von der Versuchsleitung bewusst herbeigeführter Effekt zur Steigerung der Leistung der Versuchspersonen.","c":false,"fb":"Er ist gerade nicht beabsichtigt, sondern wirkt wie eine selbsterfüllende Prophezeiung."},{"t":"Bei Doppelblindstudien muss auch nachträglich unklar bleiben, welcher Bedingung eine Versuchsperson zugeteilt war.","c":false,"fb":"Die Zuteilung muss nachträglich nachvollziehbar sein, etwa über eine dritte Person, die nicht direkt mit der Versuchsperson interagiert."},{"t":"Eine selbsterfüllende Prophezeiung tritt vor allem dann ein, wenn die betroffenen Personen nicht an die Vorhersage glauben.","c":false,"fb":"Umgekehrt: Der Glaube an die Vorhersage ist ein wesentlicher Faktor, weil erst dadurch die positive Rückkopplung zwischen Erwartung und Verhalten entsteht."},{"t":"Im Experiment von Rosenthal und Fode (1963) verbesserten sich jene Ratten deutlich stärker, deren Trainierende sie für besonders intelligent hielten.","c":true,"fb":"Tatsächlich waren die Ratten zufällig zugeteilt; die Studierenden investierten aufgrund ihrer Erwartung unterschiedlich viel Zeit in die Aufgabe."}],"concept":{"title":"Rosenthal-Effekt und Doppelblindstudie","points":["<b>Rosenthal-Effekt</b>: Effekt, der auf die Erwartungen der Versuchsleitung zurückzuführen ist — nicht beabsichtigt, sondern wirkend wie eine selbsterfüllende Prophezeiung.","<b>Rosenthal & Fode (1963)</b>: Studierende trainierten Ratten durch ein Labyrinth. Eine Hälfte hielt ihre Tiere für besonders intelligent, die andere für besonders dumm.","<b>Ergebnis</b>: Die vermeintlich intelligenten Ratten verbesserten sich zusehends, bei den „dummen“ war nahezu keine Verbesserung zu beobachten — obwohl die Zuordnung zufällig war und über die Intelligenz nichts bekannt war.","<b>Erklärung</b>: Die Erwartung veränderte das Verhalten der Studierenden, die etwa mehr Zeit in die Aufgabe investierten.","<b>Doppelblindstudie</b>: Weder Versuchsperson noch Versuchsleitung wissen, welcher Bedingung zugeordnet wurde. Nachträglich muss die Zuteilung aber nachvollziehbar bleiben, etwa über eine dritte Person.","<b>Selbsterfüllende Prophezeiung</b>: Vorhersage, die ihre Erfüllung selbst bewirkt — entscheidend ist, dass die Menschen an die Vorhersage <i>glauben</i> (Merton, 1948)."]}},{"id":"k3-b3522c66f3","kap":3,"sec":"3.5 Deskriptive Statistik","stem":"An einer Untersuchung nehmen 10 Personen aus Österreich, 8 aus Deutschland und 2 aus der Schweiz teil. Welche Aussagen treffen zu?","opts":[{"t":"Die relative Häufigkeit der Personen aus Deutschland beträgt 0,40.","c":true,"fb":"8 von 20 Personen: Die absolute Häufigkeit wird durch die Gesamtanzahl der Werte dividiert."},{"t":"Die prozentuale Häufigkeit der Personen aus der Schweiz liegt bei 20 %.","c":false,"fb":"2 von 20 ergibt eine relative Häufigkeit von 0,10 und damit 10 %."},{"t":"Prozentuale Häufigkeiten erhält man, indem man die relativen Häufigkeiten mit 100 multipliziert.","c":true,"fb":"Aus 0,50 / 0,40 / 0,10 werden so 50 % / 40 % / 10 %."},{"t":"Die Summe der absoluten Häufigkeiten beträgt immer 1.","c":false,"fb":"Das gilt für die relativen Anteile. Die absoluten Häufigkeiten summieren sich hier auf 20, also auf die Gesamtzahl der Fälle."}],"concept":{"title":"Absolute, relative und prozentuale Häufigkeiten","points":["<b>Absolute Häufigkeit</b>: Anzahl der Werte pro Variablenausprägung — im Beispiel 10 Personen aus Österreich, 8 aus Deutschland, 2 aus der Schweiz.","<b>Relative Häufigkeit</b>: Anteil an allen Werten, also absolute Häufigkeit geteilt durch Gesamtanzahl — 0,50 / 0,40 / 0,10.","<b>Summenregel</b>: Die Summe der <i>relativen</i> Anteile beträgt immer 1 — nicht die der absoluten Häufigkeiten.","<b>Prozentuale Häufigkeit</b>: relative Häufigkeit mal 100 — 50 % / 40 % / 10 %.","<b>Berichtspflicht</b>: Es muss explizit angegeben werden, ob absolute oder relative Häufigkeiten berichtet werden, sonst drohen Fehlinterpretationen.","<b>Kontinuierliche Variablen</b>: Hier bildet man Intervalle (z. B. Altersgruppen); außer den Randkategorien sollten diese möglichst gleich groß sein. Darstellung im Histogramm."]}},{"id":"k3-2b7b926bd1","kap":3,"sec":"3.5 Deskriptive Statistik","stem":"Welche Aussagen über die deskriptive Statistik treffen zu?","opts":[{"t":"Sie wird auch beschreibende Statistik genannt, weil ihre Verfahren die Daten der Stichprobe beschreiben sollen.","c":true,"fb":"Davon zu unterscheiden ist die Inferenzstatistik (schließende Statistik), die von der Stichprobe auf die Population schließt."},{"t":"Zu ihr zählen die Bestimmung von Häufigkeiten einzelner Werte und von Häufigkeitsverteilungen.","c":true,"fb":"Häufigkeitsangaben eignen sich besonders für kategoriale Variablen mit abzählbar vielen Ausprägungen."},{"t":"Zu ihr zählen Kennwerte, die etwas über die zentrale Tendenz sowie die Streuung einer Variable aussagen.","c":true,"fb":"Erst Streuungsmaße zusätzlich zur zentralen Tendenz machen die Beschreibung aussagekräftig, denn ähnliche Mittelwerte bedeuten nicht ähnliche Stichproben."},{"t":"Zu ihr zählen Zusammenhangsmaße, die Zusammenhänge zwischen zwei oder mehreren Variablen beschreiben.","c":true,"fb":"Dazu gehören Kovarianz und Korrelationskoeffizient sowie das Streudiagramm als grafische Darstellung."}],"concept":{"title":"Deskriptive und Inferenzstatistik","points":["<b>Deskriptive Statistik</b>: auch beschreibende Statistik, weil ihre Verfahren die Daten der Stichprobe beschreiben sollen.","<b>Inferenzstatistik</b>: auch schließende Statistik; schließt mithilfe der Wahrscheinlichkeitstheorie von der Stichprobe auf die Population — etwa ob ein Mittelwertsunterschied signifikant ist.","<b>Bestandteil 1</b>: Häufigkeiten einzelner Werte und Häufigkeitsverteilungen.","<b>Bestandteil 2</b>: Kennwerte zur zentralen Tendenz sowie zur Streuung einer Variable.","<b>Bestandteil 3</b>: Zusammenhangsmaße, die Zusammenhänge zwischen zwei oder mehreren Variablen beschreiben.","<b>Bedeutung von „zusammenfassend“</b>: Nicht die einzelnen Werte werden betrachtet, sondern über mehrere bzw. alle Fälle hinweg Aussagen getätigt."]}},{"id":"k3-a929c80fd2","kap":3,"sec":"3.5 Deskriptive Statistik","stem":"Welche Aussagen zu den Maßen der zentralen Tendenz treffen zu?","opts":[{"t":"Der Modalwert ist der Wert mit der größten absoluten Häufigkeit.","c":true,"fb":"Er ist vor allem bei nominalskalierten Variablen aussagekräftig; bei höherem Skalenniveau greift man eher zu Median oder arithmetischem Mittel."},{"t":"Der Median kann erst ab ordinalem Skalenniveau bestimmt werden.","c":true,"fb":"Er halbiert die aufsteigend sortierte Verteilung — dafür braucht es eine Rangordnung, die bei Nominalskalen fehlt."},{"t":"Das arithmetische Mittel ist gegenüber Ausreißern robuster als der Median.","c":false,"fb":"Die Richtung ist umgedreht: Der Median ist der robuste Kennwert. Im Sportbeispiel verdoppelt eine einzelne Leistungssportlerin das arithmetische Mittel von 3 auf 6, während der Median bei 2 bleibt."},{"t":"Die Berechnung des arithmetischen Mittels setzt mindestens Intervallskalenniveau voraus.","c":true,"fb":"Deshalb ist beim ordinalskalierten Bildungsabschluss kein sinnvolles arithmetisches Mittel bildbar."}],"concept":{"title":"Modalwert, Median und arithmetisches Mittel","points":["<b>Modalwert</b>: Wert mit der größten absoluten Häufigkeit; vor allem bei nominalem Skalenniveau aussagekräftig.","<b>Median</b>: der Wert, der die aufsteigend sortierte Verteilung halbiert; erst ab ordinalem Skalenniveau bestimmbar.","<b>Median bei gerader Anzahl</b>: Liegt er zwischen zwei Werten, gilt in der Regel das arithmetische Mittel der beiden mittleren Werte.","<b>Arithmetisches Mittel</b>: Summe aller Werte geteilt durch deren Anzahl; setzt mindestens Intervallskalenniveau voraus.","<b>Ausreißerrobustheit</b>: Der <i>Median</i> ist robust gegenüber Ausreißern, nicht das arithmetische Mittel.","<b>Sport-Beispiel</b>: [1, 2, 2, 5, 5] und [1, 2, 2, 5, 20] haben beide den Median 2, aber die Mittelwerte 3 und 6 — eine einzelne Person verdoppelt den Durchschnitt."]}},{"id":"k3-67f0e2455a","kap":3,"sec":"3.5 Deskriptive Statistik","stem":"Welche Aussagen zu Kovarianz und Korrelationskoeffizient treffen zu?","opts":[{"t":"Der Korrelationskoeffizient ist das standardisierte Maß der Kovarianz und nimmt Werte zwischen −1 und 1 an.","c":true,"fb":"Er entsteht, indem die Kovarianz durch das Produkt der beiden Standardabweichungen dividiert wird."},{"t":"Er quantifiziert den Grad des linearen Zusammenhangs und eignet sich nicht für nichtlineare, etwa U-förmig verlaufende Zusammenhänge.","c":true,"fb":"Linear heißt: Mit zunehmender Ausprägung der einen Variable verändert sich die andere in eine Richtung, nicht abwechselnd."},{"t":"Ein Korrelationskoeffizient von 0 belegt, dass zwischen den beiden Variablen überhaupt kein Zusammenhang besteht.","c":false,"fb":"Er besagt nur, dass kein linearer Zusammenhang vorliegt. Ein U-förmiger Zusammenhang bliebe davon unberührt."},{"t":"Die Kovarianz hängt von den Einheiten der beiden Variablen ab; Gewicht in Gramm führt daher zu einer anderen Kovarianz als Gewicht in Kilogramm.","c":true,"fb":"Genau diese Einheitenabhängigkeit ist der Grund für die Standardisierung zum Korrelationskoeffizienten."}],"concept":{"title":"Kovarianz und Korrelationskoeffizient","points":["<b>Streudiagramm</b>: erste grafische Annäherung; jeder Punkt repräsentiert eine Versuchseinheit, in der Psychologie in der Regel eine Person.","<b>Kovarianz</b>: Produkt der Abstände beider Variablen von ihren jeweiligen Mittelwerten, aufsummiert und durch die Anzahl der Versuchseinheiten geteilt.","<b>Schwäche der Kovarianz</b>: Sie hängt von den Einheiten ab — Gewicht in Gramm liefert eine andere Kovarianz als Gewicht in Kilogramm.","<b>Korrelationskoeffizient r</b>: standardisiertes Maß der Kovarianz, berechnet als Kovarianz geteilt durch das Produkt der beiden Standardabweichungen; Wertebereich −1 bis 1.","<b>Was r <i>nicht</i> kann</b>: nichtlineare, etwa U-förmige Zusammenhänge quantifizieren. Ein r von 0 bedeutet daher nur, dass kein <i>linearer</i> Zusammenhang vorliegt.","<b>Einkreis-Faustregel</b>: Je kreisförmiger die Punktwolke, desto geringer die Korrelation; je schmaler die Ellipse, desto höher. Bei perfekter Korrelation liegen alle Punkte auf einer Linie."]}},{"id":"k3-229c4fc484","kap":3,"sec":"3.5 Deskriptive Statistik","stem":"Welche Aussage zu den Maßen der Streuung trifft zu?","opts":[{"t":"Die Standardabweichung ist das Quadrat der Varianz.","c":false,"fb":"Sie ist die Wurzel der Varianz: SD = √Var. Für die Reaktionszeiten mit Var = 1480 ergibt das rund 38,47 ms."},{"t":"Für nominalskalierte Daten lässt sich der Interquartilsabstand als Streuungsmaß berechnen.","c":false,"fb":"Bei Nominalskalen ist gar kein Streuungsmaß berechenbar, weil zwischen den Ausprägungen keine Kleiner-größer-Beziehung besteht. Der IQA setzt mindestens Ordinalskalenniveau voraus."},{"t":"Der Interquartilsabstand gibt an, wie breit der Bereich ist, in dem die mittleren 50 % der Verteilung liegen.","c":true,"fb":"Er wird als Differenz Q3 − Q1 gebildet; bei ungerader Stichprobenanzahl wird der Median zu beiden Hälften mitgezählt."},{"t":"Je stärker die Werte streuen, desto besser repräsentiert der Mittelwert die Verteilung.","c":false,"fb":"Umgekehrt: Je mehr Streuung vorliegt, desto weniger repräsentiert der Mittelwert die Verteilung."}],"concept":{"title":"Interquartilsabstand, Varianz und Standardabweichung","points":["<b>Funktion von Streuungsmaßen</b>: Sie geben an, wie stark die Werte voneinander abweichen. Je mehr Streuung, desto <i>weniger</i> repräsentiert der Mittelwert die Verteilung.","<b>Nominalskala</b>: Kein Streuungsmaß möglich, weil zwischen den Ausprägungen keine Kleiner-Größer-Beziehung besteht.","<b>Interquartilsabstand (IQA)</b>: ab ordinalem Niveau berechenbar; Q3 − Q1, also die Breite des Bereichs, in dem die mittleren 50 % der Verteilung liegen.","<b>Varianz</b>: Summe der quadrierten Abweichungen aller Werte vom arithmetischen Mittel, geteilt durch die Gesamtanzahl N.","<b>Standardabweichung</b>: die <i>Wurzel</i> der Varianz — SD = √Var, nicht das Quadrat.","<b>Skalenvoraussetzung</b>: Varianz und Standardabweichung erfordern mindestens Intervallskalenniveau (Bortz & Schuster, 2010)."]}},{"id":"k4-89a690f73b","kap":4,"sec":"4.1 Was ist Biologische Psychologie","stem":"Welche Aussagen zur Einordnung und Abgrenzung der Biologischen Psychologie treffen zu?","opts":[{"t":"Der Begriff Biopsychologie ist eine Kurzform und wird gleichbedeutend mit Biologischer Psychologie gebraucht.","c":true,"fb":"Zutreffend. Das Skript führt Biopsychologie ausdrücklich als synonyme Kurzbezeichnung ein – hier gibt es keinen inhaltlichen Unterschied."},{"t":"Die Psychobiologie untersucht die Auswirkungen biologischer Prozesse auf Erleben und Verhalten und ist ein Teilgebiet der Psychologie.","c":false,"fb":"Nicht zutreffend. Der Gegenstand ist richtig beschrieben, die Zuordnung nicht: Die Psychobiologie zählt zur Biologie. Genau diese Verschiebung um eine Ebene ist der Prüfpunkt."},{"t":"Die Neurowissenschaften bilden ein übergeordnetes interdisziplinäres Forschungsfeld, an dem unter anderem Medizin, Biologie, Physik und Chemie beteiligt sind.","c":true,"fb":"Zutreffend. Die Biologische Psychologie ist Teil dieses Feldes – nicht umgekehrt."},{"t":"Weil die Biologische Psychologie grundlagenwissenschaftlich ausgerichtet ist, greifen anwendungsnähere Fächer wie die Klinische Psychologie nicht auf ihre Befunde zurück.","c":false,"fb":"Nicht zutreffend – die Richtung ist umgedreht. Gerade Klinische und Allgemeine Psychologie bedienen sich am Wissen der Biologischen Psychologie."}],"concept":{"title":"Biologische Psychologie und ihre Nachbarbegriffe","points":["<b>Biologische Psychologie</b>: Teilgebiet der Psychologie, das die Beziehung zwischen physischen Merkmalen, Zuständen und Prozessen einerseits und psychischen Zuständen andererseits erforscht (Schröger, Grimm & Müller, 2022).","<b>Biopsychologie</b>: reine Kurzform, synonym zu Biologischer Psychologie gebraucht.","<b>Psychobiologie</b>: befasst sich mit den psychologischen Auswirkungen biologischer Prozesse, ist aber ein Teilgebiet der <i>Biologie</i> — genau diese Zuordnung ist der Prüfpunkt.","<b>Neurowissenschaften</b>: übergeordnetes interdisziplinäres Forschungsfeld zu Aufbau und Funktionsweise des Nervensystems; beteiligt sind u. a. Medizin, Biologie, Physik und Chemie (Bear et al., 2018).","<b>Richtung der Nutzung</b>: Die Biologische Psychologie ist grundlagenwissenschaftlich; anwendungsnähere Fächer wie Klinische und Allgemeine Psychologie bedienen sich an ihrem Wissen."]}},{"id":"k4-3140569b0b","kap":4,"sec":"4.1 Was ist Biologische Psychologie","stem":"Welche Aussage beschreibt die Psychophysiologie zutreffend?","opts":[{"t":"Sie erklärt neuronale Mechanismen des Verhaltens möglichst direkt, meist über elektrische Stimulation oder chirurgische Eingriffe, häufig im Tierversuch.","c":false,"fb":"Nicht zutreffend: Das ist die Physiologische Psychologie. Der invasive Zugriff ist das Unterscheidungsmerkmal."},{"t":"Sie untersucht die psychologischen Folgen von Hirnschädigungen und entwickelt daraus diagnostische Instrumente und Rehabilitationsmaßnahmen.","c":false,"fb":"Nicht zutreffend: Das beschreibt die Neuropsychologie, den stark anwendungsorientierten Teilbereich."},{"t":"Sie untersucht am Menschen mit nicht-invasiven Verfahren wie dem EEG den Zusammenhang zwischen physiologischer Aktivität und psychologischen Prozessen.","c":true,"fb":"Zutreffend. Nicht-invasiv und am Menschen – das ist der Kern der Psychophysiologie."},{"t":"Ihre Forschungsgegenstände sind ausschließlich bildgebende Maße der Gehirnaktivität; periphere Maße spielen keine Rolle.","c":false,"fb":"Nicht zutreffend. Muskelspannung, Augenbewegungen und Herzrate gehören ausdrücklich dazu; Bildgebung ist eher die Domäne der Kognitiven Neurowissenschaft."}],"concept":{"title":"Die sechs Teilbereiche nach Pinel, Barnes und Pauli (2019)","points":["<b>Physiologische Psychologie</b>: erklärt neuronale Mechanismen möglichst direkt — elektrische Stimulation oder chirurgische Eingriffe, häufig im Tierversuch. Der invasive Zugriff ist das Unterscheidungsmerkmal.","<b>Neuropsychologie</b>: untersucht am Menschen die psychologischen Auswirkungen von Hirnschädigungen; stark anwendungsorientiert mit diagnostischen Instrumenten und Rehabilitationsmaßnahmen.","<b>Psychophysiologie</b>: Zusammenhang physiologischer Aktivität und psychologischer Prozesse am Menschen, nicht-invasiv (z. B. EEG). Auch periphere Maße wie Muskelspannung, Augenbewegungen und Herzrate; typische Themen sind Stress, Emotion, biologische Rhythmen.","<b>Kognitive Neurowissenschaft</b>: junger Bereich, erforscht neuronale Grundlagen der Kognition; Domäne der funktionellen und strukturellen Bildgebung (z. B. MRT).","<b>Psychopharmakologie</b>: Manipulation neuronaler Aktivität und des Verhaltens durch Medikamente und Drogen; interdisziplinär mit Ärzt:innen und Pharmakolog:innen.","<b>Vergleichende Psychologie</b>: vergleicht das Verhalten verschiedener Spezies, um Evolution, Genetik und adaptives Verhalten zu verstehen."]}},{"id":"k4-1663738142","kap":4,"sec":"4.1 Was ist Biologische Psychologie","stem":"Welche Aussagen zu den klassischen Einzelfällen der Hirnforschung treffen zu?","opts":[{"t":"Phineas Gage erlitt 1848 eine Verletzung des linken vorderen Frontallappens; sein Verhalten veränderte sich danach deutlich, während Wahrnehmung, Gedächtnis und Intelligenz intakt blieben.","c":true,"fb":"Zutreffend. Genau dieses Auseinanderfallen von erhaltener Kognition und verändertem Sozialverhalten machte den Fall so folgenreich."},{"t":"Paul Broca schloss aus dem Fall „Tan“, dass der betroffene Bereich der linken Hemisphäre für das Sprachverständnis entscheidend sein müsse.","c":false,"fb":"Nicht zutreffend. Die Hemisphäre stimmt, die Funktion nicht: Broca schloss auf die Sprachproduktion. Das Verständnis war bei „Tan“ ja erhalten."},{"t":"Gage verlor die Sehfähigkeit auf dem linken Auge und seine linke Gesichtshälfte war teilweise gelähmt; Sprache, Haltung und Bewegung blieben intakt.","c":true,"fb":"Zutreffend. Die körperlichen Folgen waren erstaunlich gering – Gage sprach bereits wenige Minuten nach dem Unfall wieder."},{"t":"Bei der Broca-Aphasie kommt es zu einem teilweisen Verlust der Sprachproduktion, während das Sprachverständnis weitgehend erhalten bleibt.","c":true,"fb":"Zutreffend. „Teilweise“ und „weitgehend“ sind hier keine Abschwächung, sondern die korrekte Beschreibung des Störungsbildes."}],"concept":{"title":"Phineas Gage und Patient „Tan“","points":["<b>Gage 1848</b>: Eine Eisenstange durchfuhr bei einer Explosion seinen Schädel — Eintritt unterhalb des linken Wangenknochens, Austritt oben am Kopf. Untersucht wurde er von John Harlow.","<b>Körperliche Folgen bei Gage</b>: Verlust der Sehfähigkeit auf dem linken Auge, teilweise Lähmung der linken Gesichtshälfte. Sprache, Haltung und Bewegung blieben intakt — er sprach bereits wenige Minuten nach dem Unfall wieder.","<b>Das Auffällige</b>: Wahrnehmung, Gedächtnis und Intelligenz blieben völlig intakt, doch das Verhalten änderte sich deutlich — von freundlich und rücksichtsvoll zu rücksichtslos, impulsiv, obszön und unzuverlässig.","<b>Betroffenes Areal</b>: der linke vordere Frontallappen, heute u. a. mit Handlungsplanung und Impulskontrolle assoziiert (Sevmez, Adanir & Ince, 2022).","<b>Patient „Tan“</b>: konnte nur noch „tan“ sagen, verstand Gesprochenes aber weiterhin. Paul Broca (1824–1880) fand nach dem Tod eine Auffälligkeit in der linken Hemisphäre.","<b>Brocas Schluss</b>: Der Bereich ist für die <i>Sprachproduktion</i> entscheidend — nicht für das Verständnis. Bei der Broca-Aphasie kommt es zum teilweisen Verlust der Sprachproduktion bei weitgehend erhaltenem Sprachverständnis (Domanski, 2013)."]}},{"id":"k4-44ef7da363","kap":4,"sec":"4.2.1 Bausteine des Nervensystems","stem":"Welche Aussagen über Neuronen treffen zu?","opts":[{"t":"Sensorische Neuronen veranlassen Muskeln zur Kontraktion oder Entspannung und rufen so Bewegungen hervor.","c":false,"fb":"Nicht zutreffend: Das leisten Motoneuronen. Sensorische Neuronen nehmen Information aus Umwelt und Körperinnerem auf."},{"t":"Neuere Untersuchungen schätzen die Zahl der Neuronen im menschlichen Gehirn auf etwa 86 Milliarden.","c":true,"fb":"Zutreffend. Die lange genannten 100 Milliarden gelten als überholt; achten Sie darauf, welche Zahl als „neuer“ ausgewiesen wird."},{"t":"Weil viele neurowissenschaftliche Studien nur männliche Probanden untersucht haben, spricht man vom Gender Data Gap – einer fehlenden Datenerhebung für ein Geschlecht.","c":true,"fb":"Zutreffend. Diese Fußnote ist mit Ziffer gekennzeichnet und damit prüfungsrelevant."},{"t":"Die Neuronendichte variiert deutlich zwischen den Gehirnregionen; im Kleinhirn ist sie beispielsweise höher als im Großhirn.","c":true,"fb":"Zutreffend. Merken Sie sich die Richtung: Kleinhirn dichter besiedelt als Großhirn."}],"concept":{"title":"Die drei Neuronenarten und die Zahlen dahinter","points":["<b>Sensorische Neuronen</b>: nehmen Information aus Umwelt oder Körperinnerem auf, indem sie auf spezifischen Input reagieren.","<b>Interneuronen</b>: kommunizieren innerhalb des Nervensystems mit anderen Neuronen und integrieren Informationen.","<b>Motoneuronen</b>: rufen Bewegungen hervor, indem sie Muskeln zur Kontraktion oder Entspannung veranlassen.","<b>Anzahl</b>: Lange galten 100 Milliarden Neuronen als Durchschnittswert; neuere Untersuchungsmethoden schätzen etwa 86 Milliarden.","<b>Gender Data Gap</b>: Wie in vielen neurowissenschaftlichen Studien wurden dabei nur Gehirne männlicher Probanden untersucht — gemeint ist eine fehlende Datenerhebung für ein Geschlecht. Diese Fußnote ist mit Ziffer gekennzeichnet und damit prüfungsrelevant.","<b>Dichte</b>: variiert deutlich zwischen Regionen — im Kleinhirn höher als im Großhirn (Lent et al., 2012)."]}},{"id":"k4-7a081a5224","kap":4,"sec":"4.2.1 Bausteine des Nervensystems","stem":"Welche Aussage zum Aufbau eines typischen Neurons ist korrekt?","opts":[{"t":"Die Dendriten sind im Allgemeinen deutlich länger als das Axon und entspringen an zahlreichen Stellen des Somas.","c":false,"fb":"Nicht zutreffend. Der zweite Halbsatz stimmt, die Längenangabe ist umgedreht: Dendriten sind in der Regel viel kürzer als Axone."},{"t":"Das Ende eines Axons wird als Axonhügel bezeichnet; dort findet die Informationsweitergabe an andere Zellen statt.","c":false,"fb":"Nicht zutreffend – hier werden zwei Orte verwechselt. Der Axonhügel liegt am Austritt aus dem Zellkörper; das Ende heißt Axonterminale bzw. Synapsenendknöpfchen."},{"t":"Im Zellkern, auch Nucleus genannt, befinden sich die Golgi-Apparate und Ribosomen des Neurons.","c":false,"fb":"Nicht zutreffend. Im Zellkern liegt die genetische Information (DNA); Golgi-Apparate und Ribosomen sind Organellen im Soma."},{"t":"Die Zellmembran besteht aus einer Lipid-Doppelschicht, in die zahlreiche Proteinmoleküle eingebettet sind.","c":true,"fb":"Zutreffend. Diese Proteine sind die Grundlage für Ionenkanäle, Pumpen und Rezeptoren – also für praktisch alles Weitere im Kapitel."}],"concept":{"title":"Aufbau eines typischen Neurons","points":["<b>Zellmembran</b>: grenzt das Neuron ab, besteht aus einer Lipid-Doppelschicht mit eingebetteten Proteinmolekülen, die die Basis vieler Membranfunktionen bilden.","<b>Soma (Zellkörper, Perikaryon)</b>: enthält den Zellkern sowie zumeist zahlreiche Organellen wie Mitochondrien, Golgi-Apparate und Ribosomen.","<b>Zellkern (Nucleus)</b>: hier ist die komplette genetische Information (DNA) gespeichert — die Organellen liegen im Soma, nicht im Zellkern.","<b>Axon</b>: transportiert Information weg vom Zellkörper hin zu den Endknöpfchen; tritt am Axonhügel aus dem Soma aus. Länge von unter 1 Millimeter bis über 1 Meter.","<b>Axonterminale / Synapsenendknöpfchen</b>: das <i>Ende</i> des Axons, dort findet die Informationsweitergabe statt — nicht zu verwechseln mit dem Axonhügel am Anfang.","<b>Dendriten</b>: im Allgemeinen sehr viel <i>kürzer</i> als die Axone, entspringen an zahlreichen Stellen des Somas und dienen dem Empfang von Informationen (Schandry, 2016)."]}},{"id":"k4-8ebdef261f","kap":4,"sec":"4.2.1 Bausteine des Nervensystems","stem":"Welche Aufgaben von Gliazellen werden im Kapitel genannt?","opts":[{"t":"Sie lösen an der präsynaptischen Membran die Exocytose aus, indem sie Calciumionen in die Axonterminale schleusen.","c":false,"fb":"Nicht zutreffend. Der Calciumeinstrom erfolgt über spannungsgesteuerte Calciumkanäle des Neurons selbst – Gliazellen sind daran nicht beteiligt."},{"t":"Sie bereiten Nährstoffe für Neuronen auf und entsorgen zelluläres Abfallmaterial beschädigter oder abgestorbener Neuronen.","c":true,"fb":"Zutreffend. Beteiligung am Gehirnstoffwechsel ist eine der Kernaufgaben."},{"t":"Nach heutigem Kenntnisstand beschränkt sich ihre Rolle auf eine stützende Funktion für die Neuronen.","c":false,"fb":"Nicht zutreffend. Das war die frühere Annahme; heute kennt man deutlich mehr Funktionen – daher auch der Name „vergessene Zellen“."},{"t":"Sie können überschüssige Neurotransmitter und andere Substanzen aus dem synaptischen Spalt aufnehmen.","c":true,"fb":"Zutreffend. Astrozyten bauen aufgenommene Transmitter ab und geben die Abbauprodukte an die Neurone zurück."}],"concept":{"title":"Gliazellen — die „vergessenen Zellen“","points":["<b>Überholte Sicht</b>: Früher galten sie vorrangig als Stützzellen; heute weiß man, dass sie an deutlich mehr Prozessen beteiligt sind (Allen & Lyons, 2018).","<b>Embryonale Entwicklung</b>: Sie unterstützen neu gebildete Neuronen dabei, den richtigen Ort im Gehirn zu finden.","<b>Stoffwechsel</b>: Sie bereiten Nährstoffe für Neuronen auf und entsorgen zelluläres Abfallmaterial beschädigter oder abgestorbener Neuronen.","<b>Synaptischer Spalt</b>: Sie nehmen überschüssige Neurotransmitter und andere Substanzen auf.","<b>Blut-Hirn-Schranke</b>: Astrozyten umgeben die Blutgefäße im Gehirn mit Fett, sodass nicht fettlösliche Giftstoffe die Barriere nicht überwinden.","<b>Neuronale Kommunikation</b>: Vermutet wird eine aktive Rolle, indem sie die Konzentration jener Ionen beeinflussen, die die Übertragung von Nervenimpulsen ermöglichen (Gerrig et al., 2018)."]}},{"id":"k4-ae76df1444","kap":4,"sec":"4.2.1 Bausteine des Nervensystems","stem":"Welche Aussage über Myelin und myelinbildende Zellen ist zutreffend?","opts":[{"t":"Im zentralen Nervensystem bilden Oligodendrozyten das Myelin; im peripheren Nervensystem übernehmen Schwann-Zellen eine vergleichbare Funktion.","c":true,"fb":"Zutreffend. Merkhilfe: Oligodendrozyt = ZNS, Schwann-Zelle = PNS."},{"t":"Ein Oligodendrozyt bildet stets nur ein einziges Myelinsegment, während eine Schwann-Zelle mehrere Segmente an verschiedenen Axonen myelinisieren kann.","c":false,"fb":"Nicht zutreffend – die beiden Zelltypen sind vertauscht. Der Oligodendrozyt bildet mehrere Segmente, oft an mehr als einem Axon; jede Schwann-Zelle nur eines."},{"t":"Die Myelinschicht überzieht das Axon lückenlos; die Ranvier-Schnürringe liegen unterhalb der Myelinsegmente.","c":false,"fb":"Nicht zutreffend. Die Schicht besteht aus Segmenten, und die Ranvier-Schnürringe sind genau die unmyelinisierten Stellen dazwischen."},{"t":"Neuere Studien bestätigen das Verhältnis von etwa zehn Gliazellen pro Neuron im Nervensystem.","c":false,"fb":"Nicht zutreffend. Dieses Verhältnis gilt als Überschätzung; neuere Studien gehen von etwa gleich vielen Gliazellen wie Neuronen aus."}],"concept":{"title":"Myelin, Ranvier-Schnürringe und die Zahlenverhältnisse","points":["<b>Myelin</b>: Schutzschicht aus Fett um einige Arten von Axonen; auch Markscheide, Myelinscheide oder Myelinschicht genannt.","<b>Doppelte Wirkung</b>: Schutz vor mechanischer Beanspruchung und deutliche Erhöhung der Leitungsgeschwindigkeit (Schandry, 2016).","<b>Ranvier-Schnürringe</b>: die unmyelinisierten Stellen <i>zwischen</i> den Myelinsegmenten — die Schicht ist also nicht durchgängig.","<b>Oligodendrozyten</b>: bilden das Myelin im zentralen Nervensystem; ein Oligodendrozyt kann <i>mehrere</i> Myelinsegmente bilden, oft an mehr als einem Axon.","<b>Schwann-Zellen</b>: vergleichbare Funktion im peripheren Nervensystem; jede Schwann-Zelle bildet nur <i>ein</i> Myelinsegment (Pinel et al., 2019).","<b>Anzahl der Gliazellen</b>: Das früher angenommene Verhältnis von zehn zu eins gilt als Überschätzung — neuere Studien gehen von etwa gleich vielen Gliazellen wie Neuronen aus. Im Kleinhirn weniger Gliazellen als Neuronen, im Großhirn mehr."]}},{"id":"k4-06605606ec","kap":4,"sec":"4.2.2 Ruhe- und Aktionspotenzial","stem":"Welche Aussagen zum Ruhepotenzial treffen zu?","opts":[{"t":"Das Membranpotenzial liegt im Ruhezustand bei etwa −70 Millivolt; die intrazelluläre Flüssigkeit ist gegenüber der extrazellulären negativ geladen.","c":true,"fb":"Zutreffend. Diese negative Ladung im Zellinneren bedeutet: Das Neuron ist elektrisch polarisiert."},{"t":"Natrium- und Chloridionen liegen in hoher Konzentration im Zellinneren vor, Kaliumionen dagegen im Zelläußeren.","c":false,"fb":"Nicht zutreffend – die Verteilung ist genau umgedreht. Natrium und Chlorid überwiegen außen, Kalium innen."},{"t":"Im Ruhezustand ist die Zellmembran hoch permeabel für Chlorid- und Kaliumionen, für Natriumionen dagegen nur sehr gering.","c":true,"fb":"Zutreffend. Die geringe Natrium-Permeabilität ist der Grund, warum die außen wartenden Natriumionen nicht einfach einströmen."},{"t":"Ionenkanäle sind in der Regel nur für einen bestimmten Ionentyp durchlässig.","c":true,"fb":"Zutreffend. Durch einen Kalium-Ionenkanal passieren Kaliumionen, andere Ionen nicht."}],"concept":{"title":"Das Ruhepotenzial und die Verteilung der Ionen","points":["<b>Membranpotenzial</b>: Spannungsunterschied an der Membran durch unterschiedliche Ionenkonzentrationen innen und außen.","<b>Ruhewert</b>: etwa −70 Millivolt — die intrazelluläre Flüssigkeit ist gegenüber der extrazellulären negativ geladen, das Neuron ist polarisiert.","<b>Außen hoch konzentriert</b>: positiv geladene Natriumionen (sehr hoch) und negativ geladene Chloridionen.","<b>Innen hoch konzentriert</b>: positiv geladene Kaliumionen (sehr hoch).","<b>Selektive Permeabilität</b>: Im Ruhezustand ist die Membran hoch permeabel für Chlorid- und Kaliumionen, für Natriumionen dagegen sehr gering.","<b>Ionenkanäle</b>: können offen oder geschlossen sein und sind in der Regel nur für einen bestimmten Ionentyp durchlässig (Schandry, 2016)."]}},{"id":"k4-d4d776e745","kap":4,"sec":"4.2.2 Ruhe- und Aktionspotenzial","stem":"Welche Aussage zu den Prozessen, die das Ruhepotenzial erzeugen und aufrechterhalten, ist korrekt?","opts":[{"t":"Die Natrium-Kalium-Pumpe transportiert zwei Natriumionen nach außen und drei Kaliumionen nach innen.","c":false,"fb":"Nicht zutreffend – die Zahlen sind vertauscht. Drei Natriumionen hinaus, zwei Kaliumionen hinein."},{"t":"Diffusion bezeichnet die Bewegung von Ionen aus Bereichen niedriger Konzentration hin zu Bereichen hoher Konzentration.","c":false,"fb":"Nicht zutreffend. Die Richtung ist umgedreht: von hoher zu niedriger Konzentration, also in Richtung gleichmäßiger Verteilung."},{"t":"Auf die Natriumionen wirken Konzentrations- und Potenzialgradient in dieselbe Richtung: Beide treiben sie in das Zellinnere.","c":true,"fb":"Zutreffend. Genau deshalb braucht es die überwiegend geschlossenen Natriumkanäle und zusätzlich die Pumpe."},{"t":"Für die Kaliumionen in der intrazellulären Flüssigkeit besteht ein besonders starkes Bestreben, dem Potenzialgradienten zu folgen, weil sie dem Membranpotenzial entgegenstehen.","c":false,"fb":"Nicht zutreffend. Kaliumionen innen und Chloridionen außen sind bereits im Einklang mit dem Membranpotenzial – für sie besteht dieses Bestreben gerade nicht."}],"concept":{"title":"Die vier Prozesse hinter dem Ruhepotenzial","points":["<b>1. Selektive Permeabilität</b>: Natriumionen können trotz hoher Außenkonzentration im Ruhezustand kaum ins Zellinnere gelangen.","<b>2. Konzentrationsgradient</b>: Teilchen tendieren zu gleichmäßiger Verteilung und wandern von hoher zu niedriger Konzentration — diese Bewegung heißt Diffusion.","<b>3. Potenzialgradient</b>: Die Ionen streben danach, den Spannungsunterschied auszugleichen. Für Natriumionen außen bedeutet das: hinein. Kaliumionen innen und Chloridionen außen haben dieses Bestreben nicht, da sie bereits im Einklang mit dem Membranpotenzial stehen.","<b>Zusammenwirken bei Natrium</b>: Konzentrations- und Potenzialgradient wirken in <i>dieselbe</i> Richtung — beide treiben Natrium ins Zellinnere.","<b>4. Natrium-Kalium-Pumpe</b>: befördert unter Energieaufwand drei Natriumionen hinaus und zwei Kaliumionen hinein. Merkrichtung: 3 raus, 2 rein.","<b>Warum Kalium konstant bleibt</b>: Da die Membran für Kalium hoch permeabel ist, diffundiert es durch die offenen Kanäle wieder hinaus — über die Zeit ändert sich die Kaliumkonzentration nicht."]}},{"id":"k4-157eb8b334","kap":4,"sec":"4.2.2 Ruhe- und Aktionspotenzial","stem":"Welche Aussagen zur Auslösung eines Aktionspotenzials sind zutreffend?","opts":[{"t":"Überschreitet das integrierte Gesamtsignal einen Schwellenwert von etwa −55 mV, wird ein Aktionspotenzial ausgelöst.","c":true,"fb":"Zutreffend. Entscheidend ist die Integration, also die Zusammenfassung aller Signale an Dendriten und Soma."},{"t":"Inhibitorische Signale senken die Polarisation der Membran und erhöhen die Feuerwahrscheinlichkeit des Neurons.","c":false,"fb":"Nicht zutreffend – das beschreibt exzitatorische Signale. Inhibitorische Signale hyperpolarisieren und senken die Feuerwahrscheinlichkeit."},{"t":"Die Stärke des ausgelösten Aktionspotenzials wächst mit der Intensität der auslösenden Signale.","c":false,"fb":"Nicht zutreffend. Nach dem Alles-oder-Nichts-Gesetz ist ein Aktionspotenzial für eine Zelle immer gleich stark – die Intensität beeinflusst nur, ob es überhaupt ausgelöst wird."},{"t":"Beim Overshoot steigt das Membranpotenzial auf etwa +50 Millivolt an; die intrazelluläre Flüssigkeit ist dann positiv geladen.","c":true,"fb":"Zutreffend. Kurzzeitige Umkehr der Ladungsverhältnisse – von −70 mV auf etwa +50 mV."}],"concept":{"title":"Von der Integration zum Alles-oder-Nichts-Gesetz","points":["<b>Exzitatorische Signale</b>: führen zur Depolarisation — das Membranpotenzial wird weniger negativ und die Feuerwahrscheinlichkeit steigt.","<b>Inhibitorische Signale</b>: führen zur Hyperpolarisation — das Membranpotenzial wird noch negativer und die Feuerwahrscheinlichkeit sinkt.","<b>Integration</b>: Die verschiedenen Signale an Dendriten und Soma werden zu einem Gesamtsignal zusammengefasst.","<b>Schwellenwert</b>: Wird er bei etwa −55 mV überschritten, wird ein Aktionspotenzial ausgelöst.","<b>Alles-oder-Nichts-Gesetz</b>: Unterhalb der Schwelle passiert nichts; oberhalb ist das Aktionspotenzial für eine Zelle immer gleich stark und steht in keiner Beziehung zur Intensität der auslösenden Signale.","<b>Overshoot</b>: massive kurzzeitige Umkehr von −70 auf etwa +50 Millivolt; in dieser Phase ist die intrazelluläre Flüssigkeit positiv geladen."]}},{"id":"k4-e5cffdeb2b","kap":4,"sec":"4.2.2 Ruhe- und Aktionspotenzial","stem":"Welche Aussagen zum zeitlichen Verlauf eines Aktionspotenzials sind korrekt?","opts":[{"t":"Die spannungsgesteuerten Natriumkanäle schließen sich nach circa 1 Millisekunde und gehen in einen inaktivierten Zustand über, in dem sie nicht erneut geöffnet werden können.","c":true,"fb":"Zutreffend. Diese Inaktivierung ist zugleich der Grund, warum das Aktionspotenzial nicht zurückwandern kann."},{"t":"Den Abfall der Polarisierung durch den Ausstrom von Kaliumionen bezeichnet man als Repolarisation.","c":true,"fb":"Zutreffend. Die Kaliumkanäle öffnen mit zeitlicher Verzögerung; positive Ladung verlässt die Zelle."},{"t":"In der absoluten Refraktärphase kann eine erhöhte Erregungsstärke ein zweites Aktionspotenzial herbeiführen.","c":false,"fb":"Nicht zutreffend – das gilt für die relative Refraktärphase. In der absoluten Phase bleibt jede Erregung wirkungslos."},{"t":"Weil sich die spannungsgesteuerten Kaliumkanäle erst nach Erreichen des Ruhepotenzials schließen, kommt es zur Hyperpolarisation.","c":true,"fb":"Zutreffend. Das Membranpotenzial unterschreitet dabei das Ruhepotenzial – die Zelle befindet sich im Nachpotenzial."}],"concept":{"title":"Der zeitliche Verlauf eines Aktionspotenzials","points":["<b>Aufstrich</b>: Die spannungsgesteuerten Natriumkanäle öffnen sich, Natrium strömt massiv ein, das Membranpotenzial steigt — Depolarisation bis zum Overshoot.","<b>Inaktivierung</b>: Die Natriumkanäle schließen sich nach circa 1 Millisekunde und gehen in einen inaktivierten Zustand über, in dem sie nicht erneut geöffnet werden können.","<b>Repolarisation</b>: Mit zeitlicher Verzögerung öffnen die spannungsgesteuerten Kaliumkanäle; der Ausstrom positiver Ladungen lässt das Zellinnere wieder negativ werden.","<b>Hyperpolarisation / Nachpotenzial</b>: Weil die Kaliumkanäle sich erst nach Erreichen des Ruhepotenzials schließen, unterschreitet das Membranpotenzial den Ruhewert.","<b>Absolute Refraktärphase</b>: Zu Beginn ist die Membran überhaupt nicht erregbar — auch eine stärkere Erregung bleibt wirkungslos, die Natriumkanäle sind noch inaktiviert.","<b>Relative Refraktärphase</b>: reicht bis ins Nachpotenzial; nur eine <i>erhöhte</i> Erregungsstärke kann hier ein zweites Aktionspotenzial herbeiführen (Schandry, 2016)."]}},{"id":"k4-4dbd8e056b","kap":4,"sec":"4.2.2 Ruhe- und Aktionspotenzial","stem":"Welche Aussagen zur Erregungsleitung im Axon und zu ihren Störungen treffen zu?","opts":[{"t":"Der Vorteil der passiven Leitung ist, dass das Signal auch über große Entfernungen unverändert stark bleibt.","c":false,"fb":"Nicht zutreffend. Passive Leitung ist zwar sehr schnell, das Signal verringert sich aber mit zunehmender Entfernung – deshalb nur kurze Strecken."},{"t":"In myelinisierten Axonen können Ionen die Membran nur an den Ranvier-Schnürringen passieren; dort werden neue Aktionspotenziale ausgelöst.","c":true,"fb":"Zutreffend. Daher die Formulierung, die Erregung „springe“ von Schnürring zu Schnürring – die saltatorische Erregungsleitung."},{"t":"Bei Multipler Sklerose greift das Immunsystem das Myelin der Axone im zentralen Nervensystem an; diesen Vorgang nennt man Demyelinisierung.","c":true,"fb":"Zutreffend. Folgen sind unter anderem Sehstörungen, Muskelschwäche, Missempfindungen bis hin zu Lähmungen."},{"t":"Multiple Sklerose beginnt typischerweise nach dem 60. Lebensjahr und verläuft ausnahmslos progredient ohne Schübe.","c":false,"fb":"Nicht zutreffend. Häufiger Beginn zwischen dem 20. und 45. Lebensjahr, meist in Schüben; progrediente Verläufe kommen zusätzlich vor, sind aber nicht die Regel."}],"concept":{"title":"Saltatorische Erregungsleitung und Multiple Sklerose","points":["<b>Passive Leitung</b>: sehr schnell, aber das Signal verringert sich mit zunehmender Entfernung — es kann daher nur kurze Strecken zurücklegen.","<b>Saltatorische Erregungsleitung</b>: Im Bereich der Myelinscheiden wird passiv weitergegeben, an den Ranvier-Schnürringen hat die Membran wieder Kontakt zur extrazellulären Flüssigkeit und dort liegen viele Natriumkanäle — die Erregung „springt“ von Schnürring zu Schnürring.","<b>Grenze des Abstands</b>: Die Schnürringe dürfen nicht zu weit auseinanderliegen, sonst erreicht die Potenzialveränderung den nächsten nicht.","<b>Einbahnstraße</b>: Wie das Feuer einer Zündschnur läuft das Aktionspotenzial nur in eine Richtung — die Refraktärphase des bereits durchwanderten Abschnitts verhindert das Zurückwandern.","<b>Multiple Sklerose</b>: Autoimmunerkrankung, bei der das Immunsystem das Myelin der Axone im zentralen Nervensystem angreift; die Zerstörung heißt Demyelinisierung.","<b>Verlauf und Folgen</b>: Beginn häufig zwischen dem 20. und 45. Lebensjahr, meist in Schüben mit möglicher (teilweiser) Remission; es gibt aber auch progrediente Verläufe. Symptome von Sehstörungen und Missempfindungen bis zu Lähmungen. Nicht heilbar, aber medikamentös beeinflussbar."]}},{"id":"k4-6b771fb9de","kap":4,"sec":"4.2.3 Synaptische Übertragung","stem":"Welche Aussagen zur synaptischen Übertragung sind zutreffend?","opts":[{"t":"Bei elektrischen Synapsen stoßen zwei gegenüberliegende Ionenkanäle so aneinander, dass eine Art Röhre entsteht, durch die Ionen und kleine Moleküle wandern können.","c":true,"fb":"Zutreffend. Diese gap junctions erlauben Übertragung in beide Richtungen und arbeiten sehr schnell."},{"t":"Im menschlichen Gehirn läuft die synaptische Übertragung überwiegend über chemische Synapsen.","c":true,"fb":"Zutreffend. Für die Informationsverarbeitung im ZNS spielt die chemische Synapse die weitaus größere Rolle."},{"t":"Trifft ein Aktionspotenzial in der Axonterminale ein, öffnen sich spannungsgesteuerte Calciumkanäle; der Calciumeinstrom lässt die Vesikel mit der Zellmembran verschmelzen.","c":true,"fb":"Zutreffend. Diese Freisetzung des Vesikelinhalts in den synaptischen Spalt heißt Exocytose."},{"t":"Ein Neurotransmitter kann nur dann an ein Rezeptorprotein binden, wenn er aufgrund seiner räumlichen Gestalt zur Bindungsstelle passt.","c":true,"fb":"Zutreffend. Das ist das Schlüssel-Schloss-Prinzip der postsynaptischen Rezeptoren."}],"concept":{"title":"Die chemische synaptische Übertragung Schritt für Schritt","points":["<b>Elektrische Synapsen (gap junctions)</b>: Zwei gegenüberliegende Ionenkanäle stoßen so aneinander, dass eine Art Röhre entsteht; Ionen und kleine Moleküle wandern hindurch. Übertragung in beide Richtungen möglich und sehr schnell.","<b>Chemische Synapsen</b>: Zellmembranen berühren sich nicht; die Übertragung läuft über ausgeschüttete chemische Stoffe. Im menschlichen Gehirn spielt diese Form die weitaus größere Rolle.","<b>Calciumeinstrom</b>: Trifft ein Aktionspotenzial in der Axonterminale ein, öffnen sich spannungsgesteuerte Calciumkanäle; Calciumionen fließen ein und lassen die synaptischen Vesikel mit der Zellmembran verschmelzen.","<b>Exocytose</b>: Die Vesikelmembran fusioniert mit der präsynaptischen Membran, der Inhalt wird in den synaptischen Spalt ausgeschüttet. Die Vesikelmembran wird später zurückgewonnen und neu befüllt.","<b>Schlüssel-Schloss-Prinzip</b>: Ein Neurotransmitter bindet nur dann an ein Rezeptorprotein, wenn er aufgrund seiner räumlichen Gestalt zur Bindungsstelle passt.","<b>Wirkung und Abbau</b>: Natriumkanäle öffnen → exzitatorisches postsynaptisches Potenzial; Kalium- oder Chloridkanäle öffnen → inhibitorisches. Danach überwiegend Wiederaufnahme in die präsynaptischen Endknöpfchen, der Rest wird von Enzymen abgebaut oder von Astrozyten aufgenommen."]}},{"id":"k4-6c8ac13aa6","kap":4,"sec":"4.2.4 Neurotransmitter","stem":"Welche Aussagen über Neurotransmitter sind korrekt?","opts":[{"t":"Glutamat gilt als der wichtigste exzitatorisch wirkende Neurotransmitter im Gehirn und ist der Neurotransmitter der Sinneszellen.","c":true,"fb":"Zutreffend. Glutamat ist zudem an emotionalen Reaktionen, Lernen und Gedächtnis beteiligt."},{"t":"GABA ist der bedeutendste inhibitorisch wirkende Neurotransmitter; Benzodiazepine binden an GABA-Rezeptoren und wirken unter anderem angstlösend.","c":true,"fb":"Zutreffend. Die Effekte sind angstlösend, schlaffördernd und muskelentspannend."},{"t":"Serotonin ist am Übergang zwischen Nerven und Muskeln für die motorische Kontrolle verantwortlich.","c":false,"fb":"Nicht zutreffend – das ist Acetylcholin. Serotonin reguliert unter anderem emotionale Zustände; SSRI hemmen seine Wiederaufnahme."},{"t":"Morbus Parkinson ist das Resultat absterbender dopaminproduzierender Neuronen.","c":true,"fb":"Zutreffend. Passend dazu kann ein Dopaminmangel zu Problemen der Bewegungsfähigkeit führen."}],"concept":{"title":"Die wichtigsten Neurotransmitter","points":["<b>Glutamat</b>: wichtigster exzitatorisch wirkender Neurotransmitter im Gehirn; beteiligt an emotionalen Reaktionen, Lernen und Gedächtnis und Neurotransmitter der Sinneszellen.","<b>GABA</b>: bedeutendster inhibitorisch wirkender Neurotransmitter, vor allem im Gehirn. Benzodiazepine binden an GABA-Rezeptoren und wirken angstlösend, schlaffördernd und muskelentspannend.","<b>Dopamin</b>: bei Motivations- und Belohnungsprozessen beteiligt; ein Mangel führt zu Problemen der Bewegungsfähigkeit. Morbus Parkinson resultiert aus absterbenden dopaminproduzierenden Neuronen (Dauer & Przedborski, 2003).","<b>Serotonin</b>: wichtig bei der Regulation emotionaler Zustände. SSRI hemmen die Wiederaufnahme aus dem synaptischen Spalt und werden häufig bei Depressionen verabreicht.","<b>Acetylcholin</b>: am Übergang zwischen Nerven und Muskeln für die motorische Kontrolle verantwortlich; zusätzlich an Lernen, Gedächtnis, Schlaf und Träumen beteiligt.","<b>Noradrenalin</b>: chemisch eine Vorstufe zu Adrenalin und als aktivierender Neurotransmitter an physiologischer Erregung und Wachheit beteiligt."]}},{"id":"k4-cef5f00a1a","kap":4,"sec":"4.3.1–4.3.2 Anatomie & Rückenmark","stem":"Welche Aussagen zu den anatomischen Lage- und Orientierungsbezeichnungen treffen zu?","opts":[{"t":"Auf das Gehirn bezogen bedeutet dorsal „Richtung Kopfoberseite“ und ventral „Richtung Kopfunterseite“.","c":true,"fb":"Zutreffend. Beim Gehirn gibt es zwischen Mensch und Hund keine Unterschiede – verschoben haben sich nur die Bezeichnungen am Rumpf."},{"t":"Medial bezeichnet Strukturen, die relativ weit von der Mittellinie des Körpers entfernt liegen.","c":false,"fb":"Nicht zutreffend – das ist lateral. Medial heißt nahe der Mittellinie; die Nase liegt medial zu den Augen."},{"t":"Ipsilateral bezeichnet eine Struktur auf der gegenüberliegenden Körperseite.","c":false,"fb":"Nicht zutreffend – das Begriffspaar ist vertauscht. Ipsilateral heißt gleiche Seite, kontralateral gegenüberliegende Seite."},{"t":"Beim Rumpf des Menschen zeigen dorsal und posterior in dieselbe Richtung, während im Gehirn unterschiedliche Richtungen gemeint sind.","c":true,"fb":"Zutreffend. Diese Verschiebung durch den aufrechten Gang ist der Grund für die Zusatzbegriffe superior und inferior."}],"concept":{"title":"Anatomische Lage- und Orientierungsbezeichnungen","points":["<b>dorsal / ventral am Gehirn</b>: dorsal = Richtung Kopfoberseite, ventral = Richtung Kopfunterseite.","<b>dorsal / ventral am Rumpf</b>: dorsal = Richtung Rücken, ventral = Richtung Brustkorb.","<b>anterior / posterior</b>: anterior = vorne (am Gehirn Richtung Nase, am Rumpf Richtung Brustkorb), posterior = hinten (am Gehirn Richtung Hinterhaupt, am Rumpf Richtung Rücken).","<b>Die Verschiebung durch den aufrechten Gang</b>: Beim menschlichen Rumpf zeigen dorsal und posterior sowie ventral und anterior in dieselbe Richtung — im Gehirn dagegen in unterschiedliche. Deshalb gibt es zusätzlich superior (Richtung Kopf) und inferior (Richtung Füße).","<b>medial / lateral</b>: medial = nahe der Mittellinie des Körpers (die Nase liegt medial zu den Augen), lateral = weit davon entfernt, seitlich.","<b>kontralateral / ipsilateral</b>: kontralateral = gegenüberliegende Körperseite, ipsilateral = gleiche Körperseite. Die Nerven der Sehbahn sind kontralateral verschaltet."]}},{"id":"k4-c8cb3ccd44","kap":4,"sec":"4.3.1–4.3.2 Anatomie & Rückenmark","stem":"Welche Aussagen über das Rückenmark und die Spinalnerven sind zutreffend?","opts":[{"t":"Das Rückenmark hat eine annähernd zylindrische Form und ist beim Menschen etwa 70–75 cm lang.","c":false,"fb":"Nicht zutreffend. Die Form stimmt, die Länge nicht: etwa 40–45 cm."},{"t":"Jeder Spinalnerv versorgt nicht nur sein eigenes Dermatom, sondern auch Teile der beiden benachbarten Dermatome.","c":true,"fb":"Zutreffend. Diese Überlappung ist der Grund, warum eine Schädigung eines Spinalnervs keinen völligen Sensibilitätsausfall nach sich zieht."},{"t":"Bei Reflexen werden Signale bereits im Rückenmark verarbeitet, sodass Muskel- oder Drüsenaktivitäten ohne Umweg über das Gehirn ausgelöst werden.","c":true,"fb":"Zutreffend. Bekanntestes Beispiel ist der Patellarsehnenreflex."},{"t":"Bei Schädigung eines einzelnen Spinalnervs kommt es zum vollständigen Sensibilitätsausfall des zugehörigen Dermatoms.","c":false,"fb":"Nicht zutreffend. Wegen der Mitversorgung durch benachbarte Spinalnerven bleibt ein Restempfinden erhalten."}],"concept":{"title":"Rückenmark, Spinalnerven und Dermatome","points":["<b>Aufgabe des ZNS</b>: Integration und Koordination aller körperlichen Funktionen — Verarbeitung eintreffender Information, deren Integration und das Senden von Signalen.","<b>Rückenmark</b>: im Grunde ein großer Strang an Neuronen, verbindet Gehirn und peripheres Nervensystem; liegt im Wirbelsäulenkanal, von Rückenmarksflüssigkeit umgeben.","<b>Maße</b>: annähernd zylindrische Form, beim Menschen etwa 40–45 cm lang.","<b>Spinalnerven</b>: treten durch die Zwischenräume zwischen den Wirbelkörpern auf beiden Seiten aus und verlaufen zu entfernteren Körpergebieten.","<b>Dermatom</b>: das einem Spinalnerv zugeordnete Hautgebiet. Jeder Spinalnerv versorgt zusätzlich Teile der beiden benachbarten Dermatome — deshalb folgt aus der Schädigung eines Spinalnervs <i>kein</i> völliger Sensibilitätsausfall.","<b>Reflexe</b>: verkürzte Informationsweiterleitung, bei der Signale bereits im Rückenmark verarbeitet werden. Bekanntestes Beispiel: der Patellarsehnenreflex."]}},{"id":"k4-2087270571","kap":4,"sec":"4.3.1–4.3.2 Anatomie & Rückenmark","stem":"Welche Aussage zum inneren Aufbau des Rückenmarks ist korrekt?","opts":[{"t":"Die graue Substanz besteht hauptsächlich aus Axonen, die weiße Substanz hauptsächlich aus neuronalen Zellkörpern.","c":false,"fb":"Nicht zutreffend – vertauscht. Graue Substanz: Zellkörper. Weiße Substanz: Axone."},{"t":"Die dorsal liegenden Hinterhörner der grauen Substanz enthalten überwiegend sensorische Zellgruppen, die ventral liegenden Vorderhörner überwiegend motorische.","c":true,"fb":"Zutreffend. Analog gilt für die Wurzeln: sensorische Fasern treten über die Hinterwurzel ein, motorische über die Vorderwurzel aus."},{"t":"Im Hinterstrang der weißen Substanz verlaufen die absteigenden Nervenbahnen vom Gehirn zu den peripheren Gebieten.","c":false,"fb":"Nicht zutreffend – die Richtung ist umgedreht. Hinterstrang: aufsteigend. Vorderstrang: absteigend."},{"t":"Das Spinalganglion liegt im Zentrum der grauen Substanz und ist mit Liquor gefüllt.","c":false,"fb":"Nicht zutreffend – das beschreibt den Zentralkanal. Das Spinalganglion ist eine Verdickung vor der Hinterwurzel aus Zellkörpern des peripheren Nervensystems."}],"concept":{"title":"Graue und weiße Substanz im Rückenmark","points":["<b>Graue Substanz</b>: besteht hauptsächlich aus neuronalen Zellkörpern; die hohe Dichte lässt frisch präparierte Schnitte grau erscheinen. Im Rückenmark bildet sie einen H-förmigen inneren Kern.","<b>Weiße Substanz</b>: besteht hauptsächlich aus Axonen und erscheint bei präparierten Gehirnen weiß (Bear et al., 2018).","<b>Hinterhörner</b>: die zwei dorsal liegenden Arme der grauen Substanz, überwiegend sensorische Zellgruppen.","<b>Vorderhörner</b>: die zwei ventral liegenden Arme, überwiegend motorische Zellgruppen.","<b>Stränge der weißen Substanz</b>: Hinterstrang = aufsteigende Bahnen zum Gehirn, Vorderstrang = absteigende Bahnen vom Gehirn, Seitenstrang = u. a. die Pyramidenbahn für die motorische Steuerung.","<b>Zentralkanal, Wurzeln und Spinalganglion</b>: Der Zentralkanal liegt im Zentrum der grauen Substanz und ist mit Liquor gefüllt. Sensorische Fasern treten über die Hinterwurzel ein, motorische über die Vorderwurzel aus; das Spinalganglion ist eine Verdickung vor der Hinterwurzel aus Zellkörpern des peripheren Nervensystems."]}},{"id":"k4-64fb64f9c1","kap":4,"sec":"4.3.3 Das Gehirn","stem":"Welche Aussage zur Entwicklung und zum Schutz des Gehirns ist zutreffend?","opts":[{"t":"Aus dem Mesencephalon entwickeln sich in der weiteren Entwicklung das Telencephalon und das Diencephalon.","c":false,"fb":"Nicht zutreffend. Diese beiden gehen aus dem Vorderhirnbläschen (Prosencephalon) hervor; das Mesencephalon differenziert sich nicht weiter auf."},{"t":"Die drei primären Hirnbläschen bilden sich am Neuralrohr und differenzieren sich zu Prosencephalon, Mesencephalon und Myelencephalon.","c":false,"fb":"Nicht zutreffend. Das dritte primäre Bläschen ist das Rhombencephalon (Rautenhirn); das Myelencephalon entsteht erst später daraus."},{"t":"Das Gehirn ist von drei schützenden Membranen umgeben, die Meningen beziehungsweise Hirnhäute genannt werden.","c":true,"fb":"Zutreffend. Gehirn und Rückenmark sind zusätzlich von Knochen umschlossen – das am besten geschützte Organ des Körpers."},{"t":"Die Cerebrospinalflüssigkeit liegt zwischen der äußersten und der mittleren Hirnhaut und dient vor allem der Blutversorgung des Gehirns.","c":false,"fb":"Nicht zutreffend. Sie befindet sich im Subarachnoidalraum zwischen innerster und mittlerer Hirnhaut; ihre Aufgabe ist unter anderem, das Gehirn zu stützen und zu schützen."}],"concept":{"title":"Embryonale Entwicklung und Schutz des Gehirns","points":["<b>Neuralrohr</b>: flüssigkeitsgefülltes Rohr in der frühen embryonalen Entwicklung von Wirbeltieren, aus dem das Nervensystem entsteht.","<b>Die drei primären Hirnbläschen</b>: Prosencephalon (Vorderhirn), Mesencephalon (Mittelhirn) und Rhombencephalon (Rautenhirn).","<b>Weitere Differenzierung</b>: Aus dem Vorderhirnbläschen entstehen Telencephalon (Endhirn/Großhirn) und Diencephalon (Zwischenhirn); aus dem Rautenhirn Metencephalon (Hinterhirn) und Myelencephalon (Nachhirn). Das Mesencephalon differenziert sich nicht weiter auf.","<b>Meningen</b>: drei schützende Membranen um Gehirn und Rückenmark, beim Gehirn auch Hirnhäute genannt.","<b>Subarachnoidalraum</b>: liegt zwischen der <i>innersten</i> und der mittleren Hirnhaut und enthält viele große Blutgefäße sowie die Cerebrospinalflüssigkeit.","<b>Cerebrospinalflüssigkeit</b>: stützt und schützt das Gehirn — es schwimmt gewissermaßen darin, wodurch schnelle Bewegungen abgefangen werden (Pinel et al., 2019)."]}},{"id":"k4-46054d6079","kap":4,"sec":"4.3.3 Das Gehirn","stem":"Welche Aussagen zu einzelnen Gehirnstrukturen treffen zu?","opts":[{"t":"Im Thalamus laufen die Informationen sämtlicher Sinnesorgane einschließlich des Geruchssinns zusammen.","c":false,"fb":"Nicht zutreffend. Der Geruchssinn ist die ausdrückliche Ausnahme – alle übrigen Sinnesinformationen laufen im Thalamus zusammen."},{"t":"Die Medulla oblongata ist das Zentrum für Atmung, Blutdruck und Herzschlag; eine Schädigung ist häufig tödlich.","c":true,"fb":"Zutreffend. Hier kreuzen sich außerdem afferente und efferente Nervenfasern – daher die kontralaterale Verbindung von Körper und Gehirn."},{"t":"Der Hypothalamus reguliert motivationale Verhaltensweisen wie Essen, Schlaf und Sexualität und gilt als wichtigstes Steuerzentrum des autonomen Nervensystems.","c":true,"fb":"Zutreffend. Er steuert dazu die Hormonfreisetzung aus der Hypophyse, die ventral von ihm liegt."},{"t":"Das Cerebellum bildet zusammen mit dem Pons und der Medulla oblongata den Hirnstamm.","c":false,"fb":"Nicht zutreffend – an dieser Stelle steht das Mesencephalon. Das Cerebellum gehört mit dem Pons zum Metencephalon und ist vor allem für die Motorik zuständig."}],"concept":{"title":"Die Teile des Gehirns und ihre Funktionen","points":["<b>Medulla oblongata (Myelencephalon, Nachhirn)</b>: am weitesten ventral gelegen, verbindet Gehirn und Rückenmark. Zentrum für Atmung, Blutdruck und Herzschlag; eine Schädigung ist häufig tödlich. Hier kreuzen afferente und efferente Fasern.","<b>Metencephalon (Hinterhirn)</b>: gliedert sich in Pons (Brücke) und Cerebellum (Kleinhirn). Der Pons liegt direkt über der Medulla oblongata.","<b>Cerebellum</b>: hinter dem Pons, zwei Kleinhirnhemisphären; zuständig für die Motorik — integriert Information aus Rückenmark, Gleichgewichtsorgan und anderen Hirnteilen für glatte Bewegungsabläufe.","<b>Hirnstamm</b>: gebildet aus Mesencephalon, Pons und Medulla oblongata — das Cerebellum gehört <i>nicht</i> dazu. Im Mesencephalon unterscheidet man dorsales Tectum (visuell/auditorisch) und ventrales Tegmentum (u. a. periaquäduktales Grau, Substantia nigra).","<b>Thalamus</b>: eiförmig, größtenteils graue Substanz, eine der größten Kernansammlungen des ZNS. Hier laufen die Informationen aller Sinnesorgane <i>mit Ausnahme des Geruchssinns</i> zusammen; enthält u. a. das Corpus geniculatum laterale.","<b>Hypothalamus</b>: reguliert motivationale Verhaltensweisen wie Essen, Schlaf und Sexualität, steuert die Hormonfreisetzung aus der Hypophyse und gilt als wichtigstes Steuerzentrum des autonomen Nervensystems."]}},{"id":"k4-c090c12b7c","kap":4,"sec":"4.3.3 Das Gehirn","stem":"Welche Aussage zum cerebralen Cortex und zur Lateralisation ist korrekt?","opts":[{"t":"Der cerebrale Cortex ist etwa 2–5 Zentimeter dick und besteht vorwiegend aus grauer Substanz.","c":false,"fb":"Nicht zutreffend. Die Substanz stimmt, die Größenordnung nicht: 2–5 Millimeter."},{"t":"Der Hippocampus, der eine entscheidende Bedeutung für das Gedächtnis hat, ist in den Parietallappen eingebettet.","c":false,"fb":"Nicht zutreffend. Hippocampus und Amygdala liegen im Temporallappen; die Parietallappen verarbeiten sensumotorische Informationen."},{"t":"Bei Split-Brain-Patient:innen können visuelle Reize in der linken Gesichtsfeldhälfte problemlos benannt werden, während Reize in der rechten Hälfte Schwierigkeiten bereiten.","c":false,"fb":"Nicht zutreffend – umgekehrt. Reize links werden rechtshemisphärisch verarbeitet, und der rechten Hemisphäre fehlen die Worte, weil die linke sprachdominant ist."},{"t":"Der präfrontale Cortex ist Teil des Frontallappens und wird häufig als Sitz der Persönlichkeit und des Sozialverhaltens bezeichnet.","c":true,"fb":"Zutreffend. Dort finden Aufmerksamkeit, Arbeitsgedächtnis, Handlungsplanung und Impulskontrolle statt – der Bereich, den Gages Eisenstange traf."}],"concept":{"title":"Die vier Lappen des Cortex und die Lateralisation","points":["<b>Cerebraler Cortex</b>: äußere Oberfläche des Großhirns, nur etwa 2–5 <i>Millimeter</i> dick, vorwiegend graue Substanz. Die starke Furchung vergrößert die Oberfläche ohne Volumenzuwachs.","<b>Frontallappen</b>: Planung, Sprache, Sozialverhalten, Emotionsregulation und Bewegung. Der präfrontale Cortex gilt als Sitz der Persönlichkeit und des Sozialverhaltens — genau hier war Phineas Gage verletzt.","<b>Parietallappen</b>: Integration sensumotorischer Information (Tastsinn), kontralateral verarbeitet, sowie Aufmerksamkeit und räumliche Orientierung.","<b>Temporallappen</b>: Hören und spezialisierte visuelle Areale (z. B. Gesichtererkennung). Hier eingebettet: Hippocampus (Gedächtnis) und Amygdala (emotionale Verarbeitung).","<b>Okzipitallappen</b>: Hinterhauptlappen mit vielen visuellen Arealen, u. a. dem primären visuellen Cortex.","<b>Split-Brain und Lateralisation</b>: Nach Durchtrennung des Corpus callosum können Reize der <i>linken</i> Gesichtsfeldhälfte (rechte Hemisphäre) nicht benannt werden, Reize rechts dagegen schon — die linke Hemisphäre ist sprachdominant, die rechte bei räumlicher Verarbeitung (Gazzaniga, Bogen & Sperry, 1962)."]}},{"id":"k4-8326baabed","kap":4,"sec":"4.3.4 Peripheres Nervensystem","stem":"Welche Aussagen zum peripheren Nervensystem treffen zu?","opts":[{"t":"Das autonome Nervensystem, auch vegetatives Nervensystem genannt, steuert innere Organe und arbeitet in der Regel unbewusst und ohne willkürliche Kontrolle.","c":true,"fb":"Zutreffend. Es reguliert die innere Umwelt des Körpers, indem es Drüsen stimuliert und die Organtätigkeit aufrechterhält."},{"t":"Das somatische Nervensystem reguliert die innere Umwelt des Körpers, indem es Drüsen stimuliert und die Tätigkeit innerer Organe aufrechterhält.","c":false,"fb":"Nicht zutreffend – das ist die Aufgabe des autonomen Nervensystems. Das somatische überträgt sensorische Informationen und leitet Signale an Muskeln, Gelenke und Haut."},{"t":"Bei Aktivierung des sympathischen Nervensystems werden Prozesse, die gerade nicht benötigt werden – etwa die Verdauung –, heruntergeregelt.","c":true,"fb":"Zutreffend. Gleichzeitig steigen Puls und Sauerstoffverbrauch, das Blut fließt von den inneren Organen zu den Muskeln."},{"t":"Das parasympathische Nervensystem sorgt bei Stress für eine Erhöhung von Puls und Sauerstoffverbrauch.","c":false,"fb":"Nicht zutreffend – das leistet der Sympathikus. Der Parasympathikus verlangsamt diese Prozesse wieder und regelt den Normalbetrieb."}],"concept":{"title":"Somatisches und autonomes Nervensystem","points":["<b>Gliederung</b>: Das Nervensystem teilt sich in zentrales (Gehirn und Rückenmark) und peripheres Nervensystem; letzteres wiederum in somatisches und autonomes Nervensystem.","<b>Somatisches Nervensystem</b>: überträgt sensorische Informationen von spezialisierten Rezeptoren an Haut, Muskeln und Gelenken an das ZNS — und leitet umgekehrt Signale zurück, um Bewegungen zu initiieren, zu modulieren oder zu hemmen.","<b>Autonomes (vegetatives) Nervensystem</b>: steuert innere Organe, reguliert die innere Umwelt durch Stimulation von Drüsen; läuft in der Regel unbewusst und ohne willkürliche Kontrolle ab.","<b>Sympathisches Nervensystem</b>: aktiv bei Anspannung — Adrenalinausschüttung, Blut fließt zu den Muskeln, Sauerstoffverbrauch und Puls steigen.","<b>Herunterregulierung</b>: Gerade nicht benötigte Prozesse wie die Verdauung werden dabei zurückgefahren.","<b>Parasympathisches Nervensystem</b>: verlangsamt diese Prozesse wieder — Herzschlag und Atmung beruhigen sich, die Verdauung stellt sich ein. Es regelt gewissermaßen den Normalbetrieb (Gerrig et al., 2018)."]}},{"id":"k4-d08709f905","kap":4,"sec":"4.4 Das visuelle System","stem":"Welche Aussagen zum Aufbau des Auges sind zutreffend?","opts":[{"t":"Je mehr Licht auf die Augen fällt, desto größer wird die Pupille.","c":false,"fb":"Nicht zutreffend – die Richtung ist umgedreht. Viel Licht verkleinert die Pupille, wenig Licht vergrößert sie."},{"t":"Die mittlere Augenhaut besteht aus drei strukturell verschiedenen Abschnitten: Aderhaut, Ziliarkörper und Iris.","c":true,"fb":"Zutreffend. Die äußere Augenhaut bilden Lederhaut und Cornea, die innere die Retina."},{"t":"Der Blinde Fleck bezeichnet die Stelle der Retina mit der höchsten Dichte an Photorezeptorzellen.","c":false,"fb":"Nicht zutreffend – das wäre die Fovea. Am Blinden Fleck tritt der Sehnerv aus, dort liegen gar keine Photorezeptorzellen."},{"t":"Die Cornea ist lichtdurchlässig, weil sich in ihr keine Blutgefäße befinden.","c":true,"fb":"Zutreffend. Im Gegensatz dazu ist die direkt darunterliegende Aderhaut ausgesprochen reich an Blutgefäßen."}],"concept":{"title":"Der Aufbau des Auges","points":["<b>Äußere Augenhaut</b>: hinten und seitlich die Lederhaut, vorne die Cornea (Hornhaut). Die Cornea ist lichtdurchlässig, weil sich in ihr keine Blutgefäße befinden.","<b>Mittlere Augenhaut</b>: drei strukturell verschiedene Abschnitte — Aderhaut (reich an Blutgefäßen), Ziliarkörper (mit dem Ziliarmuskel) und Iris.","<b>Iris und Pupille</b>: Die Iris fungiert als Blende. Je <i>weniger</i> Licht einfällt, desto größer wird die Pupille; je mehr Licht, desto kleiner.","<b>Innere Augenhaut</b>: die Retina (Netzhaut) mit den Photorezeptorzellen, die Licht in neuronale Signale umwandeln.","<b>Linse und Akkommodation</b>: Die bikonvexe Augenlinse ist vorne schwächer gekrümmt als hinten. Der Ziliarmuskel verändert ihre Wölbung — dieser Vorgang heißt Akkommodation und liefert die erhöhte Brechkraft für nahe Objekte.","<b>Blinder Fleck</b>: die Austrittsstelle des Sehnervs; dort befinden sich <i>keine</i> Photorezeptorzellen, folglich kann dort kein Licht umgewandelt werden."]}},{"id":"k4-5665ebb9af","kap":4,"sec":"4.4 Das visuelle System","stem":"Welche Aussage über die Photorezeptorzellen der Retina ist korrekt?","opts":[{"t":"Stäbchen sind lichtempfindlicher als Zapfen und spielen daher bei dämmriger Beleuchtung eine wichtige Rolle.","c":true,"fb":"Zutreffend. Grund ist die höhere Konzentration von Photopigmenten im langen zylindrischen Außenglied der Stäbchen."},{"t":"Im menschlichen Auge gibt es etwa 20-mal so viele Zapfen wie Stäbchen.","c":false,"fb":"Nicht zutreffend – das Verhältnis ist umgedreht: etwa 20-mal so viele Stäbchen wie Zapfen."},{"t":"Die Fovea ist der Ort des schärfsten Sehens, weil dort ausschließlich sehr viele Stäbchen vorkommen.","c":false,"fb":"Nicht zutreffend. In der Fovea kommen ausschließlich sehr viele Zapfen vor – deshalb werden dort Farben und räumliche Details am genauesten erkannt."},{"t":"Die Umwandlung von Lichtenergie in neuronale Signale wird als Akkommodation bezeichnet.","c":false,"fb":"Nicht zutreffend – das ist die Transduktion. Akkommodation meint die Veränderung der Linsenform durch den Ziliarmuskel."}],"concept":{"title":"Stäbchen, Zapfen und die Transduktion","points":["<b>Transduktion</b>: die Umwandlung von Lichtenergie in neuronale Signale; findet in den Photorezeptorzellen statt — nicht zu verwechseln mit der Akkommodation.","<b>Stäbchen</b>: langes zylindrisches Außenglied mit vielen Photopigmenten, dadurch deutlich lichtempfindlicher; wichtig bei dämmriger Beleuchtung.","<b>Zapfen</b>: kürzeres, spitz zulaufendes Außenglied; dominieren bei guter Beleuchtung und liefern scharfe farbige Wahrnehmungen.","<b>Mengenverhältnis</b>: Im menschlichen Auge gibt es etwa 20-mal so viele <i>Stäbchen</i> wie Zapfen.","<b>Fovea</b>: Ort mit ausschließlich sehr vielen <i>Zapfen</i> und damit der Ort des schärfsten Sehens — Farben und räumliche Details werden dort am genauesten erkannt.","<b>Drei Zapfentypen</b>: unterschiedliche Photopigmente reagieren besonders gut auf blaues, grünes oder rotes Licht; die Wellenlängenbereiche überlappen sich, und die Farbwahrnehmung hängt von der relativen Beteiligung aller drei ab."]}},{"id":"k4-1a7b5876e9","kap":4,"sec":"4.4 Das visuelle System","stem":"Welche Aussagen zur Farbfehlsichtigkeit treffen zu?","opts":[{"t":"Am häufigsten ist die Rot-Grün-Schwäche, bei der entweder die Funktion der Grün- oder der Rot-Zapfen eingeschränkt ist.","c":true,"fb":"Zutreffend. Ursache ist eine Verschiebung des Empfindlichkeitsspektrums in Richtung des jeweils anderen Zapfentyps."},{"t":"Die Rot-Grün-Sehschwäche entwickelt sich meist erst im Erwachsenenalter und verstärkt sich im Laufe der Zeit.","c":false,"fb":"Nicht zutreffend. Sie ist angeboren und verändert sich im Laufe der Zeit nicht."},{"t":"Die Rot-Grün-Sehschwäche tritt bei Männern deutlich häufiger auf, weil das verantwortliche Gen auf dem X-Chromosom liegt.","c":true,"fb":"Zutreffend. Frauen können einen Defekt in der Regel über das zweite X-Chromosom ausgleichen, Männer nicht."},{"t":"Der frühere Begriff „Farbenblindheit“ ist irreführend, weil betroffene Personen meist sehr wohl Farben sehen und unterscheiden können.","c":true,"fb":"Zutreffend. Farbfehlsichtigkeit meint die teilweise oder komplette Unfähigkeit, Farben zu unterscheiden – vollständige Blindheit für Farben ist der Ausnahmefall."}],"concept":{"title":"Farbfehlsichtigkeit und die Rot-Grün-Schwäche","points":["<b>Definition</b>: teilweise oder komplette Unfähigkeit, Farben zu unterscheiden; entsteht, wenn Zapfentypen fehlen oder nicht richtig funktionieren.","<b>Warum „Farbenblindheit“ irreführend ist</b>: Betroffene können meist sehr wohl Farben sehen und unterscheiden.","<b>Rot-Grün-Schwäche</b>: die häufigste Form; eingeschränkt ist entweder die Funktion der Grün- oder der Rot-Zapfen, weil sich deren Empfindlichkeitsspektrum in Richtung der jeweils anderen verschoben hat.","<b>Beispiel Grün-Sehschwäche</b>: Das Spektrum der Grün-Zapfen ist in den roten Wellenlängenbereich verschoben — weniger Grüntöne werden wahrgenommen, Grün lässt sich schlechter von Rot unterscheiden.","<b>Geschlechtsunterschied</b>: Bei Männern deutlich häufiger, weil das Gen auf dem X-Chromosom liegt und dominant-rezessiv vererbt wird. Frauen können einen Defekt in der Regel über das zweite X-Chromosom ausgleichen.","<b>Zeitlicher Verlauf und Prüfung</b>: Die Rot-Grün-Sehschwäche ist angeboren und verändert sich im Laufe der Zeit nicht. Einen Hinweis geben die Ishihara-Farbtafeln (Ishihara, 1972)."]}},{"id":"k4-184f3e6f1b","kap":4,"sec":"4.4 Das visuelle System","stem":"Welche Aussagen zum Weg der visuellen Information vom Auge zum Gehirn sind zutreffend?","opts":[{"t":"An der Sehnervkreuzung (Chiasma opticum) wechseln die Axone jener Zellen, die in der Retina auf der der Nase zugewandten Seite liegen, auf die kontralaterale Seite.","c":true,"fb":"Zutreffend. Die Axone von der jeweils äußeren Seite bleiben dagegen auf ihrer Seite."},{"t":"Objekte, die in der linken Gesichtsfeldhälfte wahrgenommen werden, werden in der rechten Gehirnhälfte repräsentiert.","c":true,"fb":"Zutreffend. Grund ist, dass das Bild durch die Brechung an der Linse gespiegelt auf der Retina ankommt."},{"t":"Der Großteil der Axone zieht zum Corpus geniculatum laterale im dorsalen Thalamus, in dem eine retinotrope Organisation herrscht.","c":true,"fb":"Zutreffend. Benachbarte Retinazellen übertragen auf benachbarte Stellen im CGL; die Fovea ist dabei überproportional repräsentiert."},{"t":"Der primäre visuelle Cortex (Areal V1) liegt beiderseits im Okzipitallappen und enthält unter anderem orientierungssensitive Zellen.","c":true,"fb":"Zutreffend. Daneben gibt es richtungssensitive Zellen, die bevorzugt auf Bewegung in eine bestimmte Richtung ansprechen."}],"concept":{"title":"Die Sehbahn vom Auge zum visuellen Cortex","points":["<b>Chiasma opticum</b>: An der Sehnervkreuzung wechseln die Axone jener Zellen, die in der Retina auf der der Nase zugewandten Seite liegen, auf die kontralaterale Seite. Axone von der jeweils äußeren Seite bleiben auf ihrer Seite.","<b>Konsequenz</b>: Weil das Bild durch die Brechung an der Linse gespiegelt auf der Retina ankommt, werden Objekte der linken Gesichtsfeldhälfte in der rechten Gehirnhälfte repräsentiert.","<b>Gesichtsfeld</b>: der gesamte visuelle Raum bei geradeaus stehenden Augen; eine gedachte Senkrechte durch den Fixationspunkt teilt es in linke und rechte Hälfte.","<b>Corpus geniculatum laterale (CGL)</b>: Struktur im dorsalen Thalamus, zu der der Großteil der Axone zieht. Die Informationen beider Augen bleiben getrennt, da deren Axone mit verschiedenen Zellschichten Synapsen bilden.","<b>Retinotrope Organisation</b>: Benachbarte Retinazellen übertragen auf benachbarte Stellen im CGL. Die Größenverhältnisse bleiben nicht erhalten — die Fovea ist überproportional repräsentiert.","<b>Primärer visueller Cortex (V1)</b>: beiderseits im Okzipitallappen, ebenfalls retinotrop organisiert und mehrschichtig. Enthält orientierungssensitive und richtungssensitive Zellen (Hubel & Wiesel, 1962); darüber liegen höhere Areale V2, V3 usw."]}},{"id":"k5-815fb6c972","kap":5,"sec":"5.3.3 Klassische Konditionierung","stem":"Welche Aussagen zu den Grundbegriffen der klassischen Konditionierung treffen zu?","opts":[{"t":"Das Futter stellt einen unkonditionierten Reiz dar, der darauf folgende Speichelfluss eine unkonditionierte Reaktion.","c":true,"fb":"UCS und UCR bezeichnen genau diese Verknüpfung, die beim Hund reflexhaft schon vor jeder Konditionierung vorliegt."},{"t":"Von unkonditioniertem Reiz und unkonditionierter Reaktion spricht man, weil diese Verknüpfung bereits vor der Konditionierung besteht.","c":true,"fb":"Darin liegt die Begründung der Vorsilbe: Die Verbindung ist nicht gelernt, sondern etwa durch einen Reflex vorgegeben."},{"t":"Nach mehrmaliger gemeinsamer Darbietung mit dem Futter wird die Glocke vom neutralen zum konditionierten Reiz.","c":true,"fb":"Die Paarung macht das Läuten zum Signal; die konditionierte Reaktion folgt danach auch ohne Darbietung des Futters."},{"t":"Die klassische Konditionierung wird auch als Signallernen bezeichnet.","c":true,"fb":"Der ursprünglich neutrale Reiz kündigt den zweiten Reiz an und wird damit zum Signal — daher die zweite Bezeichnung."}],"concept":{"title":"Klassische Konditionierung (Pawlow)","points":["<b>Ausgangsbeobachtung</b>: Pawlow (1849–1936) untersuchte Verdauungsdrüsen an Hunden; der Speichelfluss trat schon vor dem Fleischpulver auf — erst beim Anblick, später bei den Schritten des Versuchsleiters.","<b>UCS / UCR</b>: unkonditionierter Reiz (Futter) und unkonditionierte Reaktion (Speichelfluss); diese Verknüpfung besteht bereits vorher, z. B. reflexbedingt.","<b>Neutraler Reiz</b>: löst zunächst keine Reaktion aus, etwa das Läuten einer Glocke.","<b>CS / CR</b>: nach mehrmaliger gleichzeitiger Darbietung wird die Glocke zum konditionierten Reiz, der Speichelfluss zur konditionierten Reaktion — auch ohne Futter.","<b>Prinzip</b>: Durch gemeinsames Auftreten zweier Reize entsteht eine Assoziation; der neutrale Reiz wird zum <i>Signal</i> — daher auch <b>Signallernen</b>.","Randnotiz zur Person: Pawlow erhielt 1904 den Nobelpreis für Medizin — für die Verdauungsforschung, nicht für die Konditionierung."]}},{"id":"k5-e62c9a3bc1","kap":5,"sec":"5.2.2 Theorien der Wahrnehmung","stem":"Welche Aussage zu den psychophysischen Schwellen und ihren Untersuchungsmethoden trifft zu?","opts":[{"t":"Bei der Grenzmethode werden unterschiedlich starke Reize in zufälliger Reihenfolge dargeboten.","c":false,"fb":"Das beschreibt die Konstanzmethode. Bei der Grenzmethode wird der Reiz gerade nicht zufällig, sondern in ab- oder zunehmender Intensität dargeboten."},{"t":"Die Unterschiedsschwelle ist von der Intensität des Ausgangsreizes unabhängig.","c":false,"fb":"Sie hängt sehr wohl vom Ausgangsreiz ab: Je stärker dieser ist, desto größer muss der absolute Unterschied zum zweiten Reiz ausfallen."},{"t":"Als Absolutschwelle gilt jene Intensität, bei der ein Reiz in der Hälfte der Fälle erkannt wird.","c":true,"fb":"Die empirische Schwellenkurve verläuft S-förmig; festgelegt wird die Schwelle am Punkt mit 50 % Erkennungsrate."},{"t":"Reize oberhalb der ermittelten Absolutschwelle werden ausnahmslos wahrgenommen.","c":false,"fb":"Oberhalb der Schwelle steigt lediglich die Wahrscheinlichkeit der Entdeckung; ein eindeutiger Grenzwert existiert nicht."}],"concept":{"title":"Psychophysik nach Fechner — Schwellen und Methoden","points":["<b>Absolutschwelle</b>: kleinste Reizintensität, die nötig ist, damit ein Reiz überhaupt wahrgenommen wird; empirisch dort angesetzt, wo er in 50 % der Fälle erkannt wird.","<b>Unterschiedsschwelle</b>: kleinste Differenz, um zwei Reize zu unterscheiden — abhängig vom Ausgangsreiz: je stärker dieser, desto größer der nötige absolute Unterschied.","<b>Grenzmethode</b>: Reize werden in ab- oder zunehmender Intensität dargeboten; nach jedem Reiz erfolgt das Urteil „wahrgenommen / nicht wahrgenommen“.","<b>Konstanzmethode</b>: gleiche Urteilsaufgabe, aber zufällige statt geordnete Abfolge der Intensitäten.","<b>Psychometrische Funktion</b>: Graph der Erkennungsrate; die reale Kurve steigt allmählich an, nicht sprunghaft von 0 % auf 100 %.","Beide Methoden lassen sich auch zur Bestimmung von Unterschiedsschwellen einsetzen (Kiesel & Koch, 2018)."]}},{"id":"k5-60fc0ff6e2","kap":5,"sec":"5.4.4 Langzeitgedächtnis","stem":"Welche Aussagen zur Untergliederung des Langzeitgedächtnisses treffen zu?","opts":[{"t":"Tulving (1972) unterschied innerhalb des expliziten Gedächtnisses das semantische und das episodische Gedächtnis.","c":true,"fb":"Semantisch steht für Faktenwissen, episodisch für persönliche Erlebnisse — beide gehören zum bewusst abrufbaren Teil."},{"t":"Das episodische Gedächtnis speichert persönliche Erlebnisse samt ihrer zeitlich-räumlichen Verknüpfungen.","c":true,"fb":"Es hat stets Bezug zur eigenen Person und kann von Emotionen begleitet sein — anders als das semantische Faktenwissen."},{"t":"Resultate klassischer und operanter Konditionierung zählen zum deklarativen Gedächtnis.","c":false,"fb":"Sie gehören zum non-deklarativen, also impliziten Gedächtnis — ebenso wie nicht-assoziatives Lernen, Erwartungen und Priming."},{"t":"Squire (1992) ordnete neben dem prozeduralen Gedächtnis auch Erwartungen und Priming dem non-deklarativen Gedächtnis zu.","c":true,"fb":"Sein Beitrag bestand darin, das implizite Gedächtnis nicht mit dem prozeduralen gleichzusetzen, sondern weiter aufzufächern."}],"concept":{"title":"Untergliederung des Langzeitgedächtnisses (Becker-Carus & Wendt, 2017)","points":["<b>Eigenschaften</b>: sehr hohe Kapazität und lange, oft lebenslange Speicherdauer (Gazzaniga et al., 2017).","<b>Explizit / deklarativ</b>: bewusst abrufbare Inhalte. <b>Implizit / non-deklarativ</b>: nicht bewusst zugängliche Inhalte.","<b>Explizit → Tulving (1972)</b>: <b>semantisches Gedächtnis</b> (Faktenwissen ohne Personenbezug) und <b>episodisches Gedächtnis</b> (eigene Erlebnisse mit zeitlich-räumlichem Bezug, oft emotional gefärbt).","<b>Implizit → Squire (1992)</b>: prozedurales Gedächtnis (Radfahren, Zehnfingerschreiben) sowie klassische und operante Konditionierung, nicht-assoziatives Lernen und Erwartungen/Priming.","<b>Arbeitsteilung der Fächer</b>: implizite Prozesse behandelt vorrangig die Lernpsychologie, explizite die Gedächtnispsychologie.","<b>Empirische Basis</b>: Patient:innen mit Amnesie, die Faktenwissen verloren, motorische Aufgaben aber weiterhin beherrschten (Cohen & Squire, 1980)."]}},{"id":"k5-5053b8a712","kap":5,"sec":"5.1 Was ist Allgemeine Psychologie?","stem":"Welche Aussagen zum Selbstverständnis der Allgemeinen Psychologie treffen zu?","opts":[{"t":"Die Bezeichnung verweist darauf, dass diese Teildisziplin die Gesamtheit der Psychologie umfasst.","c":false,"fb":"Genau diese Deutung weist das Skript als naheliegenden Irrtum zurück; gemeint ist der universalistische Ansatz, kein Anspruch auf die ganze Disziplin."},{"t":"Sie folgt einem universalistischen Ansatz: der Annahme, dass alle Menschen über die gleichen psychischen Funktionen verfügen.","c":true,"fb":"Auf dieser Annahme beruht das Fach; aus ihr leitet es allgemein gültige Aussagen über psychische Funktionen ab."},{"t":"Gegenüber der Differentiellen Psychologie verschiebt sich der Blick von Unterschieden auf Gemeinsamkeiten psychischer Vorgänge.","c":true,"fb":"Die Differentielle Psychologie untersucht Unterschiede, die Allgemeine Psychologie das, was Menschen gemeinsam ist."},{"t":"Sie beschreibt in erster Linie, wie sich psychische Prozesse über die Lebensspanne verändern.","c":false,"fb":"Das ist Gegenstand der Entwicklungspsychologie; die Allgemeine Psychologie betrachtet gesunde erwachsene Personen."}],"concept":{"title":"Allgemeine Psychologie — Gegenstand und Abgrenzung","points":["<b>Universalistischer Ansatz</b>: Annahme, dass alle Menschen universell über die gleichen psychischen Funktionen verfügen (Becker-Carus & Wendt, 2017).","<b>Gegenstand</b>: grundlegende psychische Funktionen bei gesunden erwachsenen Menschen; daraus werden allgemein gültige Aussagen abgeleitet (Kiesel & Spada, 2018).","<b>Abgrenzung zur Differentiellen Psychologie</b>: dort Unterschiede, hier Gemeinsamkeiten.","<b>Abgrenzung zur Entwicklungspsychologie</b>: dort Veränderung im Laufe des Lebens, hier der gesunde Erwachsene.","<b>Abgrenzung zur Sozialpsychologie</b>: sozialpsychologische Aspekte bleiben außer Acht.","Merkhilfe: „Allgemein“ meint <i>universell</i>, nicht <i>umfassend</i>."]}},{"id":"k5-0f3b0b9569","kap":5,"sec":"5.4.3 Arbeitsgedächtnis","stem":"Welche Aussage zum Dual-Task-Paradigma und zur Studie von Robbins et al. (1996) trifft zu?","opts":[{"t":"Die Qualität der Schachzüge litt vor allem bei jenen Personen, die immer wieder dasselbe Wort aussprechen mussten.","c":false,"fb":"Diese Bedingung beanspruchte die phonologische Schleife, die beim Schach kaum benötigt wird — hier blieb die Leistung weitgehend erhalten."},{"t":"Als Doppelaufgabenkosten bezeichnet man die Leistungsdifferenz zwischen gleichzeitiger und getrennter Bearbeitung zweier Aufgaben.","c":true,"fb":"Liegt eine solche Differenz vor, spricht das für eine Beeinträchtigung durch das parallele Bearbeiten (Becker-Carus & Wendt, 2017)."},{"t":"Das Generieren zufälliger Zahlen beanspruchte in der Studie den visuell-räumlichen Notizblock.","c":false,"fb":"Zufallszahlen belasteten die zentrale Exekutive; den Notizblock beanspruchte das Tastendrücken im Uhrzeigersinn."},{"t":"Als Kontrollbedingung diente das Drücken von Tasten im Uhrzeigersinn.","c":false,"fb":"Die Kontrollbedingung bestand darin, im Sekundentakt immer dieselbe Taste zu drücken — ohne gezielte Beanspruchung einer Komponente."}],"concept":{"title":"Dual-Task-Paradigma und die Studie von Robbins et al. (1996)","points":["<b>Dual-Task</b>: Forschungsansatz, bei dem zwei Aufgaben zeitgleich bearbeitet werden; verglichen wird mit der Leistung bei getrennter Bearbeitung.","<b>Doppelaufgabenkosten (Dual-Task-Costs)</b>: die dabei entstehende Leistungsdifferenz (Becker-Carus & Wendt, 2017).","<b>Aufbau</b>: Schachprobleme lösen und parallel entweder dieselbe Taste im Sekundentakt drücken (Kontrolle), Zufallszahlen generieren (zentrale Exekutive), Tasten im Uhrzeigersinn drücken (visuell-räumlicher Notizblock) oder ein Wort wiederholen (phonologische Schleife).","<b>Ergebnis</b>: Die Schachleistung sank bei Zufallszahlen und beim Tastendrücken im Uhrzeigersinn — nicht beim Wortwiederholen.","<b>Schlussfolgerung</b>: Schach beansprucht vor allem zentrale Exekutive und visuell-räumlichen Notizblock; das stützt die Untergliederung des Arbeitsgedächtnisses.","<b>Logik des Paradigmas</b>: Zwei Aufgaben stören einander besonders dann, wenn sie dieselbe Komponente beanspruchen."]}},{"id":"k5-d5835997ef","kap":5,"sec":"5.2.4 Visuelle Wahrnehmung","stem":"Welche Aussagen zu den beiden Pfaden der visuellen Verarbeitung und zur doppelten Dissoziation treffen zu?","opts":[{"t":"Schädigungen im ventralen Pfad zeigten sich darin, dass Objekte zwar benannt, aber nicht mehr gegriffen werden konnten.","c":false,"fb":"Dieses Muster gehört zum dorsalen Pfad. Bei ventraler Schädigung war umgekehrt das Greifen möglich, das Benennen jedoch erschwert."},{"t":"Der ventrale Pfad verläuft vom visuellen Cortex zum Temporallappen und trug ursprünglich die Bezeichnung „Was“-Pfad.","c":true,"fb":"In der ursprünglichen Fassung stand er für die Objekterkennung (Mishkin, Ungerleider & Macko, 1983)."},{"t":"Goodale und Milner (1992) schlugen für den dorsalen Pfad die Bezeichnung „Wie“-Pfad vor.","c":true,"fb":"Sie stellten den Zweck der Information in den Vordergrund: Der dorsale Pfad steuert Handlungen wie Erreichen und Greifen."},{"t":"Von einer doppelten Dissoziation spricht man, wenn sich zu beiden Aufgaben Personen mit jeweils umgekehrtem Ausfallmuster finden lassen.","c":true,"fb":"Erst dieses Kreuzmuster entkräftet den Einwand, eine Aufgabe sei schlicht schwieriger als die andere."}],"concept":{"title":"Ventraler und dorsaler Pfad — und die doppelte Dissoziation","points":["<b>Ventraler Pfad</b>: visueller Cortex → Temporallappen; Objekterkennung, „Was“-Pfad (Mishkin, Ungerleider & Macko, 1983).","<b>Dorsaler Pfad</b>: visueller Cortex → Parietallappen; räumliche Verarbeitung, „Wo“-Pfad.","<b>Adaption von Goodale und Milner (1992)</b>: nicht die Qualität des Inputs, sondern der Zweck unterscheidet die Pfade — ventral <i>Vision for Perception</i>, dorsal <i>Vision for Action</i>, daher treffender „Wie“-Pfad.","<b>Befundlage</b>: dorsale Schädigung → benennen möglich, greifen schwierig; ventrale Schädigung → greifen möglich, benennen schwierig.","<b>Dissoziation</b>: Eine Person scheitert an Aufgabe A, löst aber Aufgabe B — das kann auch bloß an unterschiedlicher Schwierigkeit liegen.","<b>Doppelte Dissoziation</b>: Beide Ausfallmuster lassen sich finden. Auch sie bleibt ein indirekter Rückschluss, kein Beweis für zwei getrennte Prozesse (M. W. Eysenck & Keane, 2020)."]}},{"id":"k5-5958ac0a98","kap":5,"sec":"5.3.3 Klassische Konditionierung","stem":"Was gilt für Löschung, Spontanremission, Reizgeneralisierung und Reizdiskrimination?","opts":[{"t":"Die Spontanremission zeigt, dass die konditionierte Reaktion bei der Löschung nicht verlernt, sondern nur abgeschwächt wird.","c":true,"fb":"Nach der Löschung löst der konditionierte Reiz erneut eine — wenn auch schwache — Reaktion aus; die Assoziation ist also noch vorhanden."},{"t":"Von Reizdiskrimination spricht man, wenn auch dem konditionierten Reiz ähnliche Reize die Reaktion auslösen.","c":false,"fb":"Das ist die Reizgeneralisierung. Die Diskrimination ist ihr Gegenstück: Auf ähnliche Reize werden unterschiedliche Reaktionen gelernt."},{"t":"Beim Diskriminationstraining werden beide ähnlichen Reize gleichermaßen mit dem unkonditionierten Reiz gepaart.","c":false,"fb":"Gepaart wird nur einer der beiden Reize; die Reaktion auf den anderen nimmt dadurch allmählich ab."},{"t":"Watson und Rayner erzeugten bei Little Albert eine Furchtreaktion, die sich anschließend auf ähnliche Objekte ausweitete.","c":true,"fb":"Albert reagierte danach auch auf weißen Hasen und Pelzmantel — ein klassisches Beispiel für Reizgeneralisierung (Watson & Rayner, 1920)."}],"concept":{"title":"Löschung, Spontanremission, Generalisierung, Diskrimination","points":["<b>Löschung (Extinktion)</b>: Bleibt der UCS aus, nimmt die konditionierte Reaktion ab, bis sie schließlich ausbleibt.","<b>Spontanremission</b>: Einige Zeit nach der Löschung löst der CS erneut eine Reaktion aus — schwach und rasch verschwindend; wird der CS wieder mit dem UCS gepaart, ist die CR schnell zurück.","<b>Deutung</b>: Löschung ist kein Vergessensprozess, sondern selbst eine Form des Lernens, die neben der alten Assoziation gespeichert wird und signalisiert, dass diese nicht mehr gilt.","<b>Reizgeneralisierung</b>: Auch dem CS ähnliche Reize lösen die CR aus — je ähnlicher, desto stärker. Sie ist ein Sicherheitsfaktor, da Reize in der Natur selten identisch auftreten.","<b>Reizdiskrimination</b>: Gegenstück dazu — auf ähnliche Reize werden unterschiedliche Reaktionen gelernt.","<b>Diskriminationstraining</b>: Nur einer der beiden ähnlichen Reize wird mit dem UCS gepaart; die Reaktion auf den anderen nimmt zunehmend ab (Gerrig et al., 2018)."]}},{"id":"k5-3d7849d0cc","kap":5,"sec":"5.4.3 Arbeitsgedächtnis","stem":"Welche Aussagen zur Millerschen Zahl und zum Chunking treffen zu?","opts":[{"t":"Miller ging 1956 davon aus, dass sich im Arbeitsgedächtnis etwa sieben Einheiten behalten lassen.","c":true,"fb":"Da diese Zahl ihm auch bei anderen Prozessen begegnete, nannte er sie die magische Zahl."},{"t":"Die übliche Angabe 7 ± 2 macht deutlich, dass es sich um einen ungefähren Wert handelt.","c":true,"fb":"Die Spannweite signalisiert, dass die Kapazität nicht exakt festgelegt ist."},{"t":"Beim Chunking werden mehrere einzelne Informationen zu einer Informationseinheit gruppiert.","c":true,"fb":"Aus 1, 9, 4, 5 wird so etwa eine einzige Jahreszahl statt vier separater Ziffern."},{"t":"Ein Chunk beansprucht weniger Kapazität als die Einzelinformationen, aus denen er gebildet wurde.","c":true,"fb":"Genau darin liegt der Nutzen: Insgesamt lässt sich mehr im Arbeitsgedächtnis unterbringen."}],"concept":{"title":"Millersche Zahl und Chunking","points":["<b>Magische Zahl</b>: George A. Miller (1956) — etwa sieben Einheiten im Arbeitsgedächtnis; auch <b>Millersche Zahl</b> genannt.","<b>7 ± 2</b>: die gängige Literaturangabe macht deutlich, dass es sich um eine Näherung handelt.","<b>Erklärungswert</b>: verständlich wird, warum lange Ziffern- oder Buchstabenfolgen wie Telefonnummern oder die IBAN schwer zu merken sind.","<b>Chunking</b>: Gruppieren mehrerer einzelner Informationen zu einer Informationseinheit, z. B. 1, 9, 4, 5 als Jahreszahl 1945.","<b>Effekt</b>: Ein Chunk verbraucht weniger Speicher als vier Einzelinformationen — insgesamt lässt sich mehr behalten.","Verwandter Mechanismus: Auch das Verknüpfen neuer Inhalte mit Wissen aus dem Langzeitspeicher entlastet das Arbeitsgedächtnis."]}},{"id":"k5-f4278d4115","kap":5,"sec":"5.1 Was ist Allgemeine Psychologie?","stem":"Welche Aussage zum kognitionspsychologischen Ansatz und zu den Themenbereichen der Allgemeinen Psychologie trifft zu?","opts":[{"t":"Die Kognitive Psychologie entstand als Weiterentwicklung des Behaviorismus, den sie um beobachtbare Reiz-Reaktions-Ketten ergänzte.","c":false,"fb":"Sie entwickelte sich als Gegenreaktion auf den behavioristischen Ansatz, der kognitive Prozesse zur Gänze außer Acht lässt."},{"t":"Als eigener Themenbereich wird die Untersuchung interindividueller Unterschiede in Persönlichkeitsmerkmalen geführt.","c":false,"fb":"Das ist Gegenstand der Differentiellen Psychologie und taucht in der Auflistung der Themenbereiche nicht auf."},{"t":"Unter Volition fallen Prozesse, die mit dem Planen und Erreichen von Zielen zu tun haben.","c":true,"fb":"So definiert es das Skript in der Fußnote zum Themenbereich Emotion, Motivation, Volition (Achtziger & Gollwitzer, 2021)."},{"t":"Kognitiv bedeutet „das Wahrnehmen betreffend“ und bezieht sich auf die Aufnahme sensorischer Reize.","c":false,"fb":"Kognitiv heißt „das Denken betreffend“; die Reizaufnahme ist nur ein Ausschnitt des kognitionspsychologischen Themenspektrums."}],"concept":{"title":"Kognitive Psychologie und die Themenbereiche des Fachs","points":["<b>Kognitive Psychologie</b>: seit der kognitiven Wende der vorherrschende Ansatz der Allgemeinen Psychologie; „kognitiv“ bedeutet „das Denken betreffend“.","<b>Entstehung</b>: als Gegenreaktion zum behavioristischen Ansatz, der kognitive Prozesse vollständig ausklammert. Ziel ist es, Methoden und Theorien zu entwickeln, die den Ablauf kognitiver Prozesse erklären.","<b>Fünf Themenbereiche</b>: Wahrnehmung/Aufmerksamkeit/Bewusstsein · Lernen/Gedächtnis/Wissen · Problemlösen/Denken/Entscheiden · Emotion/Motivation/Volition · Sprache.","<b>Volition</b>: Prozesse rund um das Planen und Erreichen von Zielen (Achtziger & Gollwitzer, 2021).","<b>Prozess der Inputverarbeitung</b>: sensorischer Reiz → Rezeptoren der Sinne → Filter der Aufmerksamkeit → Wahrnehmung → Klassifikation → Denken und Urteilen → Entscheidung → Handlung.","Vorwissen, Bewertungen, Emotion und Motivation greifen in diesen Ablauf laufend ein; Sprache erlaubt es, alle Inhalte mitzuteilen."]}},{"id":"k5-74dc8db739","kap":5,"sec":"5.4.5 Gedächtniseffekte","stem":"Welche Aussagen zum seriellen Positionseffekt und zu den Abrufmethoden treffen zu?","opts":[{"t":"Der Primacy Effekt wird plausibel damit erklärt, dass frühe Wörter innerlich häufiger wiederholt werden können.","c":true,"fb":"Dieses Rehearsal gilt als die naheliegende Erklärung für den besseren Abruf am Listenanfang."},{"t":"Beim Serial Recall dürfen die gelernten Wörter in beliebiger Reihenfolge genannt werden.","c":false,"fb":"Das kennzeichnet den Free Recall. Beim Serial Recall muss die Reihenfolge der Darbietung eingehalten werden."},{"t":"Das Wiedererkennen erfordert in der Regel eine höhere Gedächtnisleistung als die eigenständige Wiedergabe.","c":false,"fb":"Das Verhältnis ist umgekehrt: Recall verlangt in der Regel mehr, da beim Recognition-Test nur alte von neuen Wörtern getrennt werden müssen."},{"t":"Der Recency Effekt wird unter anderem darauf zurückgeführt, dass die letzten Elemente noch im Kurzzeitgedächtnis präsent sind.","c":true,"fb":"Daneben wird eine höhere zeitliche Diskriminierbarkeit der späten Elemente als Erklärung diskutiert (Gruber, 2018)."}],"concept":{"title":"Serieller Positionseffekt und Abrufmethoden","points":["<b>Serieller Positionseffekt</b>: Wörter am Anfang und am Ende einer Liste werden besser erinnert als solche aus der Mitte — bei kurzen wie bei längeren Listen (Jahnke, 1965).","<b>Primacy Effekt</b>: verbesserter Abruf der ersten Elemente; Erklärung ist das häufigere innere Wiederholen (Rehearsal).","<b>Recency Effekt</b>: verbesserter Abruf der letzten Elemente; erklärt über die Präsenz im Kurzzeitgedächtnis und über die höhere zeitliche Diskriminierbarkeit (Gruber, 2018).","<b>Anwendung</b>: Im Marketing werden die wichtigsten Botschaften bewusst an den Anfang und an das Ende einer Kampagne gesetzt.","<b>Recognition (Wiedererkennen)</b>: Alte Wörter müssen von neuen Distraktorwörtern getrennt werden — so funktioniert auch Teil A der Aufnahmeprüfung.","<b>Recall (Wiedergabe)</b>: in der Regel anspruchsvoller als Recognition; <b>Free Recall</b> in beliebiger, <b>Serial Recall</b> in vorgegebener Reihenfolge (Pastötter et al., 2018)."]}},{"id":"k5-a86cd995d9","kap":5,"sec":"5.3.4 Operante Konditionierung","stem":"Welche Aussagen zu Verstärkung und Bestrafung treffen zu?","opts":[{"t":"Bei der negativen Verstärkung wird ein als unangenehm empfundener Reiz weggenommen, wodurch das Verhalten wahrscheinlicher wird.","c":true,"fb":"Beispiel aus dem Skript: die Befreiung von Haushaltsdiensten als Folge einer guten Note."},{"t":"Primäre Verstärker befriedigen keine biologischen Bedürfnisse und entstehen durch klassische Konditionierung.","c":false,"fb":"Das beschreibt sekundäre Verstärker wie Geld. Primäre Verstärker — Nahrung, Wasser — befriedigen biologische Bedürfnisse unmittelbar."},{"t":"Ein Fernsehverbot nach einer schlechten Note ist ein Beispiel für negative Bestrafung.","c":true,"fb":"Es wird ein als angenehm empfundener Reiz weggenommen, um die Auftretenswahrscheinlichkeit des Verhaltens zu senken."},{"t":"Auch bei der operanten Konditionierung lassen sich Löschung und Spontanremission beobachten.","c":true,"fb":"Bleibt die Verstärkung aus, geht das Verhalten auf das Ausgangsniveau zurück; danach kann es erneut spontan auftreten."}],"concept":{"title":"Verstärkung und Bestrafung nach Skinner","points":["<b>Verstärker</b>: Faktoren, die auf ein gezeigtes Verhalten folgen und sein Auftreten wahrscheinlicher machen.","<b>Primär vs. sekundär</b>: primäre Verstärker befriedigen biologische Bedürfnisse (Nahrung, Wasser); sekundäre — etwa Geld — tun das nicht und werden durch klassische Konditionierung geschaffen. Auch Personen können als Verstärker dienen.","<b>Positive Verstärkung</b>: angenehmer Reiz kommt hinzu (gute Note, Taschengeld). <b>Negative Verstärkung</b>: unangenehmer Reiz fällt weg (Befreiung vom Haushaltsdienst). Beide erhöhen die Auftretenswahrscheinlichkeit.","<b>Positive Bestrafung</b>: unangenehmer Reiz kommt hinzu (zusätzlicher Küchendienst). <b>Negative Bestrafung</b>: angenehmer Reiz fällt weg (Fernsehverbot, Hausarrest). Beide senken sie.","<b>Merkhilfe</b>: „positiv/negativ“ meint Hinzufügen oder Wegnehmen, „Verstärkung/Bestrafung“ die Richtung der Wahrscheinlichkeit.","Löschung bei ausbleibender Verstärkung, Spontanremission, Reizgeneralisierung und Reizdiskrimination treten auch hier auf (Gerrig et al., 2018)."]}},{"id":"k5-cd73fedc57","kap":5,"sec":"5.2.1 Wahrnehmung","stem":"Welche Aussagen zu den drei Stufen der Wahrnehmung nach Becker-Carus und Wendt (2017) treffen zu?","opts":[{"t":"Das Perzept, ein mentales Abbild des Wahrgenommenen, entsteht auf der Stufe der Klassifikation.","c":false,"fb":"Das Perzept entsteht auf der zweiten Stufe, der Wahrnehmung im engeren Sinne; die Klassifikation ordnet dieses Abbild erst danach ein."},{"t":"Die sensorische Empfindung wird eher der Biologischen Psychologie zugeordnet, die beiden folgenden Stufen der Allgemeinen Psychologie.","c":true,"fb":"Diese Arbeitsteilung nennt das Skript ausdrücklich; die Stufen zwei und drei sind zudem oft schwer voneinander zu trennen."},{"t":"Auf der dritten Stufe werden die Abbilder in bereits bekannte Kategorien eingeordnet.","c":true,"fb":"Erst dadurch wird aus dem Abbild einer Person etwa eine Fremde, ein Freund oder eine Ärztin."},{"t":"Bereits auf der ersten Stufe entsteht eine innere Repräsentation, die mit Vorerfahrungen abgeglichen wird.","c":false,"fb":"Auf der ersten Stufe werden Reize lediglich aufgenommen und in neuronale Signale umgewandelt; der Abgleich folgt eine Stufe später."}],"concept":{"title":"Die drei Stufen der Wahrnehmung (Becker-Carus & Wendt, 2017)","points":["<b>Wahrnehmung allgemein</b>: Prozess der Aufnahme und Verarbeitung von Reizen aus der Umwelt; die Aufmerksamkeit bestimmt, was aufgenommen wird und trennt Wichtiges von Unwichtigem.","<b>Stufe 1 – Sensorische Empfindung</b>: Rezeptoren der Sinnesorgane nehmen Reize auf und wandeln sie in neuronale Signale um.","<b>Stufe 2 – Wahrnehmung im engeren Sinne</b>: Bildung einer inneren Repräsentation; im Zusammenspiel mit übergeordneten Prozessen entsteht das <b>Perzept</b>, ein mentales Abbild.","<b>Stufe 3 – Klassifikation</b>: Einordnung des Abbilds in bereits bekannte Kategorien.","<b>Zuordnung</b>: Stufe 1 eher Biologische Psychologie, Stufen 2 und 3 Allgemeine Psychologie — praktisch oft schwer trennbar.","Vorwissen, Vorerfahrungen, Bewertungen, Erwartungen und Emotionen beeinflussen, was zwei Personen in derselben Situation wahrnehmen (Kiesel & Koch, 2018)."]}},{"id":"k5-e6e2a81122","kap":5,"sec":"5.4.4 Langzeitgedächtnis","stem":"Welche Aussage zur Amnesie und zum Fall H.M. trifft zu?","opts":[{"t":"Bei einer retrograden Amnesie können keine neuen Gedächtnisinhalte mehr eingespeichert werden.","c":false,"fb":"Das kennzeichnet die anterograde, vorwärts gerichtete Amnesie. Retrograd fehlen Ereignisse kurz vor der Schädigung."},{"t":"Henry Molaison entwickelte nach der Entfernung von Teilen der Temporallappen und des Hippocampus eine ausgeprägte anterograde Amnesie.","c":true,"fb":"Der Eingriff erfolgte wegen starker epileptischer Anfälle; neue Fakten und Ereignisse konnte er danach nicht mehr einspeichern."},{"t":"In perzeptiv-motorischen Lernaufgaben schnitt H.M. durchgehend schlecht ab.","c":false,"fb":"Gerade dort war er erfolgreich und behielt die erlernten Fähigkeiten sogar über ein Jahr hinaus."},{"t":"Die bahnbrechenden Studien zu diesem Fall führte Brenda Milner gemeinsam mit Hermann Ebbinghaus durch.","c":false,"fb":"Ihr Mitautor war der Neurochirurg William B. Scoville (Scoville & Milner, 1957); Ebbinghaus steht für die Vergessenskurve."}],"concept":{"title":"Amnesie und der Fall H.M.","points":["<b>Amnesie</b>: teilweiser Verlust der Erinnerungsfähigkeit infolge einer Schädigung des Gehirns — Ursachen sind Unfälle, aber auch Schlaganfall, Alkoholismus oder Gehirnentzündung.","<b>Retrograde Amnesie</b>: rückwärts gerichtet — Ereignisse kurz <i>vor</i> der Schädigung fehlen, alle übrigen kognitiven Funktionen bleiben intakt.","<b>Anterograde Amnesie</b>: vorwärts gerichtet — <i>neue</i> Inhalte lassen sich nicht mehr einspeichern; tritt häufig zusammen mit einer retrograden Amnesie auf.","<b>Henry Molaison (H.M.)</b>: Nach Entfernung von Teilen der Temporallappen und des Hippocampus wegen schwerer Epilepsie entwickelte er eine ausgeprägte anterograde Amnesie.","<b>Aufschlussreiche Dissoziation</b>: Neue Fakten und Ereignisse blieben ihm verschlossen, perzeptiv-motorische Lernaufgaben gelangen jedoch gut — ein Beleg für getrennte Gedächtnissysteme.","<b>Erforschung</b>: Brenda Milner, Neuropsychologin und Pionierin der kognitiven Neurowissenschaften, gemeinsam mit dem Neurochirurgen William B. Scoville in den 1950er Jahren (Scoville & Milner, 1957)."]}},{"id":"k5-dadece4f53","kap":5,"sec":"5.2.3 Aufmerksamkeit","stem":"Welche Aussagen zum Cueing-Paradigma und zu endogenen bzw. exogenen Hinweisreizen treffen zu?","opts":[{"t":"In der validen Bedingung erschien der Zielreiz in 80 % der Durchläufe auf der Seite, in die der Pfeil zeigte.","c":true,"fb":"In den übrigen 20 % tauchte er auf der Gegenseite auf — das ist die invalide Bedingung."},{"t":"Die Reaktionszeiten waren in den neutralen Durchgängen am kürzesten und in den validen am längsten.","c":false,"fb":"Die Reihenfolge lautet valide < neutral < invalide: Valide Durchgänge waren die schnellsten, invalide die langsamsten."},{"t":"Endogene Hinweisreize wirken bereits ab einer SOA von etwa 50 Millisekunden, exogene erst ab etwa 200 Millisekunden.","c":false,"fb":"Die Werte sind vertauscht: Exogene Reize wirken ab rund 50 ms, endogene brauchen mindestens etwa 200 ms."},{"t":"Exogene Hinweisreize wirken früher, endogene dafür länger — bis zu etwa 500 Millisekunden.","c":true,"fb":"Exogene Reize verlieren ihre Wirkung oft schon nach etwa 200 ms, endogene bleiben deutlich länger wirksam."}],"concept":{"title":"Cueing-Paradigma (Posner, 1980) und die beiden Aufmerksamkeitsarten","points":["<b>Aufbau</b>: Fixation der Bildschirmmitte, dann Hinweisreiz (Cue), dann Zielreiz; abhängige Variable ist die <b>Reaktionszeit</b> auf den Zielreiz.","<b>Drei Bedingungen</b>: neutral (neutrales Symbol, Zielreiz je 50 % links/rechts) · valide (Pfeil, 80 % korrekt) · invalide (20 % auf der Gegenseite).","<b>Ergebnis</b>: valide < neutral < invalide. Weil die Augen fixiert bleiben, scheiden Augenbewegungen als Ursache der kürzeren Reaktionszeit aus.","<b>Endogene Aufmerksamkeit</b>: von innen heraus gesteuert, beeinflusst von Erwartungen, Bewertungen, Vorwissen und Vorerfahrungen (Huestegge, 2022).","<b>Exogene Aufmerksamkeit</b>: wird von äußeren Reizen angezogen; der periphere Cue wirkt durch sein bloßes Erscheinen, ohne Bedeutungsverarbeitung.","<b>SOA (Stimulus-Onset-Asynchrony)</b>: endogen ab ca. 200 ms wirksam und bis ca. 500 ms anhaltend; exogen schon ab ca. 50 ms, aber oft nur bis ca. 200 ms."]}},{"id":"k5-efc3280129","kap":5,"sec":"5.4.5 Gedächtniseffekte","stem":"Welche Aussagen zur Vergessenskurve von Ebbinghaus und zu Interferenzphänomenen treffen zu?","opts":[{"t":"Ebbinghaus arbeitete mit Listen sinnloser Silben nach dem Muster Konsonant-Vokal-Konsonant.","c":true,"fb":"Beispiele aus dem Skript sind FUB, KAH und BIK; er wiederholte solche Listen bis zum fehlerfreien Aufsagen."},{"t":"Nach 24 Stunden ließen sich noch knapp 34 % der Arbeitsleistung einsparen.","c":true,"fb":"Der Verlauf war 58 % nach 20 Minuten, 44 % nach einer Stunde, knapp 34 % nach 24 Stunden und gut 25 % nach sechs Tagen."},{"t":"Von proaktiver Interferenz spricht man, wenn neu gelernte Inhalte das Erinnern älterer Inhalte beeinträchtigen.","c":false,"fb":"Das beschreibt die retroaktive Interferenz. Proaktiv wirkt die ältere Information störend auf das Erinnern der neueren."},{"t":"Die Gedächtnisleistung geht bereits in der ersten Stunde deutlich zurück und nimmt danach nur noch langsam ab.","c":true,"fb":"Dieser steile Abfall mit anschließend flachem Verlauf ist die charakteristische Form der Vergessenskurve."}],"concept":{"title":"Vergessenskurve von Ebbinghaus und Interferenzphänomene","points":["<b>Ebbinghaus</b>: Begründer der experimentellen Gedächtnisforschung; „Über das Gedächtnis“ (1885), gewonnen in Selbstversuchen mit <b>sinnlosen Silben</b> (Konsonant-Vokal-Konsonant, z. B. FUB, KAH, BIK).","<b>Ersparnismethode</b>: Maß für die Gedächtnisleistung sind die beim Wiedererlernen eingesparten Wiederholungen bzw. die eingesparte Zeit — je weniger Zeit nötig, desto mehr wurde behalten.","<b>Verlauf</b>: nach 20 Minuten ca. 58 % Ersparnis, nach einer Stunde 44 %, nach 24 Stunden knapp 34 %, nach sechs Tagen gut 25 %.","<b>Interferenz</b>: Ein großer Teil des Vergessens entsteht dadurch, dass andere Informationen die gewünschten Inhalte verdrängen.","<b>Proaktive Interferenz</b>: <i>ältere</i> Inhalte erschweren das Erinnern <i>neuer</i> — früh gelerntes Spanisch stört das spätere Italienisch.","<b>Retroaktive Interferenz</b>: <i>neue</i> Inhalte erschweren das Erinnern <i>älterer</i> — nach dem Chemielernen fehlt der Physikstoff. Merkhilfe: Die Vorsilbe nennt die Richtung, in die gestört wird."]}},{"id":"k5-b147342950","kap":5,"sec":"5.3.1 Lernen","stem":"Welche Aussage zum psychologischen Lernbegriff und zum nicht-assoziativen Lernen trifft zu?","opts":[{"t":"Bei der Sensitivierung führt die wiederholte Darbietung eines Reizes zu einer abnehmenden Reaktionsbereitschaft.","c":false,"fb":"Abnehmend ist die Reaktion bei der Habituation. Die Sensitivierung erhöht Empfindlichkeit und Reaktionsbereitschaft, meist bei schmerzhaften Reizen."},{"t":"Habituation und Sensitivierung gelten als nicht-assoziatives Lernen, weil keine Assoziationen zwischen Gegebenheiten gebildet werden müssen.","c":true,"fb":"Damit grenzen sie sich von klassischer und operanter Konditionierung ab, bei denen genau solche Verknüpfungen entstehen."},{"t":"Die Ausbildung der Theory of Mind wird als Lernprozess eingeordnet, da sie auf Erfahrung beruht.","c":false,"fb":"Sie zählt zu den Entwicklungsprozessen; Lernen setzt eine durch Erfahrung bewirkte Änderung des Verhaltenspotenzials voraus."},{"t":"Verhaltensänderungen infolge von Ermüdung oder Drogeneinfluss zählen zum Lernen, sofern sie beobachtbar sind.","c":false,"fb":"Das Kriterium der überdauernden Veränderung schließt genau solche vorübergehenden Zustandsänderungen aus."}],"concept":{"title":"Lernen, Verhaltenspotenzial und nicht-assoziatives Lernen","points":["<b>Definition</b>: durch Erfahrung entstandene, relativ überdauernde Verhaltensänderungen (Gerrig et al., 2018) — nicht deterministisch, sondern als veränderte Auftretenswahrscheinlichkeit zu verstehen.","<b>Verhaltenspotenzial</b>: Gelerntes muss sich nicht sofort in Leistung zeigen; die Änderung kann erst viel später sichtbar werden.","<b>Abgrenzungen</b>: Reife- und Entwicklungsprozesse zählen nicht dazu — die Theory of Mind ist ein Entwicklungs-, kein Lernprozess. „Überdauernd“ schließt Ermüdung und Drogeneinfluss aus.","<b>Explizit vs. implizit</b>: bewusstes Aneignen (Schule, Prüfungsvorbereitung) gegenüber automatisch ablaufenden Prozessen ohne bewusste Verarbeitung (I. Koch & Stahl, 2017).","<b>Habituation</b>: Gewöhnung an einen zunächst auffälligen, aber ungefährlichen Reiz — die Orientierungsreaktion nimmt ab.","<b>Sensitivierung</b>: umgekehrter Fall — bei erschreckenden oder schmerzvollen Reizen steigen Empfindlichkeit und Reaktionsbereitschaft; beides zusammen bildet das <b>nicht-assoziative Lernen</b>."]}},{"id":"k5-d39f50c9b6","kap":5,"sec":"5.4.3 Arbeitsgedächtnis","stem":"Welche Aussagen zum Arbeitsgedächtnismodell nach Baddeley treffen zu?","opts":[{"t":"Die phonologische Schleife verarbeitet sprachbasierte Informationen, auch still mitgesprochene geschriebene Wörter.","c":true,"fb":"Beim Eintippen einer gelesenen Telefonnummer hält sie die Ziffern, bis sie im Handy stehen."},{"t":"Der visuell-räumliche Notizblock kontrolliert die Aufmerksamkeit und koordiniert die übrigen Komponenten.","c":false,"fb":"Diese Aufgabe übernimmt die zentrale Exekutive. Der Notizblock speichert visuelle und räumliche Informationen kurzfristig."},{"t":"Der episodische Puffer wurde erst rund 25 Jahre nach dem ursprünglichen Modell ergänzt.","c":true,"fb":"Baddeley (2000) fügte ihn als Schnitt- und Speicherstelle zwischen den Komponenten sowie zum Langzeitgedächtnis hinzu."},{"t":"Baddeley und Hitch behielten den Begriff des Kurzzeitspeichers bei, weil dieser ausschließlich Gedächtnisaufgaben dient.","c":false,"fb":"Sie ersetzten ihn durch das Arbeitsgedächtnis, gerade weil es auch andere komplexe Aufgaben wie Kopfrechnen trägt."}],"concept":{"title":"Das Arbeitsgedächtnismodell (Baddeley & Hitch, 1974; Baddeley, 2000)","points":["<b>Anlass</b>: Kritik am Modell von Atkinson & Shiffrin; der Begriff <i>Kurzzeitspeicher</i> wird durch <b>Arbeitsgedächtnis</b> ersetzt, weil dieses auch andere komplexe Aufgaben trägt.","<b>Zentrale Exekutive</b>: komplexeste Komponente; kontrolliert die Aufmerksamkeit und koordiniert die übrigen Bestandteile, die als Hilfssysteme gelten.","<b>Phonologische Schleife</b>: Verarbeitung und kurzfristige Speicherung sprachbasierter Information — gesprochene wie beim Lesen still mitgesprochene Wörter.","<b>Visuell-räumlicher Notizblock</b>: dasselbe für visuelle und räumliche Information, etwa einen beschriebenen Weg.","<b>Episodischer Puffer</b> (Baddeley, 2000): 25 Jahre später ergänzt; verbindet die Komponenten untereinander sowie mit Wahrnehmung und Langzeitgedächtnis.","Die drei Hilfssysteme haben begrenzte Kapazität und arbeiten weitgehend unabhängig; selektive Gedächtnisausfälle nach Hirnschädigungen lassen sich damit besser erklären als mit dem Drei-Speicher-Modell."]}},{"id":"k5-674276d1ad","kap":5,"sec":"5.2.4 Visuelle Wahrnehmung","stem":"Welche Aussagen zur Tiefen- und Größenwahrnehmung treffen zu?","opts":[{"t":"Zur Linienperspektive zählt, dass parallel verlaufende Linien in der Entfernung aufeinander zulaufen.","c":true,"fb":"Sie gehört zu den monokularen Hinweisen, für die die Information eines Auges genügt."},{"t":"Weiter entfernte Objekte wirken bläulicher und weniger gesättigt — das nennt man atmosphärische Perspektive.","c":true,"fb":"Diese Färbung dient als Hinweis darauf, dass ein Objekt weiter weg ist."},{"t":"Konvergenz und Akkommodation werden als okulomotorische Tiefenhinweise bis zu einer Entfernung von drei Metern genutzt.","c":true,"fb":"Die Augen bewegen sich nach innen und die Linse verdickt sich — beides sind binokulare, okulomotorische Hinweise."},{"t":"Der Ames-Raum beruht auf einer gezielten Manipulation von Tiefenhinweisen wie der Linienperspektive.","c":true,"fb":"Zwei unterschiedlich weit entfernte Ecken erscheinen gleich weit entfernt, wodurch die nähere Person deutlich größer wirkt."}],"concept":{"title":"Tiefen- und Größenwahrnehmung","points":["<b>Monokulare Hinweise</b> (ein Auge genügt): Linienperspektive · relative Größe (der kleinere von zwei gleichen Gegenständen wirkt ferner) · Verdeckung (der verdeckte Gegenstand wirkt ferner) · atmosphärische Perspektive (bläulich, weniger gesättigt = weiter weg).","<b>Binokulare Hinweise</b>: benötigen die Information beider Augen.","<b>Okulomotorische Tiefenhinweise</b>: Konvergenz (Augen bewegen sich nach innen) und Akkommodation (Linse verdickt sich) — nutzbar bis etwa 3 Meter.","<b>Querdisparation</b>: leicht unterschiedliche Netzhautbilder beider Augen; sie allein genügt für einen Tiefeneindruck — sichtbar an Autostereogrammen.","<b>Ames-Raum</b> (Adelbert Ames, 1935): manipulierte Tiefenhinweise lassen zwei unterschiedlich weit entfernte Ecken gleich weit erscheinen.","<b>Folge im Ames-Raum</b>: Da die kleinere Person nicht als „weiter weg“ interpretiert werden kann, erscheint die nähere Person schlicht viel größer (Gazzaniga et al., 2017)."]}},{"id":"k5-9fe42e5232","kap":5,"sec":"5.2.3 Aufmerksamkeit","stem":"Welche Aussagen zu den klassischen Untersuchungen der Aufmerksamkeit treffen zu?","opts":[{"t":"Broadbent (1954) leitete aus dem Split-Span-Paradigma ab, dass die Zahlen vor der Weiterverarbeitung nach ihrer Lokalisation selektiert werden.","c":true,"fb":"Die Versuchspersonen gaben die Zahlen meist ohrweise statt paarweise wieder — die Lokalisation diente als Hinweisreiz zur Trennung."},{"t":"Beim dichotischen Hören nach Cherry (1953) konnten die Versuchspersonen den Inhalt des unbeachteten Ohrs in der Regel wiedergeben.","c":false,"fb":"Dazu konnten sie meist keine Angaben machen: Die Inhalte am anderen Ohr wurden zwar gehört, aber nicht wahrgenommen."},{"t":"Als Experimentalparadigma bezeichnet man einen häufig verwendeten experimentellen Aufbau zur Untersuchung eines bestimmten Gegenstands.","c":true,"fb":"Das Cueing-Paradigma und das Split-Span-Paradigma nennt das Skript als Beispiele dafür."},{"t":"Im Experiment von Simons und Chabris (1999) entdeckte die Gruppe, die die Pässe des weißen Teams zählte, den Gorilla häufiger.","c":false,"fb":"Es war umgekehrt: 83 % der Personen, die das schwarze Team zählten, sahen den Gorilla — beim weißen Team waren es nur 42 %."}],"concept":{"title":"Selektive Aufmerksamkeit und ihre Untersuchungsparadigmen","points":["<b>Aufmerksamkeit</b>: Filter, der vorsortiert, welche physikalischen Reize relevant sind; die <b>selektive Aufmerksamkeit</b> wählt aus vielen Sinneseindrücken eine Teilmenge aus.","<b>Unaufmerksamkeitsblindheit</b> (Simons & Chabris, 1999): 83 % der Personen, die die Pässe des <i>schwarzen</i> Teams zählten, entdeckten den Gorilla — beim weißen Team nur 42 %.","<b>Cocktailparty-Effekt</b>: Beispiel für selektives Hören; der eigene Name im Nebengespräch zieht die Aufmerksamkeit ab (Krummenacher & Müller, 2017).","<b>Dichotisches Hören</b> (Cherry, 1953): Das Wiedergeben des beachteten Textes gelingt leicht, der Inhalt am anderen Ohr wird gehört, aber nicht wahrgenommen.","<b>Split-Span-Paradigma</b> (Broadbent, 1954): Zahlenpaare werden meist ohrweise statt paarweise wiedergegeben → Selektion nach physikalischen Eigenschaften, hier der Lokalisation.","<b>Experimentalparadigma</b>: etablierter Versuchsaufbau für einen bestimmten Untersuchungsgegenstand — im Skript etwa das Cueing- und das Split-Span-Paradigma."]}},{"id":"k5-f4906b1be2","kap":5,"sec":"5.3.5 Beobachtungslernen","stem":"Welche Aussage zum Beobachtungslernen und zu den Bobo-Doll-Experimenten trifft zu?","opts":[{"t":"Das Beobachtungslernen wird dem Behaviorismus zugerechnet, weil es auf Reiz, Reaktion und Verstärkung beruht.","c":false,"fb":"Es zählt zur kognitiven Psychologie und erklärt gerade jene Lernprozesse, die nicht auf Reiz, Reaktion und Verstärkung zurückgehen."},{"t":"Im Experiment von 1965 zeigten jene Kinder die geringste Aggression, die ein Filmende mit Tadel gesehen hatten.","c":true,"fb":"Belohntes Modell und Modell ohne Konsequenzen führten dagegen zu deutlich mehr physischer und verbaler Aggression."},{"t":"Die Kinder der nicht-aggressiven Bedingung ahmten das Modell in abgeschwächter Form nach.","c":false,"fb":"Sie zeigten so gut wie kein aggressives Verhalten; die Nachahmung trat nur in der aggressiven Bedingung auf."},{"t":"Blieben Konsequenzen für die erwachsene Person aus, verhielten sich die Kinder ähnlich zurückhaltend wie nach der Tadelbedingung.","c":false,"fb":"Die Gruppe ohne Konsequenzen lag auf ähnlich hohem Aggressionsniveau wie die Gruppe mit belohntem Modell."}],"concept":{"title":"Beobachtungslernen und die Bobo-Doll-Experimente (Bandura)","points":["<b>Bezeichnungen</b>: Modelllernen, Lernen am Modell, Imitationslernen, soziales Lernen, sozialkognitive Lerntheorie — zugeordnet der kognitiven Psychologie, nicht dem Behaviorismus.","<b>Prinzip</b>: Gelernt wird durch Beobachtung anderer Lebewesen, ohne eigene Erfahrung mit Reiz, Reaktion und Verstärkung.","<b>Bobo-Doll-Experiment</b> (Bandura, Ross & Ross, 1961): Vierjährige sahen ein Modell entweder aggressiv oder nicht-aggressiv gegenüber der Puppe; nur die aggressive Bedingung führte zu ähnlichem physischem und verbalem Verhalten.","<b>Stellvertretendes Lernen</b> (Bandura, 1965): Drei Filmenden — belohnt, getadelt, ohne Konsequenzen. Gruppe 1 und Gruppe 3 zeigten mehr Aggression als die Tadelgruppe; auch Konsequenzen werden also durch Beobachtung gelernt.","<b>Menschenbild</b>: aktiv Lernender; Lernen entsteht in Wechselwirkung von Person und Umwelt (soziale Komponente) sowie durch Planen, Reflektieren und Selbstmotivieren (kognitive Komponente).","Daraus entwickelten sich die sozial-kognitiven Persönlichkeitstheorien (Hobmair, 2012; vgl. Kapitel 8.2.4)."]}},{"id":"k5-0f17885cce","kap":5,"sec":"5.2.2 Theorien der Wahrnehmung","stem":"Welche Aussagen zur Signalentdeckungstheorie treffen zu?","opts":[{"t":"Die zweite Komponente, der kognitive Entscheidungsprozess, variiert unmittelbar mit der Sensitivität der Person.","c":false,"fb":"Der Entscheidungsprozess wird ausdrücklich als von der Sensitivität unabhängig beschrieben; er greift vor allem bei uneindeutigen Reizen."},{"t":"Wird kein Reiz dargeboten und die Person meldet dennoch einen Reiz, liegt ein falscher Alarm vor.","c":true,"fb":"Das Gegenstück ist die korrekte Zurückweisung: kein Reiz dargeboten und keiner berichtet."},{"t":"Eine Nein-Sage-Tendenz äußert sich in einer vergleichsweise hohen Anzahl an Verpassern.","c":true,"fb":"Bei Unsicherheit wird eher „kein Reiz“ angegeben — auch dann, wenn tatsächlich einer dargeboten wurde."},{"t":"Eine Antworttendenz ist ein systematisches Muster im Antwortverhalten, das unabhängig vom Untersuchungsgegenstand auftritt.","c":true,"fb":"Sie kann zugunsten oder zuungunsten einer bestimmten Antwortart ausfallen; die Ja-Sage-Tendenz ist ein Beispiel dafür."}],"concept":{"title":"Signalentdeckungstheorie","points":["<b>Grundannahme</b>: Das Entdecken eines Reizes ist kein objektiver, sondern ein subjektiver Prozess aus zwei Komponenten — motivationale Faktoren und konkurrierende Reize blieben in der Psychophysik unbeachtet.","<b>Sensitivität</b>: Empfindlichkeit gegenüber dem Reiz, stark beeinflusst von der Anwesenheit anderer Reize (voller Raum vs. geräuscharmer Raum).","<b>Kognitiver Entscheidungsprozess</b>: von der Sensitivität <b>unabhängig</b>; entscheidet vor allem bei uneindeutigen Reizen über „vorhanden / nicht vorhanden“.","<b>Vier mögliche Ausgänge</b>: Treffer (Reiz + Ja) · Verpasser (Reiz + Nein) · Falscher Alarm (kein Reiz + Ja) · Korrekte Zurückweisung (kein Reiz + Nein).","<b>Ja-Sage-Tendenz</b>: viele Treffer <i>und</i> auffällig viele falsche Alarme. <b>Nein-Sage-Tendenz</b>: auffällig viele Verpasser. Beides sind <b>Antworttendenzen</b>, also systematische Muster unabhängig vom Untersuchungsgegenstand.","Die gegebene Antwort ist damit nie Resultat des Reizes allein, sondern einer Kombination aus Reiz und kognitiven Prozessen (Becker-Carus & Wendt, 2017; Gazzaniga et al., 2017)."]}},{"id":"k5-eb5bdc6fcf","kap":5,"sec":"5.4.5 Gedächtniseffekte","stem":"Welche Aussagen zum Prinzip der Enkodierspezifität treffen zu?","opts":[{"t":"Der Abruf gelingt besser, wenn die während der Enkodierung herrschenden Zustände denen beim Abruf ähneln.","c":true,"fb":"Das ist die allgemeine Formulierung des Prinzips — sie gilt für Aufgabenformate ebenso wie für Kontexte."},{"t":"Bei Godden und Baddeley (1975) war die Erinnerungsleistung am besten, wenn Lern- und Abfrageort auseinanderfielen.","c":false,"fb":"Die Leistung war gerade dann am besten, wenn Lern- und Abfrageort übereinstimmten — obwohl der Ort für die Aufgabe irrelevant war."},{"t":"Morris, Bransford und Franks (1977) zeigten, dass semantische Enkodierung dem Abruf unabhängig von der Abrufaufgabe überlegen ist.","c":false,"fb":"Beim Reimtest kehrte sich der Effekt der Verarbeitungstiefe um: Phonemisch enkodierte Wörter wurden besser erkannt."},{"t":"Passungseffekte betreffen nicht nur äußere Lernumgebungen, sondern auch innere Zustände wie die Stimmung.","c":true,"fb":"In trauriger Stimmung Eingeprägtes lässt sich in trauriger Stimmung leichter abrufen."}],"concept":{"title":"Das Prinzip der Enkodierspezifität","points":["<b>Grundaussage</b>: Die Gedächtnisleistung beim Abruf ist besser, wenn die Zustände während der Enkodierung denen beim Abruf ähneln.","<b>Morris, Bransford und Franks (1977)</b>: Bei einem Reimtest wurden phonemisch enkodierte Wörter besser erkannt als semantisch enkodierte — der Effekt der Verarbeitungstiefe kehrte sich um. Entscheidend ist die <b>Passung</b> zwischen Einpräge- und Abrufaufgabe.","<b>Godden und Baddeley (1975)</b>: Taucher:innen lernten und erinnerten Wortlisten unter Wasser oder am Ufer; die Leistung war am besten, wenn Lern- und Abfrageort übereinstimmten.","<b>Reichweite</b>: Kontexteffekte betreffen äußere Lernumgebungen ebenso wie innere Zustände, etwa die emotionale Verfassung.","<b>Erklärung</b>: Mit dem Lernmaterial werden auch die Kontextbedingungen eingespeichert; beim Abruf wirken sie als Hinweisreize (Pastötter et al., 2018).","Bemerkenswert daran: Der Kontext wirkt selbst dann, wenn er für die eigentliche Aufgabe inhaltlich völlig irrelevant ist."]}},{"id":"k5-181627bb86","kap":5,"sec":"5.3.4 Operante Konditionierung","stem":"Welche Aussage zu Thorndikes Problemkäfig und zur Skinner-Box trifft zu?","opts":[{"t":"Bei Thorndikes Paradigma war eine Assoziation zwischen zwei Reizen beobachtbar, wie sie auch der klassischen Konditionierung zugrunde liegt.","c":false,"fb":"Beobachtbar war eine Reiz-Reaktions-Verbindung: Der Mechanismus stellte den Reiz dar, sein Bedienen die Reaktion."},{"t":"Skinner entwickelte seine operante Kammer rund fünfzehn Jahre vor Thorndikes Arbeiten am Problemkäfig.","c":false,"fb":"Skinner baute den Problemkäfig etwa dreißig Jahre nach Thorndike weiter und setzte dabei auf dessen Gesetz des Effekts auf."},{"t":"Als Operandum bezeichnete Skinner alles, was in der Versuchsanordnung einen Vorgang auslösen konnte, etwa einen Hebel oder eine Taste.","c":true,"fb":"Weil der Käfig klein und reizarm war, betätigte das Tier früher oder später zwangsläufig ein vorhandenes Operandum."},{"t":"Nach dem Gesetz des Effekts sinkt die Auftretenswahrscheinlichkeit einer Reaktion, wenn ihr eine befriedigende Konsequenz folgt.","c":false,"fb":"Sie steigt in diesem Fall. Bleibt die befriedigende Konsequenz aus, vermindert sich die Wahrscheinlichkeit."}],"concept":{"title":"Von Thorndikes Problemkäfig zur Skinner-Box","points":["<b>Problemkäfig</b> (Thorndike, 1898): Katzen befreiten sich zunächst eher zufällig über einen Mechanismus; in weiteren Durchgängen gelang das immer schneller.","<b>S-R-Verbindung</b>: Anders als bei Pawlow verknüpft sich hier ein Reiz (Mechanismus) mit einer Reaktion (Bedienen) — gelernt über <b>Versuch und Irrtum</b>.","<b>Gesetz des Effekts</b>: Lernen wird durch seine Konsequenzen beeinflusst — folgt eine befriedigende Konsequenz, steigt die Auftretenswahrscheinlichkeit der Reaktion; bleibt sie aus, sinkt sie.","<b>Skinners Kritik</b>: „befriedigende Zustände“ seien nicht empirisch beobachtbar; rund dreißig Jahre nach Thorndike formalisierte er die Theorie stärker.","<b>Skinner-Box</b>: von Skinner selbst <i>operante Kammer</i> genannt; klein und reizarm, mit mindestens einem <b>Operandum</b> (Hebel, Taste), das zwangsläufig betätigt wird.","<b>Vorgehen</b>: erst die <b>Basisrate</b> ohne Verstärkung bestimmen, dann die Konditionierungsphase mit gezielter Verstärkung (Spada, Rummel & Ernst, 2018)."]}},{"id":"k5-0ae11ceebc","kap":5,"sec":"5.2.4 Visuelle Wahrnehmung","stem":"Welche Aussagen zu den Theorien des Farbensehens und zu Komplementärfarben treffen zu?","opts":[{"t":"Die Dreifarbentheorie geht auf Thomas Young zurück und wurde von Hermann von Helmholtz aufgegriffen und weiterentwickelt.","c":true,"fb":"Young postulierte sie zu Beginn des 19. Jahrhunderts; heute bestätigen drei Zapfentypen in der Retina die Grundannahme."},{"t":"Dass längeres Betrachten einer Farbe ein Nachbild in der Komplementärfarbe erzeugt, erklärt die Dreifarbentheorie.","c":false,"fb":"Genau dieses Phänomen blieb der Dreifarbentheorie verschlossen; die Gegenfarbentheorie erklärt es über die Ermüdung einer Komponente."},{"t":"Im RGB-Modell gelten Rot–Grün, Blau–Gelb sowie Schwarz–Weiß als Komplementärfarbenpaare.","c":false,"fb":"Diese Paare stammen aus Herings Gegenfarbentheorie. Im RGB-Modell sind es Rot–Cyan, Grün–Magenta und Blau–Gelb."},{"t":"Nach Hering reagiert die Rot-Grün-Einheit auf Rot mit einer Erhöhung und auf Grün mit einer Verminderung der Aktivität.","c":true,"fb":"Da eine Einheit nicht gleichzeitig erhöht und vermindert reagieren kann, ist ein grünliches Rot nicht wahrnehmbar."}],"concept":{"title":"Zwei Theorien des Farbensehens und die Komplementärfarben","points":["<b>Physikalische Basis</b>: Das menschliche Auge nimmt Wellenlängen von etwa 400–700 nm wahr; 500–570 nm werden als Grün gesehen. Lichtintensität = <b>Helligkeit</b>, Reinheit = <b>Sättigung</b>.","<b>Dreifarbentheorie</b> (Young, weitergeführt von von Helmholtz): Jede Farbe ist eine Kombination von Licht in drei Wellenlängen; drei Rezeptorsysteme mit unterschiedlicher spektraler Empfindlichkeit — heute bestätigt durch drei Zapfentypen. Farbblindheit entsteht durch Ausfall oder Fehlen von Rezeptortypen.","<b>Gegenfarbentheorie</b> (Hering): drei gegensätzlich wirkende Einheiten — Rot–Grün, Blau–Gelb, Schwarz–Weiß. Die Rot-Grün-Einheit reagiert auf Rot mit erhöhter, auf Grün mit verminderter Aktivität.","<b>Konsequenz daraus</b>: kein grünliches Rot, wohl aber ein grünliches Blau — wenn beide Einheiten geringe Aktivität zeigen.","<b>Nachbilder</b>: erklärbar über die Gegenfarbentheorie — eine Komponente ermüdet, die andere ist bei neutraler Reizung aktiver.","<b>Komplementärfarben</b>: Farbpaare, die kombiniert Weiß oder Grau ergeben. Bei Hering Rot–Grün, Blau–Gelb, Schwarz–Weiß; im RGB-Modell dagegen Rot–Cyan, Grün–Magenta und Blau–Gelb (Pinel et al., 2019)."]}},{"id":"k5-54c0295ff0","kap":5,"sec":"5.4.2 Drei-Speicher-Modell","stem":"Welche Aussagen zum Drei-Speicher-Modell von Atkinson und Shiffrin (1968) treffen zu?","opts":[{"t":"Ohne Kontrollprozesse stehen Informationen im Kurzzeitspeicher noch etwa fünf Minuten zur Verfügung.","c":false,"fb":"Nach etwa 30 Sekunden zerfallen sie oder werden durch neue Informationen verdrängt."},{"t":"Im ikonischen Register werden visuelle, im echoischen Register auditive Informationen gehalten.","c":true,"fb":"Der sensorische Speicher besteht aus solchen modalitätsspezifischen Registern; auch für die übrigen Sinne werden sie angenommen."},{"t":"Der sensorische Speicher verfügt über eine enorme Kapazität, hält seine Inhalte aber nur sehr kurz.","c":true,"fb":"Nur die beachteten Informationen gelangen weiter — der Großteil zerfällt (Pastötter, Oberauer & Bäuml, 2018)."},{"t":"Kritisiert wurde vor allem die zentrale Stellung des Kurzzeitspeichers, den nach dem Modell sämtliche neuen Informationen passieren müssen.","c":true,"fb":"Personen mit stark reduzierter verbaler Kurzzeitspanne konnten dennoch Sprache verstehen und Neues lernen."}],"concept":{"title":"Das Drei-Speicher-Modell (Atkinson & Shiffrin, 1968)","points":["<b>Sensorischer Speicher</b>: modalitätsspezifische Register — ikonisch für visuelle, echoisch für auditive Information; enorme Kapazität, sehr kurze Dauer. Nur Beachtetes gelangt weiter, der Rest zerfällt.","<b>Kurzzeitspeicher</b>: erhält Informationen aus dem sensorischen <i>und</i> aus dem Langzeitspeicher; ohne Kontrollprozesse zerfallen sie nach etwa <b>30 Sekunden</b> oder werden verdrängt.","<b>Kontrollprozesse</b>: aktives Wiederholen sowie Verknüpfen der Inhalte untereinander oder mit Langzeitwissen überführen Information in den Langzeitspeicher.","<b>Langzeitspeicher</b>: theoretisch zeitlich unbegrenzt; Erinnern kann dennoch am Wiederauffinden oder an <b>Interferenz</b> mit ähnlichen Inhalten scheitern.","<b>Verlustmechanismen im Modell</b>: Zerfall (sensorisch) · Verdrängung (Kurzzeitspeicher) · Interferenz (Langzeitspeicher).","<b>Kritik</b>: die Schlüsselstellung des Kurzzeitspeichers. Personen mit stark reduzierter verbaler Kurzzeitspanne lernten dennoch Neues, und Wortlisteneffekte belegen eine enge Wechselbeziehung zum Langzeitwissen (Pastötter et al., 2018)."]}},{"id":"k6-7e534e3659","kap":6,"sec":"6.3.1 Piaget – Stadien","stem":"Welche Zuordnungen zu Piagets Entwicklungsstadien treffen zu?","opts":[{"t":"Im präoperatorischen Stadium gelingt es dem Kind erstmals, logische Schlussfolgerungen rein auf gedanklicher Basis abzuleiten – etwa den eigenen Heimweg in eine Karte einzuzeichnen.","c":false,"fb":"Die beschriebene Leistung gehört zum konkret-operatorischen Stadium (ca. 7–11 Jahre). Das präoperatorische Stadium ist durch den rasanten Spracherwerb und einfache mentale Operationen gekennzeichnet."},{"t":"Das sensumotorische Stadium reicht von der Geburt bis etwa zum zweiten Lebensjahr; Intelligenz zeigt sich hier vor allem über sensorische und motorische Fähigkeiten.","c":true,"fb":"Fühlen, Greifen, Schmecken, Riechen und Sehen stehen im Zentrum, das Kind ist stark im Hier und Jetzt verankert."},{"t":"Als Errungenschaft des konkret-operatorischen Stadiums gilt der Spracherwerb.","c":false,"fb":"Der Spracherwerb ist die Errungenschaft des präoperatorischen Stadiums; konkret-operatorisch sind die Prinzipien der Erhaltung von Zahlen, Masse und Gewicht."},{"t":"Im formal-operatorischen Stadium wenden Jugendliche zunehmend fortgeschrittene deduktive Logik an, etwa Schlüsse der Form „Wenn A, dann B“ und „nicht B“ → „nicht A“.","c":true,"fb":"Ab etwa 11 Jahren kommen abstraktes Denken und hypothetisches Schlussfolgern hinzu; die eigene Wirklichkeit wird als eine von mehreren möglichen begriffen."}],"concept":{"title":"Die vier Entwicklungsstadien nach Piaget (Tabelle 6.3)","points":["<b>Sensumotorisch (Geburt–2 J.)</b>: Welt über basale Sinneswahrnehmung und Motorik, Zirkulärreaktionen, erste Schemata. Errungenschaft: <b>Objektpermanenz</b>.","<b>Präoperatorisch (2–7 J.)</b>: rasante Sprachentwicklung, simple mentale Operationen, Animismus und Realismus. Errungenschaft: <b>Spracherwerb</b>.","<b>Konkret-operatorisch (7–11 J.)</b>: logisches Denken auf Basis gedanklicher Vorgänge, Reversibilität. Errungenschaft: <b>Gesetz der Erhaltung / Invarianzprinzip</b>.","<b>Formal-operatorisch (ab 11 J. bis Erwachsenenalter)</b>: abstrakte, hypothetische Konzepte, deduktive Logik, ethische und wissenschaftliche Fragestellungen. Errungenschaft: <b>abstrakte Logik</b>.","<b>Stadienlogik</b>: diskontinuierlicher Sprung von einer kohärenten Art des Verstehens zur nächsthöheren; Reihenfolge bei allen Menschen gleich, Übergangszeiten kurz, jede Stufe qualitativ neu und kontextübergreifend sichtbar.","<b>Merkregel</b>: Das Stadium bestimmt sich nicht nur über das Erreichte, sondern auch darüber, dass die Errungenschaft des Folgestadiums noch fehlt."]}},{"id":"k6-242a9c6ba1","kap":6,"sec":"6.4.1 Bindung","stem":"Welche Aussage über die vier Bindungstypen aus der Fremde-Situation ist korrekt?","opts":[{"t":"Bindungstyp A (unsicher-vermeidend) zeigt sich darin, dass das Kind nach der Rückkehr der Bezugsperson Trost sucht, diesen aber nicht annehmen kann.","c":false,"fb":"Das beschreibt Typ C (unsicher-ambivalent). Typ-A-Kinder holen sich gerade keinen Trost und vermeiden es, Gefühle zu zeigen."},{"t":"Als sichere Bindung gelten die Typen A und B, während C und D als unsicher eingestuft werden.","c":false,"fb":"Nur Typ B gilt als sichere Bindung; A, C und D werden als unsichere Bindungen bezeichnet."},{"t":"Kinder des Typs A wirken nach außen ruhig, weisen über das Speichel-Cortisol gemessen aber ein sehr hohes Stressniveau auf.","c":true,"fb":"Die Speichelentnahmen zeigten die Diskrepanz zwischen äußerlicher Ruhe und tatsächlicher Stressbelastung – ein zentrales Argument dafür, dass Typ A nicht das gesunde Muster ist."},{"t":"Bindungstyp D wurde 1978 von Ainsworth, Blehar, Waters und Wall als vierter Typ ergänzt.","c":false,"fb":"Der desorganisierte Typ wurde erst 1990 von Mary Main und Judit Solomon hinzugefügt; 1978 stammt die Typologie A–C."}],"concept":{"title":"Bindungstypen nach Ainsworth (Ainsworth, Blehar, Waters & Wall, 1978; Typ D: Main & Solomon, 1990)","points":["<b>Typ A – unsicher-vermeidend</b>: äußerlich ruhig, sucht keinen Trost, vermeidet Gefühlsausdruck. Erfahrung: Bezugsperson reagiert nicht zuverlässig, Trostsuche „lohnt nicht“.","<b>Typ B – sicher gebunden</b>: weint beim Verlassen, sucht sofort Kontakt bei Rückkehr, lässt sich beruhigen. Eltern agieren vorrangig autonom und haben sich aus der eigenen Elternbeziehung gelöst.","<b>Typ C – unsicher-ambivalent</b>: kann nach der Rückkehr nicht entspannen, sucht Trost, nimmt ihn aber nicht an. Vorerfahrung: ambivalente, von liebevoll bis abweisend schwankende Reaktionen; Eltern oft noch in der Beziehung zu den eigenen Eltern verhaftet.","<b>Typ D – unsicher-desorganisiert</b>: konfuses Verhalten, Schreien am Boden, „Einfrieren“, mitunter Aggression. Annahme: Traumatisierungen in den ersten Lebensmonaten, unvorhersagbares Elternverhalten.","<b>Sicher vs. unsicher</b>: nur B ist sicher; A, C und D sind unsicher. Die Buchstabenfolge ist historisch – A wirkte nach außen ruhiger als das weinende B.","<b>Befundlage</b>: Gültigkeit über Kulturen hinweg gezeigt; Sensitivität der Bindungsperson als zentraler Umweltfaktor; die Bindungsperson muss nicht die Mutter sein."]}},{"id":"k6-42a7ddc10d","kap":6,"sec":"6.2.1 Pränatale Entwicklung","stem":"Welche Aussagen über Teratogene und sensible Phasen treffen zu?","opts":[{"t":"Teratogene können biologischer, physikalischer oder chemischer Natur sein; dazu zählen unter anderem Erkrankungen der Mutter, ionisierende Strahlung und Luftverschmutzung.","c":true,"fb":"Teratogene sind Umwelteinflüsse, die die gesunde Entwicklung des Fötus beeinträchtigen und Schädigungen des Organismus verursachen können; Suchtmittelkonsum der Mutter gehört ebenfalls dazu."},{"t":"Wie schwer die Folgen ausfallen, hängt allein vom Zeitpunkt der Einwirkung ab.","c":false,"fb":"Neben dem Zeitpunkt bestimmen auch Menge und Dauer des schädlichen Einflusses mit, wie schwerwiegend die Folgen für das Kind sind."},{"t":"Als sensible Phasen gelten meist Zeiträume starken Wachstums, in denen das Ungeborene besonders empfindlich reagiert.","c":true,"fb":"Das Kind ist zu verschiedenen Zeitpunkten im Mutterleib unterschiedlich anfällig; Wachstumsphasen sind besonders verletzlich."},{"t":"Ein niedriger sozioökonomischer Status kann über Mangelernährung der Mutter zu einer Unterversorgung des Kindes führen.","c":true,"fb":"Finanzielle Not oder Obdachlosigkeit wirken über die Ernährung der Mutter auf das Ungeborene; auch chronischer Stress und Missbrauch sind nachweislich schädlich."}],"concept":{"title":"Teratogene und ihre Wirkbedingungen","points":["<b>Definition</b>: Umwelteinflüsse, die die gesunde Entwicklung des Fötus beeinträchtigen und Schädigungen des Organismus verursachen können – biologisch, physikalisch oder chemisch.","<b>Beispiele</b>: Erkrankungen der Mutter, Luftverschmutzung, ionisierende Strahlung, Suchtmittelkonsum der Mutter.","<b>Sensible Phasen</b>: Zeitfenster besonders negativer Auswirkungen, meist Phasen starken Wachstums.","<b>Dosis und Dauer</b>: Menge und Dauer der Einwirkung bestimmen die Schwere der Folgen mit.","<b>Fehlbildungen</b>: kleinere morphologische Defekte sind kosmetischer Natur (z. B. zusätzliche Brustwarze, kurze Finger); große Defekte beeinträchtigen Lebensfähigkeit oder Funktionalität und sind teils interventionsbedürftig (z. B. Herzinsuffizienz, Gliedmaßenfehlbildungen). In Deutschland jährlich circa 49.000 Kinder mit großen Fehlbildungen.","<b>Psychosoziale Belastung</b>: pränataler Stress wurde mit Angstzuständen, Depressionen und Aufmerksamkeitsdefiziten bei Kindern in Zusammenhang gebracht (Weinstock, 2007)."]}},{"id":"k6-5319702ee4","kap":6,"sec":"6.2.4 Erwachsenenalter (körperlich)","stem":"Welche Aussagen zur Menopause und den zugrunde liegenden Prozessen treffen zu?","opts":[{"t":"Die Menopause ist definiert als der Zeitpunkt 12 Monate nach der letzten Regelblutung.","c":true,"fb":"Sie tritt meist im mittleren Erwachsenenalter, durchschnittlich um das 50. Lebensjahr, ein; davor wird die Periode in der Perimenopause bereits seltener."},{"t":"Bei der Geburt sind etwa 1 bis 2 Milliarden Eizellen angelegt.","c":false,"fb":"Angelegt sind etwa 1 bis 2 Millionen Eizellen – die Größenordnung ist um den Faktor tausend zu hoch."},{"t":"Als Atresie bezeichnet man den monatlichen Verlust von etwa 1000 Eizellen, der unabhängig vom Menstruationszyklus abläuft.","c":true,"fb":"Sinkt die Zahl so weit, dass kein Eisprung mehr möglich ist, kommt es zur Menopause."},{"t":"Für die Produktion von Östradiol und Progesteron sind die Eizellen selbst zuständig, weshalb die Hormonproduktion langsam und gleichmäßig ausläuft.","c":false,"fb":"Zuständig sind die Follikel, welche die Eizellen umgeben; der Hormonabfall erfolgt – je nachdem, wie abrupt die Periode ausbleibt – eher abrupt."}],"concept":{"title":"Hormonelle Umstellung im Erwachsenenalter","points":["<b>Menopause</b>: Zeitpunkt 12 Monate nach der letzten Regelblutung, durchschnittlich um das 50. Lebensjahr; vorgeschaltet die <b>Perimenopause</b> mit seltener werdender Periode.","<b>Ursache</b>: Reduktion der Keimzellen. Eizellen sind vollständig vor der Geburt angelegt (etwa 1–2 Millionen), monatlich gehen rund 1000 verloren (<b>Atresie</b>).","<b>Hormonproduktion</b>: die <b>Follikel</b> um die Eizellen produzieren Östradiol und Progesteron – mit der Menopause fällt die Produktion eher abrupt ab.","<b>Andropause</b>: Testosteronabfall ab etwa dem 30. bis 40. Lebensjahr, bei 20–30 % der Männer mit körperlichen und psychischen Symptomen; Spermien werden lebenslang produziert.","<b>Beschwerden beider Geschlechter</b>: Antriebsschwäche, Hitzewallungen, Schlafstörungen, depressive Verstimmungen, geringere sexuelle Lust, Erektionsstörungen (Penis wie Klitoris).","<b>Merkregel</b>: Die Menopause hat erkennbaren Start, kürzere Dauer und einen Abschluss – die Andropause nicht, weshalb ihre Beschwerden oft als Altersschwächen gedeutet werden."]}},{"id":"k6-01d70dcb03","kap":6,"sec":"6.2.4 Erwachsenenalter (körperlich)","stem":"Welche Aussagen zum Inflammaging treffen zu?","opts":[{"t":"Inflammaging bezeichnet chronische, unterschwellige Entzündungen, die mit zunehmendem Alter auftreten können.","c":true,"fb":"Das menschliche Immunsystem verändert sich mit dem Alter; unterschwellige Dauerentzündung ist die Folge."},{"t":"Der Begriff ist aus den englischen Wörtern für Entzündung und Altern zusammengesetzt.","c":true,"fb":"Inflammation und Aging ergeben Inflammaging – die Wortbildung ist selbst prüfbarer Stoff."},{"t":"Vermutet wird ein Zusammenhang mit altersbedingten Erkrankungen wie Arteriosklerose, Morbus Alzheimer und Diabetes mellitus 2.","c":true,"fb":"Ginsburg, Vennos und Koren (2008) bringen Inflammaging mit einer Vielzahl altersbedingter Krankheiten in Verbindung bzw. sehen es als begünstigenden Faktor."},{"t":"Im Verlauf des Alterungsprozesses werden zunehmend entzündungsfördernde Botenstoffe freigesetzt.","c":true,"fb":"Genau diese altersbedingte Veränderung des Immunsystems beschreibt Franceschi (2007) mit dem Begriff."}],"concept":{"title":"Inflammaging (Franceschi, 2007; Ginsburg, Vennos & Koren, 2008)","points":["<b>Wortbildung</b>: inflammation (Entzündung) + aging (Altern) → Inflammaging.","<b>Mechanismus</b>: altersbedingte Veränderung des Immunsystems, zunehmende Freisetzung entzündungsfördernder Botenstoffe.","<b>Charakter</b>: chronische, unterschwellige Entzündung – nicht ein akuter Entzündungsschub.","<b>Assoziierte Krankheiten</b>: Arteriosklerose, Morbus Alzheimer, Diabetes mellitus 2.","<b>Einordnung</b>: gehört zu den physiologischen Rückbildungsprozessen des Erwachsenenalters, neben dem langsamen Abbau von Reaktionszeit und Muskelkraft.","<b>Körpererleben</b>: Personen über 60 Jahren berichten stärkere Unsicherheit und Besorgnis gegenüber dem eigenen Körper als Personen unter 60 (Gunzelmann et al., 1999)."]}},{"id":"k6-b50011f81d","kap":6,"sec":"6.3.1 Piaget – Lernprinzipien","stem":"Welche Aussage zu Assimilation, Akkommodation und Schemata ist korrekt?","opts":[{"t":"Assimilation bezeichnet die Veränderung bereits vorhandener Schemata, damit sie zu einer neuen Information passen.","c":false,"fb":"Das ist die Definition der Akkommodation. Bei der Assimilation wird die neue Information in ein bestehendes Schema eingeordnet."},{"t":"Schemata sind angeborene Denkstrukturen, die über die Entwicklung hinweg stabil bleiben.","c":false,"fb":"Schemata entwickelt ein Mensch aufgrund seiner Erfahrungen; im Laufe der Entwicklung werden diese Denkmuster immer komplexer."},{"t":"Ordnet ein Kind eine unbekannte Katze seinem bestehenden Schema „Hund“ zu, spricht Piaget von Akkommodation.","c":false,"fb":"Das Einordnen in ein vorhandenes Schema ist Assimilation – die Bezeichnung ist hier mit dem Gegenbegriff etikettiert."},{"t":"Erklärt jemand dem Kind, dass auch Katzen vier Beine und Fell haben, und passt das Kind daraufhin sein Schema an, handelt es sich um Akkommodation.","c":true,"fb":"Das neue Schema besagt nicht mehr, dass alle Tiere mit vier Beinen und Fell Hunde sind – das vorhandene Schema wurde an die Umwelt angepasst."}],"concept":{"title":"Piagets konstruktivistisches Lernmodell","points":["<b>Schemata</b>: mentale Strukturen oder Muster, die aufgrund von Erfahrungen entwickelt werden und auf deren Basis Informationen organisiert und interpretiert werden; sie werden zunehmend komplexer.","<b>Assimilation</b>: neue Information wird in bereits existente Schemata integriert – das Schema bleibt, die Information wird eingepasst.","<b>Akkommodation</b>: neue Information führt zur Anpassung existenter Schemata – die Information bleibt, das Schema verändert sich.","<b>Konstruktivismus</b>: Kinder sind denkende und erkennende Wesen, die eigenes Wissen und ihre eigene Wirklichkeit konstruieren; sie sind eigenständig und von sich aus motiviert zu lernen.","<b>„Kinder als Wissenschafter“</b>: Sie bilden Hypothesen über ihre Umgebung und experimentieren („Was passiert, wenn ich den Brei auf den Boden werfe?“).","<b>Merkregel</b>: Assimilation – die Welt passt sich dem Kopf an; Akkommodation – der Kopf passt sich der Welt an."]}},{"id":"k6-2e4518d98b","kap":6,"sec":"6.3.2 Theory of Mind","stem":"Welche Aussagen zur Theory of Mind und zur False-Belief-Aufgabe treffen zu?","opts":[{"t":"Die False-Belief-Aufgabe („Maxi-Aufgabe“) wurde von den österreichischen Psychologen Heinz Wimmer und Josef Perner entwickelt.","c":true,"fb":"Sie ist das typische Verfahren, um die Zuschreibung mentaler Zustände zu prüfen."},{"t":"Kinder ohne Theory of Mind nennen in der Maxi-Aufgabe den grünen Schrank.","c":false,"fb":"Richtungsumkehr: Wer noch keine mentalen Zustände zuschreiben kann, antwortet auf Basis des eigenen Weltwissens mit dem blauen Schrank. Der grüne Schrank ist die Antwort der Kinder, die Maxis falsche Überzeugung verstehen."},{"t":"Die Fähigkeit, sich selbst und anderen mentale Zustände zuzuschreiben, entsteht in der Regel erst mit etwa sieben Jahren.","c":false,"fb":"Kinder sind dazu ab ungefähr 4 Jahren in der Lage; sechs Jahre ist das Alter, ab dem in der Studie fast alle Kinder die Aufgabe lösten."},{"t":"In der Studie von Wimmer und Perner (1983) lösten fast alle Kinder ab sechs Jahren die Aufgabe korrekt, während der Großteil der 3- bis 4-Jährigen daran scheiterte.","c":true,"fb":"Dieser Alterseffekt ist der Ausgangspunkt der gezielten Variationen der Aufgabe, mit denen seither untersucht wird, worauf der Unterschied genau beruht."}],"concept":{"title":"Theory of Mind und die False-Belief-Aufgabe (Wimmer & Perner, 1983)","points":["<b>Theory of Mind</b>: Fähigkeit, sich selbst und anderen mentale Zustände wie Wünsche und Überzeugungen zuzuschreiben – und zu verstehen, dass sich diese von den eigenen unterscheiden können. Ab ungefähr 4 Jahren.","<b>Aufbau der Aufgabe</b>: Maxi verstaut Schokolade im grünen Küchenschrank und geht auf den Spielplatz. Die Mutter verlegt sie in den blauen Schrank. Frage: Wo wird Maxi suchen?","<b>Lösung mit Theory of Mind</b>: grüner Schrank – das Kind trennt Maxis (falsche) Überzeugung von der eigenen Kenntnis der Lage.","<b>Lösung ohne Theory of Mind</b>: blauer Schrank – das Kind projiziert das eigene Wissen über die Welt auf Maxi.","<b>Befund</b>: fast alle Kinder ab sechs Jahren lösen die Aufgabe, der Großteil der 3- bis 4-Jährigen nicht.","<b>Abgrenzung</b>: Die Aufgabe stammt nicht von Piaget – dort gehören Objektpermanenz, Animismus und Realismus zum Repertoire."]}},{"id":"k6-f2fccb81ed","kap":6,"sec":"6.3.3 Kohlberg – Moral","stem":"Welche Aussagen entsprechen Kohlbergs Regeln zur moralischen Entwicklung?","opts":[{"t":"Eine Person kann je nach Situation gleichzeitig auf mehreren der sechs Stufen argumentieren.","c":false,"fb":"Kohlbergs erste Regel besagt ausdrücklich, dass eine Person zu einem bestimmten Zeitpunkt nur auf einer der sechs Stufen steht."},{"t":"Die Abfolge der Stufen verläuft für jede Person gleich.","c":true,"fb":"Diese Annahme übernimmt Kohlberg von Piagets Stadienlogik, die ihn zu seinem Modell inspirierte."},{"t":"Jede Stufe stellt eine neue Denkweise dar: Die Begründung des moralischen Handelns wird immer komplexer.","c":true,"fb":"Deshalb war für Kohlberg bei den meisten Niveaus nicht die Entscheidung selbst relevant, sondern deren Begründung."},{"t":"Die Stufen sollen für Menschen aus allen Kulturen gleich sein.","c":true,"fb":"Genau an dieser Universalitätsannahme setzt die spätere Kritik an, Kohlberg habe seine Theorie auf westlichen Moralkonzepten aufgebaut."}],"concept":{"title":"Kohlbergs Theorie der moralischen Entwicklung (1969, 1996)","points":["<b>Ausgangsmaterial</b>: das <b>Heinz-Dilemma</b> – Medikament stehlen oder die Frau sterben lassen. Die Niveaus leitete Kohlberg aus den Begründungen von Schülern ab.","<b>Regel 1</b>: Eine Person steht zu einem Zeitpunkt nur auf einer der sechs Stufen.","<b>Regel 2</b>: Die Abfolge der Stufen ist für jede Person gleich.","<b>Regel 3</b>: Jede Stufe ist eine neue Denkweise; die Begründung wird zunehmend komplexer.","<b>Regel 4</b>: Die Stufen sind für alle Menschen aus allen Kulturen gleich.","<b>Kritik</b>: Gilligan (1982) – Vernachlässigung der weiblichen Perspektive (Moral der Fürsorge vs. Moral der Gerechtigkeit); Jaffee & Hyde (2000) – Unterschiede vorhanden, aber klein; Snell (1996) – Instrumente zielen auf westliche Zeichen moralischen Handelns."]}},{"id":"k6-ab85f9c921","kap":6,"sec":"6.2.3 Adoleszenz (körperlich)","stem":"Welche Aussage zu primären und sekundären Geschlechtsmerkmalen ist korrekt?","opts":[{"t":"Sekundäre Geschlechtsmerkmale sind genetisch determinierte Merkmale, die für die Fortpflanzung notwendig sind.","c":false,"fb":"Diese Definition gehört zu den primären Geschlechtsmerkmalen; sekundäre Merkmale symbolisieren die Geschlechtsreife nach außen."},{"t":"Primäre Geschlechtsmerkmale sind die inneren und äußeren Geschlechtsorgane, etwa Vulva, Vagina, Gebärmutter und Eierstöcke beziehungsweise Penis und Hoden.","c":true,"fb":"Sie sind genetisch determiniert und für die Fortpflanzung notwendig – eine Definition, die bewusst absolut formuliert ist."},{"t":"Die sekundären Geschlechtsmerkmale sind bei der Geburt bereits vollständig ausgebildet und werden in der Pubertät lediglich sichtbar.","c":false,"fb":"Sie bilden sich erst in der Pubertät heran – Brustentwicklung, Bartwuchs, Tieferwerden der Stimme, Intimbehaarung."},{"t":"Sekundäre Geschlechtsmerkmale entstehen unabhängig von den Geschlechtshormonen.","c":false,"fb":"Gerade die Geschlechtshormone führen zu ihrer Ausbildung: Testosteron bei Buben, Östrogen und Progesteron bei Mädchen."}],"concept":{"title":"Primäre und sekundäre Geschlechtsmerkmale (Infobox 6.2)","points":["<b>Primär</b>: innere und äußere Geschlechtsorgane – Vulva, Vagina, Gebärmutter, Eierstöcke bzw. Penis und Hoden. Genetisch determiniert, für die Fortpflanzung notwendig.","<b>Sekundär</b>: nach außen hin erkennbare Veränderungen, die die Geschlechtsreife symbolisieren – Brustentwicklung, Bartwuchs, Tieferwerden der Stimme, Intimbehaarung.","<b>Auslöser</b>: Geschlechtshormone führen zur Ausbildung der sekundären Merkmale – bei Buben Testosteron, bei Mädchen Östrogen und Progesteron.","<b>Pubertätsbeginn</b>: Buben zwischen dem 10. und 17., Mädchen zwischen dem 9. und 14. Lebensjahr; der Zeitpunkt variiert individuell stark.","<b>Marksteine</b>: <b>Menarche</b> (erste Menstruation, im Durchschnitt mit ca. 12 Jahren) und <b>Spermarche</b> (Beginn der Spermienproduktion).","<b>Merkregel</b>: primär = zur Fortpflanzung nötig; sekundär = von außen sichtbares Signal der Reife."]}},{"id":"k6-6be4bb1607","kap":6,"sec":"6.2.1 Pränatale Entwicklung","stem":"Welche Aussagen zu den drei Phasen der pränatalen Entwicklung treffen zu?","opts":[{"t":"Das germinale Stadium reicht von der Befruchtung bis zur achten Schwangerschaftswoche.","c":false,"fb":"Es reicht bis zur 2. Schwangerschaftswoche und umfasst die ersten etwa 10 bis 14 Tage nach Bildung der Zygote; bis zur 8. Woche dauert das embryonale Stadium."},{"t":"Im embryonalen Stadium beginnen sich die zuvor neutralen, untereinander austauschbaren Stammzellen zu spezialisieren und Organe auszubilden.","c":true,"fb":"In dieser Phase wird auch der erste Herzschlag messbar – mit 120 bis 160 Schlägen pro Minute fast doppelt so schnell wie bei einer erwachsenen Person."},{"t":"Sobald die Einnistung in der Gebärmutter abgeschlossen ist, wird aus der Zygote ein Embryo.","c":true,"fb":"Die Einnistung beginnt ungefähr eine Woche nach der Befruchtung; der Übergang zum Fötus folgt erst ab der 9. Schwangerschaftswoche."},{"t":"Das fötale Stadium ist vor allem durch die beginnende Zellspezialisierung gekennzeichnet, während das Wachstum erst nach der Geburt in den Vordergrund tritt.","c":false,"fb":"Die Zuordnung ist vertauscht: Im fötalen Stadium liegt der Fokus auf Wachstum und Ausreifung, die Spezialisierung kennzeichnet das embryonale Stadium."}],"concept":{"title":"Phasen der pränatalen Entwicklung (Tabelle 6.2)","points":["<b>Germinales Stadium</b> (Befruchtung bis 2. SSW): Entstehung der Zygote, Wanderung durch den Eileiter, Einnistung in der Gebärmutter, schnelle Zellteilung – Verdopplung der Zellzahl ca. zweimal pro Tag.","<b>Embryonales Stadium</b> (3. bis 8. SSW): weitere Zellteilung, Spezialisierung der Stammzellen, Organbildung, erster Herzschlag messbar (120–160/min), erste spontane Bewegungen ab ca. der 7. SSW.","<b>Fötales Stadium</b> (9. SSW bis Geburt): Wachstum und Ausreifung; Gewicht von unter 15 Gramm auf durchschnittlich 3,3 Kilogramm, Größe bei Geburt ca. 50 Zentimeter.","<b>Zygote</b>: befruchtete Eizelle mit dem gesamten Genmaterial – 46 Chromosomen, je 23 von Mutter und Vater.","<b>Hirnreifung</b>: Wachstum von Axonen und Dendriten beginnt vorgeburtlich, bis zu 250.000 Nervenzellen pro Minute; in den ersten beiden Lebensjahren Überproduktion und paralleler Abbau durch Zelltod und <b>synaptic pruning</b>.","<b>Merkregel</b>: Zygote → Embryo (nach abgeschlossener Einnistung) → Fötus (ab der 9. SSW)."]}},{"id":"k6-7ac93ccdd9","kap":6,"sec":"6.4.2 Erikson","stem":"Welche Aussagen zu Eriksons Stufenmodell der psychosozialen Entwicklung treffen zu?","opts":[{"t":"Im frühen Erwachsenenalter steht die Krise „Intimität vs. Isolation“ im Vordergrund.","c":true,"fb":"Beziehungen einzugehen und Bindungen aufzubauen ist dabei genauso wichtig wie Zeit für sich zu haben."},{"t":"Die Adoleszenz ist von der Krise „Identität vs. Rollenkonfusion“ geprägt – der Entwicklung eines kohärenten Selbstbildes.","c":true,"fb":"Gerade diese Phase hatte große Bedeutung für die sozialwissenschaftliche Forschung und diente als Grundlage vieler Untersuchungen im Jugendalter."},{"t":"Mit erfolgreicher Bewältigung einer Krise verschwindet der zugehörige Konflikt vollständig.","c":false,"fb":"Die Bewältigung ermöglicht den Aufstieg in die nächste Phase, allerdings verschwindet keiner dieser Konflikte vollständig."},{"t":"Im mittleren Erwachsenenalter geht es um „Generativität vs. Stagnation“, unter anderem um Fürsorge für zukünftige Generationen.","c":true,"fb":"Sinnfindung und Integration in die Gemeinschaft gehören zu dieser Herausforderung; im hohen Erwachsenenalter folgt „Ich-Integrität vs. Verzweiflung“."}],"concept":{"title":"Stufenmodell der psychosozialen Entwicklung nach Erikson (Tabelle 6.5)","points":["<b>0–1 Jahr</b> Urvertrauen vs. Misstrauen · <b>1–3 Jahre</b> Autonomie vs. Selbstzweifel · <b>3–6 Jahre</b> Initiative vs. Schuldgefühl.","<b>6 Jahre bis Pubertät</b> Kompetenz vs. Minderwertigkeit · <b>Adoleszenz</b> Identität vs. Rollenkonfusion.","<b>Frühes Erwachsenenalter</b> Intimität vs. Isolation · <b>Mittleres</b> Generativität vs. Stagnation · <b>Hohes</b> Ich-Integrität vs. Verzweiflung.","<b>Mechanismus</b>: Jede Phase hat eine Thematik, die sich zu einer Krise steigert; erfolgreiche Bewältigung ist Voraussetzung für die Bewältigung der folgenden Krisen.","<b>Wichtige Einschränkung</b>: Kein Konflikt verschwindet vollständig.","<b>Bewertung</b>: In der ursprünglichen Form kaum empirisch überprüfbar, da teils zu ungenau formuliert; modifizierte Konzepte wurden zuletzt wieder aufgegriffen."]}},{"id":"k6-374d136c54","kap":6,"sec":"6.2.2 Frühe Kindheit","stem":"Welche Aussage zum Experiment der visuellen Klippe ist korrekt?","opts":[{"t":"Gibson und Walk (1960) untersuchten damit die Tiefenwahrnehmung von Kindern im Alter von sechs bis 14 Monaten.","c":true,"fb":"Sie schlossen daraus, dass bereits in der frühen Kindheit ein grundlegendes Verständnis von Tiefenwahrnehmung vorhanden ist."},{"t":"Der Versuchsaufbau geht auf Mary Ainsworth zurück, die damit erstmals frühe Wahrnehmungsleistungen systematisch erfasste.","c":false,"fb":"Personenverwechslung: Ainsworth entwickelte die Fremde-Situation zur Erfassung der Bindungsqualität, nicht die visuelle Klippe."},{"t":"Kinder, die bereits krabbeln konnten, überquerten den tief erscheinenden Teil, sobald die Mutter sie von der anderen Seite lockte.","c":false,"fb":"Richtungsumkehr: Sie weigerten sich zu krabbeln – selbst wenn die eigene Mutter versuchte, sie hinüberzulocken."},{"t":"Weil unter der Glasplatte tatsächlich ein Absturz drohte, war die Zurückhaltung der Kinder auch objektiv begründet.","c":false,"fb":"Die Klippe war durch die Glasplatte abgesichert und in keiner Weise wirklich gefährlich – nur die optische Illusion eines Abgrundes bestand."}],"concept":{"title":"Die visuelle Klippe (Gibson & Walk, 1960)","points":["<b>Aufbau</b>: Glasplatte, auf einer Seite direkt auf rot-weiß kariertem Untergrund, auf der anderen Seite etwa einen halben Meter darüber – die optische Illusion einer Klippe.","<b>Sicherheit</b>: Durch die Glasplatte war der Abgrund abgesichert; eine reale Gefahr bestand nicht.","<b>Stichprobe</b>: Kinder im Alter von sechs bis 14 Monaten.","<b>Befund</b>: Krabbelnde Kinder weigerten sich, über den tiefen Teil zu krabbeln – selbst wenn die Mutter sie lockte.","<b>Schluss</b>: Bereits in der frühen Kindheit besteht ein grundlegendes Verständnis von Tiefenwahrnehmung.","<b>Methodenkritik zur Säuglingsforschung</b>: Aussagen auf Basis präsprachlicher Verhaltensindikatoren – Blickdauer, Reaktionszeiten, Fokussierung des Blicks – sind in vielen Fällen Interpretationen und werden zum Teil divers gedeutet."]}},{"id":"k6-6fd23373f1","kap":6,"sec":"6.1 Grundlagen","stem":"Welche Aussagen zum Gegenstand der Entwicklungspsychologie und zur Einteilung der Lebensspanne treffen zu?","opts":[{"t":"Das Fach untersucht Veränderungsprozesse über die gesamte Lebensspanne – von der Empfängnis bis ins hohe Erwachsenenalter.","c":true,"fb":"Forschungsthemen sind nicht auf das Kindes- und Jugendalter beschränkt, sondern gehen weit darüber hinaus."},{"t":"Das mittlere Erwachsenenalter wird mit ungefähr 30 bis 55 Jahren angesetzt.","c":false,"fb":"Angegeben sind ca. 40 bis 65 Jahre; 20 bis 40 Jahre umfasst das frühe Erwachsenenalter, ab 65 beginnt das hohe."},{"t":"Im Zentrum stehen ausschließlich körperliche Reifungsprozesse; kognitive, sprachliche und soziale Veränderungen sind Gegenstand anderer Teildisziplinen.","c":false,"fb":"Kognitive, sprachliche und soziale Veränderungen sind ausdrücklich wichtige Forschungsbereiche der Entwicklungspsychologie."},{"t":"Dass Kindheit und Jugend besonders intensiv beforscht werden, liegt unter anderem daran, dass dort relativ zur verstrichenen Zeit mehr Veränderung stattfindet.","c":true,"fb":"Die Schwerpunktsetzung ist also eine Frage der Veränderungsdichte, nicht der fachlichen Zuständigkeit."}],"concept":{"title":"Entwicklungsphasen über die Lebensspanne (Tabelle 6.1)","points":["<b>Pränatal</b> von der Empfängnis bis zur Geburt · <b>Säuglingsalter</b> Geburt bis Ende des ersten Lebensjahres.","<b>Kleinkindalter / frühe Kindheit</b> ca. 1–3 Jahre · <b>Mittlere und späte Kindheit</b> ca. 3–11 Jahre.","<b>Pubertät / Adoleszenz</b> ca. 11–20 Jahre · <b>Frühes Erwachsenenalter</b> ca. 20–40 Jahre.","<b>Mittleres Erwachsenenalter</b> ca. 40–65 Jahre · <b>Hohes Erwachsenenalter</b> 65 Jahre und älter.","<b>Gegenstand</b>: Veränderungsprozesse auf körperlicher, kognitiver, sprachlicher und sozialer Ebene über die gesamte Lebensspanne.","<b>Leitfragen des Kapitels</b>: Anlage, Umwelt oder beides? Und verläuft Entwicklung in Stufen oder kontinuierlich?"]}},{"id":"k6-8e6d2b8cba","kap":6,"sec":"6.4.1 Bindung","stem":"Welche Aussagen zur Bindungsforschung und zum Fremde-Situation-Szenario treffen zu?","opts":[{"t":"Bindung wird definiert als emotionale Verbindung, die mit nahestehenden Personen, besonders der Mutter oder anderen frühen Bezugspersonen, aufgebaut wird.","c":true,"fb":"Diese Definition geht auf Cassidy und Shaver (1999) zurück."},{"t":"John Bowlby führte ab den 1930er Jahren Studien an Kindern durch, die in Kinderheimen aufwuchsen.","c":true,"fb":"Im Fokus standen die negativen Auswirkungen einer fehlenden Bezugsperson in der frühen Kindheit, etwa auf körperliche und emotionale Gesundheit."},{"t":"Das Szenario wurde mit Kindern zwischen 12 und 24 Monaten durchgeführt und gilt bis heute als verbreitete, anerkannte Forschungsmethode.","c":true,"fb":"Mary Ainsworth entwickelte es selbst; auf seiner Basis ließ sich Bindungsqualität erfassen und verschiedenen Bindungstypen zuordnen."},{"t":"Zentrales Untersuchungselement war die Reaktion des Kindes, wenn die Mutter in den Raum zurückkam.","c":true,"fb":"Die Trennung selbst löste bei allen Kindern Stress aus – aussagekräftig ist erst das Verhalten beim Wiedersehen."}],"concept":{"title":"Die Fremde-Situation (Ainsworth) und ihre Vorgeschichte","points":["<b>Bindung</b>: emotionale Verbindung zu nahestehenden Personen, besonders zu frühen Bezugspersonen (Cassidy & Shaver, 1999).","<b>Bowlby (1907–1990)</b>: früher Bindungsforscher, ab den 1930er Jahren Studien an Heimkindern; beschrieb die Folgen einer fehlenden Bezugsperson (Bowlby, 1953).","<b>Ainsworth (1913–1999)</b>: Entwicklungspsychologin, entwickelte in Zusammenarbeit mit Bowlby die Bindungstheorien und das Szenario der Fremde-Situation.","<b>Ablauf</b>: Kind (12–24 Monate) mit der Mutter im Spielzimmer, fremde Person kommt hinzu, Mutter verlässt den Raum und kehrt nach wenigen Minuten zurück.","<b>Auswertung</b>: Die Trennung stresst alle Kinder – bewertet wird die Reaktion auf die Rückkehr, daraus folgt die Zuordnung zu einem der vier Bindungstypen.","<b>Bindungsperson</b>: muss nicht die Mutter sein – Vater, Großeltern oder Bezugsbetreuer:innen im Heim können diese Rolle ebenfalls erfolgreich übernehmen (Shirvanian & Michael, 2017)."]}},{"id":"k6-d06b880ce5","kap":6,"sec":"6.3.4 Kognition im Erwachsenenalter","stem":"Welche Aussagen zur kognitiven Entwicklung im Erwachsenenalter treffen zu?","opts":[{"t":"Als postformales Denken bezeichnet man reflektiertes Denken, bei dem Problemstellungen identifiziert und benannt sowie mögliche Folgen von Entscheidungen antizipiert und abgewogen werden.","c":true,"fb":"Es entwickelt sich im frühen bis mittleren Erwachsenenalter."},{"t":"Blouin und McKelvie (2012) fanden einen Zusammenhang zwischen postformalem Denken und der Fähigkeit, sprachliche Metaphern und Ironie zu identifizieren und zu verstehen.","c":true,"fb":"Die Autoren interpretierten dies so, dass Menschen mit höherem Maß an postformalem Denken die volle Bedeutung von Metaphern und Ironie zugänglich ist; auch ein Zusammenhang mit Kreativität zeigte sich."},{"t":"Der Rückgang der kognitiven Fähigkeiten im Alter wird in der Regel unterschätzt und setzt früher ein als angenommen.","c":false,"fb":"Richtungsumkehr: Er wird häufig überschätzt und als zu früh einsetzend angenommen."},{"t":"Postformales Denken bildet sich nach heutigem Verständnis bereits mit dem formal-operatorischen Stadium in der Pubertät aus.","c":false,"fb":"Es entwickelt sich erst im frühen bis mittleren Erwachsenenalter; das aufstrebende Erwachsenenalter entspricht der Pubertät und ist von der weiteren Reifung des präfrontalen Kortex geprägt."}],"concept":{"title":"Kognitive Veränderungen im Erwachsenenalter","points":["<b>Altersgliederung</b>: aufstrebendes (entspricht der Pubertät), frühes (20–40), mittleres (40–65) und hohes Erwachsenenalter (ab 65).","<b>Präfrontaler Kortex</b>: reift im aufstrebenden Erwachsenenalter weiter heran; zuständig vor allem für Planung, Aufmerksamkeit und exekutive Funktionen, gern „Sitz der Persönlichkeit“ genannt.","<b>Postformales Denken</b>: reflektiertes Denken im frühen bis mittleren Erwachsenenalter – Probleme benennen, Folgen antizipieren und abwägen. Zusammenhang mit Kreativität, Metaphern- und Ironieverständnis (Blouin & McKelvie, 2012).","<b>Hohes Erwachsenenalter</b>: Veränderung der Intelligenzstruktur – die Leistungsniveaus verschiedener kognitiver Fähigkeiten korrelieren stärker miteinander als bei Jüngeren und nehmen generell ab (de Frias et al., 2007).","<b>Neurokognitive Störungen</b>: Alzheimer-Demenz und Parkinson-Krankheit häufen sich; sie haben oft eine biologische Basis und können kognitive wie motorische Fähigkeiten stark einschränken.","<b>Gestaltbarkeit</b>: Ernährung sowie körperliche und geistige Aktivität spielen eine große Rolle; gesunde Personen zeigen meist nur leichte bis gar keine Einbußen, gezieltes Training wirkt dem Abbau entgegen."]}},{"id":"k6-cb2d703962","kap":6,"sec":"6.2.1 Pränatale Entwicklung","stem":"Welche Aussagen zu schädigenden Substanzen in der Schwangerschaft treffen zu?","opts":[{"t":"Das Fetale Alkoholsyndrom (FAS) stellt die ausgeprägteste Form der Fetalen Alkoholspektrumsstörungen (FASD) dar.","c":true,"fb":"FASD bezeichnet die Reihe an Schädigungen, die vorgeburtlich durch Alkoholkonsum entstehen können; FAS ist deren Extremform."},{"t":"Zu den möglichen Folgen zählen unter anderem Wachstumsstörungen, Herzfehler und kognitive Beeinträchtigungen wie Konzentrationsstörungen und Lernschwächen.","c":true,"fb":"Auch Gesichtsfehlbildungen und Bewegungsstörungen gehören dazu; die Schwere der einzelnen Schädigungen kann unterschiedlich ausfallen."},{"t":"Bei Thalidomid (Contergan) zeigten sich unabhängig vom Zeitraum der Einnahme stets dieselben Fehlbildungen.","c":false,"fb":"Je nachdem, in welchem Zeitraum der Schwangerschaft das Medikament eingenommen wurde, traten unterschiedliche Missbildungen auf – ein Lehrbeispiel für sensible Phasen."},{"t":"Schätzungen gehen davon aus, dass weltweit etwa 9,8 % der Frauen während der Schwangerschaft Alkohol konsumieren.","c":true,"fb":"Jährlich werden weltweit um die 119.000 Kinder mit FAS geboren (Popova et al., 2017)."}],"concept":{"title":"Alkohol, Medikamente und pränatale Diagnostik","points":["<b>FASD</b>: Reihe an Schädigungen, die vorgeburtlich durch Alkoholkonsum entstehen können. <b>FAS</b> ist die ausgeprägteste Form.","<b>Mögliche Folgen</b>: Wachstumsstörungen, Gesichtsfehlbildungen, Herzfehler, Bewegungsstörungen, kognitive Beeinträchtigungen (Konzentrationsstörungen, Lernschwächen).","<b>Zahlen</b>: etwa 9,8 % der Frauen konsumieren weltweit während der Schwangerschaft Alkohol; jährlich rund 119.000 Kinder mit FAS (Popova et al., 2017).","<b>Thalidomid / Contergan</b>: in den 1950er Jahren beliebtes Beruhigungs- und Schlafmittel für Schwangere; Anfang der 1960er Jahre wurde der Zusammenhang mit Fehlbildungen bis zum völligen Fehlen von Organen oder Gliedmaßen erkannt. Art der Missbildung abhängig vom Einnahmezeitpunkt.","<b>Weitere Risiken</b>: niedriger sozioökonomischer Status, Mangelernährung, chronischer Stress, psychische Belastungen, sexueller oder körperlicher Missbrauch.","<b>Pränatale Diagnostik</b>: Bluttests und Ultraschall bei der Mutter, zusätzlich Nackenfaltenmessung, Organscreening, Fruchtwasserbiopsie – Ziel ist die frühzeitige Erkennung von Krankheiten und Fehlentwicklungen."]}},{"id":"k6-8eb1459eb6","kap":6,"sec":"6.3.3 Kohlberg – Moral","stem":"Welche Aussage zur Zuordnung von Niveaus und Stufen bei Kohlberg ist korrekt?","opts":[{"t":"Zum konventionellen Niveau gehört die Stufe „sozialer Kontrakt und individuelle Rechte“.","c":false,"fb":"Diese Stufe 5 gehört zum postkonventionellen Niveau. Konventionell sind Stufe 3 (wechselseitige Erwartungen) und Stufe 4 (soziales System und Gewissen)."},{"t":"Auf dem präkonventionellen Niveau steht die Stufe der heteronomen Moral, bei der sich Verhalten an der Vermeidung negativer Konsequenzen orientiert.","c":true,"fb":"Stufe 1 orientiert sich an Gehorsam und Bestrafung; die Furcht vor Strafe leitet das moralische Handeln."},{"t":"Dem postkonventionellen Niveau ist die Stufe „autonome Reziprozität und Vertragstreue“ zugeordnet.","c":false,"fb":"Eine Stufe dieses Namens gibt es bei Kohlberg nicht – postkonventionell sind „sozialer Kontrakt und individuelle Rechte“ sowie „universelle ethische Prinzipien“."},{"t":"Auf der Stufe „soziales System und Gewissen“ bleibt eine strafende Instanz notwendig, damit Normen eingehalten werden.","c":false,"fb":"Auf Stufe 4 ist eine strafende Instanz gerade nicht mehr notwendig: Das Handeln ist von internalisierten Werten geprägt."}],"concept":{"title":"Moralische Niveaus und Stufen nach Kohlberg (Tabelle 6.4)","points":["<b>Präkonventionell</b> – Normen werden noch nicht als gesellschaftliche Vereinbarungen erkannt. Stufe 1: heteronome Moral (Gehorsam, Strafvermeidung). Stufe 2: Individualismus und Austausch („Wie du mir, so ich dir“).","<b>Konventionell</b> – die Perspektive eines Gesellschaftsmitglieds wird eingenommen. Stufe 3: wechselseitige Erwartungen und interpersonelle Konformität. Stufe 4: soziales System und Gewissen, strafende Instanz nicht mehr nötig.","<b>Postkonventionell</b> – universelle ethische Prinzipien stehen über gesellschaftlichen Normen. Stufe 5: sozialer Kontrakt und individuelle Rechte. Stufe 6: universelle ethische Prinzipien.","<b>Benennungslogik</b>: Die Niveaus sind danach benannt, inwieweit ein Individuum die Konventionen einer Gesellschaft anerkennt.","<b>Heinz-Dilemma auf Stufe 5</b>: Das Medikament soll gestohlen werden, weil das Recht auf Leben höher wiegt als Gesetzestreue oder Eigentumsrecht.","<b>Kohlbergs Einschränkung</b>: Stufe 6 hielt er für rein hypothetisch und von niemandem erreichbar; nur wenige Erwachsene gelangen bis Stufe 5, die meisten argumentieren auf Basis von Stufe 4."]}},{"id":"k6-d90e0da52a","kap":6,"sec":"6.4.3 Identität (Marcia)","stem":"Welche Aussagen zu James Marcias Modell des Identitätsstatus treffen zu?","opts":[{"t":"Die vier Identitätskategorien sind – wie Eriksons Phasen – als aufeinanderfolgende Stufen zu verstehen.","c":false,"fb":"Gerade das ist der Unterschied zu Erikson: Sie sind als Ergebnis der Bewältigung psychosozialer Aufgaben zu verstehen, nicht als Stufenfolge."},{"t":"Bei der übernommenen Identität („Foreclosure“) wurde keine erkennbare Identitätskrise durchlaufen; Werte und Überzeugungen von Eltern und Rollenvorbildern werden unhinterfragt übernommen.","c":true,"fb":"Dieser Status ist von autoritären Werten wie Gehorsam, Führung und Respekt vor hierarchisch höhergestellten Personen gekennzeichnet; das Selbstwertgefühl ist anfällig für negative Information."},{"t":"Als fünften Status beschreibt Marcia die konsolidierte Identität („Identity Consolidation“), in der ein erarbeitetes Selbstbild im Erwachsenenalter stabilisiert wird.","c":false,"fb":"Marcias Katalog ist mit vier Kategorien abgeschlossen; ein fünfter Status dieses Namens existiert nicht."},{"t":"Die kritische Identität („Moratorium“) verbindet einen hohen Grad an Exploration mit einem niedrigen Grad an Verbindlichkeit.","c":true,"fb":"Jugendliche in diesem Status erleben eine Identitätskrise und lassen sich alle Möglichkeiten offen, ohne sich festzulegen."}],"concept":{"title":"Identitätsstatus nach Marcia (1966)","points":["<b>Diffuse Identität („Identity Diffusion“)</b>: weder kohärentes Selbstkonzept noch Auseinandersetzung mit der eigenen Identitätsfindung.","<b>Übernommene Identität („Foreclosure“)</b>: keine erkennbare Krise, unhinterfragte Übernahme von Werten der Eltern und Rollenvorbilder, autoritäre Werte, Selbstwert anfällig für negative Information.","<b>Kritische Identität („Moratorium“)</b>: Identitätskrise wird erlebt, hohe Exploration bei niedriger Verbindlichkeit, alle Möglichkeiten bleiben offen.","<b>Erarbeitete Identität („Identity Achievement“)</b>: Krise durchlaufen, neues Selbstbild erfolgreich erarbeitet, weniger autoritäre Werte, Selbstwert robuster gegenüber negativer Information.","<b>Verhältnis zu Erikson</b>: Marcias Forschung gilt als Weiterentwicklung von Eriksons Theorie – die vier Status sind aber keine Stufenfolge, sondern Ergebnisse der Aufgabenbewältigung mit dem Ziel einer „Ich-Identität“.","<b>Entwicklungsaufgabe</b>: Die Bildung eines kohärenten Selbstbildes ist eine der zentralen Aufgaben der Adoleszenz."]}},{"id":"k6-616867a36e","kap":6,"sec":"6.2.3 Adoleszenz (körperlich)","stem":"Welche Aussagen zur Pubertät treffen zu?","opts":[{"t":"Bei Mädchen sind vor allem Östrogen und Progesteron ausschlaggebend, bei Buben vermehrt gebildetes Testosteron.","c":true,"fb":"Hormonelle Veränderungen liefern die Grundlage der körperlichen Veränderungen; die Geschlechtshormone führen zur Ausbildung der sekundären Geschlechtsmerkmale."},{"t":"Bei Mädchen liegt der Beginn der Pubertät in der Regel zwischen dem 11. und 16. Lebensjahr.","c":false,"fb":"Angegeben ist der Bereich vom 9. bis zum 14. Lebensjahr; der Bereich vom 10. bis 17. Lebensjahr gilt für Buben."},{"t":"Die Menarche tritt im Durchschnitt mit ungefähr 12 Jahren auf, der Zeitpunkt schwankt jedoch stark.","c":true,"fb":"Er hängt von der genetischen Grundlage sowie von körperlichen Faktoren wie dem Gewicht ab."},{"t":"Als Spermarche bezeichnet man den Beginn der Spermienproduktion.","c":true,"fb":"Bei Buben beginnt die Pubertät mit dem Wachstum der Hoden, der Schambehaarung und des Penis; die Spermarche fällt in diese Phase."}],"concept":{"title":"Sexuelle Reifung in der Adoleszenz","points":["<b>Adoleszenz</b>: Übergang von der Kindheit ins Erwachsenenalter, Phase der sexuellen Reifung; hormonelle Veränderungen liefern die Grundlage.","<b>Leithormone</b>: Testosteron bei Buben, Östrogen und Progesteron bei Mädchen.","<b>Zeitfenster</b>: Pubertätsbeginn bei Buben zwischen dem 10. und 17., bei Mädchen zwischen dem 9. und 14. Lebensjahr – individuell stark variabel.","<b>Menarche</b>: erste Menstruation, im Durchschnitt mit ca. 12 Jahren; abhängig von genetischer Grundlage und körperlichen Faktoren wie dem Gewicht.","<b>Spermarche</b>: Beginn der Spermienproduktion; bei Buben setzt die Pubertät mit Wachstum von Hoden, Schambehaarung und Penis ein.","<b>Psychische Seite</b>: Starke körperliche Veränderungen und hormonelle Schwankungen können das Wohlbefinden beeinträchtigen und zu geringem Selbstwert und psychischem Stress führen (Duchesne et al., 2017)."]}},{"id":"k6-c31c29becb","kap":6,"sec":"6.2.2 Frühe Kindheit","stem":"Welche Aussage zu Reflexen im Säuglingsalter und zum Kniesehnenreflex ist korrekt?","opts":[{"t":"Der Kniesehnenreflex wird über das Großhirn vermittelt und lässt sich daher durch Übung beeinflussen.","c":false,"fb":"Die Verschaltung läuft als „Abkürzung“ über das Rückenmark – müsste der Körper auf eine Antwort des Großhirns warten, wäre es für die schnellen motorischen Prozesse meist zu spät. Der Reflex ist nicht trainierbar."},{"t":"Wie Such- und Saugreflex verschwindet der Kniesehnenreflex in den ersten Lebensmonaten wieder.","c":false,"fb":"Der Kniesehnenreflex besteht ein Leben lang und bleibt im Wesentlichen gleich – er ist im Skript gerade das Gegenbeispiel zu den frühkindlichen Reflexen."},{"t":"Beim Kniesehnenreflex erfolgt über das Rückenmark die reflexartige Kontraktion der kniestreckenden Muskulatur – eine Schutzreaktion.","c":true,"fb":"Betroffen ist der Muskel Quadriceps Femoris; die Abkürzung über das Rückenmark verhindert Verletzungen des Gewebes bei schneller, starker Dehnung."},{"t":"Der Suchreflex wird beim Neugeborenen anfangs durch Berührung der Fußsohle ausgelöst.","c":false,"fb":"Ausgelöst wird er beispielsweise durch Berührung der Wangen; er hilft dem Kind, eine Nahrungsquelle zu finden."}],"concept":{"title":"Reflexe: frühkindlich vs. lebenslang (Infobox 6.1)","points":["<b>Reflex</b>: rasches, unwillkürliches Reaktionsmuster, das der Organismus auf einen Reiz zeigt.","<b>Suchreflex</b>: anfangs etwa durch Berührung der Wangen ausgelöst, hilft beim Finden einer Nahrungsquelle (z. B. Brust).","<b>Saugreflex</b>: ermöglicht die Nahrungsaufnahme an der gefundenen Quelle. Beide Reflexe dienen der Ernährung und verschwinden in den ersten Lebensmonaten.","<b>Kniesehnenreflex (Patellarsehnenreflex)</b>: Schlag auf die Patellarsehne erhöht ruckartig die Dehnung, über das Rückenmark folgt die Kontraktion des Quadriceps Femoris.","<b>Funktion</b>: Schutzreaktion – die Abkürzung über das Rückenmark spart die Zeit, die eine Antwort des Großhirns kosten würde.","<b>Abgrenzung</b>: Der Kniesehnenreflex ist nicht trainierbar, bleibt im Wesentlichen gleich und besteht ein Leben lang."]}},{"id":"k6-e1f1bfa0d0","kap":6,"sec":"6.3.1 Piaget – Kritik","stem":"Welche Aussagen zur heutigen Bewertung von Piagets Theorie treffen zu?","opts":[{"t":"Baillargeon (1987) zeigte, dass erste Formen des Verständnisses von Objektpermanenz bereits mit etwa 3,5 Monaten erkennbar sind.","c":true,"fb":"Piaget hatte diese Errungenschaft erst mit ungefähr 8 Monaten angesetzt."},{"t":"Aus heutiger Sicht hat Piaget das Erwerbsalter mancher Errungenschaften systematisch zu niedrig eingeschätzt.","c":false,"fb":"Richtungsumkehr: Er schätzte es eher zu hoch ein und unterschätzte damit die Fähigkeiten der Kinder."},{"t":"Nicht alle kognitiven Veränderungen lassen sich in klar abtrennbare Stadien unterteilen; manche verlaufen stadienübergreifend.","c":true,"fb":"Diese Einschränkung betrifft den Kern der Stadienannahme, ohne den Wert der Theorie insgesamt aufzuheben."},{"t":"Als Ursache der Fehleinschätzung gilt vor allem, dass Piagets Testaufgaben zu einfach waren, um die Fähigkeiten der Kinder auszureizen.","c":false,"fb":"Umgekehrt: Manche Aufgabenstellungen waren aufgrund zu hoher Komplexität des Testmaterials bzw. der Testsituation nicht geeignet, die tatsächlichen Fähigkeiten abzubilden."}],"concept":{"title":"Piagets Theorien aus heutiger Sicht","points":["<b>Fortbestehender Einfluss</b>: bis heute wichtige Grundlage für das Verständnis kognitiver Veränderungen, mit theoretischen und praktischen Anwendungen (Barrouillet, 2015; DeVries, 2000).","<b>Revision der Altersangaben</b>: Objektpermanenz bereits ab ca. 3,5 Monaten statt erst mit 8 Monaten (Baillargeon, 1987).","<b>Unterschätzte Kinder</b>: Erwerbsalter tendenziell zu hoch eingeschätzt; Aufgaben teils zu komplex, sodass zusätzliche Voraussetzungen fehlten und sich das Zielverhalten nicht zeigen konnte.","<b>Stadienannahme aufgeweicht</b>: nicht alle kognitiven Veränderungen sind klar abtrennbar, manche verlaufen stadienübergreifend.","<b>Objektpermanenz neu gelesen</b>: Möglicherweise fehlt kleinen Kindern nicht das Wissen um das verdeckte Objekt, sondern die Handlungsfähigkeit, es selbst wieder sichtbar zu machen – die fehlende Reaktion ist dann kein Beleg für fehlendes Wissen.","<b>Merkregel</b>: Kritik trifft die Altersgrenzen und die Trennschärfe der Stadien, nicht die Grundidee der aktiven Wissenskonstruktion."]}},{"id":"k6-76aea5faa5","kap":6,"sec":"6.2.2 Frühe Kindheit","stem":"Welche Aussagen zur Wahrnehmung von Neugeborenen und Säuglingen treffen zu?","opts":[{"t":"Neugeborene bevorzugen die Stimme der eigenen Mutter, was sich unter anderem an einem beschleunigten Herzschlag zeigt.","c":true,"fb":"Diese Präferenz besteht durch die Zeit im Mutterleib bereits von Geburt an (Kisilevsky et al., 2009)."},{"t":"Säuglinge ziehen den Geruch der eigenen Mutter dem fremder Personen vor.","c":true,"fb":"Cernoch und Porter (1985); zudem beruhigt der Geruch der eigenen Muttermilch in schmerzlichen Situationen schneller als der anderer Mütter (Nishitani et al., 2009)."},{"t":"Im Vergleich zu Erwachsenen ist das Sehvermögen Neugeborener in Schärfe, Kontrast- und Farbempfindlichkeit eingeschränkt.","c":true,"fb":"Menschen werden dennoch mit weitgehend funktionierendem Sehvermögen geboren und reagieren auf visuelle Muster mit Kopf- und Augenbewegungen."},{"t":"Neugeborene zeigen Präferenzen etwa für gemusterte gegenüber ungemusterten Reizen und für menschliche Gesichter gegenüber gesichtsunähnlichen Reizen.","c":true,"fb":"Ebenso bevorzugt werden Bewegung gegenüber statischen Mustern, Dreidimensionales gegenüber Zweidimensionalem und Neues gegenüber Bekanntem (S. P. Johnson, 2011)."}],"concept":{"title":"Sinne und Präferenzen im Säuglingsalter","points":["<b>Ausgangslage</b>: Alle Sinne sind nach der Geburt vorhanden, aber unterschiedlich gut ausgebildet.","<b>Präferenz für die Mutter</b>: Stimme (beschleunigter Herzschlag; Kisilevsky et al., 2009), Gesicht (Bushnell, 2001), Geruch (Cernoch & Porter, 1985), beruhigende Wirkung der eigenen Muttermilch (Nishitani et al., 2009).","<b>Sehvermögen</b>: weitgehend funktionsfähig, aber in Schärfe, Kontrast- und Farbempfindlichkeit eingeschränkt.","<b>Visuelle Präferenzen</b>: gemustert vor ungemustert, Bewegung vor Statik, dreidimensional vor zweidimensional, neu vor bekannt, Gesichter vor gesichtsunähnlichen Reizen (S. P. Johnson, 2011).","<b>Umwelt und Deprivation</b>: Das Kind gestaltet seine Lernerfahrungen aktiv mit; extreme Deprivation veränderte das Wachstum des Gehirns und zog unter anderem verringerte Intelligenz nach sich (Mackes et al., 2020).","<b>Forschungsmethodik</b>: Fortschritte durch ausdifferenzierte experimentelle Bedingungen und präsprachliche Verhaltensindikatoren – Blickdauer, Reaktionszeiten, Blickfokussierung."]}},{"id":"k6-d11124232e","kap":6,"sec":"6.3.1 Piaget – Stadien","stem":"Welche Aussagen zu Animismus und Realismus treffen zu?","opts":[{"t":"Als Animismus bezeichnet man es, wenn Kinder nicht lebenden Objekten menschliche Gefühle und Vorhaben zuschreiben.","c":true,"fb":"Typische Aussage: „Mein Teddybär ist heute ganz traurig, weil er die Omi vermisst!“"},{"t":"Der kindliche Realismus meint, dass Kinder nicht zwischen Vorstellungen und der Realität unterscheiden können, sodass mentale Vorgänge wie Denken oder Träumen für sie extern real sind.","c":true,"fb":"Nach Piaget müssten Kinder daher bejahen, dass sie einen bloß vorgestellten Keks verschenken können."},{"t":"Untersuchungen zeigten, dass der Realismus deutlich seltener auftritt als von Piaget ursprünglich postuliert.","c":true,"fb":"Kinder können früh zwischen Realität und Vorstellung unterscheiden – ein Beispiel für die Revision einzelner Annahmen Piagets."},{"t":"Beide Phänomene ordnet Piaget dem konkret-operatorischen Stadium zu, in dem sich das logische Denken ausbildet.","c":false,"fb":"Sie gehören zum präoperatorischen Stadium (ca. 2–7 Jahre). Im konkret-operatorischen Stadium sind viele dieser Entwicklungsaufgaben bereits gelöst."}],"concept":{"title":"Das präoperatorische Stadium (ca. 2–7 Jahre)","points":["<b>Sprache</b>: rasante Weiterentwicklung – neue Wörter und Bezeichnungen für Objekte, erste simple mentale Operationen in der bloßen Vorstellung.","<b>Animismus</b>: nicht lebende Objekte oder Phänomene werden als lebendig angesehen; Feuer oder Wolken werden Eigenschaften von Lebewesen wie atmen, fühlen oder sterben zugeschrieben – begründet etwa damit, dass sie sich „bewegen“.","<b>Realismus</b>: Nicht Existierendes wird als real verstanden; Kinder unterscheiden nicht zwischen Vorstellung und Realität, mentale Vorgänge gelten als extern real.","<b>Empirische Relativierung</b>: Der Realismus tritt deutlich seltener auf als postuliert, da Kinder früh zwischen Realität und Vorstellung trennen können.","<b>Abgrenzung nach unten</b>: Im sensumotorischen Stadium steht die Objektpermanenz im Zentrum.","<b>Abgrenzung nach oben</b>: Erst im konkret-operatorischen Stadium gelingen logische Schlüsse rein auf gedanklicher Basis, Reversibilität und Invarianz."]}},{"id":"k6-18f0f336cd","kap":6,"sec":"6.2.4 Erwachsenenalter (körperlich)","stem":"Welche Aussage zur Andropause und zur Fruchtbarkeit im Alter ist korrekt?","opts":[{"t":"Die Testosteronproduktion beginnt bei Männern etwa ab dem 50. bis 60. Lebensjahr abzunehmen.","c":false,"fb":"Sie nimmt bereits ab etwa dem 30. bis 40. Lebensjahr kontinuierlich ab; Beginn und Tempo sind individuell sehr verschieden."},{"t":"Wie Eizellen sind auch Spermien bereits bei der Geburt vollständig angelegt und werden im Laufe des Lebens verbraucht.","c":false,"fb":"Spermien werden – anders als Eizellen – ein Leben lang produziert, weshalb Männer bis ins hohe Alter Kinder zeugen könnten."},{"t":"Wechselbedingte Beschwerden fallen Männern in der Regel stärker auf als Frauen, weil die Andropause deutlicher einsetzt.","c":false,"fb":"Umgekehrt: Sie fallen Frauen eher auf, weil die Menopause erkennbarer startet, kürzer dauert und einen Abschluss hat."},{"t":"Die Andropause verläuft in der Regel ohne wahrnehmbaren Startpunkt und ohne fixiertes Ende, weshalb Beschwerden oft als Altersschwächen gedeutet werden.","c":true,"fb":"Der Prozess ist deutlich langsamer als die Menopause; die Beschwerden werden dann nicht dem Wechsel im Hormonsystem zugeordnet."}],"concept":{"title":"Andropause: der männliche Wechsel","points":["<b>Beginn</b>: Testosteronproduktion nimmt ab etwa dem 30. bis 40. Lebensjahr kontinuierlich ab; Alter und Tempo individuell sehr verschieden.","<b>Symptomatik</b>: Bei etwa 20 bis 30 % der Männer macht sich der Abfall körperlich und psychisch bemerkbar – erst dann spricht man von Andropause.","<b>Spermien</b>: Qualität und Anzahl sinken langsam ab; die Prozesse können teilweise unabhängig vom Hormonabfall verlaufen.","<b>Lebenslange Produktion</b>: Spermien werden – anders als Eizellen – ein Leben lang gebildet; Zeugungsfähigkeit bleibt möglich, die Befruchtungswahrscheinlichkeit sinkt jedoch.","<b>Beschwerden beider Geschlechter</b>: Antriebsschwäche, Hitzewallungen, Schlafstörungen, depressive Verstimmungen, geringere sexuelle Lust, Erektionsstörungen (Penis wie Klitoris).","<b>Wahrnehmungsunterschied</b>: Die Menopause hat erkennbaren Beginn, kürzere Dauer und einen Abschluss – die Andropause nicht, weshalb ihre Beschwerden oft als Altersschwächen gelten."]}},{"id":"k6-1a5541c752","kap":6,"sec":"6.3.1 Piaget – Stadien","stem":"Welche Aussagen zum konkret-operatorischen Stadium und zum Invarianzprinzip treffen zu?","opts":[{"t":"Kinder vor diesem Stadium achten beim Umschütten vor allem auf die Breite des Glases und vernachlässigen die Höhe.","c":false,"fb":"Richtungsumkehr: Sie scheinen die Breite zu vernachlässigen und nur auf die Höhe zu achten."},{"t":"Reversibilität zeigt sich etwa daran, dass ein Mädchen, das auf die Frage nach einer Schwester mit „Ja, die Anne“ antwortet, auch bejaht, dass Anne eine Schwester hat.","c":true,"fb":"Formal entspricht das dem Schluss: wenn X + X = Y, dann gilt Y − X = X."},{"t":"Das Gesetz der Erhaltung – auch Invarianzprinzip – wird in diesem Stadium im Regelfall ohne Probleme nachvollzogen.","c":true,"fb":"Das Verständnis der Reversibilität ist die Voraussetzung dafür; vorher bleibt die Umschüttaufgabe ungelöst."},{"t":"Bevor Kinder dieses Stadium erreichen, lösen sie die Umschüttaufgabe zuverlässig, sobald die Flüssigkeit mehrmals zwischen den Gläsern hin- und hergeschüttet wird.","c":false,"fb":"Der Fehler tritt selbst dann auf, wenn die Flüssigkeit abwechselnd hin- und hergeschüttet wird."}],"concept":{"title":"Konkret-operatorisches Stadium (ca. 7–11 Jahre)","points":["<b>Kern</b>: Das logische Denken steht im Vordergrund; die Phase erstreckt sich etwa über die Grundschulzeit.","<b>Gedankliche Schlüsse</b>: Logische Schlussfolgerungen werden ausschließlich auf Basis gedanklicher Vorgänge abgeleitet – etwa den Heimweg in eine Karte einzeichnen oder Informationen aus einem Text kombinieren.","<b>Reversibilität</b>: Umkehrbarkeit von Beziehungen und Operationen – „Anne ist meine Schwester“ ⇔ „Ich bin Annes Schwester“; formal: X + X = Y, also Y − X = X.","<b>Gesetz der Erhaltung / Invarianzprinzip</b>: Die Menge bleibt gleich, auch wenn sich die Form des Behälters ändert.","<b>Klassische Prüfaufgabe</b>: Flüssigkeit wird in ein höheres, schmaleres Glas umgefüllt. Vor dem Stadium achten Kinder nur auf die Höhe und vernachlässigen die Breite – auch bei mehrfachem Hin- und Herschütten.","<b>Anschluss</b>: Im formal-operatorischen Stadium kommen abstraktes Denken, hypothetisches Schlussfolgern und deduktive Logik hinzu."]}},{"id":"k7-0457209ce3","kap":7,"sec":"7.3.4 Gehorsam gegenüber Autoritäten","stem":"Welche Aussagen zum Aufbau und zum Ergebnis von Milgrams erstem Gehorsamsexperiment (1963) treffen zu?","opts":[{"t":"Die Rollen von Lehrer und Schüler wurden per Münzwurf vergeben, um jede Einflussnahme der Versuchsleitung auf die Rollenverteilung auszuschließen.","c":false,"fb":"Der Münzwurf zur Rollenzuteilung stammt aus dem Stanford Gefängnisexperiment. Bei Milgram lag die Verteilung fest: Die echte Versuchsperson fungierte stets als Lehrer."},{"t":"Die Versuchsperson übernahm die Rolle des Lehrers; der Schüler war eine eingeweihte Person, deren Reaktionen für alle Durchgänge standardisiert waren.","c":true,"fb":"Bis auf die Versuchsperson waren alle Beteiligten eingeweiht; auf jede Stufe der vermeintlichen Stromschläge folgten stets dieselben Reaktionen."},{"t":"Von den 40 Teilnehmern brach die Mehrzahl spätestens bei 300 Volt ab, sobald der Protest des Schülers durch die Wand zu hören war.","c":false,"fb":"Alle 40 Teilnehmer verabreichten Stromstöße bis mindestens 300 Volt, und 26 von ihnen gingen bis zur letzten Stufe."},{"t":"Die Skala reichte von 15 bis 450 Volt, wobei der oberste Bereich von 435 bis 450 Volt nur mit „XXX“ gekennzeichnet war.","c":true,"fb":"Der Bereich von 375 bis 420 Volt trug die Beschriftung „Gefahr: heftiger Stromstoß“, die beiden höchsten Stufen lediglich „XXX“."}],"concept":{"title":"Das Milgram-Experiment (1963; 1974)","points":["<b>Drei Rollen</b>: Versuchsleiter (V, Autoritätsperson), eingeweihter „Schüler“ (S) und Versuchsperson als „Lehrer“ (L). Vorgeblich untersucht wurde der Effekt von Bestrafung auf das Lernen.","<b>Skala</b>: 15 bis 450 Volt; 375–420 Volt „Gefahr: heftiger Stromstoß“, 435–450 Volt „XXX“. Ab 300 Volt protestierte der Schüler, danach antwortete er nicht mehr.","<b>Ergebnis</b>: Alle 40 Teilnehmer (Männer, 20–50 Jahre) gingen bis 300 Volt, 26 von 40 — also 65 % — bis zur Höchststufe. Befragte Psychiater und Bürger hatten zuvor 1 % vorhergesagt.","<b>Bedingende Faktoren (Milgram, 1974)</b>: Mit abnehmender Distanz zum Schüler sinkt der Gehorsam (im selben Raum noch über 30 %); ein per Telefon anweisender Versuchsleiter senkt ihn ebenfalls; im heruntergekommenen Gebäude statt in Yale gingen noch annähernd 50 % bis zur Höchststufe.","<b>Gradueller Anstieg</b>: Der Einstieg bei 15 Volt umgeht die Hemmschwelle — ein sofortiger 450-Volt-Auftrag hätte stärkeren Widerstand ausgelöst.","<b>Verantwortungsverlagerung</b>: Man erlebt sich als „ausführendes Werkzeug“ und schreibt die Verantwortung der Autorität zu (Blass, 1999)."]}},{"id":"k7-8def5ac736","kap":7,"sec":"7.2.1 Schemata","stem":"Welche Aussagen über die Wissensstrukturen treffen zu, die der Konstruktion sozialer Realität zugrunde liegen?","opts":[{"t":"Kategorien ordnen Inhalte einem Oberbegriff zu, wobei die Zuordnung auf subjektiv wahrgenommenen Gemeinsamkeiten beruht.","c":true,"fb":"Kategorien gelten als elementare Wissensstruktur; maßgeblich ist die subjektiv wahrgenommene, nicht die objektiv geprüfte Gemeinsamkeit."},{"t":"Skripte bezeichnen sozial geteilte Überzeugungen über erwartete Merkmale und Verhaltensweisen von Angehörigen einer sozialen Kategorie.","c":false,"fb":"Das ist die Definition des Stereotyps. Skripte betreffen Ablaufvorstellungen, etwa das „Drehbuch Konzertbesuch“ vom Ticketkauf bis zum Verlassen des Saals."},{"t":"Prototypen veranschaulichen die mit einer Kategorie assoziierten Merkmale am besten und lassen sich im statistischen Sinne als Mittelwert der Kategorie auffassen.","c":true,"fb":"Der Prototyp ist als typischster Vertreter einer Kategorie definiert — im Beispiel des Kapitels die prototypische Konzertbesucherin."},{"t":"In assoziativen Netzwerken sind einander ähnliche semantische Kategorien stärker miteinander verbunden als sehr unterschiedliche.","c":true,"fb":"Häufige gleichzeitige Aktivierung stärkt die Verbindung: Konzert- und Kinobesuch liegen näher beieinander als Konzertbesuch und Familienfeier."}],"concept":{"title":"Schemata und ihre Zuordnungshilfen (Jonas, Stroebe & Hewstone, 2014)","points":["<b>Schema</b>: übergeordnete Wissensstruktur, die Wissen und Erleben gliedert und dadurch Wahrnehmung, Interpretation, Erinnerung und Verhalten beeinflusst. Umfasst Attribute und die Beziehungen zwischen Konzepten.","<b>Kategorie</b> (Zuordnungshilfe): Zuordnung von Inhalten zu einem Oberbegriff auf Basis subjektiv wahrgenommener Gemeinsamkeiten.","<b>Prototyp</b> (Zuordnungshilfe): typischster Vertreter einer Kategorie, im statistischen Sinne deren Mittelwert.","<b>Stereotyp</b> (angewandte Wissensstruktur): sozial geteilte Überzeugung über erwartete Merkmale von Kategoriemitgliedern; Individualität bleibt außen vor.","<b>Skript</b> (angewandte Wissensstruktur): Vorstellung typischer Handlungsabläufe; bleibt auch bei kleineren Abweichungen erhalten.","<b>Assoziatives Netzwerk</b>: Merkregel — Kategorien und Prototypen sind Zuordnungshilfen, Stereotype und Skripte angewandte Wissensstrukturen; ihre Verbindungen bilden das Netzwerk."]}},{"id":"k7-a1de6339d7","kap":7,"sec":"7.5.4 Situative Determinanten prosozialen Handelns","stem":"Welche Aussagen zum Bystander-Effekt und zu den ihn erklärenden Prozessen treffen zu?","opts":[{"t":"Verantwortungsdiffusion bezeichnet die Angst, von den übrigen Anwesenden für ein Eingreifen negativ bewertet zu werden.","c":false,"fb":"Das beschreibt die Bewertungsangst. Verantwortungsdiffusion meint die Verteilung der Verantwortung über alle Anwesenden, sodass sich niemand persönlich zuständig fühlt."},{"t":"Je mehr Personen anwesend sind, desto geringer wird die Wahrscheinlichkeit, dass einem Opfer geholfen wird (Darley & Latané, 1968).","c":true,"fb":"Wer sich für die einzige Zeugin oder den einzigen Zeugen hält, leistet eher Hilfe als jemand, der weitere mögliche Helfende vermutet."},{"t":"Von pluralistischer Ignoranz spricht man, wenn alle Anwesenden aus dem abwartenden Verhalten der übrigen schließen, die Lage erfordere kein Eingreifen.","c":true,"fb":"Latané und Darley (1970) beschreiben damit einen wechselseitigen Fehlschluss: Jede und jeder liest aus der Untätigkeit der anderen Unbedenklichkeit heraus."},{"t":"Der Mordfall Kitty Genovese ereignete sich 1968; die Ermittlungen ergaben, dass es lediglich drei Zeug:innen gab.","c":false,"fb":"Der Fall datiert auf 1964, und es soll mindestens 38 Zeug:innen gegeben haben — gerade diese hohe Zahl machte ihn zum Impuls für die Hilfeverhaltensforschung."}],"concept":{"title":"Bystander-Effekt und der Fall Kitty Genovese","points":["<b>Auslöser</b>: 1964 wurde die 28-jährige Catherine „Kitty“ Genovese nahe ihrem Wohnhaus attackiert; mindestens 38 Zeug:innen wurden aufmerksam, niemand griff ein oder rief die Polizei.","<b>Bystander-Effekt</b> (Darley & Latané, 1968): Die Wahrscheinlichkeit, dass geholfen wird, sinkt mit der Zahl der Anwesenden.","<b>Pluralistische Ignoranz</b> (Latané & Darley, 1970): Alle orientieren sich am Verhalten der übrigen und schließen irrtümlich, die Situation erfordere kein Einschreiten.","<b>Verantwortungsdiffusion</b>: Die Verantwortung „verteilt“ sich über alle Anwesenden; niemand fühlt sich persönlich zuständig.","<b>Bewertungsangst</b>: Auch wer sich der eigenen Verantwortung bewusst ist, hilft womöglich nicht — aus Furcht vor negativer Beurteilung durch die Anwesenden."]}},{"id":"k7-47315f7759","kap":7,"sec":"7.2.3 Zwei-Prozess-Modelle: ELM","stem":"Welche Aussage über das Elaboration-Likelihood-Model (Petty & Cacioppo, 1986) trifft zu?","opts":[{"t":"Entlang der peripheren Route wird das Gehörte einer kritischen, systematischen Prüfung der Argumente unterzogen.","c":false,"fb":"Das kennzeichnet die zentrale Route. Die periphere Route arbeitet unsystematisch-heuristisch mit einfachen Entscheidungsregeln (Urteilsheuristiken) und affektiven Prozessen."},{"t":"Das ELM geht von zwei interagierenden Systemen aus, die synergistisch oder antagonistisch zusammenwirken können.","c":false,"fb":"Von zwei interagierenden Systemen spricht das Reflektiv-Impulsiv-Modell. Das ELM beschreibt zwei Routen als entgegengesetzte Endpunkte eines Kontinuums."},{"t":"Die Elaborationswahrscheinlichkeit hängt neben der Verarbeitungsmotivation auch von der Verarbeitungskapazität und der verfügbaren Zeit ab.","c":true,"fb":"Verarbeitungskapazität meint dabei das (Vor-)Wissen im betreffenden Bereich — wer gewillt und in der Lage ist, wählt eher die zentrale Route."},{"t":"Elaboration bezeichnet das Ausmaß, in dem eine Botschaft emotional statt sachlich formuliert ist.","c":false,"fb":"Elaboration meint das Ausmaß, in dem die empfangende Person über die Argumente der Botschaft reflektiert — eine Eigenschaft der Verarbeitung, nicht der Botschaft."}],"concept":{"title":"Elaboration-Likelihood-Model (Petty & Cacioppo, 1986)","points":["<b>Gegenstand</b>: Prozesse der Persuasion — was geschieht, wenn eine Botschaft von etwas überzeugen und eine Einstellung ändern soll.","<b>Elaboration</b>: Ausmaß, in dem eine Person über die Argumente der Botschaft reflektiert; zentrales Kriterium zur Unterscheidung simpler und aufwändiger Verarbeitung.","<b>Zentrale Route</b>: bei hoher Motivation und Kapazität — systematische, kritische Prüfung. Starke Argumente erzeugen vorwiegend positive Gedanken und damit Einstellungsänderung, schwache Argumente nicht.","<b>Periphere Route</b>: bei unzureichender Motivation oder Kapazität — heuristische Verarbeitung über Urteilsheuristiken und Affekte, etwa die zugeschriebene Glaubwürdigkeit der Quelle („Auf Expert:innen kann man sich verlassen“).","<b>Elaborationswahrscheinlichkeit</b>: hängt ab von Verarbeitungsmotivation, Verarbeitungskapazität ((Vor-)Wissen) und verfügbarer Zeit.","<b>Merkregel</b>: Die beiden Routen sind Endpunkte eines Kontinuums, keine getrennten Systeme — genau darin unterscheidet sich das ELM vom RIM."]}},{"id":"k7-8eff4d7729","kap":7,"sec":"7.4.2 Minimalgruppenparadigma nach Tajfel","stem":"Welche Aussagen zu Henri Tajfels Experimenten zum Minimalgruppenparadigma treffen zu?","opts":[{"t":"Die Buben wurden anhand eines trivialen Kriteriums zufällig zwei Gruppen zugeteilt, die weder Kontakt noch unterschiedliche Gruppenziele hatten.","c":true,"fb":"Die Gruppen standen in keiner Konkurrenz zueinander und interagierten nicht — genau das macht sie zu minimalen Gruppen."},{"t":"Bei Item B wurde bevorzugt 96 : 50 gewählt, weil damit der Profit der eigenen Gruppe am höchsten ausfiel.","c":false,"fb":"Gewählt wurde eher 84 : 20. Den Schülern war der maximale Unterschied zur Outgroup wichtiger als der maximale eigene Profit."},{"t":"Ein Anteil des verteilten Geldes floss an die zuteilende Person zurück, was deren Bevorzugung der eigenen Gruppe ökonomisch erklärt.","c":false,"fb":"Weder die zuteilende Person noch ihre Gruppe erhielten Geld. Gerade deshalb lässt sich die Ingroup-Bevorzugung nicht durch Eigennutz erklären."},{"t":"Gehörten beide Empfänger derselben Gruppe an — gleich ob Ingroup oder Outgroup —, verteilten die Buben nach der Strategie Fairness.","c":true,"fb":"Erst die Kombination aus einem Ingroup- und einem Outgroup-Mitglied löste die Bevorzugung aus; innerhalb einer Gruppe wurde gerecht geteilt."}],"concept":{"title":"Minimalgruppenparadigma (Tajfel, 1970; 1971)","points":["<b>Fragestellung</b>: Welche minimalen Bedingungen genügen, damit Ingroup-Bevorzugung und Outgroup-Diskriminierung entstehen?","<b>Aufbau</b>: Schüler im Alter von 14 bis 15 Jahren, anonyme und zufällige Zuteilung anhand eines trivialen Kriteriums (z. B. Münzwurf), keine Interaktion, keine Konkurrenz, kein Gewinn für die zuteilende Person oder deren Gruppe.","<b>Aufgabe</b>: Verteilung von Werteinheiten über Zahlenpaar-Matrizen, die an den Polen jeweils zwei Strategien gegenüberstellen.","<b>Die kontrastierten Strategien</b>: Fairness, maximaler Unterschied, maximaler Profit der eigenen Gruppe bzw. maximaler gemeinsamer Profit sowie Fremdgruppenbegünstigung.","<b>Befund</b>: Der maximale Unterschied wurde dem maximalen Ingroup-Gewinn vorgezogen — also nicht nur Bevorzugung der eigenen, sondern aktive Schädigung der fremden Gruppe.","<b>Abgrenzung zu Sherif</b>: Es braucht keine reale Konkurrenzsituation. Fußnote 24 merkt an, dass diese Gruppen die übliche Definition (Interaktion der Mitglieder!) gar nicht erfüllen und Tajfels Befunde den Gruppenbegriff daher erweitern."]}},{"id":"k7-0d17d2aaba","kap":7,"sec":"7.3.1 Soziale Erleichterung vs. soziale Hemmung","stem":"Welche Aussagen zu sozialer Erleichterung und sozialer Hemmung treffen zu?","opts":[{"t":"Soziale Erleichterung — die Leistungssteigerung in Anwesenheit anderer — tritt vor allem bei einfach zu lösenden Aufgaben auf.","c":true,"fb":"Bei herausfordernden oder ungeübten Aufgaben kehrt sich der Effekt um und es kommt zur sozialen Hemmung."},{"t":"Zajonc (1965) führte den Effekt auf den Anstieg an physiologischer Erregung zurück, den man unter Beobachtung erlebt.","c":true,"fb":"Die Distraction-Conflict-Theory (Baron, 1986) ergänzt diese Erklärung später um den kognitiven Aufmerksamkeitskonflikt."},{"t":"Nach der Distraction-Conflict-Theory werden die Aufmerksamkeitsressourcen so umverteilt, dass vor allem die peripheren Aspekte der Aufgabe beachtet werden.","c":false,"fb":"Es verhält sich umgekehrt: Ressourcen werden abgezogen, sodass nur noch die zentralen Aspekte beachtet und periphere vernachlässigt werden — bei leichten Aufgaben ein Vorteil."},{"t":"Zanbaka, Ulinski, Goolkasian und Hodges (2007) zeigten eine Leistungsverschlechterung von Psychologiestudierenden bei schwierigen Mathematikaufgaben unter Anwesenheit anderer.","c":true,"fb":"Der Befund illustriert die soziale Hemmung: Die geteilte Aufmerksamkeit verhindert den bei schwierigen Aufgaben nötigen kognitiven Einsatz."}],"concept":{"title":"Soziale Erleichterung und soziale Hemmung","points":["<b>Soziale Erleichterung</b>: bessere Leistung in Anwesenheit anderer, und zwar bei einfachen Aufgaben. Erstmals 1898 von Norman Triplett beobachtet — Jugendliche wickelten unter Beobachtung eine Angelspule schneller auf.","<b>Soziale Hemmung</b>: schlechtere Leistung in Anwesenheit anderer, und zwar bei schwierigen Aufgaben oder wenn die Person ungeübt bzw. wenig vorbereitet ist (Zanbaka et al., 2007).","<b>Erregungserklärung</b> (Zajonc, 1965): Beobachtung erhöht die physiologische Erregung.","<b>Distraction-Conflict-Theory</b> (Baron, 1986) in drei Schritten: 1. Anwesende stellen eine Ablenkung dar; 2. daraus entsteht ein Aufmerksamkeitskonflikt zwischen Aufgabe und Beobachtenden; 3. Ressourcen werden von der Aufgabe abgezogen, sodass nur zentrale Aspekte beachtet werden.","<b>Merkregel</b>: Die Verengung auf zentrale Aspekte hilft bei leichten Aufgaben und schadet bei schwierigen — derselbe Mechanismus erklärt daher beide Effekte."]}},{"id":"k7-7ecec156e7","kap":7,"sec":"7.2.2 Priming","stem":"Welche Aussagen zum Priming und zu den im Kapitel berichteten Studien treffen zu?","opts":[{"t":"Yi (1990) fand, dass negativ geprimte Personen eine Autowerbung positiver beurteilten, weil die Anzeige im Kontrast zum Zeitungsartikel aufgewertet wurde.","c":false,"fb":"Es war umgekehrt: Positiv geprimte Personen berichteten eine positivere Einstellung gegenüber der Werbung und eine stärkere Kaufabsicht."},{"t":"Damit ein positiver Primingeffekt eintritt, müssen Prime und Target derselben Wortart angehören.","c":false,"fb":"Erforderlich ist eine assoziative Verknüpfung von Prime und Target — inhaltlich beim semantischen, emotional beim affektiven Priming."},{"t":"Von negativem Priming spricht man, wenn der Prime die Zugänglichkeit zum Target verringert statt sie zu erleichtern.","c":true,"fb":"Der Regelfall ist das positive Priming, bei dem der Prime den Zugang zum Target erhöht beziehungsweise erleichtert."},{"t":"Neely (1977) verwendete eine lexikalische Entscheidungsaufgabe, bei der so schnell wie möglich zu beurteilen war, ob ein Stimulus ein Wort ist oder nicht.","c":true,"fb":"Die Reaktionszeit sank, wenn dem Zielwort (z. B. Rotkehlchen) ein inhaltlich verwandter Prime (z. B. Vogel) vorausging."}],"concept":{"title":"Priming als Methode der sozialpsychologischen Forschung","points":["<b>Definition</b>: unbewusste Aktivierung von Gedächtnisinhalten durch einen vorhergehenden Hinweisreiz (Prime), die die Verarbeitung eines Zielreizes (Target) beeinflusst — engl. to prime = vorbereiten.","<b>Positives Priming</b>: erhöhte, erleichterte Zugänglichkeit zum Target. <b>Negatives Priming</b>: verringerte, erschwerte Zugänglichkeit.","<b>Voraussetzung</b>: Prime und Target müssen assoziativ miteinander verknüpft sein.","<b>Semantisches Priming</b>: inhaltliche Verknüpfung. Neely (1977) setzte eine lexikalische Entscheidungsaufgabe ein — Wort oder sinnlose Buchstabenfolge? Kürzere Reaktionszeiten nach verwandtem Prime.","<b>Affektives Priming</b>: ein emotionaler Reiz beeinflusst die Verarbeitung des Zielreizes. Yi (1990): Nach einem positiven Zeitungsartikel wurde eine Autowerbung positiver bewertet und die Kaufabsicht war stärker.","<b>Einordnung</b>: Priming dient dazu, unbewusste soziale Kognitionen überhaupt untersuchbar zu machen (Cameron, Brown-Iannuzzi & Payne, 2012)."]}},{"id":"k7-ddca796edd","kap":7,"sec":"7.3.6 Soziale Rollen und Normen","stem":"D. W. Johnson und Johnson (2013) haben sozialpsychologische Gruppendefinitionen gesichtet und die dort verwendeten Kriterien zusammengetragen. Welche der folgenden Kriterien führen sie auf?","opts":[{"t":"Gegenseitige Abhängigkeit — was einem Mitglied widerfährt, wirkt sich auch auf die übrigen Mitglieder aus.","c":true,"fb":"Interdependenz ist eines der aufgeführten Kriterien; die Mitglieder stehen zueinander in einem Wirkungszusammenhang."},{"t":"Wahrnehmung der Zugehörigkeit — die Mitglieder nehmen sich selbst als Teil der Gruppe wahr.","c":true,"fb":"Neben objektiven Merkmalen wie Interaktion und Zielen steht damit auch ein subjektives Kriterium in der Liste."},{"t":"Strukturierte Beziehungen — die Interaktionen beruhen auf einem bewussten oder unbewussten Set aus Rollen und Normen.","c":true,"fb":"Auch ohne ausdrückliche Absprache regeln Rollen und Normen, wie die Mitglieder miteinander umgehen."},{"t":"Motivation — die Mitglieder befriedigen durch die Gruppenmitgliedschaft ein persönliches Bedürfnis.","c":true,"fb":"Das Kriterium ergänzt die eher strukturellen Bedingungen um eine individuelle, bedürfnisbezogene."}],"concept":{"title":"Was ist eine Gruppe im sozialpsychologischen Sinn?","points":["<b>Zwei Grundbedingungen</b>: eine Mehrzahl an Personen und Interaktion zwischen diesen Personen. Alle Personen, die 2020 in Österreich eine Grippe hatten, sind daher keine Gruppe im sozialpsychologischen Sinn.","<b>Keine allgemein gültige Definition</b>: D. W. Johnson und Johnson (2013) fanden zahlreiche Kriterien, die von verschiedenen Autor:innen angenommen werden, aber nicht zwingend alle gemeinsam.","<b>Die sieben aufgelisteten Kriterien</b>: Ziele, gegenseitige Abhängigkeit, Interaktion, Wahrnehmung der Zugehörigkeit, strukturierte Beziehungen, gegenseitiger Einfluss, Motivation.","<b>Gruppengröße</b>: Ob mehr als zwei Personen nötig sind, ist unklar — viele Studien des Kapitels arbeiten mit Dyaden. Manche Gruppeneffekte hängen jedoch direkt an der Größe.","<b>Mehrfachmitgliedschaft</b>: Man gehört üblicherweise mehreren Gruppen gleichzeitig an und nimmt in jeder eine andere soziale Rolle ein."]}},{"id":"k7-2ccdb06947","kap":7,"sec":"7.3.3 Einfluss von Minderheiten","stem":"Welche Aussage zur Studie von Moscovici, Lage und Naffrechoux (1969) zur Farbwahrnehmung trifft zu?","opts":[{"t":"Die gezeigten Bilder waren tatsächlich grün in unterschiedlicher Helligkeit; die eingeweihte Minderheit bezeichnete sie als blau.","c":false,"fb":"Umgekehrt: Die Bilder waren durchgehend blau in unterschiedlicher Helligkeit, und die Minderheit nannte sie „grün“."},{"t":"Wurde die abweichende Farbangabe konsistent vertreten, schlossen sich rund 8 % der Versuchspersonen an; bei inkonsistenter Minderheit war es etwa 1 %.","c":true,"fb":"Die Konsistenz ist damit der zentrale Einflussfaktor von Minderheiten — inkonsistent hieß hier: nur in etwa einem Drittel der Fälle „grün“."},{"t":"Die Gruppen umfassten jeweils vier Personen, von denen eine als Minderheit fungierte.","c":false,"fb":"Von insgesamt sechs Gruppenmitgliedern waren zwei eingeweihte Helfer:innen der Versuchsleitung."},{"t":"In der anschließenden Befragung nahmen die Versuchspersonen aus der konsistenten Bedingung weniger Farbnuancen wahr als jene aus der inkonsistenten.","c":false,"fb":"Sie berichteten mehr Nuancen — ein Hinweis darauf, dass der Minderheiteneinfluss indirekt auf innere Überzeugungen wirkt und länger anhält."}],"concept":{"title":"Einfluss von Minderheiten","points":["<b>Ausgangslage</b>: Minderheiten verfügen weder über Macht noch über ein positives soziales Image; sie gelten eher als unvernünftig und abweichend. Ihr Einfluss liegt daher im Verhalten (Moscovici & Mugny, 1983).","<b>Konsistenz</b>: zentraler Einflussfaktor — die abweichende Überzeugung muss systematisch und gleichbleibend vertreten werden.","<b>Farbwahrnehmungsstudie</b> (Moscovici, Lage & Naffrechoux, 1969): sechs Personen, davon zwei eingeweiht; durchgehend blaue Bilder wurden als „grün“ bezeichnet. Konsistent ca. 8 %, inkonsistent ca. 1 % Anschluss.","<b>Nachwirkung</b>: Versuchspersonen aus der konsistenten Bedingung berichteten anschließend mehr Farbnuancen — der Einfluss wirkt indirekt und langfristig auf innere Überzeugungen.","<b>Divergentes Denken</b> (Nemeth & Kwan, 1987): In der Minderheitsbedingung wurde die abweichende Anagrammstrategie nicht blind übernommen, sondern das eigene Vorgehen erweitert; in der Mehrheitsbedingung folgte man ihr.","<b>Merkregel</b>: Mehrheiten wirken direkt, kurzfristig und auf das Verhalten; konsistente Minderheiten subtil, indirekt, langfristig und auf die Überzeugung."]}},{"id":"k7-f8c4478e5d","kap":7,"sec":"7.3.5 Bewusste soziale Einflussnahme","stem":"Welche Aussagen zur Reziprozitätsnorm und zum Door-in-the-face-Prinzip treffen zu?","opts":[{"t":"Bei Cialdini et al. (1975) stimmten 50 % der Studierenden dem zweistündigen Zoobesuch zu, nachdem zuvor eine sehr große Bitte abgelehnt worden war.","c":true,"fb":"Ohne vorangegangene große Bitte lag die Zustimmung in der Vergleichsgruppe bei nur 17 %."},{"t":"Das Door-in-the-face-Prinzip beruht darauf, dass eine bereits gewährte kleine Bitte ein Commitment erzeugt, dem man konsistent bleiben möchte.","c":false,"fb":"Das beschreibt das Foot-in-the-door-Prinzip. Door-in-the-face beruht auf Reziprozität: Das Zurückstecken der bittenden Person wird als Entgegenkommen erwidert."},{"t":"In Regans (1971) Untersuchung kauften jene Versuchspersonen mehr Lose, denen die eingeweihte Person zuvor in der Pause ein Getränk mitgebracht hatte.","c":true,"fb":"Die unaufgeforderte Gefälligkeit erzeugte ein Verpflichtungsgefühl — unabhängig davon, ob die Lose überhaupt gewollt waren."},{"t":"Die Reziprozitätsnorm entfaltet ihre Wirkung nur dann, wenn die empfangende Person die Gefälligkeit ausdrücklich erbeten hat.","c":false,"fb":"Menschen fühlen sich durch sozialen Druck zur Erwiderung verpflichtet, unabhängig davon, ob sie das wollen oder die Gefälligkeit erbeten haben."}],"concept":{"title":"Judo-Strategien: Reziprozität und sequenzielle Bitten (Werth & Mayer, 2020)","points":["<b>Judo-Strategien</b>: bewusste Beeinflussungstechniken — Prinzip sozialer Bewährtheit, Prinzip der Knappheit, Kontrastprinzip, Reziprozitätsnorm, Commitment und weitere.","<b>Reziprozitätsnorm</b>: soziale Norm, wonach Geben und Nehmen sich die Waage halten sollen; sie erzeugt Verpflichtungsgefühle. Regan (1971): Getränk in der Pause führte zu mehr gekauften Losen.","<b>Door-in-the-face</b>: zuerst eine große Bitte mit kalkulierter Ablehnung, danach die kleinere. Cialdini et al. (1975): 17 % gegenüber 50 % Zustimmung zum Zoobesuch. Beruht auf <b>Reziprozität</b>.","<b>Foot-in-the-door</b>: zuerst die kleine Bitte, dann die große. Freedman & Fraser (1966): 22 % gegenüber 53 % Zustimmung zur Bestandsaufnahme im Haus. Beruht auf <b>Commitment</b> und dem Streben nach Konsistenz.","<b>Commitment</b>: wird besonders verhaltenswirksam, wenn es aktiv und öffentlich geäußert, mit Anstrengung verbunden und freiwillig eingegangen wird. Beim Foot-in-the-door dürfen die beiden Bitten sogar von verschiedenen Personen stammen, sofern sie dasselbe Thema betreffen.","<b>Merkregel</b>: Door-in-the-face = groß vor klein, Gegenseitigkeit. Foot-in-the-door = klein vor groß, Selbstbild."]}},{"id":"k7-74bb4ff746","kap":7,"sec":"7.4.3 Stereotype, Vorurteile und Diskriminierung","stem":"Welche Aussagen zur Unterscheidung von Stereotyp, Vorurteil und Diskriminierung treffen zu?","opts":[{"t":"Das Stereotyp bildet die kognitive Komponente der Voreingenommenheit und umfasst Überzeugungen darüber, wie verschiedene Gruppen sind und welche Eigenschaften sie haben.","c":true,"fb":"Ein klassisches Beispiel ist die Wahrnehmung von Geschlechterunterschieden, etwa „Frauen sind fürsorglich und emotional“."},{"t":"Diskriminierung bezeichnet das ungerechtfertigte, benachteiligende Verhalten aufgrund von Voreingenommenheit und stellt damit die Verhaltenskomponente dar.","c":true,"fb":"Im Beispiel des Kapitels: weniger herausfordernde Aufgaben und weniger Feedback für Schülerinnen."},{"t":"Vorurteile sind definitionsgemäß negativ; positiv getönte Zuschreibungen fallen begrifflich unter das Stereotyp.","c":false,"fb":"Vorurteile umfassen ausdrücklich positive und negative Empfindungen gegenüber einer Gruppe — auch Sympathie für Fans der eigenen Mannschaft ist ein Vorurteil."},{"t":"Das Vorurteil ist die affektive Komponente der Voreingenommenheit und bezeichnet die Empfindungen gegenüber einer Gruppe.","c":true,"fb":"Stereotyp (Kognition), Vorurteil (Affekt) und Diskriminierung (Verhalten) bilden zusammen die drei Komponenten."}],"concept":{"title":"Voreingenommenheit in drei Komponenten","points":["<b>Stereotyp — kognitiv</b>: sozial geteilte Überzeugungen hinsichtlich erwarteter Merkmale und Verhaltensweisen von Angehörigen einer sozialen Kategorie.","<b>Vorurteil — affektiv</b>: positive wie negative Empfindungen gegenüber einer Gruppe.","<b>Diskriminierung — Verhalten</b>: ungerechtfertigtes, benachteiligendes Verhalten aufgrund von Voreingenommenheit.","<b>Beispielkette</b>: Eine Lehrperson hält Schülerinnen für weniger begabt (Stereotyp), empfindet sie als frustrierend (Vorurteil) und gibt ihnen weniger herausfordernde Aufgaben (Diskriminierung).","<b>Theorie der Sozialen Identität</b> (Tajfel & Turner, 2004): Gruppenzugehörigkeiten helfen zu einer positiven sozialen Identität — abhängig davon, wie die eigene Gruppe im Vergleich mit relevanten Outgroups abschneidet.","<b>Selbsterfüllende Prophezeiung</b> (Banks, 1988): Das Stereotyp erzeugt die Benachteiligung, die es anschließend bestätigt."]}},{"id":"k7-e65bc8f60b","kap":7,"sec":"7.5.2 Empathie-Altruismus-Hypothese","stem":"Welche Aussagen zum Experiment von Toi und Batson (1982) über das Hilfeverhalten gegenüber der Studentin Carol treffen zu?","opts":[{"t":"Der schwierige Ausweg bestand darin, dass Carol zu Hause blieb und ein Treffen gegebenenfalls eigens hätte vereinbart werden müssen.","c":false,"fb":"Das war der leichte Ausweg. Beim schwierigen Ausweg sollte Carol in der Folgewoche im Kurs sein und dort an Rollstuhl und eingegipsten Beinen leicht zu erkennen sein."},{"t":"In der Bedingung hoher Empathie waren in beiden Ausweg-Varianten um die 80 % der Versuchspersonen zur Hilfe bereit.","c":true,"fb":"Der Unterschied zwischen leichtem und schwierigem Ausweg verschwand — ein Hinweis darauf, dass hier keine Kosten-Nutzen-Abschätzung stattfand."},{"t":"Die Experimentalgruppe war instruiert, sich beim Hören der Aufnahme möglichst auf die objektiven Details des Beitrags zu konzentrieren.","c":false,"fb":"Das war die Instruktion der Kontrollgruppe (niedrige Empathie). Die Experimentalgruppe sollte sich in die vorkommenden Personen hineinversetzen."},{"t":"In der Bedingung niedriger Empathie half rund ein Drittel, wenn ein leichter Ausweg bestand, gegenüber etwa drei Vierteln beim schwierigen Ausweg.","c":true,"fb":"Konkret 33 % gegenüber 76 % — ohne Empathie schlägt die Abwägung von Kosten und Nutzen durch."}],"concept":{"title":"Empathie-Altruismus-Hypothese","points":["<b>Altruismus</b>: uneigennützige Rücksichtnahme auf andere, gekennzeichnet durch Selbstlosigkeit in Denken, Fühlen und Handeln (Bergius & Six, 2021).","<b>Empathie</b>: Fähigkeit, sich an die Stelle einer anderen Person zu versetzen und deren Ereignisse und Emotionen aus ihrer Perspektive nachzuempfinden (vgl. Aronson, Wilson & Akert, 2014).","<b>Studie Toi & Batson (1982)</b>: gekreuzt wurden Empathie (hoch/niedrig) und Schwierigkeit des Auswegs (leicht/schwierig). Niedrige Empathie: 76 % vs. 33 %; hohe Empathie: in beiden Varianten um die 80 %.","<b>Schluss</b>: Bei Empathie unterbleibt die Kosten-Nutzen-Abschätzung. Ein Nutzen — etwa bessere Stimmung — kann dennoch entstehen, gilt aber als Nebeneffekt (Werth & Mayer, 2020).","<b>Prüfkriterium für echten Altruismus</b>: Verschlechtert ein fehlgeschlagener Hilfeversuch die Stimmung? Bei empathisch motivierter Hilfe ja, weil die Notlinderung ausbleibt; sonst genügt bereits der Versuch zur Gewissensberuhigung.","<b>Empathieförderlich</b>: Kennen der Person, wahrgenommene Ähnlichkeit, unverschuldete Notlage; auf Seiten der Helfenden eine Veranlagung zu empathischem Verhalten sowie das weibliche Geschlecht."]}},{"id":"k7-20b747e390","kap":7,"sec":"7.2 Soziale Kognition","stem":"Werth, Denzler und Mayer (2020) unterscheiden drei prototypische Stufen sozialer Kognition. Welche Aussagen dazu treffen zu?","opts":[{"t":"Auf der ersten Stufe erfolgt die unbewusste Filterung relevanter Reize auf Basis von Aufmerksamkeit.","c":true,"fb":"Welche Reize gefiltert werden, hängt unter anderem von der Person, der sozialen Situation und der aktuellen Stimmung ab."},{"t":"Die drei Stufen sind trennscharf voneinander abgegrenzt und laufen strikt nacheinander ab.","c":false,"fb":"Die Stufen können sich in der Abfolge überlappen und sind daher gerade nicht völlig voneinander abgrenzbar."},{"t":"Auf der Stufe der Kategorisierung/Enkodierung wird der wahrgenommenen Information in Abhängigkeit vom Vorwissen Bedeutung zugeschrieben.","c":true,"fb":"Interpretation und Einordnung sind hier der Kern — im Partybeispiel die Deutung der Abwesenheit der Freundin als alarmierend."},{"t":"Alle drei Stufen werden von der Wissensorganisation und dem Gedächtnis beeinflusst.","c":true,"fb":"Das organisierte Vorwissen ist Grundlage der Informationsverarbeitung auf jeder Stufe, nicht nur auf der letzten."}],"concept":{"title":"Drei Stufen sozialer Kognition (Werth, Denzler & Mayer, 2020)","points":["<b>Soziale Kognition</b>: mentale Prozesse im Kontext sozialer Situationen — wie Informationen über soziale Objekte (eigene Person, andere) aufgenommen und verarbeitet werden und welche Gedanken, Gefühle und Handlungen daraus folgen.","<b>Stufe 1 — Wahrnehmung</b>: unbewusste Filterung relevanter Reize auf Basis von Aufmerksamkeit.","<b>Stufe 2 — Kategorisierung/Enkodierung</b>: Interpretation und Einordnung der Reize in Abhängigkeit des Vorwissens; der Information wird Bedeutung zugeschrieben.","<b>Stufe 3 — Urteilsgenerierung/Erinnerung</b>: Schlussfolgerungen, Urteilsbildung und Entscheidungen über angebrachtes Verhalten in bestimmten Situationen.","<b>Querliegend</b>: Wissensorganisation und Gedächtnis (Vorwissen) beeinflussen alle drei Stufen; die Stufen können einander überlappen.","<b>Soziale Akteure</b>: nicht nur Einzelpersonen, sondern auch Gruppen und Gesellschaften."]}},{"id":"k7-c594cdf1de","kap":7,"sec":"7.3.2 Einfluss von Mehrheiten","stem":"Welche Aussagen zum Asch-Experiment und zum Konformitätsbegriff treffen zu?","opts":[{"t":"Die echte Versuchsperson war so platziert, dass sie ihr Urteil meist an fünfter Stelle abgab.","c":true,"fb":"So hörte sie vor ihrer eigenen Antwort bereits mehrere übereinstimmende Urteile der eingeweihten Personen."},{"t":"In den kritischen Durchgängen schlossen sich die Versuchspersonen in etwa einem Drittel der Fälle der offensichtlich falschen Mehrheitsmeinung an.","c":true,"fb":"Bearbeiteten sie dieselbe Aufgabe allein, lag die Fehlerquote bei unter 1 %."},{"t":"Die eingeweihten Personen gaben von Beginn an durchgängig die falsche Antwort, um die Versuchsperson früh unter Druck zu setzen.","c":false,"fb":"In den ersten Durchgängen antworteten sie offensichtlich richtig; erst danach folgten die für das Experiment relevanten Durchgänge mit einheitlich falscher Antwort."},{"t":"Konformität bezeichnet die Unterordnung unter den Willen einer Person, der Macht oder Autorität zugeschrieben wird.","c":false,"fb":"Das ist Gehorsam. Konformität meint die Anpassung des eigenen Denkens oder Handelns an die Meinung der Mehrheit, gegebenenfalls trotz besseren Wissens."}],"concept":{"title":"Asch-Experiment und Konformität","points":["<b>Aufbau</b> (Asch, 1956): eine Versuchsperson in einer Gruppe eingeweihter Helfer:innen. Zu beurteilen war, welche von drei Linien einer Referenzlinie gleicht; die Urteile wurden laut und nacheinander abgegeben, die echte Versuchsperson meist an fünfter Stelle.","<b>Ablauf</b>: In den ersten Durchgängen antworteten alle richtig; danach gaben die Eingeweihten einheitlich eine eindeutig falsche Antwort.","<b>Ergebnis</b>: Anschluss an die falsche Mehrheit in rund einem Drittel der Fälle; allein bearbeitet lag die Fehlerquote unter 1 %.","<b>Konformität</b>: Anpassung des eigenen Denkens oder Handelns an die Mehrheitsmeinung, gegebenenfalls trotz besseren Wissens.","<b>Zwei Quellen</b> (Myers, 2014): normativer sozialer Einfluss („Das tut man (nicht)“) und informationaler sozialer Einfluss („Was die anderen tun, muss richtig sein“).","<b>Abgrenzung</b>: Gehorsam setzt zusätzlich Macht oder Autorität auf Seiten der einflussnehmenden Person voraus."]}},{"id":"k7-c596a52087","kap":7,"sec":"7.4.1 Ferienlagerexperiment der Sherifs","stem":"Welche Aussagen zum Ferienlagerexperiment des Ehepaars Sherif treffen zu?","opts":[{"t":"Gemeinsame nicht kompetitive Aktivitäten wie Filmschauen und Essen genügten, um die Feindseligkeit zwischen den Gruppen abzubauen.","c":false,"fb":"Dieser erste Versuch reichte gerade nicht aus. Nötig waren Aufgaben, die nur gemeinsam zu bewältigen waren — etwa die Reparatur der manipulierten Wasserversorgung."},{"t":"In der ersten Phase entwickelten die beiden Gruppen eigene Identitäten und Hierarchien, spezifische Rituale und selbst gewählte Gruppennamen.","c":true,"fb":"Es entstand zunehmend Gruppenkohäsion; die Gruppen nannten sich „Klapperschlangen“ und „Adler“."},{"t":"Die Versuchsleitung manipulierte den Punktestand der Wettbewerbe so, dass ein für beide Gruppen frustrierendes Kopf-an-Kopf-Rennen entstand.","c":true,"fb":"Dazu dienten etwa manipulierbare Schnitzeljagden; nur so blieb die Konkurrenz durchgängig aufrecht."},{"t":"Die 22 teilnehmenden Buben waren einander zuvor unbekannt und hinsichtlich Alter, Hintergrund und Bildungsniveau bewusst vergleichbar ausgewählt.","c":true,"fb":"Alle waren 11 bis 12 Jahre alt, hatten einen vergleichbaren sozioökonomischen Mittelschichthintergrund und keine bekannten persönlichen Schwierigkeiten."}],"concept":{"title":"Ferienlagerexperiment der Sherifs (1961; robbers cave experiment)","points":["<b>Stichprobe</b>: 22 einander unbekannte Buben, 11–12 Jahre, vergleichbarer Hintergrund; drei Wochen Ferienlager in den USA.","<b>Phase 1 — Gruppenbildung</b>: zufällige Aufteilung, räumlich getrennte Herbergen, Aktivitäten nur innerhalb der eigenen Gruppe. Es entsteht <b>Gruppenkohäsion</b>: eigene Identitäten, Hierarchien, Rituale, Namen („Klapperschlangen“, „Adler“).","<b>Gruppenkohäsion</b>: Ausmaß, in dem eine Gruppe als geschlossene Einheit auftritt; bestimmt durch die Beziehungen der Mitglieder und den Wunsch, Teil der Gruppe zu bleiben. Hohe Kohäsion erleichtert Zielsetzung und Zielerreichung (D. W. Johnson & Johnson, 2013).","<b>Phase 2 — Konflikt</b>: Wettbewerbe mit Preisen nur für das Gewinnerteam, manipulierter Punktestand für ein knappes Rennen. Folge: Beleidigungen, Vorurteile, gegenseitiges Meiden, Überfälle auf die Lager, physische Gewalt — bei gleichzeitig steigender Solidarität in der eigenen Gruppe.","<b>Phase 3 — Befriedung</b>: Räumliche Nähe genügt nicht. Erst übergeordnete Ziele, die nur gemeinsam erreichbar sind, führen zu Kooperation, Durchmischung und Abbau der Vorurteile.","<b>Inter- vs. Intragruppenkonflikt</b>: inter = zwischen Gruppen, intra = innerhalb einer Gruppe (lat. inter = zwischen, intra = innerhalb)."]}},{"id":"k7-14fc253272","kap":7,"sec":"7.3.6 Soziale Rollen und Normen","stem":"Welche Aussage zum Stanford Gefängnisexperiment (Haney, Banks & Zimbardo, 1973) trifft zu?","opts":[{"t":"Das auf 14 Tage angelegte Experiment musste nach nur sechs Tagen abgebrochen werden.","c":true,"fb":"Anlass waren emotionale Zusammenbrüche einzelner Häftlinge, die ängstlich, verzweifelt wurden und depressive Züge zeigten."},{"t":"Die 21 Studenten wurden anhand eines vorab erhobenen Persönlichkeitsprofils den Rollen Wärter und Häftling zugewiesen.","c":false,"fb":"Die Zuordnung erfolgte durch das Werfen einer Münze, gerade um jede Einflussnahme der Versuchsleitung auf die Rollenverteilung auszuschließen."},{"t":"Griggs und Whitehead (2014) halten fest, dass sich etwa zwei Drittel der Wärter zu sadistischen Handlungen hinreißen ließen.","c":false,"fb":"Es war rund ein Drittel; zwei Drittel gingen trotz der manipulierten Situation human mit den Häftlingen um."},{"t":"Ein Aufstand der Häftlinge blieb aus, weshalb die Wärter ihre Maßnahmen aus eigenem Antrieb verschärften.","c":false,"fb":"Bereits am zweiten Tag kam es zum Aufstand — erst darauf folgten die härteren Maßnahmen wie der Entzug von Betten und Kleidung."}],"concept":{"title":"Stanford Gefängnisexperiment (Haney, Banks & Zimbardo, 1973)","points":["<b>Aufbau</b>: 21 männliche Studenten, Zuteilung zu „Gefängniswärter“ und „Häftling“ per Münzwurf, simuliertes Gefängnis im Untergeschoss eines Gebäudes der Universität Stanford, geplant für 14 Tage.","<b>Deindividuation durch Ausstattung</b>: Häftlinge erhielten Nummern statt Namen, ein langes Hemd und eine Kappe aus Nylonstrümpfen; Wärter khakifarbene Uniform, Pfeife, Schlagstock und verspiegelte Sonnenbrille.","<b>Verlauf</b>: Schikanen der Wärter, Aufstand am zweiten Tag, danach Entzug von Betten und Kleidung, Abspritzen mit dem Feuerlöscher, verwehrter Toilettengang.","<b>Abbruch</b>: nach sechs statt vierzehn Tagen wegen emotionaler Zusammenbrüche einzelner Häftlinge.","<b>Einschränkung</b>: Die Versuchsleitung gestand im Nachhinein, die Wärter indirekt zu Grausamkeiten instruiert zu haben. Etwa ein Drittel der Wärter handelte sadistisch, zwei Drittel human (Griggs & Whitehead, 2014).","<b>Deindividuation</b>: Vernachlässigung der eigenen Identität und verstärkte Anpassung an Gruppennormen; durch Masken oder Uniformen zusätzlich verstärkt (Rehm, Steinleitner & Lilli, 1987)."]}},{"id":"k7-9c28853af5","kap":7,"sec":"7.5.1 Evolutionspsychologische Erklärung","stem":"Welche Aussagen zur evolutionspsychologischen Erklärung prosozialen Verhaltens treffen zu?","opts":[{"t":"Die Verwandtenselektion (Hamilton, 1964) beruht auf der Motivation, die Überlebenschancen der eigenen Nachkommen und nahen Verwandten zu sichern.","c":true,"fb":"Prosoziales Verhalten erscheint aus dieser Sicht gerechtfertigt, wenn es die Chance der Weitergabe der eigenen Gene erhöht."},{"t":"Der Ansatz greift vor allem bei alltäglichen Gefälligkeiten, bei denen die Weitergabe der Gene nicht bedroht ist.","c":false,"fb":"Es geht gerade um Situationen, in denen die Weitergabe der Gene maßgeblich bedroht ist — etwa durch Tod oder Verletzung (Burnstein, Crandall & Kitayama, 1994)."},{"t":"Die Hilfsbereitschaft fällt gegenüber Personen höher aus, die man als sich selbst ähnlich wahrnimmt und mit denen man vermehrt Kontakt hat.","c":true,"fb":"Aus wahrgenommener Ähnlichkeit wird implizit auf genetische Ähnlichkeit geschlossen."},{"t":"Hilfeverhalten gegenüber nicht verwandten Personen lässt sich mit diesem Ansatz grundsätzlich nicht erklären.","c":false,"fb":"Über die implizit unterstellte genetische Ähnlichkeit erklärt der Ansatz auch Hilfe für Bekannte, Freunde und andere ähnliche, nicht verwandte Personen."}],"concept":{"title":"Drei Erklärungen prosozialen Verhaltens","points":["<b>Prosoziales Verhalten</b>: jegliches Verhalten, durch das das Wohlergehen anderer erhöht werden soll, absichtlich und freiwillig gezeigt (vgl. Eisenberg & Fabes, 1998).","<b>Evolutionspsychologischer Ansatz</b>: Verwandtenselektion (kin selection; Hamilton, 1964) — Hilfe sichert die Weitergabe der eigenen Gene, besonders wenn diese bedroht ist.","<b>Erweiterung auf Nichtverwandte</b>: Wahrgenommene Ähnlichkeit wird implizit als genetische Ähnlichkeit gedeutet, weshalb auch Bekannten und Freunden geholfen wird (Burnstein et al., 1994).","<b>Empathie-Altruismus-Hypothese</b>: Hilfe aus Empathie, ohne Kosten-Nutzen-Abschätzung; echter Altruismus ist damit möglich.","<b>Soziale-Austausch-Theorie</b> (Homans, 1961): wahrer Altruismus existiert nicht — Kosten und soziale Belohnungen werden gegeneinander abgewogen.","<b>Merkregel</b>: Der evolutionäre Ansatz erklärt vor allem, <i>wem</i> geholfen wird; die beiden anderen Theorien, <i>warum</i> überhaupt geholfen wird."]}},{"id":"k7-71b41db159","kap":7,"sec":"7.2.3 Zwei-Prozess-Modelle: RIM","stem":"Welche Aussagen zum Reflektiv-Impulsiv-Modell (Strack & Deutsch, 2004) treffen zu?","opts":[{"t":"Das reflektive System erfordert Zeit und Kapazität, läuft daher sequenziell ab und greift vor allem auf Inhalte des Langzeitgedächtnisses zurück.","c":true,"fb":"Seine Entscheidungen beruhen auf faktischem und evaluativem Wissen und setzen ausreichend kognitive Kapazität und Motivation voraus."},{"t":"Die Prozesse des impulsiven Systems sind schnell, effizient und können parallel ablaufen, weil sie kaum Motivation und Kapazität erfordern.","c":true,"fb":"Verhalten beruht hier überwiegend auf assoziativen Verbindungen, etwa Verhaltensschemata, und kann auch ohne bewusste Ziele gezeigt werden."},{"t":"Hofmann, Rauch und Gawronski (2007) schlossen aus ihren Daten, dass bei unzureichender kognitiver Kapazität das impulsive System handlungsleitend ist.","c":true,"fb":"In der Experimentalgruppe, deren Selbstregulation durch Emotionsunterdrückung beansprucht war, sagte die Einstellung zu Schokolinsen den Konsum vorher — nicht das Diätstreben."},{"t":"Antagonistisches Zusammenspiel bedeutet, dass beide Systeme in dieselbe Richtung wirken und einander verstärken.","c":false,"fb":"Das beschreibt das synergistische Zusammenspiel. Antagonistisch heißt: in die entgegengesetzte Richtung laufend."}],"concept":{"title":"Reflektiv-Impulsiv-Modell (Strack & Deutsch, 2004)","points":["<b>Grundidee</b>: nicht zwei Routen wie im ELM, sondern zwei <b>interagierende Systeme</b>; das Modell zielt auf die Erklärung von Verhalten.","<b>Reflektives System</b>: bewusstes Verhalten auf Basis von Fakten, möglichen Konsequenzen und Werten; sequenziell, aufwändig, greift als Kontrollmechanismus auf das Langzeitgedächtnis zurück; benötigt Kapazität und Motivation.","<b>Impulsives System</b>: Verhalten überwiegend auf Basis assoziativer Verbindungen (z. B. Verhaltensschemata); schnell, effizient, parallel ablaufend, auch ohne bewusste Ziele.","<b>Zusammenspiel</b>: synergistisch (gleiche Richtung) oder antagonistisch (entgegengesetzte Richtung) — Tortenbeispiel: annehmen, aber nur ein kleines Stück, gegenüber ablehnen.","<b>Hofmann, Rauch & Gawronski (2007)</b>: Kontrollgruppe mit hohen Ressourcen — je höher das Diätstreben, desto weniger Schokolinsen. Experimentalgruppe mit beanspruchter Selbstregulation — je positiver die Einstellung, desto mehr Konsum.","<b>Selbstregulation</b>: Steuerung des eigenen Verhaltens im Hinblick auf selbst gesetzte Ziele, bestehend aus Selbstbeobachtung (Ist-Zustand) und Selbstbewertung (Vergleich mit dem Soll-Wert); daraus folgt Selbstverstärkung oder Verhaltensänderung (Reinecker, 2022)."]}},{"id":"k7-a0ae8e8e7a","kap":7,"sec":"7.3.2 Einfluss von Mehrheiten","stem":"Welche Aussage zur Unterscheidung von normativem und informationalem sozialem Einfluss (Myers, 2014) trifft zu?","opts":[{"t":"Beim normativen sozialen Einfluss wird die Mehrheitsüberzeugung nach außen geteilt, während insgeheim die eigene, abweichende Überzeugung fortbestehen kann.","c":true,"fb":"Angepasst wird das nach außen sichtbare Verhalten — Ziel ist es, soziale Ablehnung zu vermeiden beziehungsweise Anerkennung zu gewinnen."},{"t":"Informationaler sozialer Einfluss entsteht vor allem aus dem Bestreben, soziale Ablehnung durch die Gruppe zu vermeiden.","c":false,"fb":"Das ist das Motiv des normativen Einflusses. Informational heißt: Die anderen werden als kompetent wahrgenommen und ihr Verhalten für das richtige gehalten."},{"t":"Krisensituationen und Zeitdruck senken den informationalen sozialen Einfluss, weil zur Orientierung an anderen kaum Zeit bleibt.","c":false,"fb":"Sie erhöhen ihn — ebenso wie die zugeschriebene Expertise der Anwesenden und die Wichtigkeit des Urteils."},{"t":"Der Chamäleon-Effekt (Chartrand & Bargh, 1999) ist ein Beispiel für normativen sozialen Einfluss, weil bewusst Gruppennormen befolgt werden.","c":false,"fb":"Der Chamäleon-Effekt beschreibt das <b>unbewusste</b> Nachahmen nonverbaler Verhaltensweisen wie Gesten und Gesichtsausdrücke — eine bewusste Normbefolgung liegt gerade nicht vor."}],"concept":{"title":"Normativer und informationaler sozialer Einfluss (Myers, 2014)","points":["<b>Normativer sozialer Einfluss</b> — „Das tut man (nicht)“: Anpassung an soziale Normen, um soziale Ablehnung zu vermeiden und Anerkennung zu gewinnen. Die Mehrheitsüberzeugung wird nach außen geteilt, insgeheim kann die abweichende bestehen bleiben.","<b>Soziale Normen</b>: Regeln einer Gruppe oder Gesellschaft für akzeptiertes Verhalten, Werte und Einstellungen; sie variieren nach Gruppe, Kontext und sozialer Situation.","<b>Informationaler sozialer Einfluss</b> — „Das, was die anderen tun, muss richtig sein“: andere dienen als Informationsquelle für adäquates Handeln, weil sie als kompetent wahrgenommen werden.","<b>Verstärker des informationalen Einflusses</b>: Mehrdeutigkeit oder Neuheit der Situation, Krisensituationen, zugeschriebene Expertise der Anwesenden, Wichtigkeit des Urteils.","<b>Chamäleon-Effekt</b> (Chartrand & Bargh, 1999): unbewusstes Nachahmen nonverbaler Verhaltensweisen — Versuchspersonen strichen sich häufiger übers Gesicht bzw. wippten mit dem Fuß, wenn ihr Gegenüber dies tat."]}},{"id":"k7-cfbc50dfe4","kap":7,"sec":"7.5.3 Soziale-Austausch-Theorie","stem":"Welche Aussagen zur Sozialen-Austausch-Theorie (Homans, 1961) treffen zu?","opts":[{"t":"Nach dieser Theorie unterbleibt jede Kosten-Nutzen-Abschätzung, sobald Empathie für die notleidende Person empfunden wird.","c":false,"fb":"Das ist die Aussage der Empathie-Altruismus-Hypothese. Die Soziale-Austausch-Theorie hält die Abwägung gerade für den entscheidenden Mechanismus."},{"t":"Der Theorie zufolge existiert wahrer Altruismus nicht; geholfen wird, wenn die sozialen Belohnungen die Kosten überwiegen.","c":true,"fb":"Die Kurzformel des Kapitels lautet: Eine Hand wäscht die andere."},{"t":"Peinlichkeit und Zeitaufwand zählen nicht zu den sozialen Kosten, weil ihnen kein messbarer Wert zukommt.","c":false,"fb":"Zeitaufwand, Gefahr, Schmerz und Peinlichkeit werden ausdrücklich als Beispiele sozialer Kosten geführt."},{"t":"Als soziale Belohnungen gelten unter anderem ein erhöhtes Selbstwertgefühl, Anerkennung durch die Gruppe und die Reduktion von Stress.","c":true,"fb":"Auch die Aussicht auf künftige Hilfe anderer Menschen als Gegenleistung zählt dazu."}],"concept":{"title":"Soziale-Austausch-Theorie (Homans, 1961)","points":["<b>Grundannahme</b>: Wahrer Altruismus existiert nicht — prosoziales Verhalten folgt einer Abwägung.","<b>Soziale Kosten</b>: Zeitaufwand, Gefahr, Schmerz, Peinlichkeit und Ähnliches.","<b>Soziale Belohnungen</b>: Erhöhung des Selbstwertgefühls, Anerkennung durch die Gruppe, künftige Hilfe anderer als Gegenleistung, Reduktion von Stress.","<b>Entscheidungsregel</b>: Geholfen wird, wenn die sozialen Belohnungen in Relation zu den Kosten überwiegen.","<b>Abgrenzung</b>: Die Empathie-Altruismus-Hypothese behauptet das Gegenteil — bei Empathie unterbleibt die Kosten-Nutzen-Abschätzung, ein Nutzen kann aber als Nebeneffekt entstehen."]}},{"id":"k7-caddf59339","kap":7,"sec":"7.3.1 Soziale Erleichterung vs. soziale Hemmung","stem":"Welche Aussage zum Experiment von Muller et al. (2004) und zu Illusory Conjunction Tasks trifft zu?","opts":[{"t":"Illusory Conjunction Tasks (Treisman & Schmidt, 1982) erzeugen Wahrnehmungstäuschungen gerade dann, wenn die Aufmerksamkeit besonders eng fokussiert ist.","c":false,"fb":"Umgekehrt: Sie führen zur Täuschung, wenn die Aufmerksamkeit <b>nicht</b> fokussiert ist und zentrale Hinweisreize unverarbeitet bleiben."},{"t":"Die niedrigere Fehlerrate unter Beobachtung wird auf eine breitere, eher periphere Aufmerksamkeit zurückgeführt.","c":false,"fb":"Erklärt wird sie durch die erhöhte <b>selektive</b> Aufmerksamkeit auf die zentralen Aspekte der Aufgabe; gerade die breite, periphere Aufmerksamkeit erzeugt die Täuschung."},{"t":"Versuchspersonen, die die Aufgabe in Anwesenheit anderer bearbeiteten, nahmen seltener fälschlich ein Dollarzeichen wahr.","c":true,"fb":"Präsentiert wurden häufig nur die Bestandteile senkrechter Strich und S nebeneinander — wer sie zum Dollarzeichen verband, hatte breit statt selektiv wahrgenommen."},{"t":"Muller et al. untersuchten mit dieser Aufgabe die soziale Hemmung, weil die Anwesenheit anderer die Fehlerrate erhöhte.","c":false,"fb":"Die Fehlerrate sank unter Beobachtung. Die Untersuchung stützt damit die Distraction-Conflict-Theory als Erklärung der sozialen Erleichterung."}],"concept":{"title":"Illusory Conjunction Tasks und der Aufmerksamkeitskonflikt","points":["<b>Illusory Conjunction Tasks</b> (Treisman & Schmidt, 1982): Aufgaben, die zur Wahrnehmungstäuschung führen, wenn die Aufmerksamkeit der Person nicht fokussiert ist.","<b>Mechanismus</b>: Die fehlende Verarbeitung zentraler Hinweisreize führt dazu, dass zwei kurz präsentierte, unabhängige Objekte fälschlich zu einem kombiniert beziehungsweise als ein Objekt erinnert werden.","<b>Beispiele</b>: Ein senkrechter Strich und ein S nebeneinander werden als Dollarzeichen erinnert; ein blauer Kreis und ein rotes Quadrat werden zum roten Kreis.","<b>Muller et al. (2004)</b>: Versuchspersonen, die unter Anwesenheit anderer arbeiteten, fielen der visuellen Täuschung seltener zum Opfer.","<b>Deutung</b>: Die Beobachtung erhöht die selektive Aufmerksamkeit auf zentrale Aufgabenaspekte — genau der Mechanismus, den die Distraction-Conflict-Theory (Baron, 1986) für die soziale Erleichterung annimmt."]}},{"id":"k7-b8418512b6","kap":7,"sec":"7.4 Intergruppenprozesse","stem":"Welche Aussagen zu Ingroup, Outgroup und der Theorie der Sozialen Identität (Tajfel & Turner, 2004) treffen zu?","opts":[{"t":"Als Ingroup gilt jene soziale Kategorie oder Gruppe, der man sich zugehörig fühlt und als deren Mitglied man sich identifiziert.","c":true,"fb":"Die Outgroup ist demgegenüber die Fremdgruppe, zu der kein Zugehörigkeitsgefühl besteht."},{"t":"Ob die eigene soziale Identität als positiv erlebt wird, hängt davon ab, wie die Ingroup im Vergleich mit relevanten Outgroups abschneidet.","c":true,"fb":"Der Vergleich ist der entscheidende Mechanismus — deshalb wirkt sich auch eine Abwertung der Outgroup auf die eigene Identität aus."},{"t":"Einer fremden Gruppe zu schaden, kann eine plausible Strategie sein, um die eigene soziale Identität und Selbsteinschätzung aufzuwerten.","c":true,"fb":"Nicht die absolute Lage der eigenen Gruppe zählt, sondern ihr relativer Stand im Vergleich."},{"t":"Gruppenzugehörigkeiten können auch konstruktive Folgen haben; van Bavel et al. (2020) fanden einen Zusammenhang zwischen nationaler Identifikation und der Unterstützung von Maßnahmen gegen die Ausbreitung von Covid-19.","c":true,"fb":"Der Befund zeigt, dass die Folgen von Gruppenzugehörigkeit sowohl destruktiv als auch konstruktiv ausfallen können."}],"concept":{"title":"Ingroup, Outgroup und soziale Identität","points":["<b>Ingroup</b>: soziale Kategorie oder Gruppe, der man sich zugehörig fühlt und als deren Mitglied man sich identifiziert. <b>Outgroup</b>: Fremdgruppe, zu der kein Zugehörigkeitsgefühl besteht.","<b>Theorie der Sozialen Identität</b> (Tajfel & Turner, 2004): Menschen streben ein positives Selbstbild an; Gruppenzugehörigkeiten helfen, eine positive soziale Identität zu erfahren.","<b>Vergleichsmechanismus</b>: Die soziale Identität wird als positiv erlebt, wenn die eigene Gruppe im Vergleich mit relevanten Outgroups gut abschneidet — daher kann die Schädigung der Outgroup funktional sein.","<b>Funktionen von Gruppenzugehörigkeit</b>: Sinn- und Identitätsstiftung, Orientierung in der Welt, Geborgenheit, Befriedigung des Bedürfnisses nach sozialer Eingebundenheit und Kontakt, Grundlage von Selbstdefinition und Selbstwert.","<b>Konstruktive Seite</b>: van Bavel et al. (2020) — die Identifikation mit der eigenen Nation stand im Zusammenhang mit der Unterstützung von Maßnahmen gegen Covid-19 und dem eigenen Gesundheitsverhalten."]}},{"id":"k7-5a66219e1b","kap":7,"sec":"7.3.5 Bewusste soziale Einflussnahme","stem":"Welche Aussage zum Prinzip der Knappheit und zur Reaktanz trifft zu?","opts":[{"t":"Ditto und Jemmott (1989) zeigten, dass seltene Güter gemäßigter beurteilt werden, weil Unsicherheit über ihren Wert besteht.","c":false,"fb":"Knappheit bewirkt eine <b>extremere</b> Beurteilung: Tendenziell positive Eigenschaften werden bei seltenen Gütern als noch positiver bewertet."},{"t":"Reaktanz bezeichnet einen aversiven Zustand infolge wahrgenommener Freiheitseinschränkung; zu ihrer Reduktion wird genau entgegen der Einschränkung gehandelt (Brehm, 1966).","c":true,"fb":"Deshalb steigert schwere Erreichbarkeit die Attraktivität eines Guts zusätzlich — die eingeschränkte Freiheit soll wiederhergestellt werden."},{"t":"Bei Zellinger et al. (1975) sank der Wunsch, ein Buch zu erwerben, deutlich, sobald es als altersbeschränkt gekennzeichnet war.","c":false,"fb":"Der Wunsch war deutlich <b>erhöht</b> — ein klassischer Reaktanzbefund."},{"t":"Das Kontrastprinzip besagt, dass ein Gut allein aufgrund seiner geringen Verfügbarkeit als wertvoller gilt.","c":false,"fb":"Das ist das Prinzip der Knappheit. Das Kontrastprinzip betrifft die Bewertung in Abhängigkeit von einem Vergleichsstandard — etwa ein mittelmäßiges Produkt neben schlechteren."}],"concept":{"title":"Knappheit, Reaktanz, soziale Bewährtheit und Kontrastprinzip","points":["<b>Prinzip der Knappheit</b> — „Was rar ist, muss viel wert sein“: begrenzte Verfügbarkeit oder befristete Angebote erzeugen den Impuls, sofort zuzugreifen, unabhängig vom tatsächlichen Bedarf.","<b>Zwei Wirkwege der Knappheit</b>: extremere Beurteilung seltener Güter (Ditto & Jemmott, 1989) und das Auslösen von Reaktanz.","<b>Reaktanz</b> (Brehm, 1966): aversiver Zustand bei wahrgenommener Freiheitseinschränkung; gehandelt wird entgegen der Einschränkung, wodurch die Attraktivität des Guts steigt. Zellinger et al. (1975): Eine Altersbeschränkung erhöhte den Kaufwunsch deutlich.","<b>Prinzip sozialer Bewährtheit</b> — „Was alle tun, muss gut sein“: Friedman und Fireworker (1977) — als „fantastisch“ beschriebener Wein wurde besser bewertet und teurer eingeschätzt.","<b>Kontrastprinzip</b> — „Im Vergleich zu …“: Bewertung anhand eines Vergleichsstandards; ein mittelmäßiges Produkt wirkt neben schlechteren attraktiv, und Kund:innen empfinden diese Beratung fälschlich als besonders fair."]}},{"id":"k7-a55be5b11a","kap":7,"sec":"7.4.3 Stereotype, Vorurteile und Diskriminierung","stem":"Welche Aussagen zu selbsterfüllenden Prophezeiungen und zur Bedrohung durch Stereotype treffen zu?","opts":[{"t":"Nach Banks (1988) kann allein die Existenz eines Stereotyps zu seiner Bewahrheitung beitragen, etwa über geringere schulische Förderung.","c":true,"fb":"Die verringerte Förderung mindert die Fähigkeiten tatsächlich, wodurch das ursprüngliche Stereotyp bestätigt erscheint — eine sich selbstverstärkende Schleife."},{"t":"Bei Spencer, Steele und Quinn (1999) fiel die Leistung der Frauen nur in der Experimentalgruppe schlechter aus als die der Männer; in der Kontrollgruppe zeigten sich keine Geschlechtsunterschiede.","c":true,"fb":"Der Experimentalgruppe war zusätzlich mitgeteilt worden, es gebe Kontroversen darüber, ob Geschlechtsunterschiede bei mathematischen Aufgaben bestehen."},{"t":"Bei Steele und Aronson (1995) schnitt jene Gruppe Schwarzer Personen am schlechtesten ab, die annahm, es würden ihre intellektuellen Fähigkeiten gemessen.","c":true,"fb":"Verglichen wurde mit derselben Aufgabe als Problemlöseaufgabe sowie mit einer Gruppe Weißer Personen."},{"t":"Johns, Schmader und Martens (2005) konnten den Effekt deutlich verringern oder sogar aufheben, indem sie die Frauen vorab über Stereotype Threat aufklärten.","c":true,"fb":"Die kognitiven Effekte des Stereotyps lassen sich damit auch auf kognitivem Weg wieder auflösen."}],"concept":{"title":"Selbsterfüllende Prophezeiung und Bedrohung durch Stereotype","points":["<b>Selbsterfüllende Prophezeiung</b> (Banks, 1988): Das Stereotyp erzeugt eine Benachteiligung, die es anschließend bestätigt — Mädchen werden in Mathematik weniger gefördert, entwickeln dadurch tatsächlich geringere Fähigkeiten und bestätigen so das Stereotyp.","<b>Erwartungshaltungen von Lehrpersonen</b> wirken sich besonders auf die Leistung schwacher Schüler:innen aus (Madon, Jussim & Eccles, 1997).","<b>Bedrohung durch Stereotype</b> (Stereotype Threat): Der Hinweis auf ein leistungsbezogenes Gruppenstereotyp löst ein hohes Bedrohungslevel und die Angst aus, das Stereotyp zu erfüllen — und mindert dadurch die Leistung.","<b>Spencer, Steele & Quinn (1999)</b>: Mathematiktest bei ausbalancierter tatsächlicher Leistung; nur in der Experimentalgruppe mit Hinweis auf Geschlechtsunterschiede schnitten Frauen schlechter ab.","<b>Steele & Aronson (1995)</b>: Wurde derselbe Test als psychodiagnostisches Instrument zur Ermittlung intellektueller Fähigkeit angekündigt, schnitten Schwarze Personen am schlechtesten von drei Gruppen ab.","<b>Auflösbarkeit</b>: Johns, Schmader & Martens (2005) — die vorherige Aufklärung über Stereotype Threat verringerte oder beseitigte den Effekt."]}},{"id":"k7-b3c2af04e5","kap":7,"sec":"7.1 Was ist Sozialpsychologie?","stem":"Welche Aussage über Gegenstand und Vorgehen der Sozialpsychologie trifft zu?","opts":[{"t":"Im Unterschied zur Persönlichkeitspsychologie misst die Sozialpsychologie situativen Faktoren eine nachrangige Bedeutung bei.","c":false,"fb":"Es verhält sich umgekehrt: Gerade situative Faktoren werden als sehr wichtig erachtet, weil sie das menschliche Verhalten beeinflussen."},{"t":"Sozialpsychologische Experimente arbeiten typischerweise so, dass eine Persönlichkeitseigenschaft manipuliert und die daraus folgende Veränderung der Situation beobachtet wird.","c":false,"fb":"Manipuliert wird eine situative Variable; beobachtet werden die Veränderungen des Verhaltens."},{"t":"Intergruppenprozesse bezeichnen jene Prozesse, die innerhalb einer Gruppe ablaufen.","c":false,"fb":"Innerhalb einer Gruppe laufen Intragruppenprozesse ab; inter meint zwischen Gruppen."},{"t":"Für den sozialen Einfluss spielt es keine wesentliche Rolle, ob die anderen Personen direkt anwesend sind.","c":true,"fb":"Auch Gedanken wie „Was würden meine Eltern davon halten?“ belegen den Einfluss abwesender Personen."}],"concept":{"title":"Gegenstand der Sozialpsychologie","points":["<b>Gegenstand</b>: der soziale Einfluss anderer Menschen — also die Wirkung anderer auf das eigene Erleben, Fühlen, Denken und Verhalten. Diesem Einfluss ist in der Regel schwer zu entkommen.","<b>Anwesenheit ist nicht entscheidend</b>: Auch abwesende Personen wirken, etwa über Gedanken wie „Wie würden meine Freunde über mich denken?“.","<b>Situationsbetonung</b>: Anders als die Persönlichkeitspsychologie (Kapitel 8) erachtet die Sozialpsychologie situative Faktoren als sehr wichtig. Viele Experimente manipulieren daher eine situative Variable und beobachten die Verhaltensänderung.","<b>Aufbau des Kapitels</b>: soziale Kognition (7.2), sozialer Einfluss und Intragruppenprozesse (7.3), Intergruppenprozesse (7.4), prosoziales Verhalten (7.5).","<b>Intra vs. inter</b>: Intragruppenprozesse laufen innerhalb einer Gruppe ab, Intergruppenprozesse zwischen Gruppen."]}},{"id":"k8-4b8c485f63","kap":8,"sec":"8.2.2 Psychodynamische Theorie der Persönlichkeit","stem":"Welche Aussagen zum Drei-Instanzen-Modell nach Freud treffen zu?","opts":[{"t":"Das Es agiert nach dem Lustprinzip: Angestrebt wird die sofortige Befriedigung der Bedürfnisse, ohne auf andere Faktoren oder Konsequenzen zu achten.","c":true,"fb":"Zentral sind dabei die Grundbedürfnisse Schlaf und Nahrungsaufnahme, der Überlebenstrieb, der Sexual- und Fortpflanzungstrieb (Libido) sowie der Aggressionstrieb (Thanatos)."},{"t":"Das Ich stellt jenen Teil der Persönlichkeitsstruktur dar, der größtenteils bewusst ist, aber auch unbewusste Elemente hat.","c":true,"fb":"Damit ist das Ich die am stärksten bewusstseinsnahe der drei Instanzen – Es und Über-Ich sind überwiegend unbewusst."},{"t":"Das Über-Ich handelt nach dem Realitätsprinzip und versucht, Triebe und Wertevorstellungen zusammenzubringen.","c":false,"fb":"Realitätsprinzip und Vermittlerrolle gehören zum Ich. Das Über-Ich handelt nach dem Moralitätsprinzip und repräsentiert den Sinn für Moral, Werte- und Normvorstellungen."},{"t":"Das Über-Ich ist nach Freud vollständig bewusst und deshalb jederzeit willentlich kontrollierbar.","c":false,"fb":"Das Über-Ich ist – ähnlich wie das Es – zum überwiegenden Teil unbewusst; es kann aber ins Bewusstsein gebracht werden."}],"concept":{"title":"Die drei Instanzen und ihre Prinzipien","points":["Es → Lustprinzip: schnellstmögliche Befriedigung grundlegender Bedürfnisse und Triebe. Primitivster Teil, unbewusst.","Ich → Realitätsprinzip: vermittelt zwischen Trieben (Es) und moralischen Idealen (Über-Ich). Größtenteils bewusst.","Über-Ich → Moralitätsprinzip: Sinn für Moral, verinnerlichte Werte- und Normvorstellungen, „Gewissen“. Überwiegend unbewusst.","Eisbergmodell: der kleinere Teil der Prozesse ist bewusst, der größere läuft unbewusst ab."]}},{"id":"k8-8c83abbc49","kap":8,"sec":"8.3.1 Persönlichkeitsfragebögen","stem":"Welche Aussagen zum Minnesota Multiphasic Personality Inventory (MMPI-2) treffen zu?","opts":[{"t":"Die Bearbeitung der 567 dichotomen Items nimmt etwa eine Stunde in Anspruch.","c":true,"fb":"Dichotom heißt: für die Beantwortung stehen zwei Kategorien zur Verfügung – beim MMPI „richtig“ oder „falsch“ im Sinne von zutreffend/nicht zutreffend."},{"t":"Das Verfahren umfasst 240 Items, die auf einer fünfstufigen Antwortskala beantwortet werden.","c":false,"fb":"240 Items und ein fünfstufiges Antwortformat kennzeichnen das NEO-PI-R, nicht das MMPI-2."},{"t":"Die erste Fassung wurde 1970 von Fahrenberg, Hampel und Selg herausgegeben.","c":false,"fb":"Die erste Fassung des MMPI stammt von 1942 und geht auf Starke Hathaway und Charnley McKinley zurück. Fahrenberg, Hampel und Selg gaben das Freiburger Persönlichkeitsinventar (erste Auflage 1970) heraus."},{"t":"Das MMPI-2 umfasst zehn Validitätsskalen sowie drei klinische Skalen.","c":false,"fb":"Die Zahlen sind vertauscht: zehn klinische Skalen und drei Validitätsskalen – dazu fünfzehn Inhaltsskalen und reine Forschungs-Zusatzskalen."}],"concept":{"title":"MMPI-2 im Überblick","points":["Erstfassung 1942 von Hathaway & McKinley; deutschsprachig aktuell als MMPI-2.","Skalen: 10 klinische (z. B. Hypochondrie, Depression, Schizophrenie, soziale Introversion), 15 Inhaltsskalen (z. B. Zwanghaftigkeit, Zynismus), 3 Validitätsskalen (z. B. Lügen-Skala) plus Zusatzskalen nur für Forschungszwecke.","567 dichotome Items, Bearbeitungsdauer ca. 1 Stunde, als Einzel- oder Gruppentestung möglich.","Ziel: ausführliche Beschreibung wichtiger Persönlichkeitseigenschaften und psychischer Störungen; zusätzlich Anspruch auf eignungsdiagnostische Anwendbarkeit."]}},{"id":"k8-dedb6767d6","kap":8,"sec":"8.2.1 Trait-Theorien: Galen und Eysenck","stem":"Welche Aussagen zur Temperamentenlehre und zu Eysencks Persönlichkeitsdimensionen treffen zu?","opts":[{"t":"Der Phlegmatiker ist nach dieser Zuordnung labil und introvertiert.","c":false,"fb":"Labil und introvertiert ist der Melancholiker. Der Phlegmatiker ist stabil und introvertiert."},{"t":"Der Choleriker ist labil und extravertiert.","c":true,"fb":"Beim Choleriker steht nach Galen die gelbe Gallenflüssigkeit im Vordergrund."},{"t":"Eysenck reduzierte Persönlichkeit im Wesentlichen auf die Interaktion der drei Dimensionen Extraversion, Stabilität und Psychotizismus.","c":false,"fb":"Es sind zwei Dimensionen: Extraversion vs. Introversion und Stabilität vs. Labilität."},{"t":"Galens Temperamentenlehre gründet auf der Vier-Säfte-Lehre nach Aristoteles.","c":false,"fb":"Die Vier-Säfte-Lehre geht auf Hippokrates zurück; Galen baute im 2. Jahrhundert n. Chr. darauf auf."}],"concept":{"title":"Temperamente im Koordinatenkreuz Eysencks","points":["Phlegmatiker – Schleim – stabil + introvertiert (beherrscht, träge, zaghaft, friedlich).","Melancholiker – schwarze Galle – labil + introvertiert.","Sanguiniker – Blut – stabil + extravertiert (optimistisch, kontaktfreudig, spontan, gesellig).","Choleriker – gelbe Galle – labil + extravertiert.","Eysenck (1916–1997) postulierte sein Modell auf Basis von Zwillingsstudien; Persönlichkeit gilt sowohl bei Galen als auch bei Eysenck als stabil und dauerhaft."]}},{"id":"k8-f5d03f434f","kap":8,"sec":"8.3 Persönlichkeitsdiagnostik: Datenquellen nach Cattell","stem":"Welche Aussagen zu den drei Informationsquellen nach Cattell treffen zu?","opts":[{"t":"Q-Daten umfassen Selbsteinschätzungen und Selbstberichte einer Person, zum Beispiel über die eigenen Gefühle und Einstellungen.","c":true,"fb":"„Questionnaire data“ – die in Forschung und Praxis am häufigsten genutzte Quelle."},{"t":"L-Daten werden auf Basis der Ergebnisse objektiver Tests gewonnen und basieren auf Verhaltensleistung.","c":false,"fb":"Das beschreibt die T-Daten („Test data“). L-Daten („Life-record data“) stammen aus der Biographie und dem typischen Alltagsverhalten einer Person."},{"t":"Standardisierte Persönlichkeitsfragebögen und Interviews sind beide der Gruppe der Q-Daten zuzuordnen.","c":true,"fb":"Beide Verfahrensgruppen beruhen auf Selbstberichten der befragten Person."},{"t":"Diese drei Informationsquellen wurden von Paul Costa und Robert McCrae beschrieben.","c":false,"fb":"Sie gehen auf Raymond Cattell (1946) zurück. Costa und McCrae stehen für das NEO-Persönlichkeitsinventar."}],"concept":{"title":"L-, Q- und T-Daten","points":["L-Daten (Life-record data): Biographie und typisches Alltagsverhalten → Verhaltensbeobachtung und -beurteilung.","Q-Daten (Questionnaire data): Selbsteinschätzungen und Selbstberichte → Persönlichkeitsfragebögen und Interviews.","T-Daten (Test data): Ergebnisse objektiver Tests, basierend auf Verhaltensleistung → Objektive Persönlichkeitstests.","Projektive Verfahren gelten als eher umstrittene Gruppe und haben heute geringe praktische Bedeutung."]}},{"id":"k8-767a2aa74a","kap":8,"sec":"8.2.4 Soziale Lerntheorie nach Rotter","stem":"Welche Aussagen zur sozialen Lerntheorie nach Rotter treffen zu?","opts":[{"t":"Externale Kontrollüberzeugungen beschreiben das Ausmaß, in dem eine Person Ereignisse als Konsequenz ihres eigenen Verhaltens erlebt.","c":false,"fb":"Das ist die Definition der internalen Kontrollüberzeugung. External heißt: Ereignisse werden auf andere Personen, Schicksal oder Zufall zurückgeführt."},{"t":"Der Verstärkungswert bezeichnet die Einschätzung der Wahrscheinlichkeit, mit der Verhalten X in Situation S zu Verstärker V führt.","c":false,"fb":"Das ist die Erwartung (E). Der Verstärkungswert (VW) ist die individuelle Einschätzung, wie attraktiv der Verstärker in der Situation ist."},{"t":"Das Verhaltenspotential beschreibt die Wahrscheinlichkeit des Auftretens eines bestimmten Verhaltens in einer bestimmten Situation, die eine bestimmte Verstärkung erwarten lässt.","c":true,"fb":"Es hängt von der Erwartung und vom Verstärkungswert ab."},{"t":"Rotters Verhaltensgleichung bestimmt den Verstärkungswert als Funktion aus Erwartung und Verhaltenspotential.","c":false,"fb":"Die Gleichung ist umgestellt worden. Korrekt: VP = f(E × VW) – das Verhaltenspotential ist die Funktion aus Erwartung und Verstärkungswert."}],"concept":{"title":"Rotters Verhaltensgleichung und Kontrollüberzeugungen","points":["VPxsv = f(Exsv × VWsv).","VP = Verhaltenspotenzial: Wahrscheinlichkeit, dass Verhalten X in Situation S mit Aussicht auf Verstärker V auftritt.","E = Erwartung: Einschätzung der Wahrscheinlichkeit, dass Verhalten X in Situation S zu Verstärker V führt.","VW = Verstärkungswert: wie attraktiv Verstärker V in Situation S für die Person ist.","Kontrollüberzeugungen (locus of control of reinforcement): internal = Ereignis als Folge eigenen Verhaltens; external = Ereignis als Folge anderer, des Schicksals oder des Zufalls."]}},{"id":"k8-c998021b77","kap":8,"sec":"8.2.3 Humanistische Theorien: Carl Rogers","stem":"Welche Aussagen zu den von Rogers geprägten Grundvoraussetzungen treffen zu?","opts":[{"t":"Kongruenz bedeutet Echtheit im therapeutischen Setting: Die Therapeutin bzw. der Therapeut sollte dem Individuum so gegenübertreten, wie sie oder er tatsächlich ist.","c":true,"fb":"Weder ein Vorbild darzustellen noch sich hinter einer Fassade oder Rolle zu verstecken ist in diesem Sinne indiziert."},{"t":"Bedingungslose Akzeptanz bedeutet, dass jeder Aspekt der Gefühle oder Erfahrungen des Individuums akzeptiert wird – egal ob positiv, negativ, angstbesetzt, freudig oder abnorm.","c":true,"fb":"Dazu gehört, sich fürsorglich um das Gegenüber als eigenständige Person zu kümmern."},{"t":"Empathie meint das Einfühlen in die Welt des Individuums, als wäre es die eigene, ohne aber jemals den Bezug zur Realität zu verlieren.","c":true,"fb":"Dadurch gelingt es, die Gefühle des Individuums besser zu verstehen und zu verbalisieren."},{"t":"Rogers formulierte diese Grundvoraussetzungen im Rahmen seiner Arbeiten zur Hierarchie menschlicher Bedürfnisse.","c":false,"fb":"Die Hierarchie der Bedürfnisse (Bedürfnispyramide) stammt von Abraham Maslow. Rogers stützte seine Theorien auf die therapeutische Arbeit mit Klientinnen und Klienten."}],"concept":{"title":"Rogers’ drei Grundvoraussetzungen (1957)","points":["Kongruenz: Echtheit – keine Fassade, keine Rolle, kein Vorbild-Anspruch.","Bedingungslose Akzeptanz: fürsorgliche Annahme aller Gefühle und Erfahrungen des Gegenübers.","Empathie: Einfühlen in die Welt des Individuums, als wäre sie die eigene, bei erhaltenem Realitätsbezug.","Ziel: die Veränderung der Persönlichkeit des Individuums bestmöglich unterstützen. Carl Rogers (1902–1987) gilt als zentraler Vertreter der humanistischen Schule."]}},{"id":"k8-9b83beb959","kap":8,"sec":"8.1.1 Was ist Persönlichkeit?","stem":"Welche Aussagen zu den Kernmerkmalen des Persönlichkeitsbegriffs treffen zu?","opts":[{"t":"Der Persönlichkeitsbegriff bezieht sich auf nicht pathologische Unterschiede zwischen Menschen.","c":true,"fb":"Pathologische Ausprägungen ordnet man eher der Klinischen Psychologie zu."},{"t":"Die geforderte Stabilität zeigt sich in zwei Aspekten: in temporaler (zeitlicher) Stabilität und in transsituativer Konsistenz.","c":true,"fb":"Also Stabilität über die Lebenszeit und Stabilität über Situationen hinweg."},{"t":"Pathologische Ausprägungen von Persönlichkeitseigenschaften bilden den Kernbereich der Persönlichkeitspsychologie.","c":false,"fb":"Richtungsumkehr: Gerade solche Ausprägungen würde man eher der Klinischen Psychologie zuordnen, nicht der Persönlichkeitspsychologie."},{"t":"Zu den Kernmerkmalen zählt die Referenzialität zu einer Vergleichspopulation.","c":true,"fb":"Die Ausprägungen müssen zwischen Menschen variieren und zu den Ausprägungen von Referenzpopulationen in Bezug gesetzt werden können."}],"concept":{"title":"Kernmerkmale des Persönlichkeitsbegriffs","points":["(a) nicht pathologische Unterschiede zwischen Menschen.","(b) Stabilität von Persönlichkeitseigenschaften – temporale (zeitliche) Stabilität und transsituative Konsistenz.","(c) Referenzialität zu einer Vergleichspopulation.","Es gibt nicht die eine richtige Definition: Allport (1937) betont die dynamische Anpassung an die Umwelt, Herzberg & Roth (2014) die zeitliche Stabilität."]}},{"id":"k8-568f874933","kap":8,"sec":"8.3.4 Objektive Persönlichkeitstests: der IAT","stem":"Welche Aussagen zum Impliziten Assoziationstest (IAT) treffen zu?","opts":[{"t":"Die Grundannahme lautet, dass die Sortieraufgabe einfacher ist – also kürzere Reaktionszeiten erfordert –, wenn stark miteinander assoziierte Konzepte derselben Taste zugeordnet sind.","c":true,"fb":"Zum Beispiel „Ich“ und „Glück“ gegenüber „Ich“ und „Qual“."},{"t":"Beim IAT handelt es sich um einen standardisierten Test wie das MMPI, der inhaltlich stets in identischer Form eingesetzt wird.","c":false,"fb":"Der IAT ist kein standardisierter Test, sondern eine Methodik, die für unterschiedliche Bereiche inhaltlich angepasst werden kann."},{"t":"Die gezeigten Stimuli werden ausschließlich einer Objektdimension zugeordnet; eine Attributdimension ist nicht vorgesehen.","c":false,"fb":"Es gibt beide: die Objektdimension (z. B. Ich vs. Nicht-Ich) und die Attributdimension (z. B. positiv vs. negativ). Ihre Variation ist das Kernprinzip des Verfahrens."},{"t":"Implizite Assoziationstests weisen insgesamt unzureichende Reliabilitätswerte sowie einen eher geringen Zusammenhang mit Fragebogenmaßen auf.","c":true,"fb":"Ein zentraler Kritikpunkt trotz der Vorteile bei der Verfälschungssicherheit."}],"concept":{"title":"IAT (Greenwald, McGhee & Schwartz, 1998)","points":["Computergestützte Diskriminationsaufgaben: Stimuli in der Bildschirmmitte werden per Tastendruck möglichst rasch und fehlerfrei einer Seite zugeordnet.","Zwei Dimensionen: Objektdimension (Ich vs. Nicht-Ich) und Attributdimension (positiv vs. negativ).","Über die Reaktionszeiten werden indirekt Rückschlüsse auf Einstellungen gezogen – Einsatz bei Einstellungen, Stereotypen, Vorurteilen und Selbstkonzepten.","Vorteil: schwer verfälschbar, da der Messgegenstand nicht ersichtlich ist. Nachteil: unzureichende Reliabilität, geringer Zusammenhang mit subjektiven Verfahren."]}},{"id":"k8-5ca7a734d9","kap":8,"sec":"8.2.4 Belohnungsaufschub nach Mischel","stem":"Welche Aussagen zu den Experimenten zum Belohnungsaufschub treffen zu?","opts":[{"t":"Die Versuchsleitung verließ den Raum für circa 45 Minuten, sodass die Kinder mit der Süßigkeit allein waren.","c":false,"fb":"Es waren circa 15 Minuten."},{"t":"Kinder mit höherer Selbstkontrolle wurden zehn Jahre später von ihren Lehrkräften als sozial weniger kompetent eingeschätzt.","c":false,"fb":"Doppelt verdreht: Die Einschätzung erfolgte durch die Eltern, und die Kinder galten als akademisch und sozial kompetenter als ihre Altersgenossen."},{"t":"Der „Marshmallow-Test“ geht auf Albert Bandura zurück, der damit das Lernen am Modell untersuchte.","c":false,"fb":"Die Experimente stammen von Walter Mischel und Kolleg:innen. Bandura untersuchte das Modelllernen in den Bobo-Doll-Experimenten."},{"t":"Untersucht wurde die Fähigkeit zum Belohnungsaufschub bei Kindern im Alter von circa 3,5 bis 6 Jahren.","c":true,"fb":"Sie hatten die Wahl zwischen einer kleinen, sofort verfügbaren Verstärkung und der doppelten Menge nach einer Wartezeit."}],"concept":{"title":"Delay of gratification (Mischel)","points":["Definition: Tendenz, auf eine sofort verfügbare Verstärkung zugunsten einer höherwertigen, zeitlich versetzten Verstärkung zu verzichten.","Setting: Kinder von ca. 3,5 bis 6 Jahren; Versuchsleitung verlässt den Raum für ca. 15 Minuten; gemessen wird die Widerstandsdauer.","Langzeitbefund: Kinder mit höherer Selbstkontrolle wurden zehn Jahre später von ihren Eltern als akademisch und sozial kompetenter eingeschätzt, zeigten bessere schulische Leistungen und besseren Umgang mit Frustration und Stress.","Beobachtete Strategien: Augen bedecken, mit Händen und Füßen spielen, singen oder mit sich selbst sprechen."]}},{"id":"k8-52249b7809","kap":8,"sec":"8.2.1 Big-Five-Modell und HEXACO-Modell","stem":"Welche Aussagen zum Big-Five- und zum HEXACO-Modell treffen zu?","opts":[{"t":"Das Big-Five-Modell basiert auf einem lexikalischen Ansatz und ging von circa 18.000 eigenschaftsbezogenen Begriffen aus.","c":true,"fb":"Aus diesen wurden fünf große, basale Faktoren beziehungsweise Dimensionen der Persönlichkeit identifiziert."},{"t":"Die Beschreibung der Persönlichkeitsstruktur erfolgt dimensional: Eine Person wird nicht einem Typ zugeteilt, sondern kann auf jeder der fünf Dimensionen verschieden stark ausgeprägt sein.","c":true,"fb":"Das unterscheidet den Ansatz von Typologien wie jener Galens."},{"t":"Das HEXACO-Modell postuliert sechs große Faktoren, darunter Ehrlichkeit-Demut (Honesty-Humility).","c":true,"fb":"Es stellt das Big-Five-Modell nicht grundsätzlich in Frage, da sich beide inhaltlich in großen Bereichen überschneiden."},{"t":"Die Fünf-Faktoren-Struktur konnte in verschiedenen Ländern und Kontinenten, Kulturen sowie in Gruppen unterschiedlichen Bildungsgrades in ähnlicher Weise aufgezeigt werden.","c":true,"fb":"Deshalb wird sie als „den Menschen inhärente Persönlichkeitsstruktur“ angenommen."}],"concept":{"title":"Big Five (OCEAN) und HEXACO","points":["Big Five: Offenheit für Erfahrungen, Gewissenhaftigkeit, Extraversion, Verträglichkeit, Neurotizismus – Eselsbrücke OCEAN.","Grundlage: lexikalischer Ansatz aus ca. 18.000 eigenschaftsbezogenen Begriffen (Goldberg, 1990; McCrae & Costa, 2008); aktuell dominantestes Modell der Forschung.","Erhebung vor allem über Fragebogenverfahren mit Items auf mehrstufiger Skala; NEO-PI von Costa und McCrae (1985) war eines der ersten Verfahren für Erwachsene.","HEXACO (Ashton et al., 2004): sechs Faktoren – Ehrlichkeit-Demut, Emotionalität, Extraversion, Verträglichkeit, Gewissenhaftigkeit, Offenheit für Erfahrungen."]}},{"id":"k8-60e31f0b74","kap":8,"sec":"8.1.2 Allgemeine vs. Differentielle vs. Persönlichkeitspsychologie","stem":"Welche Aussagen zu den Forschungsrichtungen treffen zu?","opts":[{"t":"Die Allgemeine Psychologie bezieht sich auf Phänomene oder Gesetzmäßigkeiten, die für möglichst alle Menschen gültig sind.","c":true,"fb":"Beispielfrage: „Zeigen Menschen aggressives Verhalten, wenn sie frustriert sind?“"},{"t":"Die Differentielle Psychologie stellt das Individuum mit seinen persönlichen Charakteristika in den Fokus und vergleicht es mit einer altersmäßig entsprechenden Referenzgruppe.","c":false,"fb":"Das ist die Perspektive der Persönlichkeitspsychologie. Die Differentielle Psychologie befasst sich mit Unterschieden zwischen Menschen bzw. Menschengruppen."},{"t":"Differentielle Psychologie und Persönlichkeitspsychologie sind klar voneinander trennbar und werden deshalb im Studium als getrennte Fächer geführt.","c":false,"fb":"Richtungsumkehr: Wegen der sehr großen Überschneidungsbereiche spricht man im Studium vom gemeinsamen Fach Differentielle Psychologie und Persönlichkeitspsychologie."},{"t":"„Reagieren Menschen, die über hoch ausgeprägte emotionale Intelligenz verfügen, weniger aggressiv auf Frustration als andere?“ ist eine typische Fragestellung der Differentiellen Psychologie.","c":true,"fb":"Sie zielt auf Phänomene, die für manche Menschengruppen gelten, nicht aber für alle."}],"concept":{"title":"Drei Blickwinkel auf menschliches Verhalten","points":["Allgemeine Psychologie – allgemeingültige Aussagen: das Verhalten aller Menschen.","Differentielle Psychologie – Unterschiedlichkeit: das Verhalten mancher Menschen bzw. Gruppen.","Persönlichkeitspsychologie – Individualität: das Verhalten des Einzelnen, verglichen mit einer Referenzgruppe.","Zwei übergeordnete Perspektiven auf Verhaltensunterschiede: Persönlichkeitsunterschiede (Differentielle/Persönlichkeitspsychologie) vs. soziale Situationen und Interaktionen (Sozialpsychologie)."]}},{"id":"k8-8964f3b74a","kap":8,"sec":"8.3.2 Psychologisch-diagnostisches Interview","stem":"Welche Aussagen zum Strukturierungsgrad diagnostischer Interviews treffen zu?","opts":[{"t":"Beim teilstrukturierten Interview liegt ein Leitfaden mit allen zu stellenden Fragen vor; die Reihenfolge ist flexibel und die befragte Person kann vollkommen frei antworten.","c":true,"fb":"Damit steht es zwischen dem freien und dem vollstrukturierten Interview."},{"t":"Ein Vorteil des vollstrukturierten Interviews ist, dass es wichtige Bereiche erfasst, die in weniger strukturierten Formaten übersehen würden.","c":false,"fb":"Richtungsumkehr: Gerade vollstrukturierte Interviews können wichtige Bereiche übersehen, die in einem weniger strukturierten Format auftauchen würden."},{"t":"Im vollstrukturierten Interview werden die Fragen in festgelegter Reihenfolge gestellt und anhand vorgegebener Antwortkategorien beantwortet.","c":true,"fb":"Freiheit für eigene Ideen oder ein freies Gespräch zu Teilaspekten ist nicht vorgesehen."},{"t":"Je mehr Teile des Interviews vorab festgelegt sind, desto strukturierter ist es und umso objektiver sind in der Regel die Ergebnisse.","c":true,"fb":"Deshalb ist bei vielen Bewerbenden und mehreren Interviewenden ein hoher Strukturierungsgrad besonders wichtig."}],"concept":{"title":"Strukturierungsgrade und ihre Folgen","points":["Unstrukturiert (frei): keine vorab festgelegte Struktur, Frageninhalte oder Auswertung; frei fließende Konversation, aber kaum faire Vergleichbarkeit.","Teilstrukturiert: Leitfaden mit allen Fragen, flexible Reihenfolge, freie Antwortmöglichkeit.","Vollstrukturiert: feste Fragen, feste Reihenfolge, vorgegebene Antwortkategorien – objektiv, aber künstlich und blind für nicht vorgesehene Bereiche.","Qualitätssicherung: Schulungen, Interviewleitfäden & Strukturierung, vorab definierte Eignungsmerkmale, Interviewprotokoll, regelgeleitete Auswertung nach einem einheitlichen Schema."]}},{"id":"k8-9477a1d260","kap":8,"sec":"8.2.3 Humanistische Theorien: Abraham Maslow","stem":"Welche Aussagen zur Bedürfnispyramide nach Maslow treffen zu?","opts":[{"t":"Maslow nahm an, dass alle Bedürfnisse angeboren sind, sich ein Bedürfnis einer höheren Stufe aber erst entwickeln kann, wenn die darunterliegenden befriedigt sind.","c":true,"fb":"Daraus folgt, dass hierarchisch höherliegende Bedürfnisse erst im Laufe des Lebens auftreten."},{"t":"Ein Kritikpunkt an der Bedürfnispyramide ist die dem Modell zugrundeliegende Eindimensionalität.","c":true,"fb":"Wahrscheinlicher erscheint die Annahme verschiedener, miteinander konkurrierender Bedürfnisse aus verschiedenen Ebenen."},{"t":"In kollektivistisch geprägten Kulturen gilt die Selbstverwirklichung als höchstes Ziel der Persönlichkeitsentwicklung, weshalb die Pyramide dort besonders gut zutrifft.","c":false,"fb":"Umgekehrt: In kollektivistisch geprägten Kulturen sei das höchste Ziel, ein wertvolles Mitglied der Gesellschaft zu sein und die eigenen Bedürfnisse denen der Gemeinschaft unterzuordnen. Die Kritik lautet, das Modell treffe nur auf individualistische westliche Kulturen zu."},{"t":"An der Spitze der Pyramide steht das Bedürfnis nach Wertschätzung (Erfolg, Status, Respekt, Anerkennung).","c":false,"fb":"Das ist die Stufe darunter. An höchster Stelle steht das Bedürfnis nach Selbstverwirklichung."}],"concept":{"title":"Bedürfnispyramide nach Maslow (1978)","points":["Von unten nach oben: Physiologische Bedürfnisse (Nahrung, Schlaf, Sexualität, Gesundheit) → Sicherheitsbedürfnisse → Soziale Bedürfnisse (Zugehörigkeit, Liebe, Intimität, Freundschaft, Familie) → Bedürfnis nach Wertschätzung (Erfolg, Status, Respekt, Anerkennung) → Bedürfnis nach Selbstverwirklichung.","Selbstverwirklichung: das psychologische Bedürfnis, sein volles Potenzial auszuschöpfen; die Form der Erfüllung variiert von Mensch zu Mensch.","Personen unterscheiden sich in der Stärke der Bedürfnisse – daraus erklären sich interindividuelle Unterschiede in den verfolgten Handlungszielen.","Kritik: Eindimensionalität sowie kulturelle Einseitigkeit (nur individualistische westliche Kulturen)."]}},{"id":"k8-55c1117c32","kap":8,"sec":"8.2.1 Trait und State","stem":"Welche Aussagen zu Trait, State und zum State-Trait-Modell der Angst treffen zu?","opts":[{"t":"Das State-Trait-Modell der Angst geht auf Spielberger (1972) zurück.","c":true,"fb":"Es unterscheidet zwischen Trait-Angst (Eigenschaftsangst) und State-Angst (Zustandsangst)."},{"t":"Ein State bezeichnet eine zeitlich überdauernde und über Situationen generalisierte Verhaltensbereitschaft.","c":false,"fb":"Das ist die Definition des Traits. Ein State ist ein vorübergehender psychischer Zustand – zeitlich fluktuierend und situationsspezifisch."},{"t":"Die Trait-Angst wird in diesem Modell als vorübergehender, situationsspezifischer Zustand beschrieben.","c":false,"fb":"Umgekehrt: Trait-Angst ist eine relativ stabile Anfälligkeit für Angstreaktionen. Vorübergehend und situationsspezifisch ist die State-Angst."},{"t":"Personen mit hoher Trait-Angst lassen sich von einem Ereignis wie einer wichtigen Prüfung mit hoher Wahrscheinlichkeit weniger verängstigen als Personen mit niedriger Trait-Angst.","c":false,"fb":"Richtungsumkehr: Sie lassen sich deutlich mehr verängstigen."}],"concept":{"title":"Trait vs. State","points":["Trait: Disposition im Sinne einer zeitlich überdauernden, über Situationen generalisierten Verhaltensbereitschaft – z. B. Ängstlichkeit als generelle Tendenz, Angst zu empfinden.","State: vorübergehender psychischer Zustand, zeitlich fluktuierend und situationsspezifisch – z. B. momentane Angst vor einem konkreten Objekt.","State-Trait-Modell der Angst (Spielberger, 1972): Die Prüfungsphase ist Auslöser erhöhter State-Angst; die individuelle Höhe der Reaktion erklärt sich aus der Trait-Angst.","Furcht vs. Ängstlichkeit: Furcht bezieht sich auf ein konkretes Objekt bzw. eine reale Gefahr und ist meist eine rationale Reaktion; Ängstlichkeit hat ohne konkrete Bedrohung mehr irrationale Aspekte und kann länger anhalten."]}},{"id":"k8-5c6308090b","kap":8,"sec":"8.1.1 Disposition und Temperament","stem":"Welche Aussagen zu den Begriffen Disposition und Temperament treffen zu?","opts":[{"t":"Dispositionen sind unmittelbar beobachtbar und lassen sich deshalb direkt erfassen.","c":false,"fb":"Richtungsumkehr: Dispositionen sind nicht direkt beobachtbar, sondern manifestieren sich im Verhalten."},{"t":"Temperament setzt sich aus den drei globalen Komponenten Erregung, Emotionalität und Selbstregulation zusammen.","c":true,"fb":"Es bezeichnet biologisch verankerte individuelle Unterschiede in der Reaktivität auf Stimuli sowie in der Fähigkeit, Erregung und emotionale Reaktionen aktiv zu kontrollieren."},{"t":"Dispositionen weisen eine hohe genetische Verankerung auf, sind eher stabil und schwer zu verändern.","c":true,"fb":"Sie können auch als „Veranlagung“ bezeichnet werden und lassen sich wenig durch die Umwelt beeinflussen."},{"t":"Der Begriff der dispositionalen Negativität wurde von Derryberry und Rothbart (1988) geprägt.","c":false,"fb":"Personenverwechslung: Die dispositionale Negativität wird im Skript Shackman et al. (2016) zugeordnet; Derryberry und Rothbart (1988) stehen für die Temperamentsdefinition."}],"concept":{"title":"Verwandte Begriffe der Persönlichkeitseigenschaft","points":["Disposition: abstrakte, breite und stabile Merkmale mit hoher genetischer Verankerung; nicht direkt beobachtbar, sondern im Verhalten manifest; „Veranlagung“.","Dispositionale Negativität (Shackman et al., 2016): Neigung, häufiger und intensiver negative Gefühle zu erleben – Betroffene sind meist ängstlicher, unsicherer, kritischer und unzufriedener.","Temperament (Derryberry & Rothbart, 1988): drei globale Komponenten – Erregung, Emotionalität, Selbstregulation; biologisch verankerte Unterschiede in Reaktivität und Kontrollfähigkeit.","Diese Begriffe überschneiden sich mit der Persönlichkeitseigenschaft, sind ihr aber nicht gleichzusetzen."]}},{"id":"k8-c4b128fd66","kap":8,"sec":"8.3.5 Projektive Tests","stem":"Welche Aussagen zu projektiven Verfahren treffen zu?","opts":[{"t":"Projektive Verfahren erfüllen die heute üblichen psychometrischen Gütekriterien in der Regel gut und werden deshalb in der Forschung breit eingesetzt.","c":false,"fb":"Die Testgüte projektiver Verfahren wird heute überwiegend negativ beurteilt; Objektivität, Reliabilität und Validität sind nur schwer erzielbar bzw. beurteilbar."},{"t":"Der Rorschach-Test wurde 1921 veröffentlicht und stammt vom Schweizer Psychoanalytiker Hermann Rorschach.","c":true,"fb":"Bewertet wird unter anderem, ob die Deutung von der Gesamtstruktur oder von Details ausgeht, ob Farbe die Deutung beeinflusst und wie originell die Deutung ist."},{"t":"Der Thematische Apperzeptionstest wurde 1943 in der ersten Auflage von Henry Murray publiziert.","c":true,"fb":"Zu mehrdeutigen Bildern sozialer Situationen sollen „dramatische“ Geschichten erfunden werden, um Motive und Zukunftserwartungen offenzulegen."},{"t":"Das Brickenkamp-Testhandbuch unterscheidet bei projektiven Verfahren Form-Deute-Verfahren, verbal-thematische Verfahren sowie zeichnerische und Gestaltungsverfahren.","c":true,"fb":"Beispiele sind der Rorschach-Test, der TAT und der Baum-Test."}],"concept":{"title":"Projektive Verfahren im Überblick","points":["Grundannahme: Bei der Deutung mehrdeutiger Items projizieren Menschen ihre Einstellungen, Wünsche und Motive in die Deutung.","Form-Deute-Verfahren: Rorschach-Test (1921, Hermann Rorschach, 1884–1922) – symmetrische Klecksfiguren; heute kritisch gesehen, in der Forschung kaum noch verwendet, Anwendung erfordert aufwändige Einschulung.","Verbal-thematische Verfahren: TAT (1943, Henry Murray, 1893–1988); verwandt sind Satzergänzungsverfahren.","Zeichnerische und Gestaltungsverfahren: z. B. der Baum-Test.","Stellenwert heute: kaum an psychometrischen Ansprüchen messbar; im klinischen Bereich eher Technik dialogischer Gesprächsführung als Test."]}},{"id":"k8-fbec3cf9a0","kap":8,"sec":"8.3.3 Verhaltensbeobachtung und -beurteilung","stem":"Welche Aussagen zur Verhaltensbeobachtung treffen zu?","opts":[{"t":"Eine Feldbeobachtung findet unter natürlichen Bedingungen statt, etwa im beruflichen oder privaten Umfeld.","c":true,"fb":"Die Laborbeobachtung findet dagegen in einer künstlichen Situation statt, über die die Diagnostikerin bzw. der Diagnostiker volle Kontrolle hat."},{"t":"Von einer teilnehmenden Beobachtung spricht man, wenn die beobachtende Person mit der beobachteten Person interagiert.","c":true,"fb":"Beispiel: ein Rollenspiel im Rahmen eines Assessment-Centers, in das die beobachtende Person aktiv involviert ist."},{"t":"Die indirekte Beobachtung erfolgt asynchron, zum Beispiel auf Basis einer Videoaufzeichnung.","c":true,"fb":"Die direkte Beobachtung erfolgt dagegen in der Situation, also während des Geschehens."},{"t":"Ziel der Verhaltensbeobachtung ist es, über beobachtbare Indikatoren auf nicht direkt beobachtbare Merkmale zu schließen.","c":true,"fb":"Persönlichkeitsmerkmale wie Gewissenhaftigkeit oder Extraversion lassen sich nicht unmittelbar sehen."}],"concept":{"title":"Varianten der Verhaltensbeobachtung","points":["Unsystematisch (frei, ohne festgelegte Kriterien – wie eine Alltagsbeobachtung) vs. systematisch (festgelegte Kriterien für Ort, Zeit, Auswertung).","Labor (künstliche, kontrollierte Situation) vs. Feld (natürliche Bedingungen).","Teilnehmend (Interaktion mit der beobachteten Person) vs. nicht teilnehmend.","Direkt (in der Situation) vs. indirekt (asynchron, z. B. per Video).","Selbstbeobachtung (Selbstreflexion des eigenen Verhaltens) vs. Fremdbeobachtung (durch geschulte Diagnostiker:innen).","Auf die Beobachtung folgt die Verhaltensbeurteilung: Diagnose der Merkmalsausprägung auf Grundlage der Beobachtungsergebnisse."]}},{"id":"k8-21aa11cc1e","kap":8,"sec":"8.2.4 Sozial-kognitive Theorie nach Bandura","stem":"Welche Aussagen zur Selbstwirksamkeitserwartung treffen zu?","opts":[{"t":"Personen mit hoher Selbstwirksamkeitserwartung sehen schwierige Aufgaben eher als zu vermeidende Bedrohungen denn als zu meisternde Herausforderungen.","c":false,"fb":"Richtungsumkehr: Sie sehen schwierige Aufgaben eher als zu meisternde Herausforderungen, stecken sich höhere Ziele und stellen sich Situationen mit der Gewissheit, die Kontrolle zu behalten."},{"t":"Verbale Persuasion – die mündliche Überzeugung durch andere, dass man das Zeug zum Erfolg hat – zählt zu den vier Erfahrungsquellen der Selbstwirksamkeit.","c":true,"fb":"Sie ist eine von vier Quellen, die Bandura annimmt."},{"t":"Der Begriff der Selbstwirksamkeitserwartung wurde von Walter Mischel im Rahmen der „Cognitive social learning person variables“ geprägt.","c":false,"fb":"Personenverwechslung: Der Begriff self-efficacy stammt von Albert Bandura. Mischel postulierte die fünf Persönlichkeitsvariablen."},{"t":"Die Interpretation physiologischer Befindlichkeiten zählt ebenfalls zu den Quellen – physiologische Stressreaktionen sollten positiv, etwa als energetisierend, gedeutet werden.","c":true,"fb":"Andernfalls werden sie als hemmend erlebt."}],"concept":{"title":"Bandura: Kernannahmen und Quellen der Selbstwirksamkeit","points":["Kernannahmen: Verhalten ist größtenteils kognitiv bedingt (Selbstregulation); Lernen besteht vor allem in der Wahrnehmung von Handlungskonsequenzen; Lernen am Modell durch Beobachtung anderer (Bobo-Doll-Experimente).","Vier Erfahrungsquellen der Selbstwirksamkeit: eigene Wirksamkeitserfahrungen durch Überwindung von Hindernissen; stellvertretende Erfahrung sozialer Modelle; verbale Persuasion; Interpretation physiologischer Befindlichkeiten.","Wirkung: hohe Selbstwirksamkeit → schwierige Aufgaben als Herausforderung, höhere Ziele, Kontrollgewissheit."]}},{"id":"k8-c4a3ff6c40","kap":8,"sec":"8.3.1 NEO-PI-R und FPI-R","stem":"Welche Aussagen zu diesen mehrdimensionalen Persönlichkeitstestsystemen treffen zu?","opts":[{"t":"Das FPI-R umfasst zehn Sekundärskalen und zwei Standardskalen.","c":false,"fb":"Die Zahlen sind vertauscht: zehn Standardskalen (z. B. Lebenszufriedenheit, Erregbarkeit, Aggressivität) und zwei Sekundärskalen (Extraversion und Emotionalität im Sinne von Eysenck)."},{"t":"Das NEO-PI-R besteht aus 240 Items und erfasst 30 Persönlichkeitsfacetten, von denen jeweils sechs den fünf Hauptskalen zugeordnet sind.","c":true,"fb":"Die durchschnittliche Bearbeitungsdauer beträgt 35 bis 45 Minuten."},{"t":"Die Items des NEO-PI-R werden in einem dichotomen Antwortformat beantwortet.","c":false,"fb":"Sie werden auf einer fünfstufigen Antwortskala beantwortet (Extrempole: stimme überhaupt nicht zu – stimme voll und ganz zu). Dichotom sind MMPI-2 und FPI-R."},{"t":"Das Freiburger Persönlichkeitsinventar erschien in erster Auflage im Jahr 1942.","c":false,"fb":"Die erste Auflage erschien 1970; seit 2020 liegt es revidiert in 9. Auflage vor. 1942 ist das Erscheinungsjahr der ersten MMPI-Fassung."}],"concept":{"title":"NEO-PI-R und FPI-R im Vergleich","points":["NEO-PI-R (Ostendorf & Angleitner, 2004; nach Costa & McCrae): 240 Items, 30 Facetten, je 6 pro Hauptskala, fünfstufige Antwortskala, 35–45 Minuten; Form S (Selbstbericht) und Form F (Fremdbeurteilung).","FPI-R (Fahrenberg, Hampel & Selg): erste Auflage 1970, seit 2020 in 9. Auflage; 138 Items, dichotom (stimmt / stimmt nicht), 20–30 Minuten; 10 Standardskalen und 2 Sekundärskalen.","Facette = Subskala, die einer übergeordneten Skala zugeordnet ist; z. B. wird Verträglichkeit im NEO-PI-R über sechs Facetten (Vertrauen, Freimütigkeit, Altruismus, Entgegenkommen, Bescheidenheit, Gutherzigkeit) mit je acht Items erhoben."]}},{"id":"k8-7bc12ba9e1","kap":8,"sec":"8.2.4 Kognitives Persönlichkeitsmodell nach Mischel","stem":"Welche Aussagen zu Mischels fünf Persönlichkeitsvariablen treffen zu?","opts":[{"t":"Zu den Variablen zählen Ergebniserwartungen: spezifische Erwartungen hinsichtlich der Folgen unterschiedlicher Verhaltensmöglichkeiten in einer bestimmten Situation.","c":true,"fb":"Diese Erwartungen müssen nicht zwingend mit den objektiven Eventualitäten der Situation übereinstimmen."},{"t":"Subjektive Werte umfassen individuelle Präferenzen und Aversionen gegenüber bestimmten Reizen.","c":true,"fb":"Diese Reize können als Anreize bzw. Verstärker fungieren oder dazu führen, dass ein Verhalten unterbleibt."},{"t":"Selbstregulationssysteme und Pläne beschreiben, dass Personen sich auch ohne externe Einschränkungen individuelle Ziele setzen.","c":true,"fb":"Verhalten wird durch selbst auferlegte Standards und Konsequenzen modifiziert – je nach Abweichung folgt Selbstkritik oder Selbstzufriedenheit."},{"t":"Mischel postulierte diese Variablen als voneinander unabhängige Größen, die nicht miteinander interagieren.","c":false,"fb":"Die fünf „Cognitive social learning person variables“ interagieren ausdrücklich miteinander."}],"concept":{"title":"Die fünf „Cognitive social learning person variables“ (Mischel, 1973)","points":["Kognitive und verhaltensbezogene Konstruktionskompetenz: stabile, situationsübergreifende Fähigkeit, anpassungsfähige Verhaltensweisen zu erzeugen.","Kodierung und Kategorisierung von Ereignissen: wie jemand Beobachtetes verschlüsselt und welche persönlichen Konstrukte er anlegt.","Ergebniserwartungen hinsichtlich Verhalten und Stimuli.","Subjektive Werte: Präferenzen und Aversionen gegenüber Reizen.","Selbstregulationssysteme und Pläne: selbst gesetzte Ziele, Standards und Konsequenzen.","Mischel verfolgte einen integrativen Ansatz und verstand Persönlichkeit als kognitives Verarbeitungssystem, geprägt durch Lernerfahrungen und Sozialisierung."]}},{"id":"k8-2ec7044679","kap":8,"sec":"8.1.1 Infobox: Referenzgruppe","stem":"Welche Aussagen zur Referenzgruppe bzw. Referenzpopulation treffen zu?","opts":[{"t":"Löst eine Person in einem IQ-Test 80 % der Fragen korrekt, ist dieses Ergebnis unabhängig von der Referenzgruppe als überdurchschnittlich zu werten.","c":false,"fb":"Genau das Gegenteil ist der Fall: Dasselbe Ergebnis kann durchschnittlich, unterdurchschnittlich oder überdurchschnittlich sein – je nachdem, wie die Referenzgruppe im Mittel abschneidet."},{"t":"Referenzgruppen dienen dazu, absolute Rohwerte einer Person zu bestimmen, ohne dass ein Vergleich mit anderen Personen notwendig wäre.","c":false,"fb":"Der Vergleich ist gerade der Zweck: Die Referenzgruppe ermöglicht eine relative Aussage zur Merkmalsausprägung einer Person."},{"t":"Die Vergleichsgruppe besteht meist aus Personen desselben Alters und Geschlechts sowie desselben historischen Zeitraums und derselben Kultur.","c":true,"fb":"Nur so lassen sich individuelle Werte sinnvoll relativieren."},{"t":"Persönlichkeitsausprägungen sind nur dann individuelle Besonderheiten, wenn sie zwischen Personen variieren und in Bezug zu einer Referenzpopulation gestellt werden.","c":true,"fb":"Deshalb gehört die Referenzialität zu den Kernmerkmalen des Persönlichkeitsbegriffs."}],"concept":{"title":"Referenzgruppe","points":["Definition: Vergleichsgruppe, anhand derer individuelle Werte einer Person relativiert werden können.","Zusammensetzung: meist Personen desselben Alters und Geschlechts, desselben historischen Zeitraums und derselben Kultur.","Funktion: Ergebnisse psychologischer Tests werden mit den zu erwartenden Ergebnissen der Referenzgruppe verglichen – daraus ergibt sich die Einordnung als durchschnittlich, über- oder unterdurchschnittlich."]}},{"id":"k8-2c74721778","kap":8,"sec":"8.2.3 Humanistische Psychologie und Charlotte Bühler","stem":"Welche Aussagen zur Humanistischen Psychologie treffen zu?","opts":[{"t":"Charlotte Bühler emigrierte in die USA und gilt dort als Alleinbegründerin der humanistischen Psychologie.","c":false,"fb":"Sie gilt nach ihrer Emigration als Mitbegründerin der humanistischen Psychologie in den USA – daneben als Begründerin der Wiener Schule der Kleinkinder- und Jugendpsychologie, als Wegbereiterin der Gerontopsychologie und als Begründerin der modernen Entwicklungspsychologie."},{"t":"Zu Bühlers vier Grundtendenzen zählt die Tendenz zur Reduktion innerer Spannung durch Triebabfuhr.","c":false,"fb":"Diese Tendenz gehört nicht zum Katalog. Die vier Grundtendenzen sind: persönliche Zufriedenheit, Anpassung zur Erlangung von Sicherheit, Kreativität und Selbstentfaltung sowie Aufrechterhaltung der inneren Ordnung."},{"t":"Die Humanistische Psychologie formierte sich in den 1960er Jahren als Gegenbewegung zur Psychoanalyse und zum Behaviorismus.","c":true,"fb":"Sie gilt als weitere große Schule der Psychologie."},{"t":"Im Vordergrund der humanistischen Persönlichkeitstheorien steht das Krankheitsbild einer Person.","c":false,"fb":"Richtungsumkehr: Nicht das Krankheitsbild, sondern das Wachstumspotenzial einer Person steht im Vordergrund."}],"concept":{"title":"Humanistische Persönlichkeitstheorien","points":["Entstehung: 1960er Jahre, als Gegenbewegung zu Psychoanalyse und Behaviorismus; im Zentrum steht das Wachstumspotenzial, nicht das Krankheitsbild.","Kernannahmen: Phänomenologie (jedes Individuum nimmt Realität auf eigene Weise wahr); subjektive Wahrnehmung beeinflusst Denken und Handeln; Verstehen gelingt nur aus der Perspektive der anderen Person; das Selbstkonzept ist ein wichtiges Persönlichkeitsmerkmal; jeder Mensch strebt nach Selbstverwirklichung.","Selbstkonzept: das Bild, das eine Person von sich selbst hat – geprägt durch frühe Erfahrungen und soziale Interaktionen (Calhoun & Morse, 1977).","Charlotte Bühler (1893–1974), vier Grundtendenzen: persönliche Zufriedenheit; Anpassung zur Erlangung von Sicherheit; Kreativität und Selbstentfaltung; Aufrechterhaltung der inneren Ordnung."]}},{"id":"k8-1ede5d0d9b","kap":8,"sec":"8.3 / 8.3.4 Gütekriterien und Objektive Persönlichkeitstests","stem":"Welche Aussagen zu Objektiven Persönlichkeitstests und Gütekriterien treffen zu?","opts":[{"t":"Die erste Generation Objektiver Persönlichkeitstests geht auf Hans Eysenck zurück.","c":false,"fb":"Personenverwechslung: Die erste Generation geht auf Raymond Cattell zurück. Eysenck steht für das Zwei-Dimensionen-Modell der Persönlichkeit."},{"t":"Objektive Persönlichkeitstests verfügen über keine sogenannte face validity bzw. Augenscheinvalidität.","c":true,"fb":"Für die Testperson ist nicht erkennbar, welche Eigenschaft gemessen wird – die Ergebnisse sind dadurch weniger anfällig für Verzerrungen."},{"t":"Als objektive Parameter gelten etwa die Reaktionszeit oder die Anzahl gelöster Aufgaben.","c":true,"fb":"Aus den beobachteten Reaktionen werden Rückschlüsse auf die Persönlichkeit gezogen."},{"t":"Zu den Hauptgütekriterien psychologischer Tests zählen Objektivität, Reliabilität und Validität.","c":true,"fb":"Die Gütekriterien teilen sich in Haupt- und Nebengütekriterien auf; die drei genannten sind die zentralen Qualitätsmerkmale."}],"concept":{"title":"Objektive Persönlichkeitstests (OPT)","points":["Definition: hoch standardisierte Testsituationen, in denen für die Testperson nicht erkennbar ist, welche Eigenschaft gemessen wird (keine face validity).","„Objektiv“ heißt hier: keine Selbstbeurteilung der zu erhebenden Eigenschaft durch die Testperson; objektive Parameter sind z. B. Reaktionszeit oder Anzahl gelöster Aufgaben.","Erste Generation: Raymond Cattell. Zweite Generation: computergestützt, komplexe und flexible Testungen.","Varianten: als Leistungstest „getarnte“ OPTs sowie Verfahren, die „echte“ Lebenssituationen simulieren.","Hauptgütekriterien aller psychologischen Verfahren: Objektivität, Reliabilität, Validität."]}},{"id":"k8-28ade66b87","kap":8,"sec":"8.3.1 Selbstberichtsverfahren","stem":"Welche Aussagen zu Selbstberichtsverfahren treffen zu?","opts":[{"t":"Selbstberichtsverfahren sind in der Anwendung deutlich aufwändiger als Fremdbewertungen.","c":false,"fb":"Richtungsumkehr: Selbstbewertungen sind in der Regel sehr ökonomisch – etwa als Gruppentestung mit nur einer Testleitung. Die Fremdbewertung ist meist deutlich aufwändiger."},{"t":"Soziale Erwünschtheit bezeichnet die Tendenz, Antworten bewusst so zu verfälschen, dass man möglichst ungünstig erscheint.","c":false,"fb":"Umgekehrtes Vorzeichen: Bei sozialer Erwünschtheit bemüht sich die befragte Person, mit ihren Antworten den Erwartungen und sozialen Normen der Gesellschaft bzw. der betroffenen Gruppe zu entsprechen."},{"t":"Ein Vorteil ist, dass nicht von außen Beobachtbares – etwa Einstellungen oder Persönlichkeitsmerkmale – erfasst werden kann.","c":true,"fb":"Zudem sind sie für sehr viele Persönlichkeitsmerkmale verfügbar und erlauben den Vergleich anhand von Normwerten."},{"t":"Ein Nachteil ist, dass Selbsteinsicht der befragten Person nötig ist.","c":true,"fb":"Hinzu kommt die Anfälligkeit für bewusste und unbewusste Selbsttäuschung sowie die Verfälschbarkeit."}],"concept":{"title":"Selbstberichtsverfahren: Vor- und Nachteile","points":["Vorteile: für sehr viele Persönlichkeitsmerkmale verfügbar; erfassen auch nicht von außen Beobachtbares; Vergleich mit anderen anhand von Normwerten; ökonomisch in Zeit und Kosten (Computer- oder Gruppentestung).","Nachteile: Selbsteinsicht der befragten Person nötig; anfällig für bewusste und unbewusste Selbsttäuschung; verfälschbar.","Selbst- vs. Fremdbewertung: Die Selbstbewertung ist leicht manipulierbar, aber niemand kennt die Person so gut wie sie sich selbst. Die Fremdbewertung liefert meist ein zutreffenderes Bild von außen, ist aber aufwändiger und hängt von der Einschulung der Beurteilenden sowie der verfügbaren Informationsmenge ab.","Soziale Erwünschtheit: Selbstdarstellung im Sinne der Erwartungen und sozialen Normen der Gesellschaft bzw. der Gruppe."]}},{"id":"k8-274541106a","kap":8,"sec":"8.2.4 Kognitives Persönlichkeitsmodell nach Kelly","stem":"Welche Aussagen zu Kellys Psychologie der persönlichen Konstrukte und zum Rep-Test treffen zu?","opts":[{"t":"Kelly entwickelte den Rep-Test, um Personen auf standardisierten, allgemein gültigen Dimensionen einzuordnen.","c":false,"fb":"Sein Modell beruht gerade auf der Kritik daran, Menschen auf vorgegebenen theoretischen Dimensionen einzuordnen („dogmatische Rigidität“). Ermittelt werden individuelle Beschreibungen."},{"t":"Die Elemente des Rep-Tests sind vorgegebene theoretische Konstrukte, die für alle Testpersonen identisch sind.","c":false,"fb":"Begriffsverwechslung: Die Elemente sind konkrete Bezugspersonen, mit denen die Testperson bedeutende soziale Rollen (Mutter, Vater, Chefin etc.) konkretisiert. Die Konstrukte beziehen sich erst auf diese Elemente."},{"t":"Kelly betonte, dass persönliche Konstrukte über die Lebensspanne unveränderlich bleiben.","c":false,"fb":"Richtungsumkehr: Persönliche Konstrukte können sich im Laufe des Lebens verändern – Anpassungen werden nötig, wenn sich die Lebensumstände ändern."},{"t":"Aus den Elementen werden zufällig Dreiergruppen gebildet; die Testperson bestimmt, welche zwei Elemente eine Ähnlichkeit besitzen, die das dritte nicht hat.","c":true,"fb":"Genau die dafür herangezogenen Unterscheidungen zeigen, welche Konstrukte in der subjektiven Wirklichkeit der Person wichtige Rollen spielen."}],"concept":{"title":"Kelly: Psychologie der persönlichen Konstrukte","points":["Ausgangspunkt: Kritik daran, Menschen auf vorgegebenen theoretischen Dimensionen einzuordnen; stattdessen individuell passende Dimensionen je Person.","Persönliche Konstrukte: individuelle Muster, geprägt von eigenen Erfahrungen, Vorstellungen und Interpretationen; über die Lebensspanne veränderbar.","Rep-Test (Role construct repertory test, Kelly, 1955): Schritt 1 – bedeutende soziale Rollen durch Bezugspersonen konkretisieren (= Elemente). Schritt 2 – zufällige Dreiergruppen bilden und bestimmen, welche zwei Elemente einander ähnlich sind und worin sie sich vom dritten unterscheiden.","Ergebnis: keine standardisierten Dimensionen, sondern individuelle Beschreibungen des persönlichen Umfelds."]}}];

